import React from 'react';
import {
  FormControl,
  FormControlLabel,
  FormHelperText,
  Radio,
  RadioGroup,
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  Chip,
  List,
  ListItem,
  ListItemIcon,
  ListItemText
} from '@mui/material';
import {
  Visibility as VisibilityIcon,
  Edit as EditIcon,
  DeleteForever as DeleteIcon,
  Add as AddIcon,
  Refresh as RefreshIcon,
  Security as SecurityIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps, AccessType } from '../../types';
import StepLayout from '../shared/StepLayout';

/**
 * Componente para a etapa de seleção do tipo de acesso
 */
const AccessTypeStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t } = useTranslation(['requests', 'common', 'error', 'access']);

  // Manipulador para mudança de tipo de acesso
  const handleAccessTypeChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = (event.target as HTMLInputElement).value as AccessType;
    dispatch({ type: 'SET_ACCESS_TYPE', payload: value });
  };

  // Removida a função handleNext para evitar duplicação de botões

  // Renderizar detalhes do tipo de acesso
  const renderAccessTypeDetails = (type: AccessType) => {
    // Estilo comum para ícones menores
    const iconStyle = { fontSize: '0.9rem' };
    
    // Estilo comum para chips menores
    const chipStyle = { 
      height: 18, 
      '& .MuiChip-label': { 
        px: 0.8, 
        fontSize: '0.65rem',
        fontWeight: 500
      }
    };
    
    // Estilos para ListItem e ListItemText mais compactos
    const listItemSx = { py: 0.5 };
    const listItemTextSx = {
      m: 0,
      '& .MuiListItemText-primary': { 
        fontSize: '0.75rem', 
        fontWeight: 500 
      },
      '& .MuiListItemText-secondary': { 
        fontSize: '0.7rem',
        mt: 0
      }
    };
    
    switch (type) {
      case AccessType.READ:
        return (
          <List dense disablePadding>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <VisibilityIcon color="success" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.readData')} 
                secondary={t('access:access.readDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <Chip size="small" label="SELECT" color="success" sx={chipStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.selectPrivilege')} 
                secondary={t('access:access.selectPrivilegeDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
          </List>
        );
      
      case AccessType.READWRITE:
        return (
          <List dense disablePadding>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <VisibilityIcon color="info" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.readData')} 
                secondary={t('access:access.readDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <EditIcon color="info" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.modifyData')} 
                secondary={t('access:access.modifyDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <AddIcon color="info" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.insertData')} 
                secondary={t('access:access.insertDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28, alignSelf: 'flex-start', mt: 0.5 }}>
                <Box display="flex" gap={0.5} flexWrap="wrap">
                  <Chip size="small" label="SELECT" color="info" sx={chipStyle} />
                  <Chip size="small" label="INSERT" color="info" sx={chipStyle} />
                  <Chip size="small" label="UPDATE" color="info" sx={chipStyle} />
                </Box>
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.readWritePrivileges')} 
                secondary={t('access:access.readWritePrivilegesDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
          </List>
        );
      
      case AccessType.ADMIN:
        return (
          <List dense disablePadding>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <VisibilityIcon color="error" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.readData')} 
                secondary={t('access:access.readDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <EditIcon color="error" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.modifyData')} 
                secondary={t('access:access.modifyDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <AddIcon color="error" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.insertData')} 
                secondary={t('access:access.insertDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <DeleteIcon color="error" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.deleteData')} 
                secondary={t('access:access.deleteDataDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28 }}>
                <SecurityIcon color="error" sx={iconStyle} />
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.adminPrivileges')} 
                secondary={t('access:access.adminPrivilegesDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
            <ListItem sx={listItemSx}>
              <ListItemIcon sx={{ minWidth: 28, alignSelf: 'flex-start', mt: 0.5 }}>
                <Box display="flex" gap={0.5} flexWrap="wrap">
                  <Chip size="small" label="SELECT" color="error" sx={chipStyle} />
                  <Chip size="small" label="INSERT" color="error" sx={chipStyle} />
                  <Chip size="small" label="UPDATE" color="error" sx={chipStyle} />
                  <Chip size="small" label="DELETE" color="error" sx={chipStyle} />
                </Box>
              </ListItemIcon>
              <ListItemText 
                primary={t('access:access.allPrivileges')} 
                secondary={t('access:access.allPrivilegesDesc')}
                sx={listItemTextSx}
              />
            </ListItem>
          </List>
        );
      
      default:
        return null;
    }
  };

  return (
    <StepLayout
      title={String(t('wizard.steps.accessType'))}
      subtitle={String(t('wizard.accessTypeStepSubtitle'))}
      icon="access"
    >
      <Box sx={{ width: '100%', maxWidth: 'none' }}>
      <Grid container spacing={3} sx={{ width: '100%' }}>
        <Grid item xs={12}>
          <FormControl component="fieldset" error={!!state.errors.accessType}>
            <RadioGroup
              aria-label="access-type"
              name="access-type-radio-group"
              value={state.accessType}
              onChange={handleAccessTypeChange}
            >
              <Grid container spacing={3} sx={{ width: '100%' }}>
                <Grid item xs={12} lg={4}>
                  <Card 
                    sx={{ 
                      height: '140px',
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': { transform: 'translateY(-4px)' },
                      border: state.accessType === AccessType.READ ? 2 : 1,
                      borderColor: state.accessType === AccessType.READ ? 'success.main' : 'divider',
                      bgcolor: state.accessType === AccessType.READ ? 'success.50' : 'background.paper',
                      display: 'flex',
                      flexDirection: 'column'
                    }}
                    onClick={() => dispatch({ type: 'SET_ACCESS_TYPE', payload: AccessType.READ })}
                  >
                    <CardContent sx={{ p: 1.5, flex: 1, display: 'flex', flexDirection: 'column' }}>
                      <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.5}>
                        <Typography variant="subtitle1" component="div" color="success.main">
                          {t('access:readOnly')}
                        </Typography>
                        <FormControlLabel
                          value={AccessType.READ}
                          control={<Radio size="small" />}
                          label=""
                          sx={{ m: 0 }}
                        />
                      </Box>
                      
                      <Box display="flex" alignItems="center" mb={1} sx={{ flex: 1 }}>
                        <VisibilityIcon color="success" sx={{ mr: 1, fontSize: '1rem' }} />
                        <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
                          {t('access:access.readOnlyDesc')}
                        </Typography>
                      </Box>
                      
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, minHeight: '32px', alignItems: 'flex-start' }}>
                        <Chip 
                          label="SELECT" 
                          color="success" 
                          size="small" 
                          sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }}
                        />
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
                
                <Grid item xs={12} lg={4}>
                  <Card 
                    sx={{ 
                      height: '140px',
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': { transform: 'translateY(-4px)' },
                      border: state.accessType === AccessType.READWRITE ? 2 : 1,
                      borderColor: state.accessType === AccessType.READWRITE ? 'info.main' : 'divider',
                      bgcolor: state.accessType === AccessType.READWRITE ? 'info.50' : 'background.paper',
                      display: 'flex',
                      flexDirection: 'column'
                    }}
                    onClick={() => dispatch({ type: 'SET_ACCESS_TYPE', payload: AccessType.READWRITE })}
                  >
                    <CardContent sx={{ p: 1.5, flex: 1, display: 'flex', flexDirection: 'column' }}>
                      <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.5}>
                        <Typography variant="subtitle1" component="div" color="info.main">
                          {t('access:readWrite')}
                        </Typography>
                        <FormControlLabel
                          value={AccessType.READWRITE}
                          control={<Radio size="small" />}
                          label=""
                          sx={{ m: 0 }}
                        />
                      </Box>
                      
                      <Box display="flex" alignItems="center" mb={1} sx={{ flex: 1 }}>
                        <RefreshIcon color="info" sx={{ mr: 1, fontSize: '1rem' }} />
                        <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
                          {t('access:access.readWriteDesc')}
                        </Typography>
                      </Box>
                      
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, minHeight: '32px', alignItems: 'flex-start' }}>
                        <Chip label="SELECT" color="info" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                        <Chip label="INSERT" color="info" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                        <Chip label="UPDATE" color="info" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
                
                <Grid item xs={12} lg={4}>
                  <Card 
                    sx={{ 
                      height: '140px',
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': { transform: 'translateY(-4px)' },
                      border: state.accessType === AccessType.ADMIN ? 2 : 1,
                      borderColor: state.accessType === AccessType.ADMIN ? 'error.main' : 'divider',
                      bgcolor: state.accessType === AccessType.ADMIN ? 'error.50' : 'background.paper',
                      display: 'flex',
                      flexDirection: 'column'
                    }}
                    onClick={() => dispatch({ type: 'SET_ACCESS_TYPE', payload: AccessType.ADMIN })}
                  >
                    <CardContent sx={{ p: 1.5, flex: 1, display: 'flex', flexDirection: 'column' }}>
                      <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.5}>
                        <Typography variant="subtitle1" component="div" color="error">
                          {t('access:admin')}
                        </Typography>
                        <FormControlLabel
                          value={AccessType.ADMIN}
                          control={<Radio size="small" />}
                          label=""
                          sx={{ m: 0 }}
                        />
                      </Box>
                      
                      <Box display="flex" alignItems="center" mb={1} sx={{ flex: 1 }}>
                        <SecurityIcon color="error" sx={{ mr: 1, fontSize: '1rem' }} />
                        <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
                          {t('access:access.adminDesc')}
                        </Typography>
                      </Box>
                      
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, minHeight: '32px', alignItems: 'flex-start' }}>
                        <Chip label="SELECT" color="error" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                        <Chip label="INSERT" color="error" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                        <Chip label="UPDATE" color="error" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                        <Chip label="DELETE" color="error" size="small" sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }} />
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              </Grid>
            </RadioGroup>
            
            {state.errors.accessType && (
              <FormHelperText error>{state.errors.accessType}</FormHelperText>
            )}
          </FormControl>
        </Grid>
        
        <Grid item xs={12}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <Typography variant="body2" fontWeight="medium" color="text.secondary">
              {t('access:access.detailedPermissions')}
            </Typography>
            <Box sx={{ flex: 1, height: 1, mx: 1, borderBottom: '1px dashed', borderColor: 'divider' }} />
          </Box>
          
          <Card variant="outlined" sx={{ bgcolor: 'background.paper' }}>
            <CardContent sx={{ p: 1, '&:last-child': { pb: 1 } }}>
              {renderAccessTypeDetails(state.accessType)}
            </CardContent>
          </Card>
          
          {state.accessType === AccessType.ADMIN && (
            <Typography color="error" variant="caption" sx={{ mt: 1, display: 'block', fontStyle: 'italic' }}>
              {t('access:access.adminWarning')}
            </Typography>
          )}
        </Grid>
      </Grid>
      </Box>
    </StepLayout>
  );
};

export default AccessTypeStep;
