import i18n from 'i18next';
import { initReactI18next, useTranslation as useTranslationBase } from 'react-i18next';
import HttpBackend from 'i18next-http-backend';
import LanguageDetector from 'i18next-browser-languagedetector';

// Definir todos os namespaces disponíveis
export const namespaces = [
  'common',
  'auth',
  'audit',
  'dashboard',
  'users',
  'permissions',
  'requests',
  'settings',
  'servers',
  'databases',
  'sync',
  'syncconfig',
  'sync-dashboard',
  'monitoring',
  'logs',
  'notifications',
  'profile',
  'activation',
  'validation',
  'access',
  'metrics',
  'errors',
  'cloud'
] as const;

// Tipo para namespace
export type Namespace = typeof namespaces[number];

// Detectar idioma salvo ou usar padrão
const savedLanguage = localStorage.getItem('i18nextLng') || 'en';

// Inicializar i18n
i18n
  .use(HttpBackend)
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    lng: savedLanguage,
    fallbackLng: 'en',
    debug: false,
    
    // Configuração de namespaces
    ns: namespaces,
    defaultNS: 'common',
    
    // Configurações de performance
    react: {
      useSuspense: true,
      bindI18n: 'languageChanged loaded',
      bindI18nStore: 'added removed',
      transEmptyNodeValue: '',
      transSupportBasicHtmlNodes: true,
      transKeepBasicHtmlNodesFor: ['br', 'strong', 'i', 'p']
    },
    
    // Configuração do backend
    backend: {
      loadPath: '/locales/{{lng}}/{{ns}}.json',
      crossDomain: false,
      withCredentials: false,
      requestOptions: {
        cache: 'no-cache'
      }
    },
    
    // Opções de detecção de idioma
    detection: {
      order: ['localStorage', 'navigator'],
      caches: ['localStorage'],
      excludeCacheFor: ['cimode']
    },
    
    // Opções de interpolação
    interpolation: {
      escapeValue: false
    },
    
    // Otimização de performance
    load: 'languageOnly',
    preload: ['en', 'pt'],
    
    // Habilitar carregamento de namespaces
    partialBundledLanguages: true,
    cleanCode: true,
    
    // Carregamento de recursos
    saveMissing: process.env.NODE_ENV === 'development',
    saveMissingTo: 'current',
    missingKeyHandler: (lngs: readonly string[], ns: string, key: string) => {
      if (process.env.NODE_ENV === 'development') {
        console.warn(`Tradução ausente: ${ns}:${key}`);
        
        // Verifica se a chave contém um "." e se está faltando o prefixo de namespace
        if (key.includes('.') && !key.includes(':')) {
          console.warn(`Possível erro de formato - Use "${key.split('.')[0]}:${key.split('.')[1]}" ao invés de "${key}"`);
        }
      }
    }
  });

// Função utilitária para mudar idioma com persistência no localStorage
export const changeLanguage = async (language: string) => {
  await i18n.changeLanguage(language);
  localStorage.setItem('i18nextLng', language);
};

// Exportar o hook useTranslation tipado
export const useTranslation = (ns?: Namespace | Namespace[]) => {
  return useTranslationBase(ns);
};

// Adicionar função para compatibilidade com código existente
window.__i18nConfig = {
  reloadTranslations: async () => {
    await i18n.reloadResources();
  }
};

// Manter compatibilidade com window.__preloadedLanguage
if (window.__preloadedLanguage) {
  i18n.changeLanguage(window.__preloadedLanguage);
}

// Declaração global para TypeScript
declare global {
  interface Window {
    __preloadedLanguage?: string;
    __i18nConfig?: {
      reloadTranslations: () => Promise<void>;
    };
  }
}

export default i18n;