import { RequestFormState, RequestFormAction, DatabaseType, AccessType } from './types';

// Estado inicial do formulário
export const initialState: RequestFormState = {
  userId: '',
  serverId: '',
  databaseName: '',        // Novo: nome do banco de dados
  schemaName: '',          // Schema será definido conforme o tipo de banco
  tables: [],
  accessType: AccessType.READ,
  justification: '',
  expirationDate: '',
  isPermanent: false,

  databaseType: null,
  currentStep: 0,
  previousStep: 0,
  direction: 'none',
  errors: {},
  isLoading: false,

  users: [],
  servers: [],
  databases: [],
  tablesList: [],
  schemas: [],
  schemasMap: {}, // Mapa de schemas para PostgreSQL (database => schemas[])
  
  // Service user fields
  isServiceUser: false,
  serviceUserName: '',
  serviceUserDescription: '',
  
  // Database-level permission flag
  isDatabaseLevel: false,
};

// Reducer para gerenciar o estado do formulário
export const requestFormReducer = (
  state: RequestFormState,
  action: RequestFormAction
): RequestFormState => {
  switch (action.type) {
    case 'SET_USER':
      return {
        ...state,
        userId: action.payload,
        errors: { ...state.errors, userId: '' }
      };

    case 'SET_SERVER':
      // Ao mudar o servidor, resetamos todos os campos dependentes
      return {
        ...state,
        serverId: action.payload,
        databaseName: '',     // Limpar nome do banco
        schemaName: 'public', // Reset para valor padrão (apenas para PostgreSQL)
        tables: [],
        errors: { ...state.errors, serverId: '' }
      };

    case 'SET_DATABASE_NAME':
      // Nova ação para definir explicitamente o nome do banco de dados
      return {
        ...state,
        databaseName: action.payload,
        // Reset de valores dependentes - Oracle também usa schemas
        schemaName: (state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.ORACLE) ? state.schemaName || '' : '',
        tables: [],
        errors: { ...state.errors, databaseName: '' }
      };

    case 'SET_DATABASE':
      // Mantido para compatibilidade - comportamento adaptado para nova estrutura
      return {
        ...state,
        serverId: action.payload,
        tables: [],
        errors: { ...state.errors, serverId: '' }
      };

    case 'SET_SCHEMA':
      // Ao mudar o schema, resetamos as tabelas
      return {
        ...state,
        schemaName: action.payload,
        tables: [],
        errors: { ...state.errors, schemaName: '' }
      };

    case 'SET_TABLES':
      return {
        ...state,
        tables: action.payload,
        errors: { ...state.errors, tables: '' }
      };

    case 'SET_ACCESS_TYPE':
      return {
        ...state,
        accessType: action.payload,
        errors: { ...state.errors, accessType: '' }
      };

    case 'SET_JUSTIFICATION':
      return {
        ...state,
        justification: action.payload,
        errors: { ...state.errors, justification: '' }
      };

    case 'SET_EXPIRATION_DATE':
      return {
        ...state,
        expirationDate: action.payload,
        errors: { ...state.errors, expirationDate: '' }
      };

    case 'SET_IS_PERMANENT':
      return {
        ...state,
        isPermanent: action.payload,
        // Se é permanente, limpa a data de expiração
        expirationDate: action.payload ? '' : state.expirationDate,
        errors: { ...state.errors, isPermanent: '' }
      };

    case 'SET_DATABASE_TYPE':
      return {
        ...state,
        databaseType: action.payload,
        // Ajustar schema padrão conforme o tipo de banco - Oracle também usa schemas
        schemaName: action.payload === DatabaseType.POSTGRESQL ? 'public' : ''
      };

    case 'SET_CURRENT_STEP':
      return {
        ...state,
        previousStep: state.currentStep,
        currentStep: action.payload,
        // Determinar a direção da transição
        direction: action.payload > state.currentStep ? 'left' : 'right'
      };

    case 'SET_PREVIOUS_STEP':
      return { ...state, previousStep: action.payload };

    case 'SET_DIRECTION':
      return { ...state, direction: action.payload };

    case 'SET_ERRORS':
      return { ...state, errors: { ...state.errors, ...action.payload } };

    case 'SET_LOADING':
      return { ...state, isLoading: action.payload };

    case 'SET_USERS':
      return { ...state, users: action.payload };

    case 'SET_SERVERS':
      return { ...state, servers: action.payload };

    case 'SET_DATABASES':
      return { ...state, databases: action.payload };

    case 'SET_TABLES_DATA':
      return { ...state, tablesList: action.payload };

    case 'SET_SCHEMAS':
      return { ...state, schemas: action.payload };

    case 'SET_SCHEMAS_MAP':
      return { ...state, schemasMap: action.payload };

    case 'SET_SERVICE_USER_INFO':
      return {
        ...state,
        isServiceUser: action.payload.isServiceUser,
        serviceUserName: action.payload.serviceUserName,
        serviceUserDescription: action.payload.serviceUserDescription,
      };

    case 'SET_DATABASE_LEVEL':
      return {
        ...state,
        isDatabaseLevel: action.payload,
        // Se é database-level, limpa a seleção de tabelas
        tables: action.payload ? [] : state.tables,
      };

    case 'RESET_FORM':
      return {
        ...initialState,
        // Preserva apenas algumas configurações do estado atual
        users: state.users,
        servers: state.servers
      };

    case 'INITIALIZE_FORM':
      return { ...state, ...action.payload };

    default:
      return state;
  }
};