import React from 'react';
import { Box, Typography, Paper, Grid, SxProps, Theme, Avatar, Tooltip, Fade } from '@mui/material';
import {
  Dataset as DatabaseIcon,
  Storage as StorageIcon,
  TableChart as TableChartIcon,
  AccessTime as AccessTimeIcon,
  Check as CheckIcon,
  Dns as DnsIcon,
  Person as PersonIcon,
  Description as DescriptionIcon,
  Schema as SchemaIcon,
  Key as KeyIcon
} from '@mui/icons-material';

interface StepLayoutProps {
  title: string;
  subtitle?: string;
  icon?: 'user' | 'server' | 'database' | 'schema' | 'table' | 'access' | 'duration' | 'justification' | 'review';
  children: React.ReactNode;
  sx?: SxProps<Theme>;
  nextDisabled?: boolean;
}

/**
 * Componente de layout padronizado para as etapas do formulário
 */
const StepLayout: React.FC<StepLayoutProps> = ({ 
  title, 
  subtitle, 
  icon, 
  children,
  sx = {},
  nextDisabled
}) => {
  // Configuração de ícones com cores e tooltips
  const iconConfig = {
    user: {
      icon: <PersonIcon fontSize="large" />,
      color: '#2196F3',
      tooltip: 'Selecione o usuário que receberá as permissões'
    },
    server: {
      icon: <StorageIcon fontSize="large" />,
      color: '#3F51B5',
      tooltip: 'Escolha o servidor de banco de dados'
    },
    database: {
      icon: <DatabaseIcon fontSize="large" />,
      color: '#4CAF50',
      tooltip: 'Selecione o banco de dados'
    },
    schema: {
      icon: <SchemaIcon fontSize="large" />, // Ícone mais apropriado para schema
      color: '#FF9800',
      tooltip: 'Escolha o schema PostgreSQL'
    },
    table: {
      icon: <TableChartIcon fontSize="large" />,
      color: '#9C27B0',
      tooltip: 'Selecione as tabelas para acesso'
    },
    access: {
      icon: <KeyIcon fontSize="large" />, // Ícone mais apropriado para acesso
      color: '#F44336',
      tooltip: 'Defina o tipo de acesso necessário'
    },
    duration: {
      icon: <AccessTimeIcon fontSize="large" />,
      color: '#00BCD4',
      tooltip: 'Escolha a duração do acesso'
    },
    justification: {
      icon: <DescriptionIcon fontSize="large" />,
      color: '#607D8B',
      tooltip: 'Forneça um motivo para esta solicitação'
    },
    review: {
      icon: <CheckIcon fontSize="large" />,
      color: '#4CAF50',
      tooltip: 'Revise todos os detalhes da solicitação'
    }
  };

  // Selecionar a configuração do ícone
  const getIconConfig = () => {
    return icon ? iconConfig[icon] : {
      icon: <DnsIcon fontSize="large" />,
      color: '#9E9E9E',
      tooltip: 'Etapa do processo'
    };
  };

  const iconData = getIconConfig();

  return (
    <Box sx={{ width: '100%', ...sx }}>
      <Grid container spacing={2} alignItems="center" sx={{ mb: 3 }}>
        {icon && (
          <Grid item xs="auto">
            <Tooltip 
              title={iconData.tooltip} 
              placement="top" 
              arrow
              TransitionComponent={Fade}
              TransitionProps={{ timeout: 600 }}
            >
              <Avatar 
                sx={{ 
                  bgcolor: `${iconData.color}20`, // Versão transparente da cor para o fundo
                  color: iconData.color,
                  width: 56, 
                  height: 56,
                  boxShadow: '0 2px 10px rgba(0,0,0,0.08)'
                }}
              >
                {iconData.icon}
              </Avatar>
            </Tooltip>
          </Grid>
        )}
        <Grid item xs>
          <Typography 
            variant="h5" 
            component="h2" 
            gutterBottom={!subtitle}
            sx={{ 
              fontWeight: 600,
              color: 'text.primary'
            }}
          >
            {title}
          </Typography>
          {subtitle && (
            <Typography 
              variant="body1" 
              color="text.secondary"
              sx={{ 
                opacity: 0.8
              }}
            >
              {subtitle}
            </Typography>
          )}
        </Grid>
      </Grid>

      <Paper 
        elevation={2} // Elevação leve para melhor sombra
        sx={{ 
          p: 3, 
          minHeight: 'auto',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          bgcolor: 'background.paper',
          borderRadius: 2, // Bordas mais arredondadas
          overflow: 'hidden',
          boxShadow: '0 3px 15px rgba(0,0,0,0.06)',
          transition: 'all 0.3s ease',
          '&:hover': {
            boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
          }
        }}
      >
        {children}
      </Paper>
    </Box>
  );
};

export default React.memo(StepLayout);