import React, { useState, useEffect } from 'react';
import { useTranslation } from '../../i18n/i18n';
import ConfigPageTemplate from '../../components/Settings/ConfigPageTemplate';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  Switch,
  FormControlLabel,
  Grid,
  Alert,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  LinearProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormGroup,
  Checkbox,
  Stack,
  Tooltip,
  CircularProgress
} from '@mui/material';
import {
  Save as SaveIcon,
  CloudUpload as BackupIcon,
  Info as InfoIcon,
  Schedule as ScheduleIcon,
  Storage as StorageIcon,
  Email as EmailIcon,
  History as HistoryIcon,
  Warning as WarningIcon,
  CheckCircle as SuccessIcon,
  Error as ErrorIcon,
  Download as DownloadIcon,
  Refresh as RefreshIcon,
  Settings as SettingsIcon,
  CloudUpload as CloudUploadIcon,
  Restore as RestoreIcon,
  Cloud as S3Icon,
  Lock as LockIcon
} from '@mui/icons-material';
import { format, formatDistanceToNow } from 'date-fns';
import { ptBR, enUS } from 'date-fns/locale';
// api import removido - não utilizado

interface BackupConfig {
  id: string;
  enabled: boolean;
  schedule_cron: string;
  backup_type: string;
  retention_days: number;
  storage_path: string;
  include_audit_logs: boolean;
  include_configurations: boolean;
  include_user_data: boolean;
  notification_email: string;
  // S3 Configuration
  storage_type?: string; // "local" or "s3"
  s3_enabled?: boolean;
  s3_bucket_name?: string;
  s3_region?: string;
  s3_access_key_id?: string;
  s3_secret_access_key?: string;
  s3_storage_class?: string;
  s3_prefix?: string;
  s3_enable_versioning?: boolean;
  s3_enable_encryption?: boolean;
}

interface BackupHistory {
  id: string;
  backup_type: string;
  status: string;
  started_at: string;
  completed_at?: string;
  size_bytes?: number;
  file_path?: string;
  error_message?: string;
}

const BackupConfigPage: React.FC = () => {
  const { t, i18n } = useTranslation('settings');
  // theme removido - não utilizado
  const [config, setConfig] = useState<BackupConfig | null>(null);
  const [history, setHistory] = useState<BackupHistory[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [backupDialogOpen, setBackupDialogOpen] = useState(false);
  const [selectedComponents, setSelectedComponents] = useState({
    database: true,
    audit_logs: true,
    configurations: true
  });
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
  const [restoreDialogOpen, setRestoreDialogOpen] = useState(false);
  const [selectedBackupId, setSelectedBackupId] = useState<string | null>(null);
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  
  // Função helper para obter o locale correto do date-fns
  const getDateLocale = () => {
    return i18n.language === 'pt' ? ptBR : enUS;
  };
  const [restoring, setRestoring] = useState(false);
  const [restoreComponents, setRestoreComponents] = useState({
    database: true,
    audit_logs: true,
    configurations: true
  });
  const [testingS3, setTestingS3] = useState(false);

  const locale = i18n.language === 'pt' ? ptBR : enUS;

  useEffect(() => {
    fetchBackupConfig();
    fetchBackupHistory();
  }, []);

  const fetchBackupConfig = async () => {
    try {
      const response = await fetch('/api/backup/config', {
        credentials: 'include'
      });
      
      if (response.ok) {
        const data = await response.json();
        setConfig(data);
      } else {
        setErrorMessage(t('backup.fetchError'));
      }
    } catch (error) {
      console.error('Error fetching backup config:', error);
      setErrorMessage(t('backup.fetchError'));
    } finally {
      setLoading(false);
    }
  };

  const fetchBackupHistory = async () => {
    try {
      const response = await fetch('/api/backup/history', {
        credentials: 'include'
      });
      
      if (response.ok) {
        const data = await response.json();
        setHistory(data || []);
      }
    } catch (error) {
      console.error('Error fetching backup history:', error);
    }
  };

  const handleSave = async () => {
    if (!config) return;
    
    setSaving(true);
    try {
      const response = await fetch('/api/backup/config', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify(config)
      });

      if (response.ok) {
        setSuccessMessage(t('backup.saveSuccess'));
      } else {
        setErrorMessage(t('backup.saveError'));
      }
    } catch (error) {
      console.error('Error saving backup config:', error);
      setErrorMessage(t('backup.saveError'));
    } finally {
      setSaving(false);
    }
  };

  const handleStartBackup = async () => {
    try {
      const components = Object.entries(selectedComponents)
        .filter(([_, value]) => value)
        .map(([key]) => key);

      const response = await fetch('/api/backup/start', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          backup_type: 'manual',
          components
        })
      });

      if (response.ok) {
        setSuccessMessage(t('backup.startSuccess'));
        setBackupDialogOpen(false);
        // Refresh history after starting backup
        setTimeout(fetchBackupHistory, 2000);
      } else {
        setErrorMessage(t('backup.startError'));
      }
    } catch (error) {
      console.error('Error starting backup:', error);
      setErrorMessage(t('backup.startError'));
    }
  };

  const formatBytes = (bytes?: number): string => {
    if (!bytes) return '0 Bytes';
    
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed':
        return <SuccessIcon color="success" />;
      case 'failed':
        return <ErrorIcon color="error" />;
      case 'running':
        return <LinearProgress sx={{ width: 100 }} />;
      default:
        return <WarningIcon color="warning" />;
    }
  };

  const handleDownloadBackup = async (backupId: string) => {
    try {
      const response = await fetch(`/api/backup/download?id=${backupId}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Download failed');
      }

      // Obter o nome do arquivo do header Content-Disposition
      const contentDisposition = response.headers.get('Content-Disposition');
      let filename = 'backup.tar.gz';
      if (contentDisposition) {
        const match = contentDisposition.match(/filename="(.+)"/);
        if (match) {
          filename = match[1];
        }
      }

      // Criar blob e fazer download
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Error downloading backup:', error);
      setErrorMessage(t('backup.downloadError'));
    }
  };

  // getStatusColor removido - não utilizado

  const handleUploadBackup = async () => {
    if (!uploadFile) {
      setErrorMessage(t('backup.selectFileError'));
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append('backup', uploadFile);

    try {
      const response = await fetch('/api/backup/upload', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: formData
      });

      if (!response.ok) {
        const error = await response.text();
        throw new Error(error);
      }

      await response.json();
      setSuccessMessage(t('backup.uploadSuccess'));
      setUploadDialogOpen(false);
      setUploadFile(null);
      
      // Atualizar histórico
      setTimeout(fetchBackupHistory, 1000);
    } catch (error) {
      console.error('Error uploading backup:', error);
      setErrorMessage(t('backup.uploadError'));
    } finally {
      setUploading(false);
    }
  };

  const handleRestoreBackup = async () => {
    if (!selectedBackupId) {
      return;
    }

    setRestoring(true);
    
    // Coletar componentes selecionados
    const components = Object.entries(restoreComponents)
      .filter(([_, selected]) => selected)
      .map(([component]) => component);

    try {
      const response = await fetch('/api/backup/restore', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          backup_id: selectedBackupId,
          components
        })
      });

      if (!response.ok) {
        throw new Error('Restore failed');
      }

      await response.json();
      setSuccessMessage(t('backup.restoreStarted'));
      setRestoreDialogOpen(false);
      
      // Atualizar histórico
      setTimeout(fetchBackupHistory, 2000);
    } catch (error) {
      console.error('Error restoring backup:', error);
      setErrorMessage(t('backup.restoreError'));
    } finally {
      setRestoring(false);
    }
  };

  const openRestoreDialog = (backupId: string) => {
    setSelectedBackupId(backupId);
    setRestoreDialogOpen(true);
  };

  const handleTestS3Connection = async () => {
    if (!config) return;
    
    setTestingS3(true);
    setErrorMessage(null);
    setSuccessMessage(null);
    
    try {
      const response = await fetch('/api/backup/test-s3', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          bucket_name: config.s3_bucket_name,
          region: config.s3_region,
          access_key_id: config.s3_access_key_id,
          secret_access_key: config.s3_secret_access_key
        })
      });

      const result = await response.json();
      
      if (response.ok && result.success) {
        setSuccessMessage(t('backup.s3ConnectionSuccess'));
      } else {
        setErrorMessage(result.error || t('backup.s3ConnectionError'));
      }
    } catch (error) {
      console.error('Error testing S3 connection:', error);
      setErrorMessage(t('backup.s3ConnectionError'));
    } finally {
      setTestingS3(false);
    }
  };

  if (loading) {
    return (
      <ConfigPageTemplate
        title={t('backup.title')}
        icon={<BackupIcon sx={{ fontSize: 32 }} />}
        description={t('backup.description')}
      >
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      </ConfigPageTemplate>
    );
  }

  if (!config) {
    return (
      <ConfigPageTemplate
        title={t('backup.title')}
        icon={<BackupIcon sx={{ fontSize: 32 }} />}
        description={t('backup.description')}
      >
        <Alert severity="error">{t('backup.configNotFound')}</Alert>
      </ConfigPageTemplate>
    );
  }

  return (
    <ConfigPageTemplate
      title={t('backup.title')}
      icon={<BackupIcon sx={{ fontSize: 32 }} />}
      description={t('backup.description')}
    >
      <Box>

      {successMessage && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccessMessage(null)}>
          {successMessage}
        </Alert>
      )}

      {errorMessage && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setErrorMessage(null)}>
          {errorMessage}
        </Alert>
      )}

      <Grid container spacing={3}>
        {/* Configuration Card */}
        <Grid item xs={12} lg={6}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center" mb={3}>
                <SettingsIcon sx={{ mr: 1, color: 'primary.main' }} />
                <Typography variant="h6" fontWeight="medium">
                  {t('backup.configuration')}
                </Typography>
              </Box>

              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={config.enabled}
                        onChange={(e) => setConfig({ ...config, enabled: e.target.checked })}
                        color="primary"
                      />
                    }
                    label={t('backup.enableAutoBackup')}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label={t('backup.schedule')}
                    value={config.schedule_cron}
                    onChange={(e) => setConfig({ ...config, schedule_cron: e.target.value })}
                    helperText={t('backup.scheduleHelp')}
                    InputProps={{
                      startAdornment: <ScheduleIcon sx={{ mr: 1, color: 'action.active' }} />
                    }}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth>
                    <InputLabel>{t('backup.type')}</InputLabel>
                    <Select
                      value={config.backup_type}
                      onChange={(e) => setConfig({ ...config, backup_type: e.target.value })}
                      label={t('backup.type')}
                    >
                      <MenuItem value="full">{t('backup.typeFull')}</MenuItem>
                      <MenuItem value="incremental">{t('backup.typeIncremental')}</MenuItem>
                      <MenuItem value="differential">{t('backup.typeDifferential')}</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    type="number"
                    label={t('backup.retentionDays')}
                    value={config.retention_days}
                    onChange={(e) => setConfig({ ...config, retention_days: parseInt(e.target.value) })}
                    InputProps={{
                      inputProps: { min: 1, max: 365 }
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label={t('backup.storagePath')}
                    value={config.storage_path}
                    onChange={(e) => setConfig({ ...config, storage_path: e.target.value })}
                    InputProps={{
                      startAdornment: <StorageIcon sx={{ mr: 1, color: 'action.active' }} />
                    }}
                  />
                </Grid>

                {/* S3 Configuration Section */}
                <Grid item xs={12}>
                  <Typography variant="subtitle2" gutterBottom sx={{ mt: 2, display: 'flex', alignItems: 'center' }}>
                    <S3Icon sx={{ mr: 1 }} />
                    {t('backup.s3Configuration')}
                  </Typography>
                </Grid>

                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={config.s3_enabled || false}
                        onChange={(e) => setConfig({ ...config, s3_enabled: e.target.checked })}
                        color="primary"
                      />
                    }
                    label={t('backup.enableS3Backup')}
                  />
                </Grid>

                {config.s3_enabled && (
                  <>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label={t('backup.s3BucketName')}
                        value={config.s3_bucket_name || ''}
                        onChange={(e) => setConfig({ ...config, s3_bucket_name: e.target.value })}
                        required
                        helperText={t('backup.s3BucketNameHelp')}
                      />
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <FormControl fullWidth required>
                        <InputLabel>{t('backup.s3Region')}</InputLabel>
                        <Select
                          value={config.s3_region || ''}
                          onChange={(e) => setConfig({ ...config, s3_region: e.target.value })}
                          label={t('backup.s3Region')}
                        >
                          <MenuItem value="">
                            <em>{t('backup.selectRegion')}</em>
                          </MenuItem>
                          {/* US Regions */}
                          <MenuItem value="us-east-1">US East (N. Virginia)</MenuItem>
                          <MenuItem value="us-east-2">US East (Ohio)</MenuItem>
                          <MenuItem value="us-west-1">US West (N. California)</MenuItem>
                          <MenuItem value="us-west-2">US West (Oregon)</MenuItem>
                          {/* South America */}
                          <MenuItem value="sa-east-1">South America (São Paulo)</MenuItem>
                          {/* Europe */}
                          <MenuItem value="eu-west-1">Europe (Ireland)</MenuItem>
                          <MenuItem value="eu-west-2">Europe (London)</MenuItem>
                          <MenuItem value="eu-west-3">Europe (Paris)</MenuItem>
                          <MenuItem value="eu-central-1">Europe (Frankfurt)</MenuItem>
                          <MenuItem value="eu-north-1">Europe (Stockholm)</MenuItem>
                          <MenuItem value="eu-south-1">Europe (Milan)</MenuItem>
                          <MenuItem value="eu-south-2">Europe (Spain)</MenuItem>
                          <MenuItem value="eu-central-2">Europe (Zurich)</MenuItem>
                          {/* Asia Pacific */}
                          <MenuItem value="ap-south-1">Asia Pacific (Mumbai)</MenuItem>
                          <MenuItem value="ap-south-2">Asia Pacific (Hyderabad)</MenuItem>
                          <MenuItem value="ap-northeast-1">Asia Pacific (Tokyo)</MenuItem>
                          <MenuItem value="ap-northeast-2">Asia Pacific (Seoul)</MenuItem>
                          <MenuItem value="ap-northeast-3">Asia Pacific (Osaka)</MenuItem>
                          <MenuItem value="ap-southeast-1">Asia Pacific (Singapore)</MenuItem>
                          <MenuItem value="ap-southeast-2">Asia Pacific (Sydney)</MenuItem>
                          <MenuItem value="ap-southeast-3">Asia Pacific (Jakarta)</MenuItem>
                          <MenuItem value="ap-southeast-4">Asia Pacific (Melbourne)</MenuItem>
                          <MenuItem value="ap-east-1">Asia Pacific (Hong Kong)</MenuItem>
                          {/* Canada */}
                          <MenuItem value="ca-central-1">Canada (Central)</MenuItem>
                          <MenuItem value="ca-west-1">Canada (Calgary)</MenuItem>
                          {/* Middle East */}
                          <MenuItem value="me-south-1">Middle East (Bahrain)</MenuItem>
                          <MenuItem value="me-central-1">Middle East (UAE)</MenuItem>
                          {/* Africa */}
                          <MenuItem value="af-south-1">Africa (Cape Town)</MenuItem>
                          {/* Others */}
                          <MenuItem value="cn-north-1">China (Beijing)</MenuItem>
                          <MenuItem value="cn-northwest-1">China (Ningxia)</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label={t('backup.s3AccessKeyId')}
                        value={config.s3_access_key_id || ''}
                        onChange={(e) => setConfig({ ...config, s3_access_key_id: e.target.value })}
                        required
                      />
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label={t('backup.s3SecretAccessKey')}
                        type="password"
                        value={config.s3_secret_access_key || ''}
                        onChange={(e) => setConfig({ ...config, s3_secret_access_key: e.target.value })}
                        required
                        InputProps={{
                          startAdornment: <LockIcon sx={{ mr: 1, color: 'action.active' }} />
                        }}
                      />
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <FormControl fullWidth>
                        <InputLabel>{t('backup.s3StorageClass')}</InputLabel>
                        <Select
                          value={config.s3_storage_class || 'STANDARD'}
                          onChange={(e) => setConfig({ ...config, s3_storage_class: e.target.value })}
                          label={t('backup.s3StorageClass')}
                        >
                          <MenuItem value="STANDARD">{t('backup.s3StorageClassStandard')}</MenuItem>
                          <MenuItem value="STANDARD_IA">{t('backup.s3StorageClassIA')}</MenuItem>
                          <MenuItem value="GLACIER">{t('backup.s3StorageClassGlacier')}</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label={t('backup.s3Prefix')}
                        value={config.s3_prefix || 'db-manager-backups'}
                        onChange={(e) => setConfig({ ...config, s3_prefix: e.target.value })}
                        helperText={t('backup.s3PrefixHelp')}
                      />
                    </Grid>

                    <Grid item xs={12}>
                      <FormGroup>
                        <FormControlLabel
                          control={
                            <Checkbox
                              checked={config.s3_enable_versioning || false}
                              onChange={(e) => setConfig({ ...config, s3_enable_versioning: e.target.checked })}
                            />
                          }
                          label={t('backup.s3EnableVersioning')}
                        />
                        <FormControlLabel
                          control={
                            <Checkbox
                              checked={config.s3_enable_encryption || false}
                              onChange={(e) => setConfig({ ...config, s3_enable_encryption: e.target.checked })}
                            />
                          }
                          label={t('backup.s3EnableEncryption')}
                        />
                      </FormGroup>
                    </Grid>

                    <Grid item xs={12}>
                      <Button
                        variant="outlined"
                        startIcon={<CloudUploadIcon />}
                        onClick={handleTestS3Connection}
                        disabled={testingS3 || !config.s3_bucket_name || !config.s3_region || !config.s3_access_key_id || !config.s3_secret_access_key}
                      >
                        {testingS3 ? <CircularProgress size={20} /> : t('backup.testS3Connection')}
                      </Button>
                    </Grid>
                  </>
                )}

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label={t('backup.notificationEmail')}
                    value={config.notification_email}
                    onChange={(e) => setConfig({ ...config, notification_email: e.target.value })}
                    helperText={t('backup.notificationEmailHelp')}
                    InputProps={{
                      startAdornment: <EmailIcon sx={{ mr: 1, color: 'action.active' }} />
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="subtitle2" gutterBottom>
                    {t('backup.components')}
                  </Typography>
                  <FormGroup>
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={config.include_user_data}
                          onChange={(e) => setConfig({ ...config, include_user_data: e.target.checked })}
                        />
                      }
                      label={t('backup.includeUserData')}
                    />
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={config.include_audit_logs}
                          onChange={(e) => setConfig({ ...config, include_audit_logs: e.target.checked })}
                        />
                      }
                      label={t('backup.includeAuditLogs')}
                    />
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={config.include_configurations}
                          onChange={(e) => setConfig({ ...config, include_configurations: e.target.checked })}
                        />
                      }
                      label={t('backup.includeConfigurations')}
                    />
                  </FormGroup>
                </Grid>

                <Grid item xs={12}>
                  <Stack direction="row" spacing={2}>
                    <Button
                      variant="contained"
                      startIcon={<SaveIcon />}
                      onClick={handleSave}
                      disabled={saving}
                    >
                      {t('common:save')}
                    </Button>
                    <Button
                      variant="outlined"
                      startIcon={<BackupIcon />}
                      onClick={() => setBackupDialogOpen(true)}
                    >
                      {t('backup.runNow')}
                    </Button>
                    <Button
                      variant="outlined"
                      startIcon={<CloudUploadIcon />}
                      onClick={() => setUploadDialogOpen(true)}
                    >
                      {t('backup.uploadBackup')}
                    </Button>
                  </Stack>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>

        {/* Backup Status Card */}
        <Grid item xs={12} lg={6}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center" justifyContent="space-between" mb={3}>
                <Box display="flex" alignItems="center">
                  <InfoIcon sx={{ mr: 1, color: 'primary.main' }} />
                  <Typography variant="h6" fontWeight="medium">
                    {t('backup.status')}
                  </Typography>
                </Box>
                <Tooltip title={t('common:refresh')}>
                  <IconButton onClick={fetchBackupHistory} size="small">
                    <RefreshIcon />
                  </IconButton>
                </Tooltip>
              </Box>

              {history.length > 0 && history[0].status === 'completed' ? (
                <Box>
                  <Alert severity="success" sx={{ mb: 2 }}>
                    {t('backup.lastBackupSuccess', {
                      time: formatDistanceToNow(new Date(history[0].completed_at!), {
                        addSuffix: true,
                        locale: getDateLocale()
                      })
                    })}
                  </Alert>
                  
                  <Grid container spacing={2}>
                    <Grid item xs={6}>
                      <Typography variant="body2" color="text.secondary">
                        {t('backup.size')}
                      </Typography>
                      <Typography variant="body1" fontWeight="medium">
                        {formatBytes(history[0].size_bytes)}
                      </Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2" color="text.secondary">
                        {t('backup.type')}
                      </Typography>
                      <Typography variant="body1" fontWeight="medium">
                        {t(`backup.type${history[0].backup_type.charAt(0).toUpperCase() + history[0].backup_type.slice(1)}`)}
                      </Typography>
                    </Grid>
                  </Grid>
                </Box>
              ) : (
                <Alert severity="warning">
                  {t('backup.noRecentBackup')}
                </Alert>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Backup History */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center" mb={3}>
                <HistoryIcon sx={{ mr: 1, color: 'primary.main' }} />
                <Typography variant="h6" fontWeight="medium">
                  {t('backup.history')}
                </Typography>
              </Box>

              <TableContainer component={Paper} variant="outlined">
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>{t('backup.date')}</TableCell>
                      <TableCell>{t('backup.type')}</TableCell>
                      <TableCell>{t('backup.status')}</TableCell>
                      <TableCell>{t('backup.size')}</TableCell>
                      <TableCell>{t('backup.duration')}</TableCell>
                      <TableCell align="right">{t('common:actions')}</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {history && history.length > 0 ? history.map((backup) => (
                      <TableRow key={backup.id}>
                        <TableCell>
                          {format(new Date(backup.started_at), 'dd/MM/yyyy HH:mm', { locale })}
                        </TableCell>
                        <TableCell>
                          <Chip
                            label={t(`backup.type${backup.backup_type.charAt(0).toUpperCase() + backup.backup_type.slice(1)}`)}
                            size="small"
                          />
                        </TableCell>
                        <TableCell>
                          <Box>
                            <Box display="flex" alignItems="center">
                              {getStatusIcon(backup.status)}
                              <Typography sx={{ ml: 1 }}>
                                {t(`backup.status${backup.status.charAt(0).toUpperCase() + backup.status.slice(1)}`)}
                              </Typography>
                            </Box>
                            {backup.status === 'failed' && backup.error_message && (
                              <Typography variant="caption" color="error" sx={{ mt: 0.5, display: 'block' }}>
                                {backup.error_message}
                              </Typography>
                            )}
                          </Box>
                        </TableCell>
                        <TableCell>{formatBytes(backup.size_bytes)}</TableCell>
                        <TableCell>
                          {backup.completed_at && backup.started_at ?
                            formatDistanceToNow(
                              new Date(backup.started_at),
                              {
                                locale: getDateLocale(),
                                includeSeconds: true
                              }
                            ) : '-'
                          }
                        </TableCell>
                        <TableCell align="right">
                          {backup.status === 'completed' && backup.file_path && (
                            <Stack direction="row" spacing={0.5}>
                              <Tooltip title={t('backup.download')}>
                                <IconButton size="small" onClick={() => handleDownloadBackup(backup.id)}>
                                  <DownloadIcon />
                                </IconButton>
                              </Tooltip>
                              <Tooltip title={t('backup.restore')}>
                                <IconButton size="small" onClick={() => openRestoreDialog(backup.id)}>
                                  <RestoreIcon />
                                </IconButton>
                              </Tooltip>
                            </Stack>
                          )}
                        </TableCell>
                      </TableRow>
                    )) : (
                      <TableRow>
                        <TableCell colSpan={6} align="center">
                          <Typography variant="body2" color="text.secondary">
                            {t('backup.noHistory')}
                          </Typography>
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Manual Backup Dialog */}
      <Dialog
        open={backupDialogOpen}
        onClose={() => setBackupDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>{t('backup.runManualBackup')}</DialogTitle>
        <DialogContent>
          <Typography variant="body1" gutterBottom>
            {t('backup.selectComponents')}
          </Typography>
          <FormGroup>
            <FormControlLabel
              control={
                <Checkbox
                  checked={selectedComponents.database}
                  onChange={(e) => setSelectedComponents({ ...selectedComponents, database: e.target.checked })}
                />
              }
              label={t('backup.includeUserData')}
            />
            <FormControlLabel
              control={
                <Checkbox
                  checked={selectedComponents.audit_logs}
                  onChange={(e) => setSelectedComponents({ ...selectedComponents, audit_logs: e.target.checked })}
                />
              }
              label={t('backup.includeAuditLogs')}
            />
            <FormControlLabel
              control={
                <Checkbox
                  checked={selectedComponents.configurations}
                  onChange={(e) => setSelectedComponents({ ...selectedComponents, configurations: e.target.checked })}
                />
              }
              label={t('backup.includeConfigurations')}
            />
          </FormGroup>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setBackupDialogOpen(false)}>
            {t('common:cancel')}
          </Button>
          <Button
            variant="contained"
            startIcon={<BackupIcon />}
            onClick={handleStartBackup}
          >
            {t('backup.startBackup')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Upload Backup Dialog */}
      <Dialog
        open={uploadDialogOpen}
        onClose={() => setUploadDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>{t('backup.uploadBackup')}</DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 2 }}>
            <Alert severity="warning" sx={{ mb: 2 }}>
              {t('backup.uploadWarning')}
            </Alert>
            
            <Button
              variant="outlined"
              component="label"
              fullWidth
              startIcon={<CloudUploadIcon />}
              sx={{ mb: 2 }}
            >
              {uploadFile ? uploadFile.name : t('backup.selectFile')}
              <input
                type="file"
                hidden
                accept=".tar.gz"
                onChange={(e) => setUploadFile(e.target.files?.[0] || null)}
              />
            </Button>
            
            {uploadFile && (
              <Typography variant="body2" color="text.secondary">
                {t('backup.fileSize')}: {formatBytes(uploadFile.size)}
              </Typography>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => {
            setUploadDialogOpen(false);
            setUploadFile(null);
          }}>
            {t('common:cancel')}
          </Button>
          <Button
            variant="contained"
            startIcon={uploading ? <CircularProgress size={20} /> : <CloudUploadIcon />}
            onClick={handleUploadBackup}
            disabled={!uploadFile || uploading}
          >
            {uploading ? t('backup.uploading') : t('backup.upload')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Restore Backup Dialog */}
      <Dialog
        open={restoreDialogOpen}
        onClose={() => setRestoreDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>{t('backup.restoreSystem')}</DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 2 }}>
            <Alert severity="error" sx={{ mb: 2 }}>
              {t('backup.restoreWarning')}
            </Alert>
            
            <Typography variant="body2" sx={{ mb: 2 }}>
              {t('backup.selectComponentsToRestore')}
            </Typography>
            
            <FormGroup>
              <FormControlLabel
                control={
                  <Checkbox
                    checked={restoreComponents.database}
                    onChange={(e) => setRestoreComponents({ ...restoreComponents, database: e.target.checked })}
                  />
                }
                label={t('backup.includeDatabase')}
              />
              <FormControlLabel
                control={
                  <Checkbox
                    checked={restoreComponents.audit_logs}
                    onChange={(e) => setRestoreComponents({ ...restoreComponents, audit_logs: e.target.checked })}
                  />
                }
                label={t('backup.includeAuditLogs')}
              />
              <FormControlLabel
                control={
                  <Checkbox
                    checked={restoreComponents.configurations}
                    onChange={(e) => setRestoreComponents({ ...restoreComponents, configurations: e.target.checked })}
                  />
                }
                label={t('backup.includeConfigurations')}
              />
            </FormGroup>
            
            <Alert severity="info" sx={{ mt: 2 }}>
              {t('backup.safetyBackupNote')}
            </Alert>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setRestoreDialogOpen(false)}>
            {t('common:cancel')}
          </Button>
          <Button
            variant="contained"
            color="error"
            startIcon={restoring ? <CircularProgress size={20} /> : <RestoreIcon />}
            onClick={handleRestoreBackup}
            disabled={restoring || !Object.values(restoreComponents).some(v => v)}
          >
            {restoring ? t('backup.restoring') : t('backup.confirmRestore')}
          </Button>
        </DialogActions>
      </Dialog>
      </Box>
    </ConfigPageTemplate>
  );
};

export default BackupConfigPage;
