import React, { useState, useEffect, useRef, KeyboardEvent } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Chip,
  IconButton,
  Tooltip,
  Tabs,
  Tab,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Card,
  CardContent,
  Divider,
  Grid,
  Alert,
  ToggleButton,
  ToggleButtonGroup,
  Menu,
  MenuItem as MenuItemMUI,
  ListItemIcon,
  ListItemText,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
  Checkbox,
  FormControlLabel,
} from '@mui/material';
import {
  Terminal as TerminalIcon,
  Storage as DatabaseIcon,
  PlayArrow as PlayArrowIcon,
  Clear as ClearIcon,
  History as HistoryIcon,
  Storage as StorageIcon,
  Code as CodeIcon,
  TableChart as TableIcon,
  Refresh as RefreshIcon,
  Timer as TimerIcon,
  DataObject as DataObjectIcon,
  Download as DownloadIcon,
  GetApp as ExportIcon,
  Warning as WarningIcon,
  Security as SecurityIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { executeSQL, getSQLServers, getDatabases } from '../../services/sqlShellService';
import BasicDropdown from '../../components/common/BasicDropdown';
import { apiClient as api } from '../../services/api';

interface CommandEntry {
  id: string;
  type: 'prompt' | 'command' | 'result' | 'error' | 'info';
  content: string;
  timestamp: Date;
  executionTime?: number;
  rowCount?: number;
}

interface SQLServer {
  id: string;
  name: string;
  type: string;
  database_name?: string;
  host: string;
  port: number;
  status: string;
}

interface QueryResult {
  data: any[];
  fields: any[];
  rowCount: number;
  executionTime: number;
}

const SQLShellPage: React.FC = () => {
  const { t } = useTranslation(['sqlShell', 'common']);

  // Common state
  const [activeTab, setActiveTab] = useState(0);
  const [servers, setServers] = useState<SQLServer[]>([]);
  const [selectedServerId, setSelectedServerId] = useState<string>('');
  const [currentDatabase, setCurrentDatabase] = useState<string | null>(null);
  const [databases, setDatabases] = useState<string[]>([]);
  const [isExecuting, setIsExecuting] = useState(false);

  // Terminal mode state
  const [terminalContent, setTerminalContent] = useState<CommandEntry[]>([]);
  const [currentCommand, setCurrentCommand] = useState('');
  const [historyIndex, setHistoryIndex] = useState(-1);
  const [commandBuffer, setCommandBuffer] = useState<string[]>([]);
  const [multilineBuffer, setMultilineBuffer] = useState<string[]>([]);
  const [isMultiline, setIsMultiline] = useState(false);

  // Visual mode state
  const [sqlQuery, setSqlQuery] = useState('');
  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
  const [queryError, setQueryError] = useState<string>('');
  const [queryHistory, setQueryHistory] = useState<string[]>([]);
  const [outputFormat, setOutputFormat] = useState<'table' | 'terminal'>('table');
  const [exportAnchorEl, setExportAnchorEl] = useState<null | HTMLElement>(null);
  const [dumpDialogOpen, setDumpDialogOpen] = useState(false);
  const [dumpFormat, setDumpFormat] = useState<'sql' | 'csv'>('sql');
  const [dumpTables, setDumpTables] = useState<string[]>([]);
  const [selectedTables, setSelectedTables] = useState<string[]>([]);

  const terminalRef = useRef<HTMLDivElement>(null);
  const hiddenInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    loadServers();
  }, []);

  useEffect(() => {
    // Auto-scroll to bottom when new content is added
    if (terminalRef.current && activeTab === 1) {
      terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
    }
  }, [terminalContent, activeTab]);

  useEffect(() => {
    // Keep focus on hidden input when in terminal mode
    if (activeTab === 1 && hiddenInputRef.current && !isExecuting) {
      hiddenInputRef.current.focus();
    }
  }, [activeTab, terminalContent, isExecuting]);

  const loadServers = async () => {
    try {
      const response = await getSQLServers();
      if (response.success && response.data) {
        setServers(response.data);
      }
    } catch (error) {
      console.error('Error loading servers:', error);
    }
  };

  const loadDatabases = async (serverId: string) => {
    try {
      console.log('Loading databases for server:', serverId);
      const response = await getDatabases(serverId);
      console.log('Database response:', response);

      if (response.success && response.data) {
        setDatabases(response.data);
        console.log('Databases loaded:', response.data);

        // Set the first database as default if available
        if (response.data.length > 0 && !currentDatabase) {
          setCurrentDatabase(response.data[0]);
        }
      } else {
        console.warn('No databases returned or response not successful');
        setDatabases([]);
      }
    } catch (error) {
      console.error('Error loading databases:', error);
      setDatabases([]);
    }
  };

  const connectToServer = (serverId: string) => {
    console.log('Connecting to server:', serverId);
    const server = servers.find(s => s.id === serverId);

    if (server) {
      console.log('Server found:', server);
      setSelectedServerId(serverId);
      // Reset database selection when changing servers
      setCurrentDatabase(null);
      setDatabases([]); // Clear previous databases

      // Load databases for the selected server
      if (serverId) {
        loadDatabases(serverId);
      }

      if (activeTab === 1) {
        appendToTerminal({
          type: 'info',
          content: `Connected to ${server.name} (${server.type})`,
        });
        showPrompt();
      }
    } else {
      console.warn('Server not found:', serverId);
      setSelectedServerId('');
      setCurrentDatabase(null);
      setDatabases([]);
    }
  };

  // Terminal mode functions
  const appendToTerminal = (entry: Omit<CommandEntry, 'id' | 'timestamp'>) => {
    const newEntry: CommandEntry = {
      ...entry,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
    };
    setTerminalContent(prev => [...prev, newEntry]);
  };

  const showPrompt = () => {
    const serverName = servers.find(s => s.id === selectedServerId)?.name || 'dbmanager';
    const prompt = currentDatabase ? `${serverName}:${currentDatabase}` : serverName;
    appendToTerminal({
      type: 'prompt',
      content: `${prompt}> `,
    });
  };

  const clearTerminal = () => {
    setTerminalContent([]);
    setCurrentCommand('');
    setMultilineBuffer([]);
    setIsMultiline(false);
    if (selectedServerId) {
      const server = servers.find(s => s.id === selectedServerId);
      if (server) {
        appendToTerminal({
          type: 'info',
          content: `Connected to ${server.name} (${server.type})`,
        });
      }
    }
    showPrompt();
  };

  const executeTerminalCommand = async (command: string) => {
    if (!selectedServerId) {
      appendToTerminal({
        type: 'error',
        content: 'Not connected to any server. Please select a server first.',
      });
      showPrompt();
      return;
    }

    // Check for special commands
    if (command.toLowerCase() === 'clear' || command.toLowerCase() === 'cls') {
      clearTerminal();
      return;
    }

    if (command.toLowerCase() === 'help') {
      appendToTerminal({
        type: 'info',
        content: `Available commands:
  \\l, SHOW DATABASES    - List all databases
  USE <database>        - Switch to a database
  \\dt, SHOW TABLES      - Show tables in current database
  \\d <table>            - Describe table structure
  \\q, EXIT              - Exit SQL Shell
  CLEAR, CLS            - Clear terminal screen

Standard SQL commands are also supported.`,
      });
      showPrompt();
      return;
    }

    if (command.toLowerCase() === '\\q' || command.toLowerCase() === 'exit') {
      setActiveTab(0);
      return;
    }

    // Check if it's a USE command
    const useMatch = command.match(/^\s*USE\s+(\S+)\s*;?\s*$/i);
    if (useMatch) {
      const newDatabase = useMatch[1].replace(/[`"']/g, ''); // Remove quotes if any
      setCurrentDatabase(newDatabase);
      appendToTerminal({
        type: 'result',
        content: `Database changed to: ${newDatabase}`,
      });
      showPrompt();
      return;
    }

    setIsExecuting(true);
    const startTime = Date.now();

    try {
      const response = await executeSQL({
        serverId: selectedServerId,
        query: command,
        limit: 100,
        currentDatabase: currentDatabase || undefined,
      });

      const executionTime = Date.now() - startTime;

      if (response.success) {
        // Check if response has a message (for commands like USE)
        if (response.message) {
          // Check if it's a database change message
          const dbChangeMatch = response.message.match(/Database changed to: (.+)/);
          if (dbChangeMatch) {
            setCurrentDatabase(dbChangeMatch[1]);
          }
          appendToTerminal({
            type: 'result',
            content: response.message,
            executionTime: response.executionTime || executionTime,
          });
        } else if (response.data && response.data.length > 0) {
          const result = formatQueryResult(response.data, response.fields || [], response.rowCount || 0);
          appendToTerminal({
            type: 'result',
            content: result,
            executionTime: response.executionTime || executionTime,
            rowCount: response.rowCount,
          });
        } else {
          appendToTerminal({
            type: 'result',
            content: 'Query executed successfully',
            executionTime: response.executionTime || executionTime,
            rowCount: 0,
          });
        }
      } else {
        appendToTerminal({
          type: 'error',
          content: response.error || 'Query execution failed',
        });
      }
    } catch (error: any) {
      appendToTerminal({
        type: 'error',
        content: error.message || 'Network error',
      });
    } finally {
      setIsExecuting(false);
      showPrompt();
    }
  };

  // Visual mode functions
  const executeVisualQuery = async () => {
    if (!selectedServerId) {
      setQueryError('Please select a database connection first');
      return;
    }

    if (!sqlQuery.trim()) {
      setQueryError('Please enter a SQL query');
      return;
    }

    setIsExecuting(true);
    setQueryError('');
    setQueryResult(null);
    const startTime = Date.now();

    try {
      const response = await executeSQL({
        serverId: selectedServerId,
        query: sqlQuery,
        limit: 1000,
        currentDatabase: currentDatabase || undefined,
      });

      const executionTime = Date.now() - startTime;

      if (response.success) {
        setQueryResult({
          data: response.data || [],
          fields: response.fields || [],
          rowCount: response.rowCount || 0,
          executionTime: response.executionTime || executionTime,
        });

        // Add to history
        if (!queryHistory.includes(sqlQuery)) {
          setQueryHistory(prev => [sqlQuery, ...prev.slice(0, 9)]);
        }
      } else {
        setQueryError(response.error || 'Query execution failed');
      }
    } catch (error: any) {
      setQueryError(error.message || 'Network error occurred');
    } finally {
      setIsExecuting(false);
    }
  };

  const formatQueryResult = (data: any[], fields: any[], rowCount: number): string => {
    if (!data || data.length === 0) {
      return `(0 rows)`;
    }

    // Calculate column widths
    const columnWidths: number[] = [];
    fields?.forEach((field: any, index: number) => {
      const headerLength = field.name.length;
      const maxDataLength = Math.max(
        ...data.slice(0, 100).map((row: any) => {
          const value = row[field.name];
          return value !== null ? String(value).length : 4;
        })
      );
      columnWidths[index] = Math.max(headerLength, maxDataLength, 4) + 2;
    });

    let output = '';

    // Top border
    output += '+';
    columnWidths.forEach(width => {
      output += '-'.repeat(width) + '+';
    });
    output += '\n';

    // Headers
    output += '|';
    fields?.forEach((field: any, index: number) => {
      const padded = ` ${field.name}`.padEnd(columnWidths[index]);
      output += padded + '|';
    });
    output += '\n';

    // Header separator
    output += '+';
    columnWidths.forEach(width => {
      output += '-'.repeat(width) + '+';
    });
    output += '\n';

    // Data rows
    data.slice(0, 100).forEach((row: any) => {
      output += '|';
      fields?.forEach((field: any, index: number) => {
        const value = row[field.name];
        const displayValue = value !== null ? String(value) : 'NULL';
        const padded = ` ${displayValue}`.padEnd(columnWidths[index]);
        output += padded + '|';
      });
      output += '\n';
    });

    // Bottom border
    output += '+';
    columnWidths.forEach(width => {
      output += '-'.repeat(width) + '+';
    });
    output += '\n';

    // Row count
    output += `(${rowCount} row${rowCount !== 1 ? 's' : ''})`;

    return output;
  };

  const handleTerminalKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();

      // Check for multiline SQL statements
      const trimmedCommand = currentCommand.trim();

      // If the command ends with backslash, continue on next line
      if (trimmedCommand.endsWith('\\') && !trimmedCommand.endsWith('\\\\')) {
        setMultilineBuffer([...multilineBuffer, trimmedCommand.slice(0, -1)]);
        setIsMultiline(true);
        appendToTerminal({
          type: 'command',
          content: currentCommand,
        });
        setCurrentCommand('');
        return;
      }

      // Combine multiline command if exists
      const fullCommand = isMultiline
        ? [...multilineBuffer, trimmedCommand].join(' ')
        : trimmedCommand;

      if (fullCommand) {
        // Display the command
        appendToTerminal({
          type: 'command',
          content: currentCommand,
        });

        // Add to history
        setCommandBuffer(prev => [...prev, fullCommand]);

        // Execute
        executeTerminalCommand(fullCommand);

        // Reset state
        setCurrentCommand('');
        setHistoryIndex(-1);
        setMultilineBuffer([]);
        setIsMultiline(false);
      } else {
        showPrompt();
      }
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (commandBuffer.length > 0) {
        const newIndex = historyIndex < commandBuffer.length - 1 ? historyIndex + 1 : historyIndex;
        setHistoryIndex(newIndex);
        setCurrentCommand(commandBuffer[commandBuffer.length - 1 - newIndex]);
      }
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (historyIndex > 0) {
        const newIndex = historyIndex - 1;
        setHistoryIndex(newIndex);
        setCurrentCommand(commandBuffer[commandBuffer.length - 1 - newIndex]);
      } else if (historyIndex === 0) {
        setHistoryIndex(-1);
        setCurrentCommand('');
      }
    } else if (e.key === 'l' && e.ctrlKey) {
      e.preventDefault();
      clearTerminal();
    } else if (e.key === 'c' && e.ctrlKey) {
      e.preventDefault();
      if (currentCommand) {
        setCurrentCommand('');
        setMultilineBuffer([]);
        setIsMultiline(false);
        appendToTerminal({
          type: 'command',
          content: currentCommand + '^C',
        });
        showPrompt();
      }
    }
  };

  const handleTerminalClick = () => {
    // Focus the hidden input when clicking anywhere in the terminal
    if (hiddenInputRef.current && !isExecuting) {
      hiddenInputRef.current.focus();
    }
  };

  // Export functions
  const exportToCSV = () => {
    if (!queryResult || !queryResult.data || queryResult.data.length === 0) return;

    const headers = queryResult.fields.map((f: any) => f.name).join(',');
    const rows = queryResult.data.map((row: any) =>
      queryResult.fields.map((f: any) => {
        const value = row[f.name];
        if (value === null) return '';
        if (typeof value === 'string' && value.includes(',')) {
          return `"${value.replace(/"/g, '""')}"`;
        }
        return value;
      }).join(',')
    );

    const csv = [headers, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `query_results_${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.csv`;
    link.click();

    // Audit log
    logExport('csv', queryResult.rowCount);
  };

  const exportToJSON = () => {
    if (!queryResult || !queryResult.data) return;

    const json = JSON.stringify(queryResult.data, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `query_results_${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.json`;
    link.click();

    // Audit log
    logExport('json', queryResult.rowCount);
  };

  const exportToSQL = () => {
    if (!queryResult || !queryResult.data || queryResult.data.length === 0) return;

    // Generate INSERT statements
    const tableName = 'exported_data'; // You might want to parse this from the query
    const columns = queryResult.fields.map((f: any) => f.name);

    const inserts = queryResult.data.map((row: any) => {
      const values = columns.map((col: string) => {
        const value = row[col];
        if (value === null) return 'NULL';
        if (typeof value === 'number') return value;
        return `'${String(value).replace(/'/g, "''")}'`;
      });
      return `INSERT INTO ${tableName} (${columns.join(', ')}) VALUES (${values.join(', ')});`;
    });

    const sql = inserts.join('\n');
    const blob = new Blob([sql], { type: 'text/plain' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `query_results_${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.sql`;
    link.click();

    // Audit log
    logExport('sql', queryResult.rowCount);
  };

  const logExport = async (format: string, rowCount: number) => {
    try {
      await api.post('/audit/export', {
        serverId: selectedServerId,
        database: currentDatabase,
        format: format,
        rowCount: rowCount,
        query: sqlQuery,
        exportType: 'query_results'
      });
    } catch (error) {
      console.error('Failed to log export:', error);
    }
  };

  const handleDumpRequest = async () => {
    if (!selectedServerId || selectedTables.length === 0) {
      alert('Please select at least one table to dump');
      return;
    }

    try {
      // Request dump with audit and notification
      const response = await api.post('/sql/dump', {
        serverId: selectedServerId,
        database: currentDatabase,
        tables: selectedTables,
        format: dumpFormat,
        reason: 'Manual dump request from SQL Shell'
      });

      if (response.data.requiresApproval) {
        alert('Dump request submitted for approval. You will be notified when approved.');
      } else if (response.data.url) {
        // Download the dump
        window.open(response.data.url, '_blank');
      }

      setDumpDialogOpen(false);
      setSelectedTables([]);
    } catch (error: any) {
      alert(`Dump failed: ${error.response?.data?.error || error.message}`);
    }
  };

  const loadTables = async () => {
    if (!selectedServerId || !currentDatabase) return;

    try {
      const response = await executeSQL({
        serverId: selectedServerId,
        query: "SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' OR table_schema = DATABASE()",
        limit: 1000,
        currentDatabase: currentDatabase
      });

      if (response.success && response.data) {
        const tables = response.data.map((row: any) => row.table_name || row.TABLE_NAME);
        setDumpTables(tables);
      }
    } catch (error) {
      console.error('Failed to load tables:', error);
    }
  };

  const renderTerminalContent = () => {
    let displayContent = '';
    let currentLine = '';

    terminalContent.forEach((entry, index) => {
      if (entry.type === 'prompt') {
        currentLine = entry.content;
      } else if (entry.type === 'command') {
        displayContent += currentLine + entry.content + '\n';
        currentLine = '';
      } else {
        if (currentLine) {
          displayContent += currentLine + '\n';
          currentLine = '';
        }
        displayContent += entry.content;
        if (entry.executionTime) {
          displayContent += ` (${entry.executionTime}ms)`;
        }
        displayContent += '\n';
      }
    });

    // Add current input line
    if (currentLine || terminalContent.length === 0 || terminalContent[terminalContent.length - 1].type !== 'prompt') {
      const serverName = servers.find(s => s.id === selectedServerId)?.name || 'dbmanager';
      const prompt = currentDatabase ? `${serverName}:${currentDatabase}` : serverName;
      currentLine = isMultiline ? '... ' : `${prompt}> `;
    }

    displayContent += currentLine + currentCommand;

    return displayContent;
  };

  const renderServerInfo = () => {
    const server = servers.find(s => s.id === selectedServerId);
    if (!server) return null;

    return (
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
        <Chip
          icon={<StorageIcon />}
          label={server.name}
          size="small"
          color="primary"
        />
        <Chip
          label={server.type}
          size="small"
          variant="outlined"
        />
        {currentDatabase && (
          <Chip
            icon={<DatabaseIcon />}
            label={currentDatabase}
            size="small"
            color="secondary"
          />
        )}
      </Box>
    );
  };

  return (
    <Box sx={{
      position: 'fixed',
      top: 64,
      left: 280, // Ajustado para não sobrepor o sidebar
      right: 0,
      bottom: 0,
      p: 2,
      display: 'flex',
      flexDirection: 'column'
    }}>
      <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
        <TerminalIcon />
        Terminal SQL
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Execute consultas SQL diretamente em seus bancos de dados com auditoria completa
      </Typography>

      <Paper sx={{
        flex: 1,
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden'
      }}>
        <Box sx={{ borderBottom: 1, borderColor: 'divider', p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Tabs value={activeTab} onChange={(e, v) => {
            setActiveTab(v);
            if (v === 1 && selectedServerId) {
              // Initialize terminal when switching to it
              if (terminalContent.length === 0) {
                const server = servers.find(s => s.id === selectedServerId);
                if (server) {
                  appendToTerminal({
                    type: 'info',
                    content: `Connected to ${server.name} (${server.type})`,
                  });
                }
                showPrompt();
              }
            }
          }}>
            <Tab
              icon={<CodeIcon />}
              label="SQL Editor"
              iconPosition="start"
              sx={{ minHeight: 48 }}
            />
            <Tab
              icon={<TerminalIcon />}
              label="SQL Shell"
              iconPosition="start"
              sx={{ minHeight: 48 }}
            />
          </Tabs>

          <Box sx={{ minWidth: 250 }}>
            <BasicDropdown
              value={selectedServerId}
              onChange={connectToServer}
              options={[
                { value: '', label: 'Select a server...' },
                ...servers.map((server) => ({
                  value: server.id,
                  label: `${server.name} (${server.type})`,
                  icon: <StorageIcon sx={{ fontSize: 20 }} />
                }))
              ]}
              size="small"
            />
          </Box>

          {/* Dump Database Button - Only for admins */}
          {selectedServerId && currentDatabase && (
            <Box>
              <Button
                size="small"
                startIcon={<SecurityIcon />}
                onClick={() => {
                  loadTables();
                  setDumpDialogOpen(true);
                }}
                variant="contained"
                color="warning"
                sx={{ mr: 2 }}
              >
                Dump Database
              </Button>
            </Box>
          )}
        </Box>

        {/* SQL Editor Tab */}
        {activeTab === 0 && (
          <Box sx={{
            flex: 1,
            p: 2,
            overflowY: 'auto',
            overflowX: 'hidden'
          }}>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                {selectedServerId && renderServerInfo()}
              </Grid>

              <Grid item xs={12} md={3}>
                <Card variant="outlined" sx={{ overflow: 'visible', position: 'relative' }}>
                  <CardContent sx={{ overflow: 'visible', position: 'relative' }}>
                    <Typography variant="h6" gutterBottom>
                      <DatabaseIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
                      Database Connection
                    </Typography>
                    {selectedServerId ? (
                      <Box>
                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          {servers.find(s => s.id === selectedServerId)?.name}
                        </Typography>

                        <Box sx={{ mt: 2, position: 'relative', zIndex: 1 }}>
                          <BasicDropdown
                            value={currentDatabase || ''}
                            onChange={setCurrentDatabase}
                            options={
                              databases.length === 0
                                ? [{ value: '', label: 'Loading databases...' }]
                                : [
                                    { value: '', label: 'Select a database...' },
                                    ...databases.map((db) => ({
                                      value: db,
                                      label: db,
                                      icon: <DatabaseIcon sx={{ fontSize: 18 }} />
                                    }))
                                  ]
                            }
                            label="Database"
                            size="small"
                            fullWidth
                          />
                        </Box>
                      </Box>
                    ) : (
                      <Alert severity="info">Select a server connection first</Alert>
                    )}
                  </CardContent>
                </Card>

                <Card variant="outlined" sx={{ mt: 2 }}>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      <HistoryIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
                      Query History
                    </Typography>
                    {queryHistory.length > 0 ? (
                      <Box sx={{ maxHeight: 200, overflowY: 'auto' }}>
                        {queryHistory.map((query, index) => (
                          <Box
                            key={index}
                            sx={{
                              p: 1,
                              borderRadius: 1,
                              cursor: 'pointer',
                              '&:hover': { bgcolor: 'action.hover' },
                            }}
                            onClick={() => setSqlQuery(query)}
                          >
                            <Typography
                              variant="body2"
                              sx={{
                                fontFamily: 'monospace',
                                fontSize: '0.85rem',
                                whiteSpace: 'nowrap',
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                              }}
                            >
                              {query}
                            </Typography>
                          </Box>
                        ))}
                      </Box>
                    ) : (
                      <Typography variant="body2" color="text.secondary">
                        No queries in history
                      </Typography>
                    )}
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12} md={9}>
                <Card variant="outlined">
                  <CardContent>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                      <Typography variant="h6">
                        <CodeIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
                        SQL Query Editor
                      </Typography>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <Button
                          variant="contained"
                          startIcon={<PlayArrowIcon />}
                          onClick={executeVisualQuery}
                          disabled={isExecuting || !selectedServerId}
                        >
                          Execute Query
                        </Button>
                        <IconButton
                          onClick={() => {
                            setSqlQuery('');
                            setQueryResult(null);
                            setQueryError('');
                          }}
                          size="small"
                        >
                          <ClearIcon />
                        </IconButton>
                      </Box>
                    </Box>

                    <TextField
                      fullWidth
                      multiline
                      rows={8}
                      value={sqlQuery}
                      onChange={(e) => setSqlQuery(e.target.value)}
                      placeholder="Enter your SQL query here..."
                      variant="outlined"
                      sx={{
                        '& .MuiInputBase-root': {
                          fontFamily: 'monospace',
                          fontSize: '14px',
                        },
                      }}
                      onKeyDown={(e) => {
                        if (e.ctrlKey && e.key === 'Enter') {
                          executeVisualQuery();
                        }
                      }}
                    />
                    <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                      Press Ctrl+Enter to execute
                    </Typography>
                  </CardContent>
                </Card>

                {queryError && (
                  <Alert severity="error" sx={{ mt: 2 }}>
                    {queryError}
                  </Alert>
                )}

                {queryResult && (
                  <Card variant="outlined" sx={{ mt: 2 }}>
                    <CardContent>
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                        <Typography variant="h6">
                          <TableIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
                          Query Results
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center' }}>
                          <ToggleButtonGroup
                            value={outputFormat}
                            exclusive
                            onChange={(e, newFormat) => newFormat && setOutputFormat(newFormat)}
                            size="small"
                          >
                            <ToggleButton value="table">
                              <TableIcon sx={{ mr: 0.5, fontSize: 18 }} />
                              Table
                            </ToggleButton>
                            <ToggleButton value="terminal">
                              <TerminalIcon sx={{ mr: 0.5, fontSize: 18 }} />
                              Terminal
                            </ToggleButton>
                          </ToggleButtonGroup>

                          <Button
                            size="small"
                            startIcon={<ExportIcon />}
                            onClick={(e) => setExportAnchorEl(e.currentTarget)}
                            variant="outlined"
                          >
                            Export
                          </Button>

                          <Chip
                            icon={<DataObjectIcon />}
                            label={`${queryResult.rowCount} rows`}
                            size="small"
                            color="primary"
                          />
                          <Chip
                            icon={<TimerIcon />}
                            label={`${queryResult.executionTime}ms`}
                            size="small"
                            color="success"
                          />
                        </Box>
                      </Box>

                      {queryResult.data.length > 0 ? (
                        outputFormat === 'table' ? (
                          <TableContainer sx={{ maxHeight: 400, overflowY: 'auto' }}>
                            <Table size="small" stickyHeader>
                              <TableHead>
                                <TableRow>
                                  {queryResult.fields.map((field: any, index: number) => (
                                    <TableCell key={index} sx={{ fontWeight: 'bold', bgcolor: 'grey.100' }}>
                                      {field.name}
                                    </TableCell>
                                  ))}
                                </TableRow>
                              </TableHead>
                              <TableBody>
                                {queryResult.data.map((row: any, rowIndex: number) => (
                                  <TableRow key={rowIndex} hover>
                                    {queryResult.fields.map((field: any, cellIndex: number) => (
                                      <TableCell key={cellIndex}>
                                        {row[field.name] !== null ? String(row[field.name]) :
                                          <span style={{ color: '#999', fontStyle: 'italic' }}>NULL</span>}
                                      </TableCell>
                                    ))}
                                  </TableRow>
                                ))}
                              </TableBody>
                            </Table>
                          </TableContainer>
                        ) : (
                          <Box
                            sx={{
                              bgcolor: '#1e1e1e',
                              color: '#d4d4d4',
                              p: 2,
                              borderRadius: 1,
                              fontFamily: 'monospace',
                              fontSize: '13px',
                              whiteSpace: 'pre',
                              overflowX: 'auto',
                              maxHeight: 400,
                              overflowY: 'auto'
                            }}
                          >
                            {formatQueryResult(queryResult.data, queryResult.fields, queryResult.rowCount)}
                          </Box>
                        )
                      ) : (
                        <Typography variant="body2" color="text.secondary">
                          No data returned
                        </Typography>
                      )}
                    </CardContent>
                  </Card>
                )}
              </Grid>
            </Grid>
          </Box>
        )}

        {/* SQL Shell Tab - Integrated Terminal */}
        {activeTab === 1 && (
          <Box sx={{
            flex: 1,
            display: 'flex',
            flexDirection: 'column',
            overflow: 'hidden',
            bgcolor: '#1e1e1e',
          }}>
            {/* Terminal Header */}
            <Box sx={{
              p: 1.5,
              bgcolor: '#2d2d2d',
              color: '#d4d4d4',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              borderBottom: '1px solid #3e3e3e'
            }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Typography variant="body2" sx={{ fontFamily: 'monospace' }}>
                  SQL Shell
                </Typography>
                {selectedServerId && renderServerInfo()}
              </Box>

              <Box sx={{ display: 'flex', gap: 1 }}>
                <Tooltip title="Clear terminal (Ctrl+L)">
                  <IconButton onClick={clearTerminal} size="small" sx={{ color: '#d4d4d4' }}>
                    <ClearIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              </Box>
            </Box>

            {/* Terminal Body - Single integrated area */}
            <Box
              ref={terminalRef}
              onClick={handleTerminalClick}
              sx={{
                flex: 1,
                bgcolor: '#1e1e1e',
                color: '#d4d4d4',
                p: 2,
                fontFamily: 'Consolas, "Courier New", monospace',
                fontSize: '14px',
                lineHeight: 1.5,
                overflowY: 'auto',
                overflowX: 'hidden',
                cursor: 'text',
                position: 'relative',
                '&::after': isExecuting ? {} : {
                  content: '"_"',
                  animation: 'blink 1s infinite',
                  position: 'absolute',
                  color: '#d4d4d4',
                },
                '@keyframes blink': {
                  '0%, 50%': { opacity: 1 },
                  '51%, 100%': { opacity: 0 },
                },
              }}
            >
              <pre style={{ margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                {renderTerminalContent()}
              </pre>
            </Box>

            {/* Hidden input for capturing keyboard events */}
            <input
              ref={hiddenInputRef}
              type="text"
              value={currentCommand}
              onChange={(e) => setCurrentCommand(e.target.value)}
              onKeyDown={handleTerminalKeyDown}
              disabled={isExecuting}
              style={{
                position: 'absolute',
                left: '-9999px',
                width: '1px',
                height: '1px',
                opacity: 0,
              }}
              autoFocus
            />

            {/* Terminal Footer */}
            <Box sx={{
              p: 1,
              bgcolor: '#2d2d2d',
              color: '#888',
              fontSize: '11px',
              fontFamily: 'monospace',
              display: 'flex',
              gap: 2,
              borderTop: '1px solid #3e3e3e'
            }}>
              <span>HELP - Show commands</span>
              <span>|</span>
              <span>Ctrl+C - Cancel</span>
              <span>|</span>
              <span>Ctrl+L - Clear</span>
              <span>|</span>
              <span>↑/↓ - History</span>
              <span>|</span>
              <span>Tab - Autocomplete</span>
            </Box>
          </Box>
        )}
      </Paper>

      {/* Export Menu */}
      <Menu
        anchorEl={exportAnchorEl}
        open={Boolean(exportAnchorEl)}
        onClose={() => setExportAnchorEl(null)}
      >
        <MenuItemMUI onClick={() => { exportToCSV(); setExportAnchorEl(null); }}>
          <ListItemIcon>
            <DownloadIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Export as CSV</ListItemText>
        </MenuItemMUI>
        <MenuItemMUI onClick={() => { exportToJSON(); setExportAnchorEl(null); }}>
          <ListItemIcon>
            <DownloadIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Export as JSON</ListItemText>
        </MenuItemMUI>
        <MenuItemMUI onClick={() => { exportToSQL(); setExportAnchorEl(null); }}>
          <ListItemIcon>
            <DownloadIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Export as SQL</ListItemText>
        </MenuItemMUI>
      </Menu>

      {/* Dump Dialog */}
      <Dialog
        open={dumpDialogOpen}
        onClose={() => setDumpDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <WarningIcon color="warning" />
          Database Dump Request
        </DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ mb: 2 }}>
            <Alert severity="warning" sx={{ mb: 2 }}>
              <strong>Warning:</strong> Database dumps contain sensitive data and are monitored.
              This action will be logged and notifications will be sent to administrators.
            </Alert>
            Dumping database: <strong>{currentDatabase}</strong>
          </DialogContentText>

          <TextField
            fullWidth
            select
            label="Format"
            value={dumpFormat}
            onChange={(e) => setDumpFormat(e.target.value as 'sql' | 'csv')}
            sx={{ mb: 2 }}
            SelectProps={{
              native: true,
            }}
          >
            <option value="sql">SQL (.sql)</option>
            <option value="csv">CSV (.csv)</option>
          </TextField>

          <Box sx={{ mb: 2 }}>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>Select Tables</Typography>
            <Paper variant="outlined" sx={{ maxHeight: 200, overflow: 'auto', p: 1 }}>
              <FormControlLabel
                control={
                  <Checkbox
                    checked={selectedTables.length === dumpTables.length && dumpTables.length > 0}
                    indeterminate={selectedTables.length > 0 && selectedTables.length < dumpTables.length}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedTables(dumpTables);
                      } else {
                        setSelectedTables([]);
                      }
                    }}
                  />
                }
                label="Select All Tables"
                sx={{ borderBottom: 1, borderColor: 'divider', pb: 1, mb: 1, width: '100%' }}
              />
              {dumpTables.map((table) => (
                <FormControlLabel
                  key={table}
                  control={
                    <Checkbox
                      checked={selectedTables.includes(table)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedTables([...selectedTables, table]);
                        } else {
                          setSelectedTables(selectedTables.filter(t => t !== table));
                        }
                      }}
                    />
                  }
                  label={table}
                  sx={{ display: 'block', ml: 2 }}
                />
              ))}
            </Paper>
            {selectedTables.length > 0 && (
              <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                {selectedTables.length} table{selectedTables.length !== 1 ? 's' : ''} selected
              </Typography>
            )}
          </Box>

          <Alert severity="info" sx={{ mt: 2 }}>
            • Large dumps may require approval from an administrator<br />
            • You will receive an email when the dump is ready<br />
            • Dumps are automatically deleted after 24 hours
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDumpDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={handleDumpRequest}
            variant="contained"
            color="warning"
            startIcon={<SecurityIcon />}
          >
            Request Dump
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default SQLShellPage;