import React, { useEffect, useState } from 'react';
import {
  Grid,
  Typography,
  Avatar,
  Box,
  Chip,
  Paper,
  alpha,
  styled,
  useTheme,
  Collapse,
  Card,
  Button,
  TextField,
  Divider,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormHelperText
} from '@mui/material';
import {
  ErrorOutline as ErrorIcon,
  Security as SecurityIcon,
  Add as AddIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps } from '../../types';
import StepLayout from '../shared/StepLayout';
// import { UserDropdown } from '../../../common';


// SelectedCard removido - não utilizado

// ErrorContainer removido - não utilizado

// NextButton removido - não utilizado

/**
 * Component for the user selection step
 */
const UserStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t } = useTranslation(['requests', 'common', 'error']);
  const [isNewServiceUser, setIsNewServiceUser] = useState(false);
  const [serviceUserName, setServiceUserName] = useState('');
  const [serviceUserDescription, setServiceUserDescription] = useState('');
  const [serviceUserError, setServiceUserError] = useState('');
  const theme = useTheme();

  // Check if user is already selected
  useEffect(() => {
    // If we only have one user, select them automatically
    if (state.users.length === 1 && !state.userId) {
      dispatch({ type: 'SET_USER', payload: state.users[0].id });
    }
  }, [state.users, state.userId, dispatch]);
  
  // Debug: Log users in state
  useEffect(() => {
    console.log('UserStep - users in state:', state.users);
    console.log('UserStep - users count:', state.users.length);
    state.users.forEach(user => {
      console.log(`User: ${user.username}, is_service_user: ${(user as any).is_service_user}`);
    });
  }, [state.users]);

  // Auto-select functionality remains, but removed scroll behavior
  // since we no longer show the selected user card

  // Validate service user name
  const validateServiceUserName = (name: string): string => {
    if (!name || name.trim().length === 0) {
      return t('validation:required') as string;
    }
    
    // Check for invalid characters (dots, spaces, special characters)
    const invalidChars = /[-.\s@#$%^&*()+=[\]{}\\|;:'",<>/?]/;
    if (invalidChars.test(name)) {
      return t('validation:serviceUserInvalidChars', 'Nome de usuário só pode conter letras, números e underscore (_)') as string;
    }
    
    // Check if starts with number
    if (/^[0-9]/.test(name)) {
      return t('validation:serviceUserStartWithLetter', 'Nome de usuário deve começar com letra ou underscore') as string;
    }
    
    // Check minimum length
    if (name.length < 3) {
      return t('validation:serviceUserMinLength', 'Nome de usuário deve ter no mínimo 3 caracteres') as string;
    }
    
    // Check maximum length
    if (name.length > 30) {
      return t('validation:serviceUserMaxLength', 'Nome de usuário não pode exceder 30 caracteres') as string;
    }
    
    return '';
  };

  // Handler for user selection
  const handleUserSelect = (userId: string) => {
    console.log("Selecting user:", userId);
    
    // Check if "new service user" was selected
    if (userId === 'NEW_SERVICE_USER') {
      setIsNewServiceUser(true);
      dispatch({ type: 'SET_USER', payload: userId });
      return;
    }
    
    // Reset new service user state if different option selected
    setIsNewServiceUser(false);
    setServiceUserName('');
    setServiceUserDescription('');
    setServiceUserError('');
    
    // Clear any previous error
    if (state.errors.userId) {
      dispatch({
        type: 'SET_ERRORS',
        payload: { userId: '' }
      });
    }
    
    dispatch({ type: 'SET_USER', payload: userId });
  };
  
  // Handler for service user name change
  const handleServiceUserNameChange = (input: string) => {
    // Filtrar caracteres inválidos em tempo real
    const filteredName = input.replace(/[-.\s@#$%^&*()+=\[\]{}\\|;:'",<>/?]/g, '');
    
    // Se o input é diferente do filtrado, o usuário tentou digitar um caractere inválido
    if (input !== filteredName) {
      // Definir erro temporário sobre caractere inválido
      setServiceUserError(t('validation:invalidCharacterEntered', 'Caractere inválido! Use apenas letras, números e underscore (_)') as string);
      // Limpar erro após 3 segundos
      setTimeout(() => {
        const currentError = validateServiceUserName(filteredName);
        setServiceUserError(currentError);
      }, 3000);
    }
    
    setServiceUserName(filteredName);
    const error = validateServiceUserName(filteredName);
    
    // Só atualizar erro se não for sobre caractere inválido
    if (input === filteredName) {
      setServiceUserError(error);
    }
    
    // Update state with service user info
    if (!error && filteredName) {
      dispatch({ 
        type: 'SET_SERVICE_USER_INFO', 
        payload: { 
          isServiceUser: true,
          serviceUserName: filteredName,
          serviceUserDescription: serviceUserDescription
        } 
      });
    } else {
      // Clear service user info if there's an error
      dispatch({ 
        type: 'SET_SERVICE_USER_INFO', 
        payload: { 
          isServiceUser: true,
          serviceUserName: '',
          serviceUserDescription: serviceUserDescription
        } 
      });
    }
  };
  
  // Handler for service user description change
  const handleServiceUserDescriptionChange = (description: string) => {
    setServiceUserDescription(description);
    
    if (!serviceUserError) {
      dispatch({ 
        type: 'SET_SERVICE_USER_INFO', 
        payload: { 
          isServiceUser: true,
          serviceUserName: serviceUserName,
          serviceUserDescription: description
        } 
      });
    }
  };

  // Validação customizada para o step
  useEffect(() => {
    if (state.userId === 'NEW_SERVICE_USER' && isNewServiceUser) {
      // Don't set userId errors for service user validation
      // The validation is handled by the serviceUserError state
      if (!serviceUserName) {
        setServiceUserError(t('validation:required') as string);
      }
    }
  }, [serviceUserName, isNewServiceUser, state.userId, t]);

  // Generate initials from name for avatar
  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map(part => part.charAt(0).toUpperCase())
      .slice(0, 2)
      .join('');
  };

  // Colors for avatars
  const getAvatarColor = (name: string) => {
    const colors = [
      '#1976d2', '#388e3c', '#d32f2f', '#f57c00', '#7b1fa2',
      '#0288d1', '#689f38', '#e64a19', '#fbc02d', '#512da8'
    ];
    const hash = name.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return colors[hash % colors.length];
  };

  return (
    <StepLayout
      title={String(t('wizard.steps.user'))}
      subtitle={String(t('wizard.userStepSubtitle'))}
      icon="user"
    >
      <Grid container spacing={3}>
        {state.users.length === 0 ? (
          <Grid item xs={12}>
            <Box 
              sx={{
                display: 'flex',
                alignItems: 'center',
                p: 2,
                bgcolor: alpha(theme.palette.error.light, 0.1),
                color: theme.palette.error.main,
                borderRadius: 2,
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
              }}
            >
              <ErrorIcon sx={{ mr: 1 }} />
              <Typography>
                {t('wizard.error.noUsersAvailable')}
              </Typography>
            </Box>
          </Grid>
        ) : (
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom sx={{ mb: 2, fontWeight: 500 }}>
              {t('wizard.selectUser')}
            </Typography>
            
            <FormControl 
              fullWidth 
              error={!!state.errors.userId && !isNewServiceUser}
            >
              <InputLabel>{t('form.user')}</InputLabel>
              <Select
                value={state.userId || ''}
                onChange={(e) => handleUserSelect(e.target.value)}
                label={t('form.user')}
                MenuProps={{
                  disablePortal: true,
                  PaperProps: {
                    style: {
                      maxHeight: 400,
                    },
                  },
                }}
              >
                <MenuItem value="NEW_SERVICE_USER">
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Avatar sx={{ width: 32, height: 32, bgcolor: 'success.main' }}>
                      <AddIcon fontSize="small" />
                    </Avatar>
                    <Box>
                      <Typography variant="body2">{t('newServiceUser')}</Typography>
                      <Typography variant="caption" color="text.secondary">
                        {t('newServiceUserDescription')}
                      </Typography>
                    </Box>
                  </Box>
                </MenuItem>
                {state.users.map((user) => (
                  <MenuItem key={user.id} value={user.id}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <Avatar 
                        sx={{ 
                          width: 32, 
                          height: 32, 
                          bgcolor: (user as any).is_service_user ? 'info.main' : getAvatarColor(user.username) 
                        }}
                      >
                        {(user as any).is_service_user ? (
                          <SecurityIcon fontSize="small" />
                        ) : (
                          getInitials(user.username)
                        )}
                      </Avatar>
                      <Box>
                        <Typography variant="body2">{user.username}</Typography>
                        {user.email && (
                          <Typography variant="caption" color="text.secondary">
                            {user.email}
                          </Typography>
                        )}
                      </Box>
                    </Box>
                  </MenuItem>
                ))}
              </Select>
              {state.errors.userId && !isNewServiceUser && (
                <FormHelperText>{state.errors.userId}</FormHelperText>
              )}
            </FormControl>
            
            {/* New service user fields */}
            <Collapse in={isNewServiceUser}>
              <Box sx={{ mt: 3, p: 2, bgcolor: alpha(theme.palette.primary.main, 0.05), borderRadius: 2 }}>
                <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 600, mb: 2 }}>
                  {t('serviceUserDetails')}
                </Typography>
                
                <TextField
                  fullWidth
                  label={t('serviceUserName')}
                  value={serviceUserName}
                  onChange={(e) => handleServiceUserNameChange(e.target.value)}
                  error={!!serviceUserError}
                  helperText={
                    serviceUserError || 
                    (t('serviceUserNameHelp', 'Use apenas letras, números e underscore. Ex: api_user, app_service') as string)
                  }
                  margin="normal"
                  variant="outlined"
                  inputProps={{
                    maxLength: 30,
                    pattern: '^[a-zA-Z_][a-zA-Z0-9_]*$',
                    autoComplete: 'off',
                    spellCheck: false
                  }}
                  FormHelperTextProps={{
                    sx: {
                      color: serviceUserError ? 'error.main' : 'text.secondary',
                      fontWeight: serviceUserError ? 500 : 400
                    }
                  }}
                />
                
                <TextField
                  fullWidth
                  label={t('serviceUserDescription')}
                  value={serviceUserDescription}
                  onChange={(e) => handleServiceUserDescriptionChange(e.target.value)}
                  helperText={t('serviceUserDescriptionHelp')}
                  margin="normal"
                  variant="outlined"
                  multiline
                  rows={2}
                  inputProps={{
                    maxLength: 200
                  }}
                />
              </Box>
            </Collapse>
            
          </Grid>
        )}
      </Grid>
    </StepLayout>
  );
};

export default React.memo(UserStep);