import React from 'react';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  Chip,
  Avatar,
  Button
} from '@mui/material';
import {
  Person as PersonIcon,
  Storage as StorageIcon,
  Dataset as DatabaseIcon,
  TableChart as TableChartIcon,
  ManageAccounts as ManageAccountsIcon,
  Description as DescriptionIcon,
  Check as CheckIcon,
  Edit as EditIcon,
  Folder as FolderIcon,
  Security as SecurityIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps, DatabaseType, AccessType } from '../../types';
import StepLayout from '../shared/StepLayout';

/**
 * Componente para a etapa de revisão da solicitação
 */
const ReviewStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t } = useTranslation(['requests', 'common', 'error']);

  // Navegar para uma etapa específica para edição
  const navigateToStep = (step: number) => {
    dispatch({ type: 'SET_CURRENT_STEP', payload: step });
  };

  // Formatar o tipo de acesso
  const formatAccessType = (type: AccessType) => {
    switch (type) {
      case AccessType.READ:
        return t('access:readOnly');
      case AccessType.READWRITE:
        return t('access:readWrite');
      case AccessType.ADMIN:
        return t('access:admin');
      default:
        return String(type);
    }
  };

  // Obter o usuário selecionado ou informações do service user
  const selectedUser = state.userId === 'NEW_SERVICE_USER' && state.isServiceUser
    ? {
        id: 'NEW_SERVICE_USER',
        username: state.serviceUserName || t('newServiceUser'),
        email: 'service.user@system',
        is_service_user: true
      }
    : state.users.find(user => user.id === state.userId);
  
  // Obter o servidor selecionado
  const selectedServer = state.servers.find(server => server.id === state.serverId);
  
  // selectedDatabase variável removida - não utilizada
  
  // Gerar as iniciais de um nome para exibir no avatar
  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map(part => part.charAt(0).toUpperCase())
      .slice(0, 2)
      .join('');
  };

  // Cores para os avatares
  const getAvatarColor = (name: string) => {
    const colors = [
      '#1976d2', '#388e3c', '#d32f2f', '#f57c00', '#7b1fa2',
      '#0288d1', '#689f38', '#e64a19', '#fbc02d', '#512da8'
    ];
    const hash = name.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return colors[hash % colors.length];
  };

  return (
    <StepLayout
      title={String(t('wizard.steps.review'))}
      subtitle={String(t('wizard.reviewStepSubtitle'))}
      icon="review"
    >
      {/* Container com scroll para o conteúdo da revisão */}
      <Box sx={{ 
        height: '100%',
        display: 'flex',
        flexDirection: 'column'
      }}>
        {/* Instrução de revisão compacta */}
        <Box 
          sx={{ 
            p: 1, 
            mb: 2, 
            bgcolor: 'info.50', 
            borderRadius: 1,
            border: '1px solid',
            borderColor: 'info.100',
            display: 'flex',
            alignItems: 'center',
            flexShrink: 0
          }}
        >
          <Typography variant="body2" color="info.main" sx={{ fontSize: '0.8rem' }}>
            {t('wizard.reviewInstructions')}
          </Typography>
        </Box>
        
        {/* Container com scroll para o grid */}
        <Box sx={{ 
          flex: 1,
          overflow: 'auto',
          pr: 1,
          '&::-webkit-scrollbar': {
            width: '6px',
          },
          '&::-webkit-scrollbar-track': {
            background: '#f1f1f1',
            borderRadius: '3px',
          },
          '&::-webkit-scrollbar-thumb': {
            background: '#c1c1c1',
            borderRadius: '3px',
            '&:hover': {
              background: '#a8a8a8',
            },
          },
        }}>
          <Grid container spacing={1.5}>
            {/* Informação do Usuário e Servidor numa linha */}
            <Grid item xs={12} sm={6}>
              <Card 
                variant="outlined" 
                sx={{ 
                  height: 'calc(100% - 8px)', 
                  boxShadow: 'none', 
                  borderColor: 'divider' 
                }}
              >
                <CardContent sx={{ p: 1.2 }}>
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.8}>
                    <Typography variant="subtitle2" component="div">
                      <PersonIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                      {t('wizard.userInformation')}
                    </Typography>
                    <Button
                      startIcon={<EditIcon fontSize="small" />}
                      size="small"
                      onClick={() => navigateToStep(0)}
                      sx={{ minWidth: 0, p: '1px 4px', fontSize: '0.7rem' }}
                    >
                      {t('common:edit')}
                    </Button>
                  </Box>
                  
                  {selectedUser && (
                    <Box display="flex" alignItems="center">
                      <Avatar 
                        sx={{ 
                          bgcolor: (selectedUser as any).is_service_user 
                            ? 'info.main' 
                            : getAvatarColor(selectedUser.username),
                          width: 24,
                          height: 24,
                          fontSize: '0.875rem',
                          mr: 1
                        }}
                      >
                        {(selectedUser as any).is_service_user 
                          ? <SecurityIcon sx={{ fontSize: '1rem' }} />
                          : getInitials(selectedUser.username)}
                      </Avatar>
                      <Box display="flex" alignItems="center" gap={0.5}>
                        <Typography variant="body2" noWrap>
                          {selectedUser.username}
                        </Typography>
                        {(selectedUser as any).is_service_user && (
                          <Chip 
                            label={t('serviceUser')} 
                            size="small" 
                            color="info"
                            sx={{ height: 16, fontSize: '0.65rem' }}
                          />
                        )}
                      </Box>
                    </Box>
                  )}
                </CardContent>
              </Card>
            </Grid>
            
            <Grid item xs={12} sm={6}>
              <Card 
                variant="outlined" 
                sx={{ 
                  height: 'calc(100% - 8px)', 
                  boxShadow: 'none', 
                  borderColor: 'divider' 
                }}
              >
                <CardContent sx={{ p: 1.2 }}>
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.8}>
                    <Typography variant="subtitle2" component="div">
                      <StorageIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                      {t('wizard.serverInformation')}
                    </Typography>
                    <Button
                      startIcon={<EditIcon fontSize="small" />}
                      size="small"
                      onClick={() => navigateToStep(1)}
                      sx={{ minWidth: 0, p: '1px 4px', fontSize: '0.7rem' }}
                    >
                      {t('common:edit')}
                    </Button>
                  </Box>
                  
                  {selectedServer && (
                    <Box>
                      <Typography variant="body2" noWrap>
                        {selectedServer.name}
                      </Typography>
                      <Chip 
                        label={
                          state.databaseType === DatabaseType.POSTGRESQL ? 'PostgreSQL' : 
                          state.databaseType === DatabaseType.MSSQL ? 'SQL Server' : 
                          state.databaseType === DatabaseType.ORACLE ? 'Oracle' :
                          'MySQL'
                        } 
                        color={
                          state.databaseType === DatabaseType.POSTGRESQL ? 'primary' : 
                          state.databaseType === DatabaseType.MSSQL ? 'info' : 
                          state.databaseType === DatabaseType.ORACLE ? 'warning' :
                          'secondary'
                        }
                        size="small"
                        sx={{ 
                          height: 20, 
                          fontSize: '0.7rem',
                          mt: 0.5
                        }}
                      />
                    </Box>
                  )}
                </CardContent>
              </Card>
            </Grid>
            
            {/* Informação do banco de dados e acesso numa linha */}
            <Grid item xs={12} sm={6}>
              <Card 
                variant="outlined" 
                sx={{ 
                  height: 'calc(100% - 8px)', 
                  boxShadow: 'none', 
                  borderColor: 'divider' 
                }}
              >
                <CardContent sx={{ p: 1.2 }}>
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.8}>
                    <Typography variant="subtitle2" component="div">
                      <DatabaseIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                      {t('wizard.databaseInformation')}
                    </Typography>
                    <Button
                      startIcon={<EditIcon fontSize="small" />}
                      size="small"
                      onClick={() => navigateToStep(2)}
                      sx={{ minWidth: 0, p: '1px 4px', fontSize: '0.7rem' }}
                    >
                      {t('common:edit')}
                    </Button>
                  </Box>
                  
                  {state.databaseName ? (
                    <Box>
                      <Typography variant="body2" noWrap>
                        {state.databaseName}
                      </Typography>
                      
                      {(state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE) && state.schemaName && (
                        <Box display="flex" alignItems="center" mt={0.5}>
                          <FolderIcon sx={{ fontSize: '0.875rem', mr: 0.5, color: 'text.secondary' }} />
                          <Typography variant="body2" color="text.secondary" noWrap>
                            Schema: {state.schemaName}
                          </Typography>
                        </Box>
                      )}
                    </Box>
                  ) : (
                    <Typography variant="body2" color="text.disabled" sx={{ fontStyle: 'italic' }}>
                      {t('common:notSelected') || 'Not selected'}
                    </Typography>
                  )}
                </CardContent>
              </Card>
            </Grid>
            
            <Grid item xs={12} sm={6}>
              <Card 
                variant="outlined" 
                sx={{ 
                  height: 'calc(100% - 8px)', 
                  boxShadow: 'none', 
                  borderColor: 'divider' 
                }}
              >
                <CardContent sx={{ p: 1.2 }}>
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.8}>
                    <Typography variant="subtitle2" component="div">
                      <ManageAccountsIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                      {t('wizard.accessInformation')}
                    </Typography>
                    <Button
                      startIcon={<EditIcon fontSize="small" />}
                      size="small"
                      onClick={() => navigateToStep((state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL) ? 5 : 4)}
                      sx={{ minWidth: 0, p: '1px 4px', fontSize: '0.7rem' }}
                    >
                      {t('common:edit')}
                    </Button>
                  </Box>
                  
                  <Box display="flex" alignItems="center" flexWrap="wrap" gap={0.5}>
                    <Chip 
                      label={formatAccessType(state.accessType)} 
                      color={state.accessType === AccessType.ADMIN ? 'error' : (state.accessType === AccessType.READWRITE ? 'info' : 'success')}
                      size="small"
                      sx={{ 
                        height: 20, 
                        fontSize: '0.7rem'
                      }}
                    />
                    <Chip 
                      label={state.isPermanent ? t('wizard.permanent') : t('wizard.temporary')} 
                      color={state.isPermanent ? 'warning' : 'success'}
                      size="small"
                      sx={{ 
                        height: 20, 
                        fontSize: '0.7rem'
                      }}
                    />
                    {!state.isPermanent && (
                      <Typography variant="caption" color="text.secondary" sx={{ ml: 0.5 }}>
                        {new Date(state.expirationDate).toLocaleDateString()}
                      </Typography>
                    )}
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            
            {/* Tabelas selecionadas */}
            <Grid item xs={12} sm={6}>
              <Card 
                variant="outlined" 
                sx={{ 
                  height: 'calc(100% - 8px)',
                  boxShadow: 'none', 
                  borderColor: 'divider' 
                }}
              >
                <CardContent sx={{ p: 1.2 }}>
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.8}>
                    <Typography variant="subtitle2" component="div">
                      <TableChartIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                      {t('wizard.tables')} ({state.tables.length})
                    </Typography>
                    <Button
                      startIcon={<EditIcon fontSize="small" />}
                      size="small"
                      onClick={() => navigateToStep((state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL) ? 4 : 3)}
                      sx={{ minWidth: 0, p: '1px 4px', fontSize: '0.7rem' }}
                    >
                      {t('common:edit')}
                    </Button>
                  </Box>
                  
                  <Box 
                    sx={{ 
                      display: 'flex', 
                      flexWrap: 'wrap', 
                      gap: 0.5, 
                      maxHeight: '80px', 
                      overflow: 'auto',
                      '&::-webkit-scrollbar': {
                        width: '4px',
                        height: '4px',
                      },
                      '&::-webkit-scrollbar-thumb': {
                        backgroundColor: 'rgba(0,0,0,0.2)',
                        borderRadius: '4px',
                      }
                    }}
                  >
                    {state.tables.map((tableName) => (
                      <Chip
                        key={tableName}
                        label={tableName}
                        size="small"
                        variant="outlined"
                        sx={{ 
                          height: 18, 
                          fontSize: '0.65rem'
                        }}
                      />
                    ))}
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            
            {/* Justificativa */}
            <Grid item xs={12} sm={6}>
              <Card 
                variant="outlined" 
                sx={{ 
                  height: 'calc(100% - 8px)',
                  boxShadow: 'none', 
                  borderColor: 'divider' 
                }}
              >
                <CardContent sx={{ p: 1.2 }}>
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={0.8}>
                    <Typography variant="subtitle2" component="div">
                      <DescriptionIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                      {t('wizard.justification')}
                    </Typography>
                    <Button
                      startIcon={<EditIcon fontSize="small" />}
                      size="small"
                      onClick={() => navigateToStep((state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL) ? 7 : 6)}
                      sx={{ minWidth: 0, p: '1px 4px', fontSize: '0.7rem' }}
                    >
                      {t('common:edit')}
                    </Button>
                  </Box>
                  
                  <Box 
                    sx={{ 
                      p: 1, 
                      bgcolor: 'background.default',
                      borderRadius: 1,
                      border: '1px solid',
                      borderColor: 'divider',
                      maxHeight: '80px',
                      overflow: 'auto',
                      '&::-webkit-scrollbar': {
                        width: '4px',
                      },
                      '&::-webkit-scrollbar-thumb': {
                        backgroundColor: 'rgba(0,0,0,0.2)',
                        borderRadius: '4px',
                      }
                    }}
                  >
                    <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                      {state.justification}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            
            {/* Botão de finalização */}
            <Grid item xs={12} mt={1}>
              <Box 
                sx={{ 
                  p: 1.5, 
                  bgcolor: 'primary.50', 
                  borderRadius: 1,
                  border: '1px solid',
                  borderColor: 'primary.100',
                  display: 'flex',
                  alignItems: 'center'
                }}
              >
                <CheckIcon 
                  color="primary" 
                  sx={{ 
                    mr: 1.5, 
                    fontSize: '1.2rem',
                    bgcolor: 'primary.main',
                    color: 'white',
                    borderRadius: '50%',
                    p: 0.3
                  }} 
                />
                <Typography variant="body2" fontWeight="medium" sx={{ fontSize: '0.85rem' }}>
                  {t('wizard.readyToSubmit')}
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </Box>
      </Box>
    </StepLayout>
  );
};

export default ReviewStep;