import React, { useMemo } from 'react';
import { 
  Dialog, 
  DialogTitle, 
  DialogContent, 
  DialogActions, 
  Button, 
  Typography, 
  Box,
  Chip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Alert,
  Divider,
  useTheme
} from '@mui/material';
import { 
  Close as CloseIcon,
  Warning as WarningIcon,
  Error as ErrorIcon,
  Info as InfoIcon,
  Person as PersonIcon,
  Storage as StorageIcon,
  CalendarToday as CalendarIcon,
  CheckCircle as CheckCircleIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { format, isValid } from 'date-fns';

interface Discrepancy {
  id: string;
  type: 'extra_permission' | 'missing_permission' | 'unmanaged_user' | string;
  username: string;
  serverId?: string; // Formato usado no frontend
  server_id?: string; // Formato do backend
  serverName?: string; // Formato usado no frontend
  server_name?: string; // Formato do backend
  server_type?: string;
  databaseId?: string; // Compatibilidade
  databaseName?: string; // Formato usado no frontend
  database_name?: string; // Formato do backend
  permission_database_name?: string;
  permission_schema_name?: string;
  permission_table_name?: string;
  object_type?: string;
  object_name?: string;
  table?: string; // Compatibilidade com formato antigo
  reason?: string;
  details?: string; // Compatibilidade com formato antigo
  status?: string;
  corrected?: boolean; // Compatibilidade
  detected_at?: string;
  detectedAt?: string; // Alias
  created_at?: string;
  createdAt?: string; // Alias
  action?: string;
  operations?: string[];
}

interface UnifiedDiscrepancyDialogProps {
  open: boolean;
  onClose: () => void;
  discrepancies?: Discrepancy[];
  selectedDiscrepancy?: Discrepancy;
  serverName?: string;
  onCorrect?: (discrepancyId: string) => void;
  onCorrectAll?: () => void;
  onAccept?: (discrepancyId: string) => void;
}

const UnifiedDiscrepancyDialog: React.FC<UnifiedDiscrepancyDialogProps> = ({
  open,
  onClose,
  discrepancies,
  selectedDiscrepancy,
  serverName,
  onCorrect,
  onCorrectAll,
  onAccept
}) => {
  const { t } = useTranslation('sync');
  const theme = useTheme();

  // Se temos uma discrepância selecionada, mostramos apenas ela
  const itemsToShow = useMemo(() => {
    if (selectedDiscrepancy) {
      return [selectedDiscrepancy];
    }
    return discrepancies || [];
  }, [selectedDiscrepancy, discrepancies]);

  const isDetailView = !!selectedDiscrepancy;

  // Função para formatar data
  const formatDate = (dateStr?: string) => {
    if (!dateStr) return t('unknownDate', { defaultValue: 'Unknown Date' });
    
    try {
      const date = new Date(dateStr);
      if (isValid(date)) {
        return format(date, 'PPp'); // Formato: Jan 10, 2025 at 5:30 PM
      }
    } catch (error) {
      console.error('Error parsing date:', dateStr, error);
    }
    
    return t('invalidDate', { defaultValue: 'Invalid Date' });
  };

  // Função para extrair operações extras da mensagem
  const extractExtraOperations = (reason: string): string[] => {
    // Procura por padrões como "Extra operations DELETE, INSERT, UPDATE"
    const match = reason.match(/Extra operations? ([A-Z, ]+) on/i);
    if (match) {
      return match[1].split(',').map(op => op.trim());
    }
    
    // Fallback para padrão antigo
    const matches = reason.match(/Extra operation (\w+)/g);
    if (matches) {
      return matches.map(match => match.replace('Extra operation ', ''));
    }
    return [];
  };

  // Função para extrair nome da tabela do texto de reason/details
  const extractTableNameFromText = (text: string): string | null => {
    // Procurar por padrões como "on table SCHEMA.TABLE" ou "on table TABLE"
    const tableMatch = text.match(/on table ([A-Z0-9_]+\.)?([A-Z0-9_]+)/i);
    if (tableMatch) {
      // Retornar apenas o nome da tabela (sem schema)
      return tableMatch[2];
    }
    
    // Tentar padrão mais genérico
    if (text.includes('table')) {
      const match = text.match(/table\s+([^\s(]+)/i);
      if (match) {
        const extracted = match[1];
        // Se tem schema, pegar apenas a tabela
        if (extracted.includes('.')) {
          return extracted.split('.').pop() || null;
        }
        return extracted;
      }
    }
    
    return null;
  };

  // Função para formatar a mensagem de forma simples e clara
  const formatDiscrepancyMessage = (discrepancy: Discrepancy) => {
    const { type, username, reason, permission_schema_name, permission_table_name, permission_database_name } = discrepancy;
    
    // Extrair nome da tabela limpo
    let cleanTableName = permission_table_name || discrepancy.table || '';
    let schemaName = permission_schema_name || '';
    
    // Se o nome da tabela contém schema (formato SCHEMA.TABLE), separar
    if (cleanTableName.includes('.')) {
      const parts = cleanTableName.split('.');
      if (parts.length === 2) {
        schemaName = schemaName || parts[0];
        cleanTableName = parts[1];
      }
    }
    
    // Para operações extras
    if (type === 'extra_permission' && reason) {
      const operations = extractExtraOperations(reason);
      const hasSchema = schemaName && schemaName !== '';
      
      if (operations.length > 0) {
        const operationsText = operations.join(', ');
        
        if (hasSchema) {
          return t('discrepancy.extraOperationsWithSchema', {
            user: username,
            operations: operationsText,
            database: permission_database_name || 'Unknown',
            schema: schemaName,
            table: cleanTableName,
            defaultValue: `User {{user}} has extra permissions ({{operations}}) in database {{database}}, schema {{schema}}, table {{table}}`
          });
        } else {
          return t('discrepancy.extraOperationsNoSchema', {
            user: username,
            operations: operationsText,
            database: permission_database_name || 'Unknown',
            table: cleanTableName,
            defaultValue: `User {{user}} has extra permissions ({{operations}}) in database {{database}}, table {{table}}`
          });
        }
      }
    }
    
    // Para usuários não gerenciados
    if (type === 'unmanaged_user') {
      // Verificar se a razão é a mensagem padrão em inglês
      if (reason && reason.includes('User exists in database but is not managed')) {
        return t('discrepancy.unmanagedUser', {
          user: username,
          database: permission_database_name || getServerDisplayName(discrepancy) || 'Unknown',
          defaultValue: `User {{user}} exists in database {{database}} but is not managed by dbmanager`
        });
      }
    }
    
    // Para permissões faltantes
    if (type === 'missing_permission' && reason) {
      const hasSchema = schemaName && schemaName !== '';
      
      if (hasSchema) {
        return t('discrepancy.missingPermissionsWithSchema', {
          user: username,
          database: permission_database_name || 'Unknown',
          schema: schemaName,
          table: cleanTableName,
          defaultValue: `User {{user}} is missing permissions in database {{database}}, schema {{schema}}, table {{table}}`
        });
      } else {
        return t('discrepancy.missingPermissionsNoSchema', {
          user: username,
          database: permission_database_name || 'Unknown',
          table: cleanTableName,
          defaultValue: `User {{user}} is missing permissions in database {{database}}, table {{table}}`
        });
      }
    }
    
    // Outros tipos...
    return reason || t('discrepancy.genericMessage', { defaultValue: 'Discrepancy detected during synchronization' });
  };

  // Função para obter o ícone baseado no tipo
  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'extra_permission':
        return <WarningIcon sx={{ color: theme.palette.warning.main }} />;
      case 'missing_permission':
        return <ErrorIcon sx={{ color: theme.palette.error.main }} />;
      case 'unmanaged_user':
        return <InfoIcon sx={{ color: theme.palette.info.main }} />;
      default:
        return <InfoIcon sx={{ color: theme.palette.info.main }} />;
    }
  };

  // Função para obter o chip de tipo
  const getTypeChip = (type: string) => {
    const typeLabels: Record<string, string> = {
      'extra_permission': t('discrepancy.types.extraPermission', { defaultValue: 'Extra Permission' }),
      'missing_permission': t('discrepancy.types.missingPermission', { defaultValue: 'Missing Permission' }),
      'unmanaged_user': t('discrepancy.types.unmanagedUser', { defaultValue: 'Unmanaged User' })
    };

    const typeColors: Record<string, 'warning' | 'error' | 'info'> = {
      'extra_permission': 'warning',
      'missing_permission': 'error',
      'unmanaged_user': 'info'
    };

    return (
      <Chip 
        label={typeLabels[type] || type}
        color={typeColors[type] || 'default'}
        size="small"
      />
    );
  };

  // Determinar o nome do servidor
  const getServerDisplayName = (discrepancy: Discrepancy) => {
    // Priorizar nomes legíveis sobre IDs
    const name = discrepancy.server_name || 
                 discrepancy.serverName ||
                 serverName || 
                 discrepancy.database_name || 
                 discrepancy.databaseName ||
                 discrepancy.permission_database_name;
    
    // Se o nome parece ser um UUID (tem 36 caracteres e contém hífens), tentar encontrar um nome melhor
    if (name && name.length === 36 && name.includes('-')) {
      // Se temos um serverName passado como prop, usar ele
      if (serverName && serverName.length !== 36) {
        return serverName;
      }
      // Caso contrário, retornar versão abreviada do UUID
      return `Server ${name.substring(0, 8)}...`;
    }
    
    return name || 'Unknown Server';
  };

  // Renderizar visualização detalhada para uma única discrepância
  const renderDetailView = () => {
    if (!selectedDiscrepancy) return null;

    return (
      <>
        <Box sx={{ 
          bgcolor: theme.palette.mode === 'dark' ? 'grey.900' : 'grey.50',
          p: 3,
          borderRadius: 2,
          border: `1px solid ${theme.palette.divider}`
        }}>
          <Typography 
            variant="body1" 
            sx={{ 
              lineHeight: 1.8,
              color: theme.palette.text.primary,
              fontSize: '1rem'
            }}
          >
            {formatDiscrepancyMessage(selectedDiscrepancy)}
          </Typography>
        </Box>

        <Box sx={{ mt: 3 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <StorageIcon sx={{ mr: 1, color: 'text.secondary' }} />
            <Typography variant="subtitle2" color="text.secondary" sx={{ minWidth: 100 }}>
              {t('detailsSection.server', { defaultValue: 'Server' })}:
            </Typography>
            <Typography variant="body2">
              {getServerDisplayName(selectedDiscrepancy)}
            </Typography>
          </Box>
          
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <PersonIcon sx={{ mr: 1, color: 'text.secondary' }} />
            <Typography variant="subtitle2" color="text.secondary" sx={{ minWidth: 100 }}>
              {t('detailsSection.username', { defaultValue: 'Username' })}:
            </Typography>
            <Typography variant="body2">
              {selectedDiscrepancy.username}
            </Typography>
          </Box>

          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <Typography variant="subtitle2" color="text.secondary" sx={{ minWidth: 100, ml: 4 }}>
              {t('detailsSection.status', { defaultValue: 'Status' })}:
            </Typography>
            <Chip 
              label={
                selectedDiscrepancy.status === 'pending' 
                  ? t('pending', { defaultValue: 'Pending' }) 
                  : selectedDiscrepancy.status === 'corrected' || selectedDiscrepancy.corrected
                    ? t('corrected', { defaultValue: 'Corrected' })
                    : selectedDiscrepancy.status
              }
              size="small"
              color={
                selectedDiscrepancy.status === 'pending' 
                  ? 'warning' 
                  : selectedDiscrepancy.status === 'corrected' || selectedDiscrepancy.corrected
                    ? 'success'
                    : 'default'
              }
              icon={
                selectedDiscrepancy.status === 'corrected' || selectedDiscrepancy.corrected
                  ? <CheckCircleIcon sx={{ fontSize: '1rem' }} />
                  : undefined
              }
            />
          </Box>

          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <CalendarIcon sx={{ mr: 1, color: 'text.secondary' }} />
            <Typography variant="subtitle2" color="text.secondary" sx={{ minWidth: 100 }}>
              {t('detailsSection.detectedAt', { defaultValue: 'Detected' })}:
            </Typography>
            <Typography variant="body2">
              {formatDate(selectedDiscrepancy.detected_at || selectedDiscrepancy.created_at)}
            </Typography>
          </Box>
        </Box>
      </>
    );
  };

  // Renderizar visualização de lista para múltiplas discrepâncias
  const renderListView = () => {
    if (itemsToShow.length === 0) {
      return (
        <Alert severity="info">
          {t('noDiscrepancies', { defaultValue: 'No discrepancies found' })}
        </Alert>
      );
    }

    // Agrupar discrepâncias por servidor
    const groupedByServer = itemsToShow.reduce((acc, disc) => {
      const serverKey = getServerDisplayName(disc);
      if (!acc[serverKey]) {
        acc[serverKey] = [];
      }
      acc[serverKey].push(disc);
      return acc;
    }, {} as Record<string, Discrepancy[]>);

    return (
      <>
        {Object.entries(groupedByServer).map(([server, serverDiscrepancies]) => (
          <Box key={server} sx={{ mb: 3 }}>
            <Typography variant="subtitle1" sx={{ mb: 2, fontWeight: 500 }}>
              <StorageIcon sx={{ mr: 1, verticalAlign: 'middle', fontSize: 20 }} />
              {server}
            </Typography>
            
            <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto' }}>
              <Table size="small" sx={{ minWidth: 1000 }}>
                <TableHead>
                  <TableRow>
                    <TableCell sx={{ minWidth: 150 }}>{t('type')}</TableCell>
                    <TableCell sx={{ minWidth: 120 }}>{t('username')}</TableCell>
                    <TableCell sx={{ minWidth: 120 }}>{t('table')}</TableCell>
                    <TableCell sx={{ minWidth: 300 }}>{t('details')}</TableCell>
                    <TableCell sx={{ minWidth: 100 }}>{t('status')}</TableCell>
                    <TableCell align="right" sx={{ minWidth: 180 }}>{t('actions')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {serverDiscrepancies.map((disc) => (
                    <TableRow key={disc.id}>
                      <TableCell>{getTypeChip(disc.type)}</TableCell>
                      <TableCell>{disc.username}</TableCell>
                      <TableCell>
                        {(() => {
                          // Primeiro, tentar extrair o nome da tabela do reason/details
                          const reasonText = disc.reason || disc.details || '';
                          const extractedName = extractTableNameFromText(reasonText);
                          
                          if (extractedName) {
                            return extractedName;
                          }
                          
                          // Se não encontrou no texto, usar a lógica de fallback
                          const tableName = disc.permission_table_name || 
                                          disc.table || 
                                          disc.object_name;
                          
                          // Se o nome parece ser um UUID, mostrar como desconhecido ou abreviado
                          if (tableName && tableName.length === 36 && tableName.includes('-')) {
                            // Se temos um nome melhor em outro campo, usar ele
                            if (disc.table && disc.table.length !== 36) {
                              return disc.table;
                            }
                            // Senão, indicar que não temos o nome
                            return '-';
                          }
                          
                          // Se tem schema no nome (formato SCHEMA.TABELA), extrair apenas a tabela
                          if (tableName && tableName.includes('.')) {
                            const parts = tableName.split('.');
                            return parts[parts.length - 1];
                          }
                          
                          return tableName || '-';
                        })()}
                      </TableCell>
                      <TableCell sx={{ minWidth: 300 }}>
                        <Typography 
                          variant="body2" 
                          title={disc.reason}
                          sx={{ 
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            display: '-webkit-box',
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: 'vertical',
                            whiteSpace: 'normal'
                          }}
                        >
                          {disc.reason || '-'}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Chip 
                          label={
                            disc.status === 'pending' 
                              ? t('pending') 
                              : disc.status === 'corrected' || disc.corrected
                                ? t('corrected')
                                : disc.status
                          }
                          size="small"
                          color={
                            disc.status === 'pending' 
                              ? 'warning' 
                              : disc.status === 'corrected' || disc.corrected
                                ? 'success'
                                : 'default'
                          }
                          icon={
                            disc.status === 'corrected' || disc.corrected
                              ? <CheckCircleIcon sx={{ fontSize: '1rem' }} />
                              : undefined
                          }
                        />
                      </TableCell>
                      <TableCell align="right">
                        <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                          {disc.status === 'pending' && !disc.corrected && onCorrect && 
                           disc.type !== 'extra_database' && disc.type !== 'extra_table' && (
                            <Button
                              size="small"
                              variant="outlined"
                              onClick={() => onCorrect(disc.id)}
                            >
                              {disc.type === 'missing_database' || disc.type === 'missing_table' 
                                ? t('cleanupPermissions', { defaultValue: 'Cleanup Permissions' })
                                : t('correct', { defaultValue: 'Correct' })}
                            </Button>
                          )}
                          {(disc.type === 'unmanaged_user' || 
                           disc.type === 'extra_database' || disc.type === 'missing_database' ||
                           disc.type === 'extra_table' || disc.type === 'missing_table') && 
                           disc.status === 'pending' && !disc.corrected && onAccept && (
                            <Button
                              size="small"
                              variant="outlined"
                              color="success"
                              onClick={() => onAccept(disc.id)}
                            >
                              {t('accept', { defaultValue: 'Accept' })}
                            </Button>
                          )}
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        ))}
      </>
    );
  };

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth={isDetailView ? "sm" : "xl"}
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: 2,
          boxShadow: theme.shadows[10]
        }
      }}
    >
      <DialogTitle sx={{ 
        display: 'flex',
        alignItems: 'center',
        pb: 1
      }}>
        <Box sx={{ display: 'flex', alignItems: 'center', flex: 1 }}>
          {isDetailView && selectedDiscrepancy && getTypeIcon(selectedDiscrepancy.type)}
          <Typography variant="h6" sx={{ ml: isDetailView ? 1 : 0 }}>
            {isDetailView 
              ? t('discrepancyDetails', { defaultValue: 'Discrepancy Details' })
              : t('discrepancies', { defaultValue: 'Discrepancies' })
            }
          </Typography>
          {isDetailView && selectedDiscrepancy && (
            <Box sx={{ ml: 2 }}>
              {getTypeChip(selectedDiscrepancy.type)}
            </Box>
          )}
        </Box>
        <IconButton
          edge="end"
          color="inherit"
          onClick={onClose}
          aria-label="close"
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      
      <Divider />
      
      <DialogContent sx={{ pt: 3, pb: 2 }}>
        {isDetailView ? renderDetailView() : renderListView()}
      </DialogContent>
      
      <Divider />
      
      <DialogActions sx={{ p: 2 }}>
        {!isDetailView && onCorrectAll && itemsToShow.some(d => d.status === 'pending') && (
          <Button 
            variant="contained" 
            color="primary"
            onClick={onCorrectAll}
          >
            {t('correctAll', { defaultValue: 'Correct All' })}
          </Button>
        )}
        {isDetailView && selectedDiscrepancy && selectedDiscrepancy.status === 'pending' && !selectedDiscrepancy.corrected && (
          <>
            {(selectedDiscrepancy.type === 'unmanaged_user' || 
              selectedDiscrepancy.type === 'extra_database' || selectedDiscrepancy.type === 'missing_database' ||
              selectedDiscrepancy.type === 'extra_table' || selectedDiscrepancy.type === 'missing_table') && 
              onAccept && (
              <Button 
                variant="contained" 
                color="success"
                onClick={() => {
                  onAccept(selectedDiscrepancy.id);
                  onClose();
                }}
              >
                {t('accept', { defaultValue: 'Accept' })}
              </Button>
            )}
            {(selectedDiscrepancy.type === 'missing_database' || selectedDiscrepancy.type === 'missing_table') && 
              onCorrect && (
              <Button 
                variant="outlined" 
                color="warning"
                onClick={() => {
                  onCorrect(selectedDiscrepancy.id);
                  onClose();
                }}
              >
                {t('cleanupPermissions', { defaultValue: 'Cleanup Permissions' })}
              </Button>
            )}
            {selectedDiscrepancy.type !== 'extra_database' && selectedDiscrepancy.type !== 'missing_database' &&
             selectedDiscrepancy.type !== 'extra_table' && selectedDiscrepancy.type !== 'missing_table' &&
             selectedDiscrepancy.type !== 'unmanaged_user' && onCorrect && (
              <Button 
                variant="contained" 
                color="primary"
                onClick={() => {
                  onCorrect(selectedDiscrepancy.id);
                  onClose();
                }}
              >
                {t('correct', { defaultValue: 'Correct' })}
              </Button>
            )}
          </>
        )}
        <Button 
          variant={isDetailView && selectedDiscrepancy?.status === 'pending' ? "outlined" : "contained"}
          onClick={onClose}
        >
          {t('common:close', { defaultValue: 'Close' })}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default UnifiedDiscrepancyDialog;