import React, { useEffect, useState } from 'react';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  CircularProgress,
  Chip,
  TextField,
  InputAdornment,
  IconButton,
  Paper,
  Button,
  CardActionArea,
  Checkbox,
  alpha,
  styled,
  useTheme,
  ButtonGroup,
  Badge,
  Grow,
  Avatar
} from '@mui/material';
import {
  TableChart as TableChartIcon,
  Search as SearchIcon,
  Clear as ClearIcon,
  CheckBox as CheckBoxIcon,
  CheckBoxOutlineBlank as CheckBoxOutlineBlankIcon,
  SortByAlpha as SortByAlphaIcon,
  DataObject as DataObjectIcon,
  Storage as StorageIcon
} from '@mui/icons-material';
import FormControlLabel from '@mui/material/FormControlLabel';
import Switch from '@mui/material/Switch';
import { useTranslation } from 'react-i18next';
import { StepProps, DatabaseType } from '../../types';
import StepLayout from '../shared/StepLayout';

// Card selecionável com efeitos de hover
const TableCard = styled(Card)(({ theme }) => ({
  transition: 'all 0.25s ease',
  position: 'relative',
  height: '100%',
  minHeight: '85px', // Reduzido para otimizar espaço
  display: 'flex',
  flexDirection: 'column',
  cursor: 'pointer',
  '&:hover': {
    transform: 'translateY(-3px)',
    boxShadow: theme.shadows[3],
  }
}));

// Overlay para cards selecionados
const SelectedOverlay = styled(Box)(({ theme }) => ({
  position: 'absolute',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: alpha(theme.palette.primary.main, 0.12),
  border: `2px solid ${theme.palette.primary.main}`,
  borderRadius: 'inherit',
  zIndex: 1,
  pointerEvents: 'none'
}));

/**
 * Componente para a etapa de seleção de tabelas
 * 
 * Melhorias de otimização de espaço aplicadas:
 * - Cards compactos com minHeight reduzida (85px)
 * - Avatar menor (32px) e texto menor (0.8rem)
 * - Padding reduzido nos cards e containers
 * - Grid com xl={2} para mostrar até 6 tabelas por linha
 * - Altura máxima aumentada para 600px
 * - Spacing otimizado entre elementos
 */
const TableStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t, i18n } = useTranslation(['requests', 'common', 'error']);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectAllChecked, setSelectAllChecked] = useState(false);
  const [sortAlphabetically, setSortAlphabetically] = useState(true);
  const theme = useTheme();

  // Atualizar o estado de "selecionar todos" quando as tabelas selecionadas mudam
  useEffect(() => {
    // Se todas as tabelas estão selecionadas, atualizar o estado do checkbox
    if (state.tables.length > 0 && filteredTables.length > 0 && state.tables.length >= filteredTables.length) {
      setSelectAllChecked(true);
    } else {
      setSelectAllChecked(false);
    }
  }, [state.tables, searchTerm]);

  // Filtrar tabelas baseado no termo de busca
  const filteredTables = state.tablesList
    .filter(table => table.name.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => {
      if (sortAlphabetically) {
        return a.name.localeCompare(b.name);
      } else {
        // Ordenar por seleção (tabelas selecionadas primeiro)
        const aSelected = state.tables.includes(a.name);
        const bSelected = state.tables.includes(b.name);
        
        if (aSelected && !bSelected) return -1;
        if (!aSelected && bSelected) return 1;
        return a.name.localeCompare(b.name);
      }
    });

  // Manipulador para alternar a seleção de uma tabela
  const handleToggleTable = (tableName: string) => {
    const isSelected = state.tables.includes(tableName);
    
    if (isSelected) {
      // Remover tabela
      const updatedTables = state.tables.filter(name => name !== tableName);
      dispatch({ type: 'SET_TABLES', payload: updatedTables });
    } else {
      // Adicionar tabela
      const updatedTables = [...state.tables, tableName];
      dispatch({ type: 'SET_TABLES', payload: updatedTables });
    }
  };

  // Manipulador para selecionar/desselecionar todas as tabelas
  const handleSelectAll = () => {
    if (selectAllChecked) {
      // Desselecionar todas as tabelas
      dispatch({ type: 'SET_TABLES', payload: [] });
      setSelectAllChecked(false);
    } else {
      // Selecionar todas as tabelas filtradas
      const allTableNames = filteredTables.map(table => table.name);
      dispatch({ type: 'SET_TABLES', payload: allTableNames });
      setSelectAllChecked(true);
    }
  };

  // Manipulador para limpar a busca
  const handleClearSearch = () => {
    setSearchTerm('');
  };

  // fetchTables função removida - não utilizada

  // A validação de tabelas já é feita no useRequestForm
  // Removida a função handleNext para evitar conflitos com os botões do modal principal

  // Renderizar o card para uma tabela específica
  const renderTableCard = (table: { name: string, serverId: string, databaseName?: string, schemaName?: string }, index: number) => {
    const isSelected = state.tables.includes(table.name);

    return (
        <Grid item xs={12} sm={6} md={4} lg={3} xl={2}
          key={`${table.name}-${table.databaseName || ''}-${table.schemaName || ''}`}
        >
          <TableCard variant={isSelected ? "elevation" : "outlined"} elevation={isSelected ? 3 : 1}>
            {isSelected && <SelectedOverlay />}
            <CardActionArea
              onClick={() => handleToggleTable(table.name)}
              sx={{ display: 'flex', flexDirection: 'column', height: '100%', position: 'relative', zIndex: 2 }}
            >
              <CardContent sx={{ width: '100%', p: 1, pb: 1.5 }}>
                <Box display="flex" alignItems="flex-start">
                  <Avatar
                    sx={{
                      bgcolor: isSelected ? theme.palette.primary.main : alpha(theme.palette.primary.main, 0.1),
                      width: 32,
                      height: 32,
                      mr: 1,
                    }}
                  >
                    <TableChartIcon fontSize="small" color={isSelected ? "inherit" : "primary"} />
                  </Avatar>
                  <Box flexGrow={1} sx={{ maxWidth: 'calc(100% - 32px)', mr: 1 }}>
                    <Typography 
                      variant="subtitle2" 
                      component="div" 
                      title={table.name}
                      sx={{
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        width: '100%',
                        fontSize: '0.8rem',
                        lineHeight: 1.2,
                        fontWeight: isSelected ? 600 : 500,
                        wordBreak: 'break-word',
                        display: '-webkit-box',
                        WebkitLineClamp: 2,
                        WebkitBoxOrient: 'vertical'
                      }}
                    >
                      {table.name}
                    </Typography>
                  </Box>
                  <Checkbox 
                    checked={isSelected}
                    color="primary"
                    icon={<CheckBoxOutlineBlankIcon fontSize="small" />}
                    checkedIcon={<CheckBoxIcon fontSize="small" />}
                    sx={{ p: 0.5, alignSelf: 'center' }}
                  />
                </Box>
              </CardContent>
            </CardActionArea>
          </TableCard>
        </Grid>
    );
  };

  return (
    <StepLayout
      title={String(t('wizard.steps.table'))}
      subtitle={
        state.databaseType === DatabaseType.POSTGRESQL
          ? String(t('wizard.tableStepSubtitlePostgres'))
          : String(t('wizard.tableStepSubtitle'))
      }
      icon="table"
    >
      <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
        <Grid container spacing={2}>
        {state.isLoading ? (
          <Grid item xs={12} display="flex" justifyContent="center">
            <CircularProgress />
          </Grid>
        ) : state.tablesList.length === 0 ? (
          <Grid item xs={12}>
            <Paper 
              elevation={0} 
              sx={{ 
                p: 3, 
                bgcolor: alpha(theme.palette.info.main, 0.1),
                border: `1px solid ${theme.palette.info.light}`,
                borderRadius: 2
              }}
            >
              <Box display="flex" flexDirection="column" alignItems="center" textAlign="center" gap={2}>
                <Avatar
                  sx={{
                    width: 64,
                    height: 64,
                    bgcolor: theme.palette.info.main,
                    mb: 1
                  }}
                >
                  <StorageIcon fontSize="large" />
                </Avatar>
                
                <Typography variant="h6" gutterBottom>
                  {t('permissions.noDatabaseTables', 'This database doesn\'t have any tables yet')}
                </Typography>
                
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  {state.databaseType === DatabaseType.POSTGRESQL
                    ? t('wizard.noTablesInSchema', `No tables found in schema "${state.schemaName}".`)
                    : t('wizard.noTablesInDatabase', `No tables found in database "${state.databaseName}".`)
                  }
                </Typography>
                
                <Button
                  variant="contained"
                  color="primary"
                  size="large"
                  startIcon={<CheckBoxIcon />}
                  onClick={() => {
                    // Marcar como permissão database-level
                    dispatch({ type: 'SET_DATABASE_LEVEL', payload: true });
                    // Avançar para próxima etapa
                    onNext();
                  }}
                  sx={{ mt: 1 }}
                >
                  {t('permissions.grantDatabaseLevel', 'Grant database-level permissions')}
                </Button>
                
                <Typography variant="caption" color="text.secondary" sx={{ mt: 2 }}>
                  {t('permissions.databaseLevelInfo', 'Database-level permissions will allow the user to create tables in this database.')}
                </Typography>
              </Box>
            </Paper>
          </Grid>
        ) : (
          <>
            <Grid item xs={12}>
              <Paper 
                elevation={0} 
                variant="outlined" 
                sx={{ p: 1.5, mb: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2 }}
              >
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <Chip
                    icon={state.databaseType === DatabaseType.POSTGRESQL ? <DataObjectIcon /> : <StorageIcon />}
                    label={
                      state.databaseType === DatabaseType.POSTGRESQL
                        ? `${t('database.schema')}: ${state.schemaName}`
                        : `${t('databases:databaseName')}: ${state.databaseName || 'N/A'}`
                    }
                    color={state.databaseType === DatabaseType.POSTGRESQL ? 'primary' : 'secondary'}
                    variant="filled"
                    sx={{ mr: 1 }}
                  />
                  <Badge 
                    badgeContent={state.tables.length} 
                    color="success"
                    max={999}
                    showZero
                    sx={{ ml: 1, '& .MuiBadge-badge': { fontSize: '0.75rem' } }}
                  >
                    <Chip 
                      icon={<TableChartIcon />}
                      label={t('requests:selectedTables')}
                      variant="outlined"
                      color={state.tables.length > 0 ? 'success' : 'default'}
                    />
                  </Badge>
                </Box>
                
                <Box sx={{ opacity: state.isDatabaseLevel ? 0.4 : 1, pointerEvents: state.isDatabaseLevel ? 'none' : 'auto' }}>
                  <ButtonGroup size="small" variant="outlined">
                    <Button
                      color={selectAllChecked ? "primary" : "inherit"}
                      onClick={handleSelectAll}
                      startIcon={selectAllChecked ? <CheckBoxIcon /> : <CheckBoxOutlineBlankIcon />}
                      disabled={state.isDatabaseLevel}
                    >
                      {selectAllChecked 
                        ? t('common:deselectAll') 
                        : t('common:selectAll')}
                    </Button>
                    <Button
                      color={sortAlphabetically ? "primary" : "inherit"}
                      onClick={() => setSortAlphabetically(!sortAlphabetically)}
                      startIcon={<SortByAlphaIcon />}
                    >
                      {t('common:sort')}
                    </Button>
                  </ButtonGroup>
                </Box>
              </Paper>
              
              {/* Opção para solicitar permissão database-level */}
              {state.tablesList.length > 0 && (
                <Paper 
                  elevation={0} 
                  sx={{ 
                    p: 2, 
                    mb: 2,
                    bgcolor: alpha(theme.palette.info.main, 0.05),
                    border: `1px dashed ${theme.palette.info.light}`,
                    borderRadius: 1
                  }}
                >
                  <Box display="flex" alignItems="center" justifyContent="space-between">
                    <Box display="flex" alignItems="center" gap={1}>
                      <StorageIcon color="info" />
                      <Box>
                        <Typography variant="subtitle2">
                          {t('permissions.databaseLevelOption', 'Database-level permissions')}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          {t('permissions.databaseLevelDescription', 'Grant permissions to create new tables')}
                        </Typography>
                      </Box>
                    </Box>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={state.isDatabaseLevel || false}
                          onChange={(e) => {
                            dispatch({ type: 'SET_DATABASE_LEVEL', payload: e.target.checked });
                            if (e.target.checked) {
                              // Limpar seleção de tabelas
                              dispatch({ type: 'SET_TABLES', payload: [] });
                            }
                          }}
                          color="primary"
                        />
                      }
                      label=""
                    />
                  </Box>
                </Paper>
              )}
              
              <Box mb={2}>
                <TextField
                  fullWidth
                  size="small"
                  variant="outlined"
                  placeholder={t('common:search') || 'Pesquisar tabelas...'}
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon color="action" />
                      </InputAdornment>
                    ),
                    endAdornment: searchTerm && (
                      <InputAdornment position="end">
                        <IconButton onClick={handleClearSearch} edge="end" size="small">
                          <ClearIcon />
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      backgroundColor: 'background.paper',
                      '&:hover': {
                        backgroundColor: 'background.paper',
                      },
                    },
                  }}
                />
              </Box>
              
              {state.errors.tables && (
                <Paper 
                  elevation={0} 
                  sx={{ 
                    p: 1.5, 
                    mb: 2, 
                    bgcolor: alpha(theme.palette.error.main, 0.1),
                    border: `1px solid ${theme.palette.error.light}`,
                    borderRadius: 1
                  }}
                >
                  <Typography color="error" variant="body2">
                    {state.errors.tables}
                  </Typography>
                </Paper>
              )}
              
              {filteredTables.length === 0 ? (
                <Paper elevation={0} sx={{ p: 3, textAlign: 'center', bgcolor: alpha(theme.palette.info.main, 0.05) }}>
                  <Typography variant="body1" color="text.secondary">
                    {t('common:noResults')}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    {t('common:tryAnotherSearch', 'Try another search or clear the filter')}
                  </Typography>
                </Paper>
              ) : (
                <Box sx={{ 
                  maxHeight: '600px', 
                  overflowY: 'auto', 
                  pr: 1,
                  '&::-webkit-scrollbar': {
                    width: '6px',
                  },
                  '&::-webkit-scrollbar-track': {
                    background: '#f1f1f1',
                    borderRadius: '3px',
                  },
                  '&::-webkit-scrollbar-thumb': {
                    background: '#c1c1c1',
                    borderRadius: '3px',
                    '&:hover': {
                      background: '#a8a8a8',
                    },
                  },
                }}>
                  <Grid container spacing={1.5}>
                    {filteredTables.map((table, index) => renderTableCard(table, index))}
                  </Grid>
                </Box>
              )}
            </Grid>
            
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 2 }}>
                <Typography variant="body2" color="text.secondary">
                  {t('common:showing')} {filteredTables.length} {t('common:of')} {state.tablesList.length} {t('wizard.tables')}
                </Typography>
                <Typography variant="body2" color={state.tables.length > 0 ? 'success.main' : 'text.secondary'}>
                  {state.tables.length} {t('wizard.tablesSelected')}
                </Typography>
              </Box>
            </Grid>
          </>
        )}
        </Grid>
      </Box>
    </StepLayout>
  );
};

export default TableStep;
