import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { 
  Box, 
  Typography, 
  Paper, 
  FormControlLabel, 
  Switch, 
  TextField, 
  Button, 
  Grid, 
  Alert, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  CircularProgress,
  Chip
} from '@mui/material';

interface ForwardingConfig {
  enabled: boolean;
  destinations: ForwardingDestination[];
}

interface ForwardingDestination {
  id?: string;
  name: string;
  type: 'syslog' | 'http' | 'kafka' | 'custom';
  endpoint: string;
  format: 'json' | 'cef' | 'leef' | 'raw';
  headers?: Record<string, string>;
  enabled: boolean;
  retryCount: number;
  retryInterval: number;
}

const ForwardingConfigPanel: React.FC = () => {
  const { t } = useTranslation('audit');
  const [loading, setLoading] = useState<boolean>(true);
  const [saving, setSaving] = useState<boolean>(false);
  const [config, setConfig] = useState<ForwardingConfig>({
    enabled: false,
    destinations: []
  });
  const [selectedDestination, setSelectedDestination] = useState<number | null>(null);
  const [statusMessage, setStatusMessage] = useState<{type: 'success' | 'error', message: string} | null>(null);
  const [editMode, setEditMode] = useState<boolean>(false);
  const [newDestination, setNewDestination] = useState<ForwardingDestination>({
    name: '',
    type: 'syslog',
    endpoint: '',
    format: 'json',
    enabled: true,
    retryCount: 3,
    retryInterval: 5
  });

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        setLoading(true);
        // This would be replaced with a real API call
        // const response = await api.get('/api/audit/forwarding-config');
        // setConfig(response.data);
        
        // Mocking the API response for now
        setTimeout(() => {
          setConfig({
            enabled: true,
            destinations: [
              {
                id: '1',
                name: 'Local Syslog',
                type: 'syslog',
                endpoint: 'syslog.internal:514',
                format: 'json',
                enabled: true,
                retryCount: 3,
                retryInterval: 5
              },
              {
                id: '2',
                name: 'Security SIEM',
                type: 'http',
                endpoint: 'https://siem.example.com/api/logs',
                format: 'cef',
                headers: { 'Authorization': 'Bearer TOKEN' },
                enabled: true,
                retryCount: 5,
                retryInterval: 10
              }
            ]
          });
          setLoading(false);
        }, 800);
      } catch (error) {
        console.error('Error fetching forwarding configuration:', error);
        setStatusMessage({
          type: 'error',
          message: t('forwarding.fetchError')
        });
        setLoading(false);
      }
    };

    fetchConfig();
  }, [t]);

  const handleSaveConfig = async () => {
    try {
      setSaving(true);
      // This would be replaced with a real API call
      // await api.post('/api/audit/forwarding-config', config);
      
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setStatusMessage({
        type: 'success',
        message: t('forwarding.saveSuccess')
      });
      setEditMode(false);
    } catch (error) {
      console.error('Error saving forwarding configuration:', error);
      setStatusMessage({
        type: 'error',
        message: t('forwarding.saveError')
      });
    } finally {
      setSaving(false);
    }
  };

  const handleToggleForwarding = (event: React.ChangeEvent<HTMLInputElement>) => {
    setConfig({
      ...config,
      enabled: event.target.checked
    });
  };

  const handleAddDestination = () => {
    if (newDestination.name && newDestination.endpoint) {
      setConfig({
        ...config,
        destinations: [...config.destinations, {
          ...newDestination,
          id: Date.now().toString() // Generate a temporary ID
        }]
      });
      
      // Reset the form
      setNewDestination({
        name: '',
        type: 'syslog',
        endpoint: '',
        format: 'json',
        enabled: true,
        retryCount: 3,
        retryInterval: 5
      });
      
      setEditMode(false);
    }
  };

  const handleUpdateDestination = () => {
    if (selectedDestination !== null && newDestination.name && newDestination.endpoint) {
      const updatedDestinations = [...config.destinations];
      updatedDestinations[selectedDestination] = {
        ...newDestination,
        id: config.destinations[selectedDestination].id
      };
      
      setConfig({
        ...config,
        destinations: updatedDestinations
      });
      
      setSelectedDestination(null);
      setEditMode(false);
      
      // Reset the form
      setNewDestination({
        name: '',
        type: 'syslog',
        endpoint: '',
        format: 'json',
        enabled: true,
        retryCount: 3,
        retryInterval: 5
      });
    }
  };

  const handleEditDestination = (index: number) => {
    setSelectedDestination(index);
    setNewDestination({...config.destinations[index]});
    setEditMode(true);
  };

  const handleRemoveDestination = (index: number) => {
    const updatedDestinations = [...config.destinations];
    updatedDestinations.splice(index, 1);
    setConfig({
      ...config,
      destinations: updatedDestinations
    });
  };

  const handleToggleDestination = (index: number) => {
    const updatedDestinations = [...config.destinations];
    updatedDestinations[index] = {
      ...updatedDestinations[index],
      enabled: !updatedDestinations[index].enabled
    };
    
    setConfig({
      ...config,
      destinations: updatedDestinations
    });
  };

  const handleCancelEdit = () => {
    setEditMode(false);
    setSelectedDestination(null);
    setNewDestination({
      name: '',
      type: 'syslog',
      endpoint: '',
      format: 'json',
      enabled: true,
      retryCount: 3,
      retryInterval: 5
    });
  };

  const handleTestDestination = async (destination: ForwardingDestination) => {
    try {
      setSaving(true);
      // This would be replaced with a real API call
      // await api.post('/api/audit/test-forwarding', destination);
      
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setStatusMessage({
        type: 'success',
        message: t('forwarding.testSuccess')
      });
    } catch (error) {
      console.error('Error testing forwarding destination:', error);
      setStatusMessage({
        type: 'error',
        message: t('forwarding.testError')
      });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        {t('forwarding.title')}
      </Typography>
      
      <Typography variant="body2" color="textSecondary" paragraph>
        {t('forwarding.description')}
      </Typography>

      {statusMessage && (
        <Alert 
          severity={statusMessage.type} 
          onClose={() => setStatusMessage(null)}
          sx={{ mb: 2 }}
        >
          {statusMessage.message}
        </Alert>
      )}

      <Paper sx={{ p: 3, mb: 3 }}>
        <FormControlLabel
          control={
            <Switch
              checked={config.enabled}
              onChange={handleToggleForwarding}
            />
          }
          label={t('forwarding.enableForwarding')}
        />
        
        <Typography variant="body2" color="textSecondary" sx={{ mt: 1, mb: 2 }}>
          {config.enabled 
            ? t('forwarding.enabledDescription')
            : t('forwarding.disabledDescription')
          }
        </Typography>

        <Button 
          variant="contained" 
          color="primary"
          onClick={handleSaveConfig}
          disabled={saving}
          sx={{ mt: 2 }}
        >
          {saving ? <CircularProgress size={24} /> : t('common:saveConfig')}
        </Button>
      </Paper>

      {config.enabled && (
        <>
          <Typography variant="h6" gutterBottom>
            {t('forwarding.destinations')}
          </Typography>

          {config.destinations.length > 0 ? (
            <Box mb={4}>
              {config.destinations.map((destination, index) => (
                <Paper key={destination.id} sx={{ p: 2, mb: 2, border: destination.enabled ? '1px solid #e0e0e0' : '1px dashed #e0e0e0' }}>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={8}>
                      <Typography variant="subtitle1" component="div" sx={{ display: 'flex', alignItems: 'center' }}>
                        {destination.name}
                        {!destination.enabled && (
                          <Chip 
                            label={t('common:disabled')} 
                            size="small" 
                            color="default" 
                            variant="outlined"
                            sx={{ ml: 1 }}
                          />
                        )}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {t('forwarding.type')}: {destination.type.toUpperCase()}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {t('forwarding.endpoint')}: {destination.endpoint}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {t('forwarding.format')}: {destination.format.toUpperCase()}
                      </Typography>
                    </Grid>
                    <Grid item xs={4} sx={{ textAlign: 'right' }}>
                      <Button 
                        variant="outlined" 
                        size="small" 
                        onClick={() => handleTestDestination(destination)}
                        sx={{ mr: 1 }}
                        disabled={!destination.enabled || saving}
                      >
                        {t('forwarding.test')}
                      </Button>
                      <Button 
                        variant="outlined" 
                        size="small" 
                        onClick={() => handleEditDestination(index)}
                        sx={{ mr: 1 }}
                      >
                        {t('common:edit')}
                      </Button>
                      <Button 
                        variant={destination.enabled ? "outlined" : "contained"} 
                        size="small" 
                        color={destination.enabled ? "primary" : "success"}
                        onClick={() => handleToggleDestination(index)}
                        sx={{ mr: 1 }}
                      >
                        {destination.enabled 
                          ? t('common:disable') 
                          : t('common:enable')
                        }
                      </Button>
                      <Button 
                        variant="outlined" 
                        size="small" 
                        color="error"
                        onClick={() => handleRemoveDestination(index)}
                      >
                        {t('common:delete')}
                      </Button>
                    </Grid>
                  </Grid>
                </Paper>
              ))}
            </Box>
          ) : (
            <Alert severity="info" sx={{ mb: 3 }}>
              {t('forwarding.noDestinations')}
            </Alert>
          )}

          {!editMode ? (
            <Button 
              variant="contained" 
              color="primary" 
              onClick={() => setEditMode(true)}
              sx={{ mb: 3 }}
            >
              {t('forwarding.addDestination')}
            </Button>
          ) : (
            <Paper sx={{ p: 3, mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                {selectedDestination !== null 
                  ? t('forwarding.editDestination') 
                  : t('forwarding.addDestination')
                }
              </Typography>
              
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label={t('forwarding.destinationName')}
                    fullWidth
                    value={newDestination.name}
                    onChange={(e) => setNewDestination({...newDestination, name: e.target.value})}
                    margin="normal"
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth margin="normal">
                    <InputLabel id="destination-type-label">
                      {t('forwarding.destinationType')}
                    </InputLabel>
                    <Select
                      labelId="destination-type-label"
                      value={newDestination.type}
                      label={t('forwarding.destinationType')}
                      onChange={(e) => setNewDestination({...newDestination, type: e.target.value as any})}
                    >
                      <MenuItem value="syslog">Syslog</MenuItem>
                      <MenuItem value="http">HTTP/HTTPS</MenuItem>
                      <MenuItem value="kafka">Kafka</MenuItem>
                      <MenuItem value="custom">Custom</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label={t('forwarding.endpoint')}
                    fullWidth
                    value={newDestination.endpoint}
                    onChange={(e) => setNewDestination({...newDestination, endpoint: e.target.value})}
                    margin="normal"
                    placeholder={newDestination.type === 'syslog' ? 'syslog.internal:514' : 
                      newDestination.type === 'http' ? 'https://example.com/logs' : 
                      newDestination.type === 'kafka' ? 'broker:9092/topic' : ''}
                    helperText={
                      newDestination.type === 'syslog' ? t('forwarding.syslogHelp') : 
                      newDestination.type === 'http' ? t('forwarding.httpHelp') : 
                      newDestination.type === 'kafka' ? t('forwarding.kafkaHelp') : 
                      t('forwarding.customHelp')
                    }
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth margin="normal">
                    <InputLabel id="log-format-label">
                      {t('forwarding.logFormat')}
                    </InputLabel>
                    <Select
                      labelId="log-format-label"
                      value={newDestination.format}
                      label={t('forwarding.logFormat')}
                      onChange={(e) => setNewDestination({...newDestination, format: e.target.value as any})}
                    >
                      <MenuItem value="json">JSON</MenuItem>
                      <MenuItem value="cef">CEF (Common Event Format)</MenuItem>
                      <MenuItem value="leef">LEEF (IBM QRadar)</MenuItem>
                      <MenuItem value="raw">Raw/Plain Text</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} sm={3}>
                  <TextField
                    label={t('forwarding.retryCount')}
                    type="number"
                    fullWidth
                    value={newDestination.retryCount}
                    onChange={(e) => setNewDestination({...newDestination, retryCount: parseInt(e.target.value)})}
                    margin="normal"
                    InputProps={{ inputProps: { min: 0, max: 10 } }}
                  />
                </Grid>
                <Grid item xs={12} sm={3}>
                  <TextField
                    label={t('forwarding.retryInterval')}
                    type="number"
                    fullWidth
                    value={newDestination.retryInterval}
                    onChange={(e) => setNewDestination({...newDestination, retryInterval: parseInt(e.target.value)})}
                    margin="normal"
                    InputProps={{ inputProps: { min: 1, max: 60 } }}
                  />
                </Grid>
                {newDestination.type === 'http' && (
                  <Grid item xs={12}>
                    <Typography variant="subtitle2" gutterBottom sx={{ mt: 2 }}>
                      {t('forwarding.httpHeaders')}
                    </Typography>
                    <Alert severity="info" sx={{ mb: 2 }}>
                      {t('forwarding.headersInfo')}
                    </Alert>
                  </Grid>
                )}
                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={newDestination.enabled}
                        onChange={(e) => setNewDestination({...newDestination, enabled: e.target.checked})}
                      />
                    }
                    label={t('forwarding.enableDestination')}
                  />
                </Grid>
              </Grid>

              <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
                <Button 
                  variant="outlined" 
                  onClick={handleCancelEdit}
                  sx={{ mr: 1 }}
                >
                  {t('common:cancel')}
                </Button>
                <Button 
                  variant="contained" 
                  color="primary"
                  onClick={selectedDestination !== null ? handleUpdateDestination : handleAddDestination}
                  disabled={!newDestination.name || !newDestination.endpoint}
                >
                  {selectedDestination !== null 
                    ? t('common:update') 
                    : t('common:add')
                  }
                </Button>
              </Box>
            </Paper>
          )}
        </>
      )}
    </Box>
  );
};

export default ForwardingConfigPanel;