import React, { useEffect, useState, useCallback } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  CircularProgress,
  Alert,
  Tab,
  Tabs,
} from '@mui/material';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ChartOptions,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { apiClient as api } from '../services/api';
import { useTranslation } from 'react-i18next';

// Registrar componentes do Chart.js
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

interface APIKeyStatsModalProps {
  open: boolean;
  onClose: () => void;
  apiKeyId: string;
  apiKeyName: string;
}

interface UsageData {
  endpoint: string;
  method: string;
  status_code: number;
  count: number;
  date: string;
}

const APIKeyStatsModal: React.FC<APIKeyStatsModalProps> = ({
  open,
  onClose,
  apiKeyId,
  apiKeyName,
}) => {
  const { t } = useTranslation(['settings', 'common']);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [usageData, setUsageData] = useState<UsageData[]>([]);
  const [tabValue, setTabValue] = useState(0);

  const fetchUsageData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      console.log('Fetching usage data for API key:', apiKeyId);
      const response = await api.get(`/api/api-keys/${apiKeyId}/usage`);
      console.log('Usage data response:', response);
      setUsageData(response.data || []);
    } catch (err: any) {
      console.error('Error fetching usage data:', err);
      setError(err.response?.data?.error || err.message || 'Failed to load usage data');
    } finally {
      setLoading(false);
    }
  }, [apiKeyId]);

  useEffect(() => {
    if (open && apiKeyId) {
      fetchUsageData();
    }
  }, [open, apiKeyId, fetchUsageData]);

  // Cores para diferentes métodos HTTP
  const methodColors: { [key: string]: string } = {
    GET: '#4CAF50',    // Verde
    POST: '#2196F3',   // Azul
    PUT: '#FF9800',    // Laranja
    DELETE: '#F44336', // Vermelho
    PATCH: '#9C27B0',  // Roxo
  };

  // Preparar dados para o gráfico por endpoint
  const prepareEndpointData = () => {
    const endpointMap: { [key: string]: { [method: string]: number } } = {};

    usageData.forEach((item) => {
      if (!endpointMap[item.endpoint]) {
        endpointMap[item.endpoint] = {};
      }
      if (!endpointMap[item.endpoint][item.method]) {
        endpointMap[item.endpoint][item.method] = 0;
      }
      endpointMap[item.endpoint][item.method] += item.count;
    });

    const endpoints = Object.keys(endpointMap).sort();
    const methods = [...new Set(usageData.map(d => d.method))].sort();

    const datasets = methods.map(method => ({
      label: method,
      data: endpoints.map(endpoint => endpointMap[endpoint][method] || 0),
      backgroundColor: methodColors[method] || '#666',
      borderColor: methodColors[method] || '#666',
      borderWidth: 1,
    }));

    return {
      labels: endpoints,
      datasets,
    };
  };

  // Preparar dados para o gráfico por data
  const prepareDateData = () => {
    const dateMap: { [key: string]: { [method: string]: number } } = {};

    usageData.forEach((item) => {
      if (!dateMap[item.date]) {
        dateMap[item.date] = {};
      }
      if (!dateMap[item.date][item.method]) {
        dateMap[item.date][item.method] = 0;
      }
      dateMap[item.date][item.method] += item.count;
    });

    const dates = Object.keys(dateMap).sort();
    const methods = [...new Set(usageData.map(d => d.method))].sort();

    const datasets = methods.map(method => ({
      label: method,
      data: dates.map(date => dateMap[date][method] || 0),
      backgroundColor: methodColors[method] || '#666',
      borderColor: methodColors[method] || '#666',
      borderWidth: 1,
    }));

    return {
      labels: dates,
      datasets,
    };
  };

  // Opções do gráfico
  const chartOptions: ChartOptions<'bar'> = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top' as const,
      },
      title: {
        display: true,
        text: (tabValue === 0 
          ? t('settings:apiKeys.stats.byEndpoint')
          : t('settings:apiKeys.stats.byDate')) as string,
      },
      tooltip: {
        callbacks: {
          label: (context) => {
            return `${context.dataset.label}: ${context.parsed.y} ${t('settings:apiKeys.stats.requests')}`;
          },
        },
      },
    },
    scales: {
      x: {
        stacked: true,
        ticks: {
          autoSkip: true,
          maxRotation: 45,
          minRotation: 45,
        },
      },
      y: {
        stacked: true,
        beginAtZero: true,
        ticks: {
          stepSize: 1,
        },
      },
    },
  };

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="lg" fullWidth>
      <DialogTitle>
        {t('settings:apiKeys.stats.title', { name: apiKeyName })}
      </DialogTitle>
      <DialogContent>
        {loading ? (
          <Box display="flex" justifyContent="center" alignItems="center" minHeight={400}>
            <CircularProgress />
          </Box>
        ) : error ? (
          <Alert severity="error" sx={{ mt: 2 }}>
            {error}
          </Alert>
        ) : usageData.length === 0 ? (
          <Alert severity="info" sx={{ mt: 2 }}>
            {t('settings:apiKeys.stats.noData')}
          </Alert>
        ) : (
          <Box>
            <Tabs value={tabValue} onChange={handleTabChange} sx={{ mb: 2 }}>
              <Tab label={t('settings:apiKeys.stats.byEndpoint')} />
              <Tab label={t('settings:apiKeys.stats.byDate')} />
            </Tabs>
            
            <Box sx={{ height: 400 }}>
              <Bar 
                data={tabValue === 0 ? prepareEndpointData() : prepareDateData()} 
                options={chartOptions} 
              />
            </Box>

            <Box sx={{ mt: 2 }}>
              <Typography variant="body2" color="text.secondary">
                {t('settings:apiKeys.stats.totalRequests')}: {usageData.reduce((sum, item) => sum + item.count, 0)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {t('settings:apiKeys.stats.uniqueEndpoints')}: {[...new Set(usageData.map(d => d.endpoint))].length}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {t('settings:apiKeys.stats.period')}: {t('settings:apiKeys.stats.last30Days')}
              </Typography>
            </Box>
          </Box>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>{t('close', { ns: 'common' })}</Button>
      </DialogActions>
    </Dialog>
  );
};

export default APIKeyStatsModal;