import React, { useEffect, useState, useCallback } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  ListItemSecondaryAction,
  IconButton,
  Chip,
  FormControlLabel,
  Switch,
  CircularProgress,
  Alert as MuiAlert,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Grid,
  Collapse,
  Pagination,
} from '@mui/material';
import {
  Warning as WarningIcon,
  Error as ErrorIcon,
  Info as InfoIcon,
  CheckCircle as CheckCircleIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
  Refresh as RefreshIcon,
  Block as BlockIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import queryAuditService, { QueryAuditAlert } from '../../services/queryAuditService';

interface QueryAuditAlertsProps {
  serverId: string;
  serverName: string;
}

export const QueryAuditAlerts: React.FC<QueryAuditAlertsProps> = ({
  serverId,
  serverName,
}) => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const [loading, setLoading] = useState(true);
  const [alerts, setAlerts] = useState<QueryAuditAlert[]>([]);
  const [unacknowledgedOnly, setUnacknowledgedOnly] = useState(true);
  const [selectedAlert, setSelectedAlert] = useState<QueryAuditAlert | null>(null);
  const [expandedAlerts, setExpandedAlerts] = useState<Set<string>>(new Set());
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [limit] = useState(25);

  useEffect(() => {
    setCurrentPage(1); // Reset to first page when filter changes
  }, [serverId, unacknowledgedOnly]);

  const loadAlerts = useCallback(async () => {
    try {
      setLoading(true);
      const offset = (currentPage - 1) * limit;
      const data = await queryAuditService.getAlerts(serverId, unacknowledgedOnly, limit, offset);
      console.log('Alerts API response:', data);
      setAlerts(Array.isArray(data.alerts) ? data.alerts : []);
      setTotalCount(data.total_count || 0);
      setTotalPages(data.total_pages || 1);
    } catch (error) {
      console.error('Error loading alerts:', error);
      setAlerts([]);
      setTotalCount(0);
      setTotalPages(1);
    } finally {
      setLoading(false);
    }
  }, [serverId, unacknowledgedOnly, currentPage, limit]);

  useEffect(() => {
    loadAlerts();
  }, [serverId, unacknowledgedOnly, currentPage, loadAlerts]);

  const handleAcknowledge = async (alertId: string) => {
    try {
      await queryAuditService.acknowledgeAlert(alertId);
      await loadAlerts();
    } catch (error) {
      console.error('Error acknowledging alert:', error);
    }
  };

  const handleWhitelist = async (alertId: string) => {
    try {
      await queryAuditService.whitelistQuery(alertId);
      await loadAlerts();
    } catch (error) {
      console.error('Error whitelisting query:', error);
    }
  };

  const handleClearAlerts = async () => {
    try {
      setLoading(true);
      // If unacknowledgedOnly is true, we want to clear only unacknowledged (acknowledged_only=false)
      // If unacknowledgedOnly is false, we want to clear all alerts (acknowledged_only=false)
      await queryAuditService.clearAlerts(serverId, 25, false);
      // Reset to first page after clearing
      setCurrentPage(1);
      await loadAlerts();
    } catch (error) {
      console.error('Error clearing alerts:', error);
    } finally {
      setLoading(false);
    }
  };

  const handlePageChange = (event: React.ChangeEvent<unknown>, value: number) => {
    setCurrentPage(value);
  };

  const toggleExpanded = (alertId: string) => {
    const newExpanded = new Set(expandedAlerts);
    if (newExpanded.has(alertId)) {
      newExpanded.delete(alertId);
    } else {
      newExpanded.add(alertId);
    }
    setExpandedAlerts(newExpanded);
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'critical':
      case 'high':
        return <ErrorIcon color="error" />;
      case 'medium':
        return <WarningIcon color="warning" />;
      case 'low':
        return <InfoIcon color="info" />;
      default:
        return <InfoIcon />;
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
      case 'high':
        return 'error';
      case 'medium':
        return 'warning';
      case 'low':
        return 'info';
      default:
        return 'default';
    }
  };

  const getAlertTypeLabel = (type: string) => {
    return t(`queryAudit:alerts.types.${type}`, type);
  };

  const groupAlertsByType = () => {
    const grouped: Record<string, QueryAuditAlert[]> = {};
    if (!alerts || !Array.isArray(alerts)) {
      return grouped;
    }
    alerts.forEach((alert) => {
      if (!grouped[alert.alert_type]) {
        grouped[alert.alert_type] = [];
      }
      grouped[alert.alert_type].push(alert);
    });
    return grouped;
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" p={4}>
        <CircularProgress />
      </Box>
    );
  }

  const groupedAlerts = groupAlertsByType();
  const alertTypes = Object.keys(groupedAlerts);

  return (
    <Box>
      {/* Controls */}
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <FormControlLabel
          control={
            <Switch
              checked={unacknowledgedOnly}
              onChange={(e) => setUnacknowledgedOnly(e.target.checked)}
            />
          }
          label={t('queryAudit:alerts.unacknowledgedOnly')}
        />
        <Box display="flex" gap={2}>
          <Button
            startIcon={<BlockIcon />}
            onClick={handleClearAlerts}
            variant="contained"
            color="warning"
            disabled={loading || !Array.isArray(alerts) || alerts.length === 0}
          >
            {t('queryAudit:alerts.clearAlerts')}
          </Button>
          <Button
            startIcon={<RefreshIcon />}
            onClick={loadAlerts}
            variant="outlined"
            disabled={loading}
          >
            {t('common:refresh')}
          </Button>
        </Box>
      </Box>

      {/* Alert Summary */}
      <Grid container spacing={2} mb={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:alerts.totalAlerts')}
              </Typography>
              <Typography variant="h4">
                {totalCount}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:alerts.critical')}
              </Typography>
              <Typography variant="h4" color="error">
                {Array.isArray(alerts) ? alerts.filter(a => a.severity === 'critical').length : 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:alerts.high')}
              </Typography>
              <Typography variant="h4" color="error">
                {Array.isArray(alerts) ? alerts.filter(a => a.severity === 'high').length : 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:alerts.unacknowledged')}
              </Typography>
              <Typography variant="h4">
                {Array.isArray(alerts) ? alerts.filter(a => !a.acknowledged).length : 0}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Alerts List */}
      {!Array.isArray(alerts) || alerts.length === 0 ? (
        <MuiAlert severity="info">
          {t('queryAudit:alerts.noAlerts')}
        </MuiAlert>
      ) : (
        <Box>
          {alertTypes.map((alertType) => (
            <Card key={alertType} sx={{ mb: 2 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {getAlertTypeLabel(alertType)}
                  <Chip 
                    label={groupedAlerts[alertType].length} 
                    size="small" 
                    sx={{ ml: 1 }}
                  />
                </Typography>
                <List>
                  {groupedAlerts[alertType].map((alert) => (
                    <React.Fragment key={alert.id}>
                      <ListItem>
                        <ListItemIcon>
                          {getSeverityIcon(alert.severity)}
                        </ListItemIcon>
                        <ListItemText
                          primary={
                            <Box display="flex" alignItems="center" gap={1}>
                              <Typography variant="body1">
                                {alert.alert_message}
                              </Typography>
                              <Chip
                                label={alert.severity}
                                size="small"
                                color={getSeverityColor(alert.severity) as any}
                              />
                              {alert.acknowledged && (
                                <Chip
                                  icon={<CheckCircleIcon />}
                                  label={t('queryAudit:alerts.acknowledged')}
                                  size="small"
                                  color="success"
                                  variant="outlined"
                                />
                              )}
                            </Box>
                          }
                          secondary={
                            <Box>
                              <Typography variant="caption" display="block">
                                {new Date(alert.created_at).toLocaleString()}
                              </Typography>
                              {alert.acknowledged && alert.acknowledged_by_name && (
                                <Typography variant="caption" display="block">
                                  {t('queryAudit:alerts.acknowledgedBy', {
                                    name: alert.acknowledged_by_name,
                                    date: new Date(alert.acknowledged_at!).toLocaleString()
                                  })}
                                </Typography>
                              )}
                            </Box>
                          }
                        />
                        <ListItemSecondaryAction>
                          <Box display="flex" alignItems="center">
                            {!alert.acknowledged && (
                              <>
                                <Button
                                  size="small"
                                  onClick={() => handleAcknowledge(alert.id)}
                                  sx={{ mr: 1 }}
                                >
                                  {t('queryAudit:alerts.acknowledge')}
                                </Button>
                                {/* Show whitelist button only for query-related alerts */}
                                {(alert.alert_type === 'slow_query' || 
                                  alert.alert_type === 'suspicious_query' ||
                                  alert.alert_type === 'failed_query') && (
                                  <Button
                                    size="small"
                                    startIcon={<BlockIcon />}
                                    onClick={() => handleWhitelist(alert.id)}
                                    sx={{ mr: 1 }}
                                    color="warning"
                                  >
                                    {t('queryAudit:alerts.whitelist')}
                                  </Button>
                                )}
                              </>
                            )}
                            <IconButton
                              edge="end"
                              onClick={() => toggleExpanded(alert.id)}
                            >
                              {expandedAlerts.has(alert.id) ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                            </IconButton>
                          </Box>
                        </ListItemSecondaryAction>
                      </ListItem>
                      <Collapse in={expandedAlerts.has(alert.id)}>
                        <Box px={9} pb={2}>
                          {alert.details && (
                            <Box>
                              <Typography variant="subtitle2" gutterBottom>
                                {t('queryAudit:alerts.details')}:
                              </Typography>
                              <Box
                                component="pre"
                                sx={{
                                  backgroundColor: 'grey.100',
                                  p: 1,
                                  borderRadius: 1,
                                  overflow: 'auto',
                                  fontSize: '0.875rem',
                                }}
                              >
                                {JSON.stringify(alert.details, null, 2)}
                              </Box>
                            </Box>
                          )}
                        </Box>
                      </Collapse>
                    </React.Fragment>
                  ))}
                </List>
              </CardContent>
            </Card>
          ))}

          {/* Pagination */}
          {totalPages > 1 && (
            <Box display="flex" justifyContent="center" mt={3}>
              <Pagination
                count={totalPages}
                page={currentPage}
                onChange={handlePageChange}
                color="primary"
                showFirstButton
                showLastButton
              />
            </Box>
          )}
        </Box>
      )}

      {/* Alert Details Dialog */}
      <Dialog
        open={!!selectedAlert}
        onClose={() => setSelectedAlert(null)}
        maxWidth="md"
        fullWidth
      >
        {selectedAlert && (
          <>
            <DialogTitle>
              {t('queryAudit:alerts.alertDetails')}
            </DialogTitle>
            <DialogContent>
              <Box mb={2}>
                <Typography variant="subtitle2" gutterBottom>
                  {t('queryAudit:alerts.type')}:
                </Typography>
                <Typography>{getAlertTypeLabel(selectedAlert.alert_type)}</Typography>
              </Box>
              <Box mb={2}>
                <Typography variant="subtitle2" gutterBottom>
                  {t('queryAudit:alerts.severity')}:
                </Typography>
                <Chip
                  label={selectedAlert.severity}
                  color={getSeverityColor(selectedAlert.severity) as any}
                />
              </Box>
              <Box mb={2}>
                <Typography variant="subtitle2" gutterBottom>
                  {t('queryAudit:alerts.message')}:
                </Typography>
                <Typography>{selectedAlert.alert_message}</Typography>
              </Box>
              {selectedAlert.details && (
                <Box mb={2}>
                  <Typography variant="subtitle2" gutterBottom>
                    {t('queryAudit:alerts.details')}:
                  </Typography>
                  <Box
                    component="pre"
                    sx={{
                      backgroundColor: 'grey.100',
                      p: 2,
                      borderRadius: 1,
                      overflow: 'auto',
                    }}
                  >
                    {JSON.stringify(selectedAlert.details, null, 2)}
                  </Box>
                </Box>
              )}
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setSelectedAlert(null)}>
                {t('common:close')}
              </Button>
              {!selectedAlert.acknowledged && (
                <Button
                  variant="contained"
                  onClick={() => {
                    handleAcknowledge(selectedAlert.id);
                    setSelectedAlert(null);
                  }}
                >
                  {t('queryAudit:alerts.acknowledge')}
                </Button>
              )}
            </DialogActions>
          </>
        )}
      </Dialog>
    </Box>
  );
};

export default QueryAuditAlerts;