import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Box,
  Paper,
  Typography,
  Grid,
  Card,
  CardContent,
  CircularProgress,
  Alert,
  Tab,
  Tabs,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  LinearProgress,
  Button,
  IconButton,
  Tooltip,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Divider,
  useTheme,
  alpha,
  styled,
} from '@mui/material';
import {
  Dashboard as DashboardIcon,
  Storage as StorageIcon,
  Speed as SpeedIcon,
  People as PeopleIcon,
  QueryBuilder as QueryIcon,
  Memory as MemoryIcon,
  Computer as ComputerIcon,
  Refresh as RefreshIcon,
  ArrowBack as ArrowBackIcon,
  Error as ErrorIcon,
  CheckCircle as CheckIcon,
  Timer as TimerIcon,
  DataUsage as DataUsageIcon,
} from '@mui/icons-material';
import { serverService } from '../../services/api';

// Styled Components
const MetricCard = styled(Card)(({ theme }) => ({
  height: '100%',
  transition: 'all 0.3s ease',
  '&:hover': {
    transform: 'translateY(-4px)',
    boxShadow: theme.shadows[8],
  },
}));

const MetricValue = styled(Typography)(({ theme }) => ({
  fontSize: '2.5rem',
  fontWeight: 700,
  color: theme.palette.primary.main,
}));

const ProgressBar = styled(LinearProgress)(({ theme }) => ({
  height: 8,
  borderRadius: 4,
  backgroundColor: alpha(theme.palette.primary.main, 0.1),
}));

interface Server {
  id: string;
  name: string;
  type: string;
  performance_schema_status?: string;
  pg_stat_statements_status?: string;
}

interface TableStat {
  schema: string;
  name: string;
  total_size: number;
  table_size: number;
  live_rows: number;
  dead_rows: number;
  dead_ratio: number;
  seq_scans: number;
  index_scans: number;
  index_usage_ratio: number;
  inserts: number;
  updates: number;
  deletes: number;
  hot_updates: number;
  hot_update_ratio: number;
  last_vacuum?: string;
  last_autovacuum?: string;
  last_analyze?: string;
  last_autoanalyze?: string;
}

interface IndexStat {
  schema: string;
  table: string;
  name: string;
  size: number;
  scans: number;
  tuples_read: number;
  tuples_fetched: number;
  avg_tuples_per_scan: number;
}

interface DatabaseStat {
  name: string;
  size: number;
  connections: number;
  commits: number;
  rollbacks: number;
  disk_reads: number;
  cache_hits: number;
  cache_hit_ratio: number;
  rows_returned: number;
  rows_fetched: number;
  rows_inserted: number;
  rows_updated: number;
  rows_deleted: number;
  deadlocks: number;
  temp_files: number;
  temp_bytes: number;
}

interface ServerMetrics {
  server_id: string;
  server_name: string;
  server_type: string;
  collected_at: string;
  query_metrics?: {
    total_queries: number;
    queries_per_second: number;
    slow_queries: number;
    user_query_stats?: Array<{
      username: string;
      total_queries: number;
      select_count?: number;
      insert_count?: number;
      update_count?: number;
      delete_count?: number;
      grant_revoke_count?: number;
      total_time_ms?: number;
      average_time_ms?: number;
      total_time?: number;
      avg_time?: number;
    }>;
    user_statistics?: Array<{
      username: string;
      total_queries: number;
      select_count?: number;
      insert_count?: number;
      update_count?: number;
      delete_count?: number;
      grant_revoke_count?: number;
      total_time?: number;
      avg_time?: number;
      average_time_ms?: number;
    }>;
    top_queries?: Array<{
      query_pattern?: string;
      query?: string;
      execution_count?: number;
      calls?: number;
      total_time_ms?: number;
      total_time?: number;
      average_time_ms?: number;
      avg_time?: number;
      max_time_ms?: number;
      max_time?: number;
      min_time_ms?: number;
      rows_examined?: number;
      rows_sent?: number;
      rows?: number;
    }>;
  };
  session_metrics?: {
    total_connections?: number;
    active_connections?: number;
    idle_connections?: number;
    max_connections?: number;
    user_sessions?: Array<{
      username: string;
      active_sessions: number;
      total_connections: number;
      current_database?: string;
      connected_from?: string;
    }>;
    user_connections?: Array<{
      username: string;
      connections: number;
    }>;
    connections_by_host?: { [key: string]: number };
    host_connections?: Array<{
      host: string;
      connections: number;
    }>;
    sessions_by_state?: { [key: string]: number };
  };
  process_metrics?: {
    total_processes: number;
    active_processes: number;
    sleeping_processes: number;
    process_list: Array<{
      id: number;
      user: string;
      host: string;
      database?: string;
      command: string;
      time_seconds: number;
      state?: string;
      info?: string;
    }>;
  };
  resource_metrics?: {
    database_sizes?: Array<{
      database_name?: string;
      database?: string;
      size_mb?: number;
      size?: number;
      table_count?: number;
      size_formatted?: string;
    }>;
    table_sizes?: Array<{
      database_name?: string;
      table_name?: string;
      table?: string;
      row_count?: number;
      data_size?: number;
      index_size?: number;
      data_size_mb?: number;
      index_size_mb?: number;
      total_size_mb?: number;
      size?: number;
      size_formatted?: string;
      data_size_formatted?: string;
      index_size_formatted?: string;
    }>;
  };
  table_metrics?: {
    tables?: Array<TableStat>;
    collected_at?: string;
  };
  index_metrics?: {
    indexes?: Array<IndexStat>;
    unused_indexes?: number;
    duplicate_indexes?: number;
    collected_at?: string;
  };
  database_metrics?: {
    databases?: Array<DatabaseStat>;
    collected_at?: string;
  };
  error?: string;
}

export const ServerMetricsPage: React.FC = () => {
  const { serverId } = useParams<{ serverId: string }>();
  const navigate = useNavigate();
  const { t } = useTranslation(['metrics', 'common']);
  const theme = useTheme();

  const [metrics, setMetrics] = useState<ServerMetrics | null>(null);
  const [server, setServer] = useState<Server | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  const fetchMetrics = async () => {
    if (!serverId) return;
    
    setLoading(true);
    setError(null);
    
    try {
      // Buscar informações do servidor primeiro
      const serverResponse = await serverService.getServerById(serverId);
      if (serverResponse.server) {
        setServer(serverResponse.server);
      }
      
      // Buscar métricas com todos os tipos
      const metricTypes = ['query', 'session', 'process', 'resource'];
      if (serverResponse.server?.type === 'postgres') {
        metricTypes.push('database', 'table', 'index');
      }
      
      const response = await serverService.getMetrics(serverId, metricTypes);
      console.log('Metrics response:', response);
      console.log('Metrics data:', response.metrics);
      console.log('Table metrics:', response.metrics?.table_metrics);
      console.log('Index metrics:', response.metrics?.index_metrics);
      console.log('Database metrics:', response.metrics?.database_metrics);
      if (response.success && response.metrics) {
        setMetrics(response.metrics);
      } else {
        setError(response.message || 'Erro ao carregar métricas');
      }
    } catch (err: any) {
      setError(err.message || 'Erro ao conectar com o servidor');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchMetrics();
  }, [serverId]);

  // Debug effect
  useEffect(() => {
    console.log('Current tab:', activeTab);
    console.log('isPostgres:', isPostgres);
    console.log('Table metrics:', metrics?.table_metrics);
    console.log('Index metrics:', metrics?.index_metrics);
    console.log('Database metrics:', metrics?.database_metrics);
  }, [activeTab, metrics]);

  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      // Limpar cache antes de buscar novas métricas
      if (serverId) {
        await serverService.clearMetricsCache(serverId);
      }
      await fetchMetrics();
    } catch (err) {
      console.error('Erro ao atualizar métricas:', err);
      setRefreshing(false);
    }
  };

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    console.log('Tab changed to:', newValue);
    setActiveTab(newValue);
  };

  const formatBytes = (bytes: number): string => {
    if (!bytes || bytes === 0) return '0 MB';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatTime = (ms: number): string => {
    if (!ms || ms === 0) return '0.00 ms';
    if (ms < 1000) return `${ms.toFixed(2)} ms`;
    return `${(ms / 1000).toFixed(2)} s`;
  };

  const formatMicrosToMs = (micros: number): string => {
    const ms = micros / 1000;
    return formatTime(ms);
  };

  const isPostgres = server?.type === 'postgres';
  const isMySQL = server?.type === 'mysql' || server?.type === 'mariadb';
  const isMSSQL = server?.type === 'mssql';

  const formatNumber = (num: number): string => {
    return new Intl.NumberFormat('pt-BR').format(num);
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3}>
        <Alert severity="error" icon={<ErrorIcon />}>
          {error}
        </Alert>
        <Box mt={2}>
          <Button
            variant="contained"
            startIcon={<ArrowBackIcon />}
            onClick={() => navigate('/servers')}
          >
            Voltar para Servidores
          </Button>
        </Box>
      </Box>
    );
  }

  if (!metrics) {
    return (
      <Box p={3}>
        <Alert severity="warning">Nenhuma métrica disponível</Alert>
        <Box mt={2}>
          <Button
            variant="contained"
            startIcon={<ArrowBackIcon />}
            onClick={() => navigate('/servers')}
          >
            Voltar para Servidores
          </Button>
        </Box>
      </Box>
    );
  }

  // Verificar se há erro nas métricas
  if (metrics.error) {
    return (
      <Box p={3}>
        <Alert severity="error" icon={<ErrorIcon />}>
          {metrics.error}
        </Alert>
        <Box mt={2}>
          <Button
            variant="outlined"
            startIcon={<RefreshIcon />}
            onClick={handleRefresh}
            sx={{ mr: 2 }}
          >
            Tentar Novamente
          </Button>
          <Button
            variant="contained"
            startIcon={<ArrowBackIcon />}
            onClick={() => navigate('/servers')}
          >
            Voltar para Servidores
          </Button>
        </Box>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Box display="flex" alignItems="center" gap={2}>
          <IconButton onClick={() => navigate('/servers')}>
            <ArrowBackIcon />
          </IconButton>
          <Box>
            <Typography variant="h4" fontWeight={700}>
              {t('title')} - {metrics.server_name}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {t('lastUpdate')}: {new Date(metrics.collected_at).toLocaleString('pt-BR')}
            </Typography>
          </Box>
        </Box>
        <Button
          variant="outlined"
          startIcon={refreshing ? <CircularProgress size={20} /> : <RefreshIcon />}
          onClick={handleRefresh}
          disabled={refreshing}
        >
          {t('refresh')}
        </Button>
      </Box>

      {/* Performance Schema Status for MySQL */}
      {server?.type === 'mysql' && server?.performance_schema_status && server.performance_schema_status !== 'Performance Schema já está habilitado' && (
        <Alert 
          severity="info" 
          sx={{ mb: 3, whiteSpace: 'pre-line' }}
          action={
            server.performance_schema_status.includes('está desabilitado') ? (
              <Button color="inherit" size="small" onClick={() => window.open('https://dev.mysql.com/doc/refman/8.0/en/performance-schema-startup-configuration.html', '_blank')}>
                Documentação
              </Button>
            ) : undefined
          }
        >
          <Typography variant="subtitle2" fontWeight={600} gutterBottom>
            Status do Performance Schema
          </Typography>
          {server.performance_schema_status}
        </Alert>
      )}

      {/* pg_stat_statements Status for PostgreSQL */}
      {server?.type === 'postgres' && server?.pg_stat_statements_status && (
        <Alert 
          severity="info" 
          sx={{ mb: 3, whiteSpace: 'pre-line' }}
          action={
            server.pg_stat_statements_status.includes('não está instalada') ? (
              <Button color="inherit" size="small" onClick={() => window.open('https://www.postgresql.org/docs/current/pgstatstatements.html', '_blank')}>
                Documentação
              </Button>
            ) : undefined
          }
        >
          <Typography variant="subtitle2" fontWeight={600} gutterBottom>
            Status do pg_stat_statements
          </Typography>
          {server.pg_stat_statements_status}
        </Alert>
      )}

      {/* Error Message if any */}
      {metrics.error && (
        <Alert severity="warning" sx={{ mb: 3 }}>
          {metrics.error}
        </Alert>
      )}

      {/* Overview Cards */}
      <Grid container spacing={3} mb={3}>
        <Grid item xs={12} sm={6} md={3}>
          <MetricCard>
            <CardContent>
              <Box display="flex" alignItems="center" justifyContent="space-between">
                <Box>
                  <Typography color="text.secondary" gutterBottom>
                    {t('totalQueries')}
                  </Typography>
                  <MetricValue>
                    {formatNumber(metrics.query_metrics?.total_queries || 0)}
                  </MetricValue>
                </Box>
                <QueryIcon sx={{ fontSize: 40, color: theme.palette.primary.light }} />
              </Box>
            </CardContent>
          </MetricCard>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <MetricCard>
            <CardContent>
              <Box display="flex" alignItems="center" justifyContent="space-between">
                <Box>
                  <Typography color="text.secondary" gutterBottom>
                    {t('activeConnections')}
                  </Typography>
                  <MetricValue>
                    {metrics.session_metrics?.active_connections || 0}
                  </MetricValue>
                </Box>
                <PeopleIcon sx={{ fontSize: 40, color: theme.palette.success.light }} />
              </Box>
            </CardContent>
          </MetricCard>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <MetricCard>
            <CardContent>
              <Box display="flex" alignItems="center" justifyContent="space-between">
                <Box>
                  <Typography color="text.secondary" gutterBottom>
                    {t('slowQueries')}
                  </Typography>
                  <MetricValue>
                    {formatNumber(metrics.query_metrics?.slow_queries || 0)}
                  </MetricValue>
                </Box>
                <TimerIcon sx={{ fontSize: 40, color: theme.palette.warning.light }} />
              </Box>
            </CardContent>
          </MetricCard>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <MetricCard>
            <CardContent>
              <Box display="flex" alignItems="center" justifyContent="space-between">
                <Box>
                  <Typography color="text.secondary" gutterBottom>
                    {t('totalProcesses')}
                  </Typography>
                  <MetricValue>
                    {metrics.process_metrics?.total_processes || 0}
                  </MetricValue>
                </Box>
                <ComputerIcon sx={{ fontSize: 40, color: theme.palette.info.light }} />
              </Box>
            </CardContent>
          </MetricCard>
        </Grid>
      </Grid>

      {/* Tabs */}
      <Paper sx={{ mb: 3 }}>
        <Tabs value={activeTab} onChange={handleTabChange} variant="scrollable" scrollButtons="auto">
          <Tab label={t('queryMetrics')} icon={<QueryIcon />} iconPosition="start" />
          <Tab label={t('sessionMetrics')} icon={<PeopleIcon />} iconPosition="start" />
          <Tab label={t('processMetrics')} icon={<ComputerIcon />} iconPosition="start" />
          <Tab label={t('resourceMetrics')} icon={<StorageIcon />} iconPosition="start" />
          {isPostgres && (
            <>
              <Tab 
                label={t('tableMetrics')} 
                icon={<StorageIcon />} 
                iconPosition="start"
                disabled={!metrics.table_metrics}
              />
              <Tab 
                label={t('indexMetrics')} 
                icon={<SpeedIcon />} 
                iconPosition="start"
                disabled={!metrics.index_metrics}
              />
              <Tab 
                label={t('databaseMetrics')} 
                icon={<StorageIcon />} 
                iconPosition="start"
                disabled={!metrics.database_metrics}
              />
            </>
          )}
        </Tabs>
      </Paper>

      {/* Tab Content */}
      <Paper sx={{ p: 3 }}>
        {/* Query Metrics Tab */}
        {activeTab === 0 && metrics.query_metrics && (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('userQueryStats')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('username')}</TableCell>
                    <TableCell align="right">{t('totalQueries')}</TableCell>
                    <TableCell align="right">SELECT</TableCell>
                    <TableCell align="right">INSERT</TableCell>
                    <TableCell align="right">UPDATE</TableCell>
                    <TableCell align="right">DELETE</TableCell>
                    <TableCell align="right">GRANT/REVOKE</TableCell>
                    <TableCell align="right">{t('avgTime')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {(metrics.query_metrics.user_query_stats || metrics.query_metrics.user_statistics)?.map((stat) => (
                    <TableRow key={stat.username}>
                      <TableCell>{stat.username}</TableCell>
                      <TableCell align="right">{formatNumber(stat.total_queries)}</TableCell>
                      <TableCell align="right">{formatNumber(stat.select_count || 0)}</TableCell>
                      <TableCell align="right">{formatNumber(stat.insert_count || 0)}</TableCell>
                      <TableCell align="right">{formatNumber(stat.update_count || 0)}</TableCell>
                      <TableCell align="right">{formatNumber(stat.delete_count || 0)}</TableCell>
                      <TableCell align="right">{formatNumber(stat.grant_revoke_count || 0)}</TableCell>
                      <TableCell align="right">{formatTime(stat.average_time_ms || stat.avg_time || 0)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Typography variant="h6" gutterBottom sx={{ mt: 4 }}>
              {t('topQueries')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('query')}</TableCell>
                    <TableCell align="right">{t('executions')}</TableCell>
                    <TableCell align="right">{t('avgTime')}</TableCell>
                    <TableCell align="right">{t('maxTime')}</TableCell>
                    {!isPostgres && <TableCell align="right">{t('rowsExamined')}</TableCell>}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.query_metrics.top_queries?.map((query, index) => (
                    <TableRow key={index}>
                      <TableCell>
                        <Tooltip title={query.query_pattern || query.query}>
                          <Typography variant="body2" noWrap sx={{ maxWidth: 400 }}>
                            {query.query_pattern || query.query}
                          </Typography>
                        </Tooltip>
                      </TableCell>
                      <TableCell align="right">{formatNumber(query.execution_count || query.calls || 0)}</TableCell>
                      <TableCell align="right">{formatTime(query.average_time_ms || query.avg_time || 0)}</TableCell>
                      <TableCell align="right">{formatTime(query.max_time_ms || query.max_time || 0)}</TableCell>
                      {!isPostgres && <TableCell align="right">{formatNumber(query.rows_examined || query.rows || 0)}</TableCell>}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}

        {/* Session Metrics Tab */}
        {activeTab === 1 && metrics.session_metrics && (
          <Box>
            <Grid container spacing={3} mb={3}>
              <Grid item xs={12} md={6}>
                <Typography variant="h6" gutterBottom>
                  {t('connectionOverview')}
                </Typography>
                <List>
                  <ListItem>
                    <ListItemText
                      primary={t('totalConnections')}
                      secondary={formatNumber(metrics.session_metrics.total_connections || 0)}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemText
                      primary={t('activeConnections')}
                      secondary={formatNumber(metrics.session_metrics.active_connections || 0)}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemText
                      primary={t('idleConnections')}
                      secondary={formatNumber(metrics.session_metrics.idle_connections || 0)}
                    />
                  </ListItem>
                </List>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="h6" gutterBottom>
                  {t('connectionsByHost')}
                </Typography>
                <List>
                  {(metrics.session_metrics.connections_by_host ? 
                    Object.entries(metrics.session_metrics.connections_by_host).map(([host, count]) => (
                      <ListItem key={host}>
                        <ListItemText
                          primary={host}
                          secondary={`${count} ${t('connections')}`}
                        />
                      </ListItem>
                    )) :
                    metrics.session_metrics.host_connections?.map((conn: any) => (
                      <ListItem key={conn.host}>
                        <ListItemText
                          primary={conn.host}
                          secondary={`${conn.connections} ${t('connections')}`}
                        />
                      </ListItem>
                    ))
                  )}
                </List>
              </Grid>
            </Grid>

            <Typography variant="h6" gutterBottom>
              {t('userConnections')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('username')}</TableCell>
                    <TableCell align="right">{t('connections')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {(metrics.session_metrics.user_sessions || metrics.session_metrics.user_connections)?.map((session: any) => (
                    <TableRow key={session.username}>
                      <TableCell>{session.username}</TableCell>
                      <TableCell align="right">{session.active_sessions || session.connections || 0}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}

        {/* Process Metrics Tab */}
        {activeTab === 2 && metrics.process_metrics && (
          <Box>
            <Grid container spacing={3} mb={3}>
              <Grid item xs={12} md={4}>
                <Paper sx={{ p: 2, textAlign: 'center' }}>
                  <Typography variant="h4" color="primary">
                    {metrics.process_metrics.total_processes}
                  </Typography>
                  <Typography color="text.secondary">{t('totalProcesses')}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={4}>
                <Paper sx={{ p: 2, textAlign: 'center' }}>
                  <Typography variant="h4" color="success.main">
                    {metrics.process_metrics.active_processes}
                  </Typography>
                  <Typography color="text.secondary">{t('activeProcesses')}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={4}>
                <Paper sx={{ p: 2, textAlign: 'center' }}>
                  <Typography variant="h4" color="warning.main">
                    {metrics.process_metrics.sleeping_processes}
                  </Typography>
                  <Typography color="text.secondary">{t('sleepingProcesses')}</Typography>
                </Paper>
              </Grid>
            </Grid>

            <Typography variant="h6" gutterBottom>
              {t('processList')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>ID</TableCell>
                    <TableCell>{t('user')}</TableCell>
                    <TableCell>{t('host')}</TableCell>
                    <TableCell>{t('database')}</TableCell>
                    <TableCell>{t('command')}</TableCell>
                    <TableCell align="right">{t('time')}</TableCell>
                    <TableCell>{t('state')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.process_metrics.process_list?.map((process) => (
                    <TableRow key={process.id}>
                      <TableCell>{process.id}</TableCell>
                      <TableCell>{process.user}</TableCell>
                      <TableCell>{process.host}</TableCell>
                      <TableCell>{process.database || '-'}</TableCell>
                      <TableCell>
                        <Chip
                          label={process.command}
                          size="small"
                          color={process.command === 'Sleep' ? 'default' : 'primary'}
                        />
                      </TableCell>
                      <TableCell align="right">{process.time_seconds}s</TableCell>
                      <TableCell>{process.state || '-'}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}

        {/* Resource Metrics Tab */}
        {activeTab === 3 && metrics.resource_metrics && (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('databaseSizes')}
            </Typography>
            <Grid container spacing={2} mb={4}>
              {metrics.resource_metrics.database_sizes?.map((db) => (
                <Grid item xs={12} md={6} key={db.database_name || db.database}>
                  <Paper sx={{ p: 2 }}>
                    <Typography variant="subtitle1" fontWeight={600}>
                      {db.database_name || db.database}
                    </Typography>
                    <Box display="flex" justifyContent="space-between" alignItems="center" mt={1}>
                      <Typography variant="body2" color="text.secondary">
                        {db.table_count || 0} {t('tables')}
                      </Typography>
                      <Typography variant="h6" color="primary">
                        {db.size_formatted || formatBytes(db.size || 0)}
                      </Typography>
                    </Box>
                  </Paper>
                </Grid>
              ))}
            </Grid>

            <Typography variant="h6" gutterBottom>
              {t('largestTables')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('database')}</TableCell>
                    <TableCell>{t('table')}</TableCell>
                    <TableCell align="right">{t('rows')}</TableCell>
                    <TableCell align="right">{t('dataSize')}</TableCell>
                    <TableCell align="right">{t('indexSize')}</TableCell>
                    <TableCell align="right">{t('totalSize')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.resource_metrics.table_sizes?.map((table, index) => {
                    const [dbName, tableName] = (table.table || '').split('.');
                    return (
                      <TableRow key={index}>
                        <TableCell>{table.database_name || dbName}</TableCell>
                        <TableCell>{table.table_name || tableName}</TableCell>
                        <TableCell align="right">{formatNumber(table.row_count || 0)}</TableCell>
                        <TableCell align="right">{table.data_size_formatted || formatBytes(table.data_size || 0)}</TableCell>
                        <TableCell align="right">{table.index_size_formatted || formatBytes(table.index_size || 0)}</TableCell>
                        <TableCell align="right">
                          <Typography variant="body2" fontWeight={600}>
                            {table.size_formatted || formatBytes(table.size || 0)}
                          </Typography>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}

        {/* Table Metrics Tab (PostgreSQL only) */}
        {activeTab === 4 && isPostgres && metrics.table_metrics && (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('topTablesBySize')}
            </Typography>
            <TableContainer sx={{ mb: 4 }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('schema')}</TableCell>
                    <TableCell>{t('table')}</TableCell>
                    <TableCell align="right">{t('totalSize')}</TableCell>
                    <TableCell align="right">{t('tableSize')}</TableCell>
                    <TableCell align="right">{t('indexesSize')}</TableCell>
                    <TableCell align="right">{t('rowEstimate')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.table_metrics?.tables?.sort((a, b) => b.total_size - a.total_size).slice(0, 20).map((table, index) => (
                    <TableRow key={index}>
                      <TableCell>{table.schema}</TableCell>
                      <TableCell>{table.name}</TableCell>
                      <TableCell align="right">{formatBytes(table.total_size)}</TableCell>
                      <TableCell align="right">{formatBytes(table.table_size)}</TableCell>
                      <TableCell align="right">{formatBytes(table.total_size - table.table_size)}</TableCell>
                      <TableCell align="right">{formatNumber(table.live_rows)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Typography variant="h6" gutterBottom>
              {t('topTablesByActivity')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('schema')}</TableCell>
                    <TableCell>{t('table')}</TableCell>
                    <TableCell align="right">{t('seqScans')}</TableCell>
                    <TableCell align="right">{t('indexScans')}</TableCell>
                    <TableCell align="right">{t('inserts')}</TableCell>
                    <TableCell align="right">{t('updates')}</TableCell>
                    <TableCell align="right">{t('deletes')}</TableCell>
                    <TableCell>{t('lastVacuum')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.table_metrics?.tables?.sort((a, b) => (b.seq_scans + b.index_scans) - (a.seq_scans + a.index_scans)).slice(0, 20).map((table, index) => (
                    <TableRow key={index}>
                      <TableCell>{table.schema}</TableCell>
                      <TableCell>{table.name}</TableCell>
                      <TableCell align="right">{formatNumber(table.seq_scans)}</TableCell>
                      <TableCell align="right">{formatNumber(table.index_scans)}</TableCell>
                      <TableCell align="right">{formatNumber(table.inserts)}</TableCell>
                      <TableCell align="right">{formatNumber(table.updates)}</TableCell>
                      <TableCell align="right">{formatNumber(table.deletes)}</TableCell>
                      <TableCell>
                        {table.last_autovacuum ? 
                          new Date(table.last_autovacuum).toLocaleDateString() : 
                          '-'
                        }
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}

        {/* Index Metrics Tab (PostgreSQL only) */}
        {activeTab === 5 && isPostgres && metrics.index_metrics && (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('unusedIndexes')} ({metrics.index_metrics?.indexes?.filter(idx => idx.scans === 0).length || 0})
            </Typography>
            <TableContainer sx={{ mb: 4 }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('schema')}</TableCell>
                    <TableCell>{t('table')}</TableCell>
                    <TableCell>{t('index')}</TableCell>
                    <TableCell align="right">{t('size')}</TableCell>
                    <TableCell align="right">{t('scans')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.index_metrics?.indexes?.filter(idx => idx.scans === 0).map((index, idx) => (
                    <TableRow key={idx}>
                      <TableCell>{index.schema}</TableCell>
                      <TableCell>{index.table}</TableCell>
                      <TableCell>{index.name}</TableCell>
                      <TableCell align="right">{formatBytes(index.size)}</TableCell>
                      <TableCell align="right">
                        <Chip
                          label={index.scans}
                          size="small"
                          color={index.scans === 0 ? 'error' : 'default'}
                        />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Typography variant="h6" gutterBottom>
              {t('indexUsage')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('schema')}</TableCell>
                    <TableCell>{t('table')}</TableCell>
                    <TableCell>{t('index')}</TableCell>
                    <TableCell align="right">{t('scans')}</TableCell>
                    <TableCell align="right">{t('rowsRead')}</TableCell>
                    <TableCell align="right">{t('rowsFetched')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.index_metrics?.indexes?.filter(idx => idx.scans > 0).sort((a, b) => b.scans - a.scans).slice(0, 20).map((index, idx) => (
                    <TableRow key={idx}>
                      <TableCell>{index.schema}</TableCell>
                      <TableCell>{index.table}</TableCell>
                      <TableCell>{index.name}</TableCell>
                      <TableCell align="right">{formatNumber(index.scans)}</TableCell>
                      <TableCell align="right">{formatNumber(index.tuples_read)}</TableCell>
                      <TableCell align="right">{formatNumber(index.tuples_fetched)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}

        {/* Database Metrics Tab (PostgreSQL only) */}
        {activeTab === 6 && isPostgres && metrics.database_metrics && (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('databaseStatistics')}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('database')}</TableCell>
                    <TableCell align="right">{t('size')}</TableCell>
                    <TableCell align="right">{t('connections')}</TableCell>
                    <TableCell align="right">{t('commits')}</TableCell>
                    <TableCell align="right">{t('rollbacks')}</TableCell>
                    <TableCell align="right">{t('blocksRead')}</TableCell>
                    <TableCell align="right">{t('blocksHit')}</TableCell>
                    <TableCell align="right">{t('tempFiles')}</TableCell>
                    <TableCell align="right">{t('deadlocks')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {metrics.database_metrics?.databases?.map((db: DatabaseStat) => (
                    <TableRow key={db.name}>
                      <TableCell>{db.name}</TableCell>
                      <TableCell align="right">{formatBytes(db.size)}</TableCell>
                      <TableCell align="right">{formatNumber(db.connections)}</TableCell>
                      <TableCell align="right">{formatNumber(db.commits)}</TableCell>
                      <TableCell align="right">{formatNumber(db.rollbacks)}</TableCell>
                      <TableCell align="right">{formatNumber(db.disk_reads)}</TableCell>
                      <TableCell align="right">{formatNumber(db.cache_hits)}</TableCell>
                      <TableCell align="right">{formatNumber(db.temp_files)}</TableCell>
                      <TableCell align="right">
                        <Chip
                          label={db.deadlocks}
                          size="small"
                          color={db.deadlocks > 0 ? 'error' : 'success'}
                        />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            {/* Cache Hit Ratio */}
            <Box mt={4}>
              <Typography variant="h6" gutterBottom>
                {t('cacheHitRatio')}
              </Typography>
              <Grid container spacing={2}>
                {metrics.database_metrics?.databases?.map((db: DatabaseStat) => {
                  const hitRatio = db.cache_hits > 0 ? (
                    db.cache_hits && db.disk_reads ? ((db.cache_hits / (db.cache_hits + db.disk_reads)) * 100).toFixed(2) : '0.00'
                  ) : '0.00';
                  return (
                    <Grid item xs={12} md={6} key={db.name}>
                      <Paper sx={{ p: 2 }}>
                        <Typography variant="subtitle1" fontWeight={600}>
                          {db.name}
                        </Typography>
                        <Box mt={1}>
                          <LinearProgress 
                            variant="determinate" 
                            value={parseFloat(hitRatio)} 
                            sx={{ height: 10, borderRadius: 5 }}
                            color={parseFloat(hitRatio) > 90 ? 'success' : 'warning'}
                          />
                          <Typography variant="body2" color="text.secondary" align="right" mt={0.5}>
                            {hitRatio}%
                          </Typography>
                        </Box>
                      </Paper>
                    </Grid>
                  );
                })}
              </Grid>
            </Box>
          </Box>
        )}
      </Paper>
    </Box>
  );
};