interface CloudCredentials {
  id: string;
  provider: string;
  name: string;
  description: string;
  environment?: 'dev' | 'qa' | 'staging' | 'prod';
  is_default: boolean;
  validated_at: string | null;
  validation_error: string | null;
  created_at: string;
  updated_at: string;
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`cloud-tabpanel-${index}`}
      aria-labelledby={`cloud-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const CloudProviderConfigPage: React.FC = () => {
  const { t } = useTranslation(['cloud', 'common']);
  const [tabValue, setTabValue] = useState(0);
  const [loading, setLoading] = useState(false);
  const [credentials, setCredentials] = useState<CloudCredentials[]>([]);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedCredential, setSelectedCredential] = useState<CloudCredentials | null>(null);
  const [showPasswords, setShowPasswords] = useState<{ [key: string]: boolean }>({});
  const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
    open: false,
    message: '',
    severity: 'success'
  });

  const [formData, setFormData] = useState({
    provider: 'aws',
    name: '',
    description: '',
    environment: 'prod' as 'dev' | 'qa' | 'staging' | 'prod',
    credentials: {
      accessKeyId: '',
      secretAccessKey: '',
      region: 'us-east-1',
      clientId: '',
      clientSecret: '',
      tenantId: '',
      subscriptionId: '',
      projectId: '',
      privateKey: '',
    },
    is_default: false,
  });

  useEffect(() => {
    fetchCredentials();
  }, []);

  const fetchCredentials = async () => {
    try {
      setLoading(true);
      const response = await api.get('/cloud/credentials');
      setCredentials(response.data.data || []);
    } catch (error: any) {
      setSnackbar({ open: true, message: t('credentials.fetchError'), severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  const getProviderIcon = (provider: string) => {
    switch (provider) {
      case 'aws':
        return <AWSIcon sx={{ color: '#FF9900' }} />;
      case 'azure':
        return <AzureIcon sx={{ color: '#0078D4' }} />;
      case 'gcp':
        return <GCPIcon sx={{ color: '#4285F4' }} />;
      default:
        return <CloudIcon />;
    }
  };

  const handleTestConnection = async (credentialId: string) => {
    try {
      setLoading(true);
      const response = await api.post(`/cloud/credentials/${credentialId}/test`);
      if (response.data.success) {
      setSnackbar({ open: true, message: t('providers.connectionSuccess'), severity: 'success' });
        fetchCredentials();
      } else {
        setSnackbar({ open: true, message: response.data.error || t('providers.connectionFailed'), severity: 'error' });
      }
    } catch (error: any) {
      setSnackbar({ open: true, message: error.response?.data?.error || t('providers.connectionFailed'), severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleSaveCredentials = async () => {
    try {
      setLoading(true);

      const credentialsData = {
        provider: formData.provider,
        name: formData.name,
        description: formData.description,
        environment: formData.environment,
        is_default: formData.is_default,
        credentials: {},
      };

      switch (formData.provider) {
        case 'aws':
          credentialsData.credentials = {
            accessKeyId: formData.credentials.accessKeyId,
            secretAccessKey: formData.credentials.secretAccessKey,
            region: formData.credentials.region,
          };
          break;
        case 'azure':
          credentialsData.credentials = {
            clientId: formData.credentials.clientId,
            clientSecret: formData.credentials.clientSecret,
            tenantId: formData.credentials.tenantId,
            subscriptionId: formData.credentials.subscriptionId,
          };
          break;
        case 'gcp':
          credentialsData.credentials = {
            projectId: formData.credentials.projectId,
            privateKey: formData.credentials.privateKey,
          };
          break;
      }

      if (selectedCredential) {
        await api.put(`/cloud/credentials/${selectedCredential.id}`, credentialsData);
        setSnackbar({ open: true, message: t('credentials.updateSuccess'), severity: 'success' });
      } else {
        await api.post('/cloud/credentials', credentialsData);
        setSnackbar({ open: true, message: t('credentials.createSuccess'), severity: 'success' });
      }

      setEditDialogOpen(false);
      resetForm();
      fetchCredentials();
    } catch (error: any) {
      setSnackbar({ open: true, message: error.response?.data?.error || t('credentials.saveError'), severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCredentials = async () => {
    if (!selectedCredential) return;

    try {
      setLoading(true);
      await api.delete(`/cloud/credentials/${selectedCredential.id}`);
      setSnackbar({ open: true, message: t('credentials.deleteSuccess'), severity: 'success' });
      setDeleteDialogOpen(false);
      setSelectedCredential(null);
      fetchCredentials();
    } catch (error: any) {
      setSnackbar({ open: true, message: error.response?.data?.error || t('credentials.deleteError'), severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      provider: 'aws',
      name: '',
      description: '',
      environment: 'prod',
      credentials: {
        accessKeyId: '',
        secretAccessKey: '',
        region: 'us-east-1',
        clientId: '',
        clientSecret: '',
        tenantId: '',
        subscriptionId: '',
        projectId: '',
        privateKey: '',
      },
      is_default: false,
    });
    setSelectedCredential(null);
  };

  const openEditDialog = (credential?: CloudCredentials, defaultProvider?: string) => {
    if (credential) {
      setSelectedCredential(credential);
      setFormData({
        provider: credential.provider,
        name: credential.name,
        description: credential.description,
        environment: credential.environment || 'prod',
        credentials: {
          accessKeyId: '',
          secretAccessKey: '',
          region: credential.provider === 'aws' ? 'us-east-1' :
                  credential.provider === 'azure' ? 'eastus' :
                  'us-central1',
          clientId: '',
          clientSecret: '',
          tenantId: '',
          subscriptionId: '',
          projectId: '',
          privateKey: '',
        },
        is_default: credential.is_default,
      });
    } else {
      resetForm();
      if (defaultProvider) {
        setFormData(prev => ({
          ...prev,
          provider: defaultProvider,
          credentials: {
            ...prev.credentials,
            region: defaultProvider === 'aws' ? 'us-east-1' :
                   defaultProvider === 'azure' ? 'eastus' :
                   'us-central1'
          }
        }));
      }
    }
    setEditDialogOpen(true);
  };

  const renderProviderForm = () => {
    switch (formData.provider) {
      case 'aws':
        return (
          <>
            <TextField
              fullWidth
              label={t('credentials.accessKeyId')}
              value={formData.credentials.accessKeyId}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, accessKeyId: e.target.value }
              })}
              margin="normal"
              required
            />
            <TextField
              fullWidth
              label={t('credentials.secretAccessKey')}
              type={showPasswords['aws'] ? 'text' : 'password'}
              value={formData.credentials.secretAccessKey}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, secretAccessKey: e.target.value }
              })}
              margin="normal"
              required
              InputProps={{
                endAdornment: (
                  <IconButton
                    onClick={() => setShowPasswords({ ...showPasswords, aws: !showPasswords['aws'] })}
                    edge="end"
                  >
                    {showPasswords['aws'] ? <VisibilityOffIcon /> : <VisibilityIcon />}
                  </IconButton>
                ),
              }}
            />
            <TextField
              fullWidth
              margin="normal"
              select
              label={t('credentials.region')}
              value={formData.credentials.region}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, region: e.target.value }
              })}
              SelectProps={{
                native: true,
              }}
            >
              {AWS_REGIONS.map(region => (
                <option key={region.value} value={region.value}>
                  {region.label}
                </option>
              ))}
            </TextField>
          </>
        );
      case 'azure':
        return (
          <>
            <TextField
              fullWidth
              label={t('credentials.clientId')}
              value={formData.credentials.clientId}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, clientId: e.target.value }
              })}
              margin="normal"
              required
            />
            <TextField
              fullWidth
              label={t('credentials.clientSecret')}
              type={showPasswords['azure'] ? 'text' : 'password'}
              value={formData.credentials.clientSecret}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, clientSecret: e.target.value }
              })}
              margin="normal"
              required
              InputProps={{
                endAdornment: (
                  <IconButton
                    onClick={() => setShowPasswords({ ...showPasswords, azure: !showPasswords['azure'] })}
                    edge="end"
                  >
                    {showPasswords['azure'] ? <VisibilityOffIcon /> : <VisibilityIcon />}
                  </IconButton>
                ),
              }}
            />
            <TextField
              fullWidth
              label={t('credentials.tenantId')}
              value={formData.credentials.tenantId}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, tenantId: e.target.value }
              })}
              margin="normal"
              required
            />
            <TextField
              fullWidth
              label={t('credentials.subscriptionId')}
              value={formData.credentials.subscriptionId}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, subscriptionId: e.target.value }
              })}
              margin="normal"
              required
            />
            <TextField
              fullWidth
              margin="normal"
              select
              label={t('credentials.region')}
              value={formData.credentials.region || 'eastus'}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, region: e.target.value }
              })}
              SelectProps={{
                native: true,
              }}
            >
              {AZURE_REGIONS.map(region => (
                <option key={region.value} value={region.value}>
                  {region.label}
                </option>
              ))}
            </TextField>
          </>
        );
      case 'gcp':
        return (
          <>
            <TextField
              fullWidth
              label={t('credentials.projectId')}
              value={formData.credentials.projectId}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, projectId: e.target.value }
              })}
              margin="normal"
              required
            />
            <TextField
              fullWidth
              label={t('credentials.privateKey')}
              type={showPasswords['gcp'] ? 'text' : 'password'}
              value={formData.credentials.privateKey}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, privateKey: e.target.value }
              })}
              margin="normal"
              required
              multiline
              rows={4}
              placeholder="-----BEGIN PRIVATE KEY-----..."
              InputProps={{
                endAdornment: (
                  <IconButton
                    onClick={() => setShowPasswords({ ...showPasswords, gcp: !showPasswords['gcp'] })}
                    edge="end"
                  >
                    {showPasswords['gcp'] ? <VisibilityOffIcon /> : <VisibilityIcon />}
                  </IconButton>
                ),
              }}
            />
            <TextField
              fullWidth
              margin="normal"
              select
              label={t('credentials.region')}
              value={formData.credentials.region || 'us-central1'}
              onChange={(e) => setFormData({
                ...formData,
                credentials: { ...formData.credentials, region: e.target.value }
              })}
              SelectProps={{
                native: true,
              }}
            >
              {GCP_REGIONS.map(region => (
                <option key={region.value} value={region.value}>
                  {region.label}
                </option>
              ))}
            </TextField>
          </>
        );
      default:
        return null;
    }
  };

  const getProviderCredentials = (provider: string) => {
    return credentials.filter(c => c.provider === provider);
  };

  const renderProviderTab = (provider: string) => {
    const providerCredentials = getProviderCredentials(provider);

    return (
      <Box>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Typography variant="h6">
            {provider === 'aws' ? t('providers.aws') :
             provider === 'azure' ? t('providers.azure') :
             t('providers.gcp')}
          </Typography>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => openEditDialog(undefined, provider)}
          >
            {t('providers.addProvider')}
          </Button>
        </Box>

        {providerCredentials.length === 0 ? (
          <Alert severity="info">
            {t('providers.notConfigured')}
          </Alert>
        ) : (
          <List>
            {providerCredentials.map((cred) => (
              <Card key={cred.id} sx={{ mb: 2 }}>
                <ListItem>
                  <ListItemText
                    primary={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        {cred.name}
                        {cred.environment && (
                          <Chip
                            label={cred.environment.toUpperCase()}
                            size="small"
                            color={
                              cred.environment === 'prod' ? 'error' :
                              cred.environment === 'staging' ? 'warning' :
                              'info'
                            }
                            variant="outlined"
                          />
                        )}
                        {cred.is_default && (
                          <Chip label={t('credentials.default')} size="small" color="primary" />
                        )}
                        {cred.validated_at ? (
                          <Chip
                            label={t('credentials.validated')}
                            size="small"
                            color="success"
                            icon={<CheckIcon />}
                          />
                        ) : cred.validation_error ? (
                          <Chip
                            label={t('credentials.notValidated')}
                            size="small"
                            color="error"
                            icon={<CloseIcon />}
                          />
                        ) : null}
                      </Box>
                    }
                    secondary={cred.description}
                  />
                  <ListItemSecondaryAction>
                    <IconButton
                      edge="end"
                      aria-label="test"
                      onClick={() => handleTestConnection(cred.id)}
                      disabled={loading}
                    >
                      <CloudIcon />
                    </IconButton>
                    <IconButton
                      edge="end"
                      aria-label="edit"
                      onClick={() => openEditDialog(cred)}
                      sx={{ ml: 1 }}
                    >
                      <EditIcon />
                    </IconButton>
                    <IconButton
                      edge="end"
                      aria-label="delete"
                      onClick={() => {
                        setSelectedCredential(cred);
                        setDeleteDialogOpen(true);
                      }}
                      sx={{ ml: 1 }}
                    >
                      <DeleteIcon />
                    </IconButton>
                  </ListItemSecondaryAction>
                </ListItem>
                {cred.validation_error && (
                  <CardContent>
                    <Alert severity="error">
                      {cred.validation_error}
                    </Alert>
                  </CardContent>
                )}
              </Card>
            ))}
          </List>
        )}
      </Box>
    );
  };

  return (
    <Box>
      <Typography variant="h5" sx={{ mb: 3, display: 'flex', alignItems: 'center', gap: 1 }}>
        <CloudIcon />
        {t('title')}
      </Typography>

      <Card>
        <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs value={tabValue} onChange={handleTabChange} aria-label="cloud provider tabs">
            <Tab
              label="Amazon Web Services"
              icon={<AWSIcon />}
              iconPosition="start"
            />
            <Tab
              label="Microsoft Azure"
              icon={<AzureIcon />}
              iconPosition="start"
            />
            <Tab
              label="Google Cloud Platform"
              icon={<GCPIcon />}
              iconPosition="start"
            />
          </Tabs>
        </Box>

        {loading && (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
            <CircularProgress />
          </Box>
        )}

        <TabPanel value={tabValue} index={0}>
          {renderProviderTab('aws')}
        </TabPanel>
        <TabPanel value={tabValue} index={1}>
          {renderProviderTab('azure')}
        </TabPanel>
        <TabPanel value={tabValue} index={2}>
          {renderProviderTab('gcp')}
        </TabPanel>
      </Card>

      {/* Edit/Add Dialog */}
      <Dialog
        open={editDialogOpen}
        onClose={() => setEditDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          {selectedCredential ? t('providers.editProvider') : t('providers.addProvider')}
        </DialogTitle>
        <DialogContent>
          {!selectedCredential && (
            <TextField
              fullWidth
              margin="normal"
              select
              label={t('providers.selectProvider')}
              value={formData.provider}
              onChange={(e) => setFormData({
                ...formData,
                provider: e.target.value,
                credentials: {
                  ...formData.credentials,
                  region: e.target.value === 'aws' ? 'us-east-1' :
                         e.target.value === 'azure' ? 'eastus' :
                         'us-central1'
                }
              })}
              SelectProps={{
                native: true,
              }}
              helperText={t('providers.selectProviderHelp')}
            >
              <option value="aws">{t('providers.aws')}</option>
              <option value="azure">{t('providers.azure')}</option>
              <option value="gcp">{t('providers.gcp')}</option>
            </TextField>
          )}

          <TextField
            fullWidth
            label={t('credentials.name')}
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            margin="normal"
            required
          />
          <TextField
            fullWidth
            label={t('credentials.description')}
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            margin="normal"
            multiline
            rows={2}
          />

          <TextField
            fullWidth
            margin="normal"
            select
            label={t('credentials.environment')}
            value={formData.environment}
            onChange={(e) => setFormData({ ...formData, environment: e.target.value as 'dev' | 'qa' | 'staging' | 'prod' })}
            SelectProps={{
              native: true,
            }}
            helperText={t('credentials.environmentHelp')}
          >
            <option value="dev">{t('credentials.environments.dev')}</option>
            <option value="qa">{t('credentials.environments.qa')}</option>
            <option value="staging">{t('credentials.environments.staging')}</option>
            <option value="prod">{t('credentials.environments.prod')}</option>
          </TextField>

          <Divider sx={{ my: 2 }} />

          {renderProviderForm()}

          <FormControlLabel
            control={
              <Switch
                checked={formData.is_default}
                onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
              />
            }
            label={t('credentials.setAsDefault')}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)} disabled={loading}>
            {t('common:cancel')}
          </Button>
          <Button onClick={handleSaveCredentials} variant="contained" disabled={loading}>
            {loading ? <CircularProgress size={24} /> : t('common:save')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
        <DialogTitle>{t('providers.deleteProvider')}</DialogTitle>
        <DialogContent>
          <Typography>
            {t('providers.deleteConfirm', { name: selectedCredential?.name })}
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)} disabled={loading}>
            {t('common:cancel')}
          </Button>
          <Button
            onClick={handleDeleteCredentials}
            color="error"
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={24} /> : t('common:delete')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert
          onClose={() => setSnackbar({ ...snackbar, open: false })}
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default CloudProviderConfigPage;
