import React from 'react';
import { Box } from '@mui/material';
import { useTranslation } from 'react-i18next';
import BasicDropdown from './BasicDropdown';
import MySQLIcon from '@mui/icons-material/Storage';
import PostgreSQLIcon from '@mui/icons-material/Dns';
import MariaDBIcon from '@mui/icons-material/DataObject';
import SQLServerIcon from '@mui/icons-material/TableChart';
import OracleIcon from '@mui/icons-material/Business';

export type ServerType = 'mysql' | 'postgres' | 'mariadb' | 'mssql' | 'oracle';

interface TypeBasicDropdownProps {
  value: ServerType | 'all';
  onChange: (value: ServerType | 'all') => void;
  showAll?: boolean;
  label?: string;
  size?: 'small' | 'medium';
  fullWidth?: boolean;
}

const TypeBasicDropdown: React.FC<TypeBasicDropdownProps> = ({
  value,
  onChange,
  showAll = true,
  label,
  size = 'medium',
  fullWidth = false,
}) => {
  const { t } = useTranslation('servers');

  const getTypeLabel = (type: ServerType | 'all'): string => {
    if (type === 'all') {
      return t('type.all') as string;
    }
    switch (type) {
      case 'mysql':
        return 'MySQL';
      case 'postgres':
        return 'PostgreSQL';
      case 'mariadb':
        return 'MariaDB';
      case 'mssql':
        return 'SQL Server';
      case 'oracle':
        return 'Oracle';
      default:
        return type;
    }
  };

  const getTypeIcon = (type: ServerType) => {
    switch (type) {
      case 'mysql':
        return <MySQLIcon fontSize="small" sx={{ color: '#00758F' }} />;
      case 'postgres':
        return <PostgreSQLIcon fontSize="small" sx={{ color: '#336791' }} />;
      case 'mariadb':
        return <MariaDBIcon fontSize="small" sx={{ color: '#003545' }} />;
      case 'mssql':
        return <SQLServerIcon fontSize="small" sx={{ color: '#CC2927' }} />;
      case 'oracle':
        return <OracleIcon fontSize="small" sx={{ color: '#F80000' }} />;
      default:
        return undefined;
    }
  };

  const SERVER_TYPES: ServerType[] = ['mysql', 'postgres', 'mariadb', 'mssql', 'oracle'];
  const allOptions = showAll ? ['all' as const, ...SERVER_TYPES] : SERVER_TYPES;

  const options = allOptions.map(type => ({
    value: type,
    label: getTypeLabel(type),
    icon: type !== 'all' ? getTypeIcon(type as ServerType) : undefined,
  }));

  return (
    <BasicDropdown
      value={value}
      onChange={(val) => onChange(val as ServerType | 'all')}
      options={options}
      label={label || (t('type.filterByType') as string)}
      size={size}
      fullWidth={fullWidth}
    />
  );
};

export default TypeBasicDropdown;