// Serviço para gerenciamento de servidores de banco de dados
export const serverService = {
  getServers: async () => {
    try {
      // Todos os usuários autenticados podem ver todos os servidores para fazer solicitações
      // A lógica anterior que filtrava servidores para requesters estava impedindo
      // que eles vissem servidores para os quais poderiam solicitar acesso
      const response = await apiClient.get('/api/servers');
      return response.data;
    } catch (error) {
      logger.error("Erro ao buscar servidores", { error });
      return { success: false, servers: [] };
    }
  },

  executeSql: async (serverId: string, databaseName: string, query: string, schema?: string) => {
    try {
      const response = await apiClient.post(`/api/servers/${serverId}/execute`, {
        database_name: databaseName,
        schema_name: schema,
        query: query
      });
      return response.data;
    } catch (error) {
      logger.error(`Erro ao executar SQL no servidor ${serverId}`, { error });
      return { success: false, message: `Erro ao executar SQL: ${error instanceof Error ? error.message : 'Erro desconhecido'}` };
    }
  },

  getServer: async (id: string) => {
    try {
      const response = await apiClient.get(`/api/servers/${id}`);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao buscar servidor ${id}`, { error });
      throw error;
    }
  },

  getServerById: async (id: string | number) => {
    try {
      const response = await apiClient.get(`/api/servers/${id}`);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao buscar servidor ${id}`, { error });
      throw error;
    }
  },

  testConnection: async function(serverIdOrConnectionData: string | any, connectionDataOrNothing?: any) {
    try {
      // Verificar se recebemos o ID do servidor como primeiro argumento
      if (typeof serverIdOrConnectionData === 'string') {
        const sid = serverIdOrConnectionData;
        const connData = connectionDataOrNothing || {};
        
        const response = await apiClient.post(`/api/servers/${sid}/test-connection`, connData);
        return response.data;
      }
      
      // Caso contrário, usar o objeto diretamente
      const connectionData = serverIdOrConnectionData;
      const sid = connectionData.server_id || connectionData.serverId;
      let url = '/api/servers/test-connection';
      
      if (sid) {
        url = `/api/servers/${sid}/test-connection`;
      }
      
      const response = await apiClient.post(url, connectionData);
      return response.data;
    } catch (error) {
      logger.error('Erro ao testar conexão do servidor', { error });
      return { success: false, message: 'Erro ao testar conexão' };
    }
  },

  getDatabases: async (serverId: string | number) => {
    try {
      const response = await apiClient.get(`/api/servers/${serverId}`);
      const serverData = response.data?.server || response.data;
      
      if (serverData && serverData.databases && Array.isArray(serverData.databases)) {
        return serverData.databases;
      }
      
      return [];
    } catch (error) {
      logger.error(`Erro ao buscar bancos de dados do servidor ${serverId}`, { error });
      return [];
    }
  },

  getSchemas: async (serverId: string | number, databaseName: string) => {
    try {
      const response = await apiClient.get(`/api/servers/${serverId}`);
      const serverData = response.data?.server || response.data;
      let schemas: string[] = [];

      if (serverData && serverData.schemas && typeof serverData.schemas === 'object') {
        if (serverData.schemas[databaseName] && Array.isArray(serverData.schemas[databaseName])) {
          schemas = serverData.schemas[databaseName].filter(Boolean);
        }
      }

      if (schemas.length === 0) {
        schemas = ['public', 'information_schema', 'pg_catalog'];
      }

      return { schemas };
    } catch (error) {
      logger.error(`Erro ao buscar schemas do banco ${databaseName}`, { error });
      return { schemas: ['public', 'information_schema', 'pg_catalog'] };
    }
  },

  getTables: async (serverId: string | number, databaseName: string, schemaName?: string) => {
    try {
      // Para PostgreSQL, é necessário especificar o schema
      if (schemaName) {
        // Usar a rota específica para PostgreSQL com schema
        const url = `/api/servers/${serverId}/databases/${encodeURIComponent(databaseName)}/schemas/${encodeURIComponent(schemaName)}/tables`;
        console.log(`Chamando API para tabelas PostgreSQL - URL: ${url}`);
        
        const response = await apiClient.get(url);
        console.log(`Resposta completa das tabelas PostgreSQL:`, response);
        logger.info(`Resposta das tabelas PostgreSQL para servidor ${serverId}, banco ${databaseName}, schema ${schemaName}:`, response.data);
        
        if (response.data && response.data.tables) {
          console.log(`Tabelas encontradas:`, response.data.tables);
          return { tables: response.data.tables };
        }
        console.warn(`Resposta sem tabelas para PostgreSQL:`, response.data);
        return { tables: [] };
      } else {
        // Usar a rota para MySQL sem schema
        const url = `/api/servers/${serverId}/databases/${encodeURIComponent(databaseName)}/tables`;
        console.log(`Chamando API para tabelas MySQL - URL: ${url}`);
        
        const response = await apiClient.get(url);
        console.log(`Resposta completa das tabelas MySQL:`, response);
        logger.info(`Resposta das tabelas MySQL para servidor ${serverId}, banco ${databaseName}:`, response.data);
        
        if (response.data && response.data.tables) {
          console.log(`Tabelas encontradas:`, response.data.tables);
          return { tables: response.data.tables };
        }
        console.warn(`Resposta sem tabelas para MySQL:`, response.data);
        return { tables: [] };
      }
    } catch (error) {
      logger.error(`Erro ao buscar tabelas`, { error });
      return { tables: [] };
    }
  },
  
  createServer: async (serverData: any) => {
    try {
      const response = await apiClient.post('/api/servers', serverData);
      return response.data;
    } catch (error) {
      logger.error("Erro ao criar servidor", { error });
      throw error;
    }
  },
  
  updateServer: async (id: string | number, serverData: any) => {
    try {
      const response = await apiClient.put(`/api/servers/${id}`, serverData);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao atualizar servidor ${id}`, { error });
      throw error;
    }
  },
  
  deleteServer: async (id: string | number) => {
    try {
      const response = await apiClient.delete(`/api/servers/${id}`);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao excluir servidor ${id}`, { error });
      throw error;
    }
  },

  checkServersStatus: async (serverIds: (string | number)[]) => {
    try {
      if (!serverIds || serverIds.length === 0) {
        return { success: false, message: "Nenhum servidor fornecido para verificação" };
      }

      const response = await apiClient.post('/api/servers/status', { serverIds });
      return response.data;
    } catch (error) {
      logger.error("Erro ao verificar status dos servidores", { error });
      return { success: false, status: {} };
    }
  },

  checkAdminPrivileges: async (serverId: string | number) => {
    try {
      const response = await apiClient.get(`/api/servers/${serverId}/check-admin`);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao verificar privilégios administrativos para servidor ${serverId}`, { error });
      return { success: false, isAdmin: false };
    }
  },

  getMetrics: async (serverId: string | number, metricTypes?: string[]) => {
    try {
      let url = `/api/metrics/${serverId}`;
      const params = new URLSearchParams();
      
      if (metricTypes && metricTypes.length > 0) {
        metricTypes.forEach(type => params.append('type', type));
      }
      
      if (params.toString()) {
        url += `?${params.toString()}`;
      }
      
      const response = await apiClient.get(url);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao buscar métricas do servidor ${serverId}`, { error });
      throw error;
    }
  },

  clearMetricsCache: async (serverId: string | number) => {
    try {
      const response = await apiClient.delete(`/api/metrics/${serverId}/cache`);
      return response.data;
    } catch (error) {
      logger.error(`Erro ao limpar cache de métricas do servidor ${serverId}`, { error });
      throw error;
    }
  }
};

