import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { 
  Box, 
  Typography, 
  Paper, 
  FormControlLabel, 
  Switch, 
  TextField, 
  Button, 
  Grid, 
  Alert, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  Divider,
  CircularProgress,
  Chip,
  Slider,
} from '@mui/material';
import {
} from '@mui/icons-material';

interface AuditPolicy {
  id?: string;
  name: string;
  description: string;
  enabled: boolean;
  retentionDays: number;
  sensitiveFields: string[];
  eventTypes: string[];
}

interface AuditPoliciesConfig {
  enabled: boolean;
  policies: AuditPolicy[];
  defaultRetentionDays: number;
  defaultSensitiveFields: string[];
}

const defaultConfig: AuditPoliciesConfig = {
  enabled: true,
  policies: [
    {
      id: '1',
      name: 'Default Policy',
      description: 'Default audit policy for all events',
      enabled: true,
      retentionDays: 90,
      sensitiveFields: ['password', 'auth_token', 'credit_card', 'ssn'],
      eventTypes: ['*']
    },
    {
      id: '2',
      name: 'Security Events',
      description: 'Extended retention for security-related events',
      enabled: true,
      retentionDays: 365,
      sensitiveFields: ['password', 'auth_token', 'credit_card', 'ssn'],
      eventTypes: ['FAILED_LOGIN', 'SECURITY_CHANGE', 'PERMISSION_CHANGE']
    }
  ],
  defaultRetentionDays: 90,
  defaultSensitiveFields: ['password', 'auth_token', 'credit_card', 'ssn']
};

const eventTypeOptions = [
  { value: '*', label: 'All Events' },
  { value: 'LOGIN', label: 'User Login' },
  { value: 'LOGOUT', label: 'User Logout' },
  { value: 'FAILED_LOGIN', label: 'Failed Login Attempt' },
  { value: 'CREATE_USER', label: 'User Creation' },
  { value: 'UPDATE_USER', label: 'User Update' },
  { value: 'DELETE_USER', label: 'User Deletion' },
  { value: 'INVITE_USER', label: 'User Invitation' },
  { value: 'USER_ACTIVATION', label: 'User Activation' },
  { value: 'CREATE_PERMISSION', label: 'Permission Creation' },
  { value: 'UPDATE_PERMISSION', label: 'Permission Update' },
  { value: 'DELETE_PERMISSION', label: 'Permission Deletion' },
  { value: 'REVOKE_PERMISSION', label: 'Permission Revocation' },
  { value: 'CREATE_REQUEST', label: 'Access Request Creation' },
  { value: 'APPROVE_REQUEST', label: 'Request Approval' },
  { value: 'REJECT_REQUEST', label: 'Request Rejection' },
  { value: 'CONFIG_CHANGE', label: 'System Configuration Change' },
  { value: 'SECURITY_CHANGE', label: 'Security Setting Change' },
  { value: 'ADD_DATABASE', label: 'Database Registration' },
  { value: 'UPDATE_DATABASE', label: 'Database Configuration Update' },
  { value: 'REMOVE_DATABASE', label: 'Database Removal' },
  { value: 'DATABASE_QUERY', label: 'Database Query' }
];

const AuditPoliciesPanel: React.FC = () => {
  const { t } = useTranslation('audit');
  const [loading, setLoading] = useState<boolean>(true);
  const [saving, setSaving] = useState<boolean>(false);
  const [config, setConfig] = useState<AuditPoliciesConfig>(defaultConfig);
  const [statusMessage, setStatusMessage] = useState<{type: 'success' | 'error', message: string} | null>(null);
  const [editMode, setEditMode] = useState<boolean>(false);
  const [selectedPolicy, setSelectedPolicy] = useState<number | null>(null);
  const [newPolicy, setNewPolicy] = useState<AuditPolicy>({
    name: '',
    description: '',
    enabled: true,
    retentionDays: 90,
    sensitiveFields: [],
    eventTypes: []
  });
  const [newSensitiveField, setNewSensitiveField] = useState<string>('');

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        setLoading(true);
        // This would be replaced with a real API call
        // const response = await api.get('/api/audit/policies-config');
        // setConfig(response.data);
        
        // Using mock data for now
        setTimeout(() => {
          setConfig(defaultConfig);
          setLoading(false);
        }, 800);
      } catch (error) {
        console.error('Error fetching audit policies configuration:', error);
        setStatusMessage({
          type: 'error',
          message: t('policies.fetchError')
        });
        setLoading(false);
      }
    };

    fetchConfig();
  }, [t]);

  const handleSaveConfig = async () => {
    try {
      setSaving(true);
      // This would be replaced with a real API call
      // await api.post('/api/audit/policies-config', config);
      
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setStatusMessage({
        type: 'success',
        message: t('policies.saveSuccess')
      });
      setEditMode(false);
    } catch (error) {
      console.error('Error saving audit policies configuration:', error);
      setStatusMessage({
        type: 'error',
        message: t('policies.saveError')
      });
    } finally {
      setSaving(false);
    }
  };

  const handleTogglePolicy = (event: React.ChangeEvent<HTMLInputElement>) => {
    setConfig({
      ...config,
      enabled: event.target.checked
    });
  };

  const handleRetentionSliderChange = (_event: Event, newValue: number | number[]) => {
    if (typeof newValue === 'number') {
      setConfig({
        ...config,
        defaultRetentionDays: newValue
      });
    }
  };

  const handlePolicyRetentionSliderChange = (_event: Event, newValue: number | number[]) => {
    if (typeof newValue === 'number') {
      setNewPolicy({
        ...newPolicy,
        retentionDays: newValue
      });
    }
  };

  const handleAddPolicy = () => {
    if (newPolicy.name) {
      setConfig({
        ...config,
        policies: [...config.policies, {
          ...newPolicy,
          id: Date.now().toString() // Generate a temporary ID
        }]
      });
      
      // Reset the form
      setNewPolicy({
        name: '',
        description: '',
        enabled: true,
        retentionDays: 90,
        sensitiveFields: [],
        eventTypes: []
      });
      
      setEditMode(false);
    }
  };

  const handleUpdatePolicy = () => {
    if (selectedPolicy !== null && newPolicy.name) {
      const updatedPolicies = [...config.policies];
      updatedPolicies[selectedPolicy] = {
        ...newPolicy,
        id: config.policies[selectedPolicy].id
      };
      
      setConfig({
        ...config,
        policies: updatedPolicies
      });
      
      setSelectedPolicy(null);
      setEditMode(false);
      
      // Reset the form
      setNewPolicy({
        name: '',
        description: '',
        enabled: true,
        retentionDays: 90,
        sensitiveFields: [],
        eventTypes: []
      });
    }
  };

  const handleEditPolicy = (index: number) => {
    setSelectedPolicy(index);
    setNewPolicy({...config.policies[index]});
    setEditMode(true);
  };

  const handleRemovePolicy = (index: number) => {
    const updatedPolicies = [...config.policies];
    updatedPolicies.splice(index, 1);
    setConfig({
      ...config,
      policies: updatedPolicies
    });
  };

  const handleTogglePolicyStatus = (index: number) => {
    const updatedPolicies = [...config.policies];
    updatedPolicies[index] = {
      ...updatedPolicies[index],
      enabled: !updatedPolicies[index].enabled
    };
    
    setConfig({
      ...config,
      policies: updatedPolicies
    });
  };

  const handleCancelEdit = () => {
    setEditMode(false);
    setSelectedPolicy(null);
    setNewPolicy({
      name: '',
      description: '',
      enabled: true,
      retentionDays: 90,
      sensitiveFields: [],
      eventTypes: []
    });
  };

  const handleAddSensitiveField = () => {
    if (newSensitiveField && !newPolicy.sensitiveFields.includes(newSensitiveField)) {
      setNewPolicy({
        ...newPolicy,
        sensitiveFields: [...newPolicy.sensitiveFields, newSensitiveField]
      });
      setNewSensitiveField('');
    }
  };

  const handleRemoveSensitiveField = (field: string) => {
    setNewPolicy({
      ...newPolicy,
      sensitiveFields: newPolicy.sensitiveFields.filter(f => f !== field)
    });
  };

  const handleAddGlobalSensitiveField = () => {
    if (newSensitiveField && !config.defaultSensitiveFields.includes(newSensitiveField)) {
      setConfig({
        ...config,
        defaultSensitiveFields: [...config.defaultSensitiveFields, newSensitiveField]
      });
      setNewSensitiveField('');
    }
  };

  const handleRemoveGlobalSensitiveField = (field: string) => {
    setConfig({
      ...config,
      defaultSensitiveFields: config.defaultSensitiveFields.filter(f => f !== field)
    });
  };

  const handleEventTypeChange = (event: React.ChangeEvent<{ value: unknown }>) => {
    setNewPolicy({
      ...newPolicy,
      eventTypes: event.target.value as string[]
    });
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        {t('policies.title')}
      </Typography>
      
      <Typography variant="body2" color="textSecondary" paragraph>
        {t('policies.description')}
      </Typography>

      {statusMessage && (
        <Alert 
          severity={statusMessage.type} 
          onClose={() => setStatusMessage(null)}
          sx={{ mb: 2 }}
        >
          {statusMessage.message}
        </Alert>
      )}

      <Paper sx={{ p: 3, mb: 3 }}>
        <FormControlLabel
          control={
            <Switch
              checked={config.enabled}
              onChange={handleTogglePolicy}
            />
          }
          label={t('policies.enablePolicies')}
        />
        
        <Typography variant="body2" color="textSecondary" sx={{ mt: 1, mb: 2 }}>
          {config.enabled 
            ? t('policies.enabledDescription')
            : t('policies.disabledDescription')
          }
        </Typography>

        <Divider sx={{ my: 3 }} />

        <Typography variant="subtitle1" gutterBottom>
          {t('policies.globalSettings')}
        </Typography>

        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <Typography gutterBottom>
              {t('policies.defaultRetention')}: {config.defaultRetentionDays} {t('common:days')}
            </Typography>
            <Slider
              value={config.defaultRetentionDays}
              onChange={handleRetentionSliderChange}
              aria-labelledby="retention-slider"
              valueLabelDisplay="auto"
              step={30}
              marks={[
                { value: 30, label: '30d' },
                { value: 90, label: '90d' },
                { value: 180, label: '180d' },
                { value: 365, label: '1y' },
                { value: 730, label: '2y' }
              ]}
              min={30}
              max={730}
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <Typography gutterBottom>
              {t('policies.defaultSensitiveFields')}
            </Typography>
            <Box display="flex" flexWrap="wrap" mb={2}>
              {config.defaultSensitiveFields.map((field) => (
                <Chip
                  key={field}
                  label={field}
                  onDelete={() => handleRemoveGlobalSensitiveField(field)}
                  sx={{ m: 0.5 }}
                />
              ))}
            </Box>
            <Box display="flex">
              <TextField
                label={t('policies.addSensitiveField')}
                value={newSensitiveField}
                onChange={(e) => setNewSensitiveField(e.target.value)}
                size="small"
                sx={{ mr: 1 }}
              />
              <Button
                variant="outlined"
                onClick={handleAddGlobalSensitiveField}
                disabled={!newSensitiveField}
              >
                {t('common:add')}
              </Button>
            </Box>
          </Grid>
        </Grid>

        <Button 
          variant="contained" 
          color="primary"
          onClick={handleSaveConfig}
          disabled={saving}
          sx={{ mt: 3 }}
        >
          {saving ? <CircularProgress size={24} /> : t('common:saveConfig')}
        </Button>
      </Paper>

      {config.enabled && (
        <>
          <Typography variant="h6" gutterBottom>
            {t('policies.policyList')}
          </Typography>

          {config.policies.length > 0 ? (
            <Box mb={4}>
              {config.policies.map((policy, index) => (
                <Paper key={policy.id} sx={{ p: 2, mb: 2, border: policy.enabled ? '1px solid #e0e0e0' : '1px dashed #e0e0e0' }}>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={9}>
                      <Typography variant="subtitle1" component="div" sx={{ display: 'flex', alignItems: 'center' }}>
                        {policy.name}
                        {!policy.enabled && (
                          <Chip 
                            label={t('common:disabled')} 
                            size="small" 
                            color="default" 
                            variant="outlined"
                            sx={{ ml: 1 }}
                          />
                        )}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {policy.description}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {t('policies.retention')}: {policy.retentionDays} {t('common:days')}
                      </Typography>
                      <Box display="flex" flexWrap="wrap" mt={1}>
                        <Typography variant="body2" color="textSecondary" sx={{ mr: 1 }}>
                          {t('policies.eventTypes')}:
                        </Typography>
                        {policy.eventTypes.includes('*') ? (
                          <Chip 
                            label={t('policies.allEvents')} 
                            size="small" 
                            sx={{ mr: 0.5 }}
                          />
                        ) : (
                          policy.eventTypes.map((eventType) => (
                            <Chip 
                              key={eventType} 
                              label={eventTypeOptions.find(opt => opt.value === eventType)?.label || eventType} 
                              size="small" 
                              sx={{ mr: 0.5, mb: 0.5 }}
                            />
                          ))
                        )}
                      </Box>
                    </Grid>
                    <Grid item xs={3} sx={{ textAlign: 'right' }}>
                      <Button 
                        variant="outlined" 
                        size="small" 
                        onClick={() => handleEditPolicy(index)}
                        sx={{ mr: 1, mb: 1 }}
                      >
                        {t('common:edit')}
                      </Button>
                      <Button 
                        variant={policy.enabled ? "outlined" : "contained"} 
                        size="small" 
                        color={policy.enabled ? "primary" : "success"}
                        onClick={() => handleTogglePolicyStatus(index)}
                        sx={{ mr: 1, mb: 1 }}
                      >
                        {policy.enabled 
                          ? t('common:disable') 
                          : t('common:enable')
                        }
                      </Button>
                      <Button 
                        variant="outlined" 
                        size="small" 
                        color="error"
                        onClick={() => handleRemovePolicy(index)}
                        sx={{ mb: 1 }}
                        disabled={index === 0} // Don't allow removing the default policy
                      >
                        {t('common:delete')}
                      </Button>
                    </Grid>
                  </Grid>
                </Paper>
              ))}
            </Box>
          ) : (
            <Alert severity="info" sx={{ mb: 3 }}>
              {t('policies.noPolicies')}
            </Alert>
          )}

          {!editMode ? (
            <Button 
              variant="contained" 
              color="primary" 
              onClick={() => setEditMode(true)}
              sx={{ mb: 3 }}
            >
              {t('policies.addPolicy')}
            </Button>
          ) : (
            <Paper sx={{ p: 3, mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                {selectedPolicy !== null 
                  ? t('policies.editPolicy') 
                  : t('policies.addPolicy')
                }
              </Typography>
              
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label={t('policies.policyName')}
                    fullWidth
                    value={newPolicy.name}
                    onChange={(e) => setNewPolicy({...newPolicy, name: e.target.value})}
                    margin="normal"
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={newPolicy.enabled}
                        onChange={(e) => setNewPolicy({...newPolicy, enabled: e.target.checked})}
                      />
                    }
                    label={t('policies.enablePolicy')}
                    sx={{ mt: 2 }}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label={t('policies.policyDescription')}
                    fullWidth
                    value={newPolicy.description}
                    onChange={(e) => setNewPolicy({...newPolicy, description: e.target.value})}
                    margin="normal"
                    multiline
                    rows={2}
                  />
                </Grid>
                <Grid item xs={12}>
                  <Typography gutterBottom>
                    {t('policies.retentionPeriod')}: {newPolicy.retentionDays} {t('common:days')}
                  </Typography>
                  <Slider
                    value={newPolicy.retentionDays}
                    onChange={handlePolicyRetentionSliderChange}
                    aria-labelledby="policy-retention-slider"
                    valueLabelDisplay="auto"
                    step={30}
                    marks={[
                      { value: 30, label: '30d' },
                      { value: 90, label: '90d' },
                      { value: 180, label: '180d' },
                      { value: 365, label: '1y' },
                      { value: 730, label: '2y' }
                    ]}
                    min={30}
                    max={730}
                  />
                </Grid>
                <Grid item xs={12}>
                  <FormControl fullWidth margin="normal">
                    <InputLabel id="event-types-label">
                      {t('policies.eventTypes')}
                    </InputLabel>
                    <Select
                      labelId="event-types-label"
                      multiple
                      value={newPolicy.eventTypes}
                      onChange={(e: any) => handleEventTypeChange(e)}
                      label={t('policies.eventTypes')}
                      renderValue={(selected) => (
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                          {(selected as string[]).map((value) => {
                            const option = eventTypeOptions.find(opt => opt.value === value);
                            return (
                              <Chip key={value} label={option ? option.label : value} size="small" />
                            );
                          })}
                        </Box>
                      )}
                    >
                      {eventTypeOptions.map((option) => (
                        <MenuItem key={option.value} value={option.value}>
                          {option.label}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12}>
                  <Typography gutterBottom>
                    {t('policies.sensitiveFields')}
                  </Typography>
                  <Box display="flex" flexWrap="wrap" mb={2}>
                    {newPolicy.sensitiveFields.map((field) => (
                      <Chip
                        key={field}
                        label={field}
                        onDelete={() => handleRemoveSensitiveField(field)}
                        sx={{ m: 0.5 }}
                      />
                    ))}
                  </Box>
                  <Box display="flex">
                    <TextField
                      label={t('policies.addSensitiveField')}
                      value={newSensitiveField}
                      onChange={(e) => setNewSensitiveField(e.target.value)}
                      size="small"
                      sx={{ mr: 1 }}
                    />
                    <Button
                      variant="outlined"
                      onClick={handleAddSensitiveField}
                      disabled={!newSensitiveField}
                    >
                      {t('common:add')}
                    </Button>
                  </Box>
                </Grid>
              </Grid>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
                <Button 
                  variant="outlined" 
                  onClick={handleCancelEdit}
                  sx={{ mr: 1 }}
                >
                  {t('common:cancel')}
                </Button>
                <Button 
                  variant="contained" 
                  color="primary"
                  onClick={selectedPolicy !== null ? handleUpdatePolicy : handleAddPolicy}
                  disabled={!newPolicy.name}
                >
                  {selectedPolicy !== null 
                    ? t('common:update') 
                    : t('common:add')
                  }
                </Button>
              </Box>
            </Paper>
          )}
        </>
      )}
    </Box>
  );
};

export default AuditPoliciesPanel;