import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  Avatar,
  Typography,
  Divider,
  Grid,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Snackbar,
  Alert,
  Box,
  useTheme,
  alpha,
  TextField,
} from '@mui/material';
import {
  Security as SecurityIcon,
  Save as SaveIcon,
  Refresh as RefreshIcon,
  Fingerprint as FingerprintIcon,
  VerifiedUser as VerifiedUserIcon,
  Password as PasswordIcon,
} from '@mui/icons-material';

import { configurationService } from '../../services/api';

interface SecurityConfig {
  passwordPolicy: {
    minLength: number;
    requireUppercase: boolean;
    requireLowercase: boolean;
    requireNumbers: boolean;
    requireSpecialChars: boolean;
    preventCommonPasswords: boolean;
    expirationDays: number;
    historyCount: number;
  };
  sessionPolicy: {
    sessionTimeout: number;
    maxConcurrentSessions: number;
    enforceIpLock: boolean;
  };
  apiSecurity: {
    rateLimit: number;
    requireHttps: boolean;
    corsEnabled: boolean;
    allowedOrigins: string;
  };
}

const SecurityConfigPanel: React.FC = () => {
  const { t } = useTranslation(['settings', 'common']);
  const theme = useTheme();

  // Estado para configuração de segurança
  const [securityConfig, setSecurityConfig] = useState<SecurityConfig>({
    passwordPolicy: {
      minLength: 8,
      requireUppercase: true,
      requireLowercase: true,
      requireNumbers: true,
      requireSpecialChars: true,
      preventCommonPasswords: true,
      expirationDays: 90,
      historyCount: 5
    },
    sessionPolicy: {
      sessionTimeout: 30,
      maxConcurrentSessions: 3,
      enforceIpLock: false
    },
    apiSecurity: {
      rateLimit: 100,
      requireHttps: true,
      corsEnabled: true,
      allowedOrigins: '*'
    }
  });

  // Estado para controle do painel
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);

  // Carrega as configurações de segurança iniciais
  useEffect(() => {
    fetchSecurityConfig();
  }, []);

  // Obtém as configurações de segurança do servidor
  const fetchSecurityConfig = async () => {
    setLoading(true);
    try {
      const response = await configurationService.getConfiguration('security');
      console.log('Security config response:', response);
      
      if (response && response.security) {
        setSecurityConfig(response.security);
        setHasChanges(false);
      }
    } catch (error) {
      console.error('Erro ao buscar configuração de segurança:', error);
      setErrorMessage('Erro ao carregar configurações de segurança');
    } finally {
      setLoading(false);
    }
  };

  // Salva a configuração de segurança
  const handleSaveSecurityConfig = async () => {
    setSaving(true);
    setErrorMessage(null);
    
    try {
      // Validar campos de senha
      if (securityConfig.passwordPolicy.minLength < 6) {
        setErrorMessage('O comprimento mínimo da senha deve ser pelo menos 6 caracteres');
        setSaving(false);
        return;
      }
      
      // Enviar configuração para o servidor
      const response = await configurationService.updateConfiguration({ 
        security: securityConfig 
      });
      
      console.log('Resposta ao salvar configuração de segurança:', response);
      setSuccessMessage('Configuração de segurança salva com sucesso');
      setHasChanges(false);
    } catch (error) {
      console.error('Erro ao salvar configuração de segurança:', error);
      setErrorMessage('Erro ao salvar configuração de segurança');
    } finally {
      setSaving(false);
    }
  };

  // Manipula mudanças nos campos numéricos
  const handleNumberChange = (category: keyof SecurityConfig, field: string, value: string) => {
    const numValue = parseInt(value, 10);
    
    if (!isNaN(numValue)) {
      setSecurityConfig(prev => {
        const updatedConfig = { ...prev };
        (updatedConfig[category] as any)[field] = numValue;
        return updatedConfig;
      });
      setHasChanges(true);
    }
  };

  // Manipula mudanças nos toggles
  const handleToggleChange = (category: keyof SecurityConfig, field: string, checked: boolean) => {
    setSecurityConfig(prev => {
      const updatedConfig = { ...prev };
      (updatedConfig[category] as any)[field] = checked;
      return updatedConfig;
    });
    setHasChanges(true);
  };

  // Manipula mudanças nos campos de texto
  const handleTextChange = (category: keyof SecurityConfig, field: string, value: string) => {
    setSecurityConfig(prev => {
      const updatedConfig = { ...prev };
      (updatedConfig[category] as any)[field] = value;
      return updatedConfig;
    });
    setHasChanges(true);
  };

  return (
    <Card sx={{ 
      borderRadius: 2, 
      mb: 3, 
      boxShadow: 2,
      overflow: 'hidden',
      transition: 'box-shadow 0.3s ease-in-out',
      '&:hover': {
        boxShadow: 5
      }
    }}>
      <CardHeader
        avatar={
          <Avatar sx={{ 
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            width: 48,
            height: 48
          }}>
            <SecurityIcon />
          </Avatar>
        }
        title={
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            {t('sections.security.title', 'Configurações de Segurança')}
          </Typography>
        }
        subheader={t('sections.security.description', 'Configure as políticas de segurança do sistema')}
        action={
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<RefreshIcon />}
              onClick={fetchSecurityConfig}
              disabled={loading}
              sx={{ borderRadius: 8 }}
            >
              {t('common:refresh', 'Atualizar')}
            </Button>
            <Button
              variant="contained"
              size="small"
              startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
              onClick={handleSaveSecurityConfig}
              disabled={saving || !hasChanges}
              sx={{ 
                borderRadius: 8,
                fontWeight: 'bold',
                color: 'white'
              }}
            >
              {t('common:save', 'Salvar')}
            </Button>
          </Box>
        }
      />
      <Divider />
      <CardContent sx={{ p: 3 }}>
        {errorMessage && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setErrorMessage(null)}>
            {errorMessage}
          </Alert>
        )}
        
        {loading ? (
          <Box display="flex" justifyContent="center" p={4}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            {/* Política de Senha */}
            <Typography variant="h6" sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 1, 
              mb: 2,
              fontWeight: 600
            }}>
              <PasswordIcon color="primary" />
              {t('sections.security.passwordPolicy', 'Política de Senha')}
            </Typography>
            
            <Grid container spacing={3} sx={{ mb: 4 }}>
              <Grid item xs={12} sm={6} md={4}>
                <TextField
                  fullWidth
                  label={t('sections.security.minLength', 'Comprimento Mínimo')}
                  type="number"
                  InputProps={{ 
                    inputProps: { min: 6, max: 32 }
                  }}
                  value={securityConfig.passwordPolicy.minLength}
                  onChange={(e) => handleNumberChange('passwordPolicy', 'minLength', e.target.value)}
                  helperText={t('sections.security.minLengthHint', 'Número mínimo de caracteres para senhas')}
                  variant="outlined"
                  size="small"
                />
              </Grid>
              
              <Grid item xs={12} sm={6} md={4}>
                <TextField
                  fullWidth
                  label={t('sections.security.expirationDays', 'Expiração (dias)')}
                  type="number"
                  InputProps={{ 
                    inputProps: { min: 0, max: 365 }
                  }}
                  value={securityConfig.passwordPolicy.expirationDays}
                  onChange={(e) => handleNumberChange('passwordPolicy', 'expirationDays', e.target.value)}
                  helperText={t('sections.security.expirationDaysHint', 'Dias até expiração da senha (0 = sem expiração)')}
                  variant="outlined"
                  size="small"
                />
              </Grid>
              
              <Grid item xs={12} sm={6} md={4}>
                <TextField
                  fullWidth
                  label={t('sections.security.historyCount', 'Histórico de Senhas')}
                  type="number"
                  InputProps={{ 
                    inputProps: { min: 0, max: 24 }
                  }}
                  value={securityConfig.passwordPolicy.historyCount}
                  onChange={(e) => handleNumberChange('passwordPolicy', 'historyCount', e.target.value)}
                  helperText={t('sections.security.historyCountHint', 'Número de senhas anteriores que não podem ser reutilizadas')}
                  variant="outlined"
                  size="small"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.passwordPolicy.requireUppercase}
                      onChange={(e) => handleToggleChange('passwordPolicy', 'requireUppercase', e.target.checked)}
                    />
                  }
                  label={t('sections.security.requireUppercase', 'Exigir Letras Maiúsculas')}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.passwordPolicy.requireLowercase}
                      onChange={(e) => handleToggleChange('passwordPolicy', 'requireLowercase', e.target.checked)}
                    />
                  }
                  label={t('sections.security.requireLowercase', 'Exigir Letras Minúsculas')}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.passwordPolicy.requireNumbers}
                      onChange={(e) => handleToggleChange('passwordPolicy', 'requireNumbers', e.target.checked)}
                    />
                  }
                  label={t('sections.security.requireNumbers', 'Exigir Números')}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.passwordPolicy.requireSpecialChars}
                      onChange={(e) => handleToggleChange('passwordPolicy', 'requireSpecialChars', e.target.checked)}
                    />
                  }
                  label={t('sections.security.requireSpecialChars', 'Exigir Caracteres Especiais')}
                />
              </Grid>
              
              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.passwordPolicy.preventCommonPasswords}
                      onChange={(e) => handleToggleChange('passwordPolicy', 'preventCommonPasswords', e.target.checked)}
                    />
                  }
                  label={t('sections.security.preventCommonPasswords', 'Bloquear Senhas Comuns')}
                />
                <Typography variant="caption" sx={{ display: 'block', ml: 4, mt: 0.5 }}>
                  {t('sections.security.preventCommonPasswordsHint', 'Impede o uso de senhas conhecidas e facilmente adivinhadas')}
                </Typography>
              </Grid>
            </Grid>
            
            {/* Política de Sessão */}
            <Typography variant="h6" sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 1, 
              mb: 2,
              fontWeight: 600
            }}>
              <FingerprintIcon color="primary" />
              {t('sections.security.sessionPolicy', 'Política de Sessão')}
            </Typography>
            
            <Grid container spacing={3} sx={{ mb: 4 }}>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('sections.security.sessionTimeout', 'Timeout de Sessão (minutos)')}
                  type="number"
                  InputProps={{ 
                    inputProps: { min: 5, max: 1440 }
                  }}
                  value={securityConfig.sessionPolicy.sessionTimeout}
                  onChange={(e) => handleNumberChange('sessionPolicy', 'sessionTimeout', e.target.value)}
                  helperText={t('sections.security.sessionTimeoutHint', 'Tempo de inatividade até encerramento da sessão')}
                  variant="outlined"
                  size="small"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('sections.security.maxConcurrentSessions', 'Sessões Concorrentes')}
                  type="number"
                  InputProps={{ 
                    inputProps: { min: 1, max: 10 }
                  }}
                  value={securityConfig.sessionPolicy.maxConcurrentSessions}
                  onChange={(e) => handleNumberChange('sessionPolicy', 'maxConcurrentSessions', e.target.value)}
                  helperText={t('sections.security.maxConcurrentSessionsHint', 'Número máximo de sessões simultâneas por usuário')}
                  variant="outlined"
                  size="small"
                />
              </Grid>
              
              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.sessionPolicy.enforceIpLock}
                      onChange={(e) => handleToggleChange('sessionPolicy', 'enforceIpLock', e.target.checked)}
                    />
                  }
                  label={t('sections.security.enforceIpLock', 'Restringir Sessão ao IP')}
                />
                <Typography variant="caption" sx={{ display: 'block', ml: 4, mt: 0.5 }}>
                  {t('sections.security.enforceIpLockHint', 'Limita a sessão ao IP de origem, exigindo nova autenticação se o IP mudar')}
                </Typography>
              </Grid>
            </Grid>
            
            {/* Segurança da API */}
            <Typography variant="h6" sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 1, 
              mb: 2,
              fontWeight: 600
            }}>
              <VerifiedUserIcon color="primary" />
              {t('sections.security.apiSecurity', 'Segurança da API')}
            </Typography>
            
            <Grid container spacing={3}>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('sections.security.rateLimit', 'Limite de Requisições (por minuto)')}
                  type="number"
                  InputProps={{ 
                    inputProps: { min: 10, max: 1000 }
                  }}
                  value={securityConfig.apiSecurity.rateLimit}
                  onChange={(e) => handleNumberChange('apiSecurity', 'rateLimit', e.target.value)}
                  helperText={t('sections.security.rateLimitHint', 'Número máximo de requisições por minuto por IP')}
                  variant="outlined"
                  size="small"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.apiSecurity.requireHttps}
                      onChange={(e) => handleToggleChange('apiSecurity', 'requireHttps', e.target.checked)}
                    />
                  }
                  label={
                    <Box sx={{ display: 'flex', flexDirection: 'column' }}>
                      <Typography>
                        {t('sections.security.requireHttps', 'Exigir HTTPS')}
                      </Typography>
                      <Typography variant="caption" sx={{ mt: 0.5 }}>
                        {t('sections.security.requireHttpsHint', 'Rejeita conexões não-seguras (HTTP)')}
                      </Typography>
                    </Box>
                  }
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={securityConfig.apiSecurity.corsEnabled}
                      onChange={(e) => handleToggleChange('apiSecurity', 'corsEnabled', e.target.checked)}
                    />
                  }
                  label={t('sections.security.corsEnabled', 'Habilitar CORS')}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('sections.security.allowedOrigins', 'Origens Permitidas')}
                  value={securityConfig.apiSecurity.allowedOrigins}
                  onChange={(e) => handleTextChange('apiSecurity', 'allowedOrigins', e.target.value)}
                  helperText={t('sections.security.allowedOriginsHint', 'Lista de origens separadas por vírgula (ex: https://exemplo.com), ou * para todas')}
                  variant="outlined"
                  size="small"
                  disabled={!securityConfig.apiSecurity.corsEnabled}
                />
              </Grid>
            </Grid>
          </>
        )}
      </CardContent>

      {/* Notificação de sucesso */}
      <Snackbar 
        open={!!successMessage} 
        autoHideDuration={6000} 
        onClose={() => setSuccessMessage(null)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>
    </Card>
  );
};

export default SecurityConfigPanel;
