import React from 'react';
import { Box } from '@mui/material';
import { useTranslation } from 'react-i18next';
import BasicDropdown from './BasicDropdown';
import { 
  Environment, 
  ENVIRONMENTS,
  ENVIRONMENT_COLORS 
} from '../../types/environment';

interface EnvironmentBasicDropdownProps {
  value: Environment | 'all';
  onChange: (value: Environment | 'all') => void;
  showAll?: boolean;
  label?: string;
  size?: 'small' | 'medium';
  fullWidth?: boolean;
}

const EnvironmentBasicDropdown: React.FC<EnvironmentBasicDropdownProps> = ({ 
  value, 
  onChange, 
  showAll = true,
  label,
  size = 'medium',
  fullWidth = false,
}) => {
  const { t } = useTranslation('common');

  const getEnvironmentLabel = (env: Environment | 'all'): string => {
    if (env === 'all') {
      return t('environment.all') as string;
    }
    switch (env) {
      case 'dev':
        return t('environment.dev') as string;
      case 'qa':
        return t('environment.qa') as string;
      case 'prod':
        return t('environment.prod') as string;
      default:
        return env;
    }
  };

  const allOptions = showAll ? ['all' as const, ...ENVIRONMENTS] : ENVIRONMENTS;
  
  const options = allOptions.map(env => ({
    value: env,
    label: getEnvironmentLabel(env),
    icon: env !== 'all' ? (
      <Box
        sx={{
          width: 12,
          height: 12,
          borderRadius: '50%',
          backgroundColor: ENVIRONMENT_COLORS[env as Environment],
        }}
      />
    ) : undefined,
  }));

  return (
    <BasicDropdown
      value={value}
      onChange={(val) => onChange(val as Environment | 'all')}
      options={options}
      label={label || (t('environment.filterByEnvironment') as string)}
      size={size}
      fullWidth={fullWidth}
    />
  );
};

export default EnvironmentBasicDropdown;