import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  CardActions,
  Typography,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Alert,
  Tooltip,
  InputAdornment,
  IconButton,
  Divider,
  FormHelperText,
  Box
} from '@mui/material';
import {
  Save as SaveIcon,
  Refresh as RefreshIcon,
  PlayArrow as TestIcon,
  Visibility as VisibilityIcon,
  VisibilityOff as VisibilityOffIcon,
  Info as InfoIcon
} from '@mui/icons-material';
import { configurationService } from '../../services/api';

const ElasticsearchConfigPanel: React.FC = () => {
  const { t } = useTranslation(['elasticsearch', 'common']);
  
  const [config, setConfig] = useState({
    enabled: false,
    host: 'http://elasticsearch:9200',
    indexName: 'dbmanager-audit-logs',
    username: '',
    password: '',
    apiKey: '',
    verifySSL: true,
    timeout: 5,
    batchSize: 100,
    retryCount: 3
  });
  
  const [loading, setLoading] = useState(false);
  const [testingConnection, setTestingConnection] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);
  
  useEffect(() => {
    fetchConfig();
  }, []);
  
  const fetchConfig = async () => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await configurationService.getElasticsearchConfig();
      if (response.success && response.config) {
        setConfig(response.config);
      }
    } catch (err: any) {
      setError(err.response?.data?.message || t('errors.fetchFailed'));
    } finally {
      setLoading(false);
    }
  };
  
  const handleSaveConfig = async () => {
    setSaving(true);
    setError(null);
    setSuccess(null);
    
    try {
      const response = await configurationService.updateElasticsearchConfig({ config });
      if (response.success) {
        setSuccess(t('saveSuccess'));
      }
    } catch (err: any) {
      setError(err.response?.data?.message || t('errors.saveFailed'));
    } finally {
      setSaving(false);
    }
  };
  
  const handleTestConnection = async () => {
    setTestingConnection(true);
    setError(null);
    setSuccess(null);
    
    try {
      const response = await configurationService.testElasticsearchConnection({ config });
      if (response.success) {
        setSuccess(t('testSuccess'));
      } else {
        setError(response.message || t('testFailed'));
      }
    } catch (err: any) {
      setError(err.response?.data?.message || t('testFailed'));
    } finally {
      setTestingConnection(false);
    }
  };
  
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = e.target;
    
    if (type === 'checkbox') {
      setConfig({ ...config, [name]: checked });
    } else if (type === 'number') {
      setConfig({ ...config, [name]: parseInt(value) });
    } else {
      setConfig({ ...config, [name]: value });
    }
  };
  
  return (
    <Card>
      <CardHeader
        title={
          <Box display="flex" alignItems="center">
            <Typography variant="h6">{t('title')}</Typography>
            <Tooltip title={t('description')}>
              <IconButton size="small" sx={{ ml: 1 }}>
                <InfoIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </Box>
        }
      />
      
      <CardContent>
        {loading ? (
          <Box display="flex" justifyContent="center" p={3}>
            <CircularProgress />
          </Box>
        ) : (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Alert severity="info">
                {t('description')}
              </Alert>
            </Grid>
            
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Switch
                    checked={config.enabled}
                    onChange={handleInputChange}
                    name="enabled"
                    color="primary"
                  />
                }
                label={t('enabled')}
              />
              <FormHelperText>
                {t('enabledHelper')}
              </FormHelperText>
            </Grid>
            
            <Grid item xs={12} md={8}>
              <TextField
                fullWidth
                label={t('host')}
                name="host"
                value={config.host}
                onChange={handleInputChange}
                disabled={!config.enabled}
                helperText={t('hostHelper')}
              />
            </Grid>
            
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                label={t('indexName')}
                name="indexName"
                value={config.indexName}
                onChange={handleInputChange}
                disabled={!config.enabled}
                helperText={t('indexNameHelper')}
              />
            </Grid>
            
            <Grid item xs={12}>
              <Divider sx={{ my: 2 }} />
              <Typography variant="subtitle1" gutterBottom>
                {t('authentication')}
              </Typography>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label={t('username')}
                name="username"
                value={config.username}
                onChange={handleInputChange}
                disabled={!config.enabled}
                helperText={t('usernameHelper')}
              />
            </Grid>
            
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                type={showPassword ? 'text' : 'password'}
                label={t('password')}
                name="password"
                value={config.password}
                onChange={handleInputChange}
                disabled={!config.enabled}
                helperText={t('passwordHelper')}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        aria-label="toggle password visibility"
                        onClick={() => setShowPassword(!showPassword)}
                        edge="end"
                      >
                        {showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Grid>
            
            <Grid item xs={12}>
              <TextField
                fullWidth
                type={showApiKey ? 'text' : 'password'}
                label={t('apiKey')}
                name="apiKey"
                value={config.apiKey}
                onChange={handleInputChange}
                disabled={!config.enabled}
                helperText={t('apiKeyHelper')}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        aria-label="toggle API key visibility"
                        onClick={() => setShowApiKey(!showApiKey)}
                        edge="end"
                      >
                        {showApiKey ? <VisibilityOffIcon /> : <VisibilityIcon />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Grid>
            
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Switch
                    checked={config.verifySSL}
                    onChange={handleInputChange}
                    name="verifySSL"
                    color="primary"
                    disabled={!config.enabled}
                  />
                }
                label={t('verifySSL')}
              />
              <FormHelperText>
                {t('verifySSLHelper')}
              </FormHelperText>
            </Grid>
            
            <Grid item xs={12}>
              <Divider sx={{ my: 2 }} />
              <Typography variant="subtitle1" gutterBottom>
                {t('performance')}
              </Typography>
            </Grid>
            
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                type="number"
                label={t('timeout')}
                name="timeout"
                value={config.timeout}
                onChange={handleInputChange}
                disabled={!config.enabled}
                InputProps={{ inputProps: { min: 1, max: 60 } }}
                helperText={t('timeoutHelper')}
              />
            </Grid>
            
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                type="number"
                label={t('batchSize')}
                name="batchSize"
                value={config.batchSize}
                onChange={handleInputChange}
                disabled={!config.enabled}
                InputProps={{ inputProps: { min: 10, max: 1000 } }}
                helperText={t('batchSizeHelper')}
              />
            </Grid>
            
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                type="number"
                label={t('retryCount')}
                name="retryCount"
                value={config.retryCount}
                onChange={handleInputChange}
                disabled={!config.enabled}
                InputProps={{ inputProps: { min: 0, max: 10 } }}
                helperText={t('retryCountHelper')}
              />
            </Grid>
            
            {error && (
              <Grid item xs={12}>
                <Alert severity="error">{error}</Alert>
              </Grid>
            )}
            
            {success && (
              <Grid item xs={12}>
                <Alert severity="success">{success}</Alert>
              </Grid>
            )}
          </Grid>
        )}
      </CardContent>
      
      <CardActions sx={{ justifyContent: 'flex-end', p: 2 }}>
        <Button
          variant="outlined"
          startIcon={<RefreshIcon />}
          onClick={fetchConfig}
          disabled={loading || saving || testingConnection}
        >
          {t('common:refresh')}
        </Button>
        
        <Button
          variant="outlined"
          color="primary"
          startIcon={<TestIcon />}
          onClick={handleTestConnection}
          disabled={loading || saving || testingConnection || !config.enabled}
        >
          {testingConnection ? (
            <CircularProgress size={24} />
          ) : (
            t('testConnection')
          )}
        </Button>
        
        <Button
          variant="contained"
          color="primary"
          startIcon={<SaveIcon />}
          onClick={handleSaveConfig}
          disabled={loading || saving || testingConnection}
        >
          {saving ? <CircularProgress size={24} /> : t('common:save')}
        </Button>
      </CardActions>
    </Card>
  );
};

export default ElasticsearchConfigPanel;
