import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useTranslation } from '../../i18n/i18n';
import ConfigPageTemplate from '../../components/Settings/ConfigPageTemplate';
import { 
  Box,
  Typography,
  Paper,
  Button,
  Alert,
  Stack,
  Divider,
  LinearProgress,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Card,
  CardContent,
  Grid,
  Fade,
  CircularProgress,
  Tooltip,
  alpha,
  useTheme,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormHelperText,
  Autocomplete
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  CheckCircle as CheckIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Info as InfoIcon,
  VpnKey as LicenseIcon,
  Schedule as ScheduleIcon,
  Business as BusinessIcon,
  Storage as StorageIcon,
  People as PeopleIcon,
  Category as CategoryIcon,
  CalendarToday as CalendarIcon,
  Refresh as RefreshIcon,
  Delete as DeleteIcon,
  GetApp as DownloadIcon,
  Email as EmailIcon,
  Phone as PhoneIcon,
  Public as PublicIcon,
  Badge as BadgeIcon,
  Person as PersonIcon,
  CardMembership as CardMembershipIcon
} from '@mui/icons-material';
import { apiClient as api } from '../../services/api';
import { LicenseWarning, UploadLicenseResponse } from '../../types/license';

interface LicenseInfo {
  licenseId: string;
  customerId: string;
  customerName: string;
  plan: string;
  maxServers: number;
  maxUsers: number;
  features: string[];
  issuedAt: string;
  expiresAt: string;
  daysRemaining: number;
  isExpired: boolean;
  isTrial: boolean;
}

interface SystemStatus {
  ntpValidated: boolean;
  lastNtpCheck?: string;
  ntpError?: string;
}

const LicenseConfigPage: React.FC = () => {
  const { t } = useTranslation(['settings', 'common', 'errors']);
  const theme = useTheme();
  const fileInputRef = useRef<HTMLInputElement>(null);
  
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [license, setLicense] = useState<LicenseInfo | null>(null);
  const [systemStatus, setSystemStatus] = useState<SystemStatus | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<LicenseWarning[]>([]);
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
  const [licenseKey, setLicenseKey] = useState('');
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [trialDialogOpen, setTrialDialogOpen] = useState(false);
  const [trialFormData, setTrialFormData] = useState({
    contactName: '',
    companyName: '',
    email: '',
    phone: '',
    country: '',
    taxId: '',
    employeeCount: '',
    databaseCount: ''
  });
  const [trialFormErrors, setTrialFormErrors] = useState<Record<string, string>>({});
  const [sendingTrial, setSendingTrial] = useState(false);
  const [countryValidations, setCountryValidations] = useState<Record<string, any>>({});
  const [selectedCountryCode, setSelectedCountryCode] = useState<string>('');

  useEffect(() => {
    fetchLicenseInfo();
    checkSystemStatus();
    fetchCountryValidations();
  }, []);

  const fetchLicenseInfo = async () => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await api.get('/api/license/info');
      setLicense(response.data);
    } catch (err: any) {
      console.error('Error fetching license info:', err);
      if (err.response?.status === 404) {
        // No license found - this is expected for trial mode
        setLicense(null);
      } else {
        setError(t('errors.fetchLicense'));
      }
    } finally {
      setLoading(false);
    }
  };

  const checkSystemStatus = async () => {
    try {
      const response = await api.get('/api/license/status');
      setSystemStatus(response.data);
    } catch (err) {
      console.error('Error checking system status:', err);
      setSystemStatus({ ntpValidated: false, ntpError: 'Failed to check NTP status' });
    }
  };

  const handleUploadClick = () => {
    setUploadDialogOpen(true);
    setLicenseKey('');
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      setLicenseKey(content);
    };
    reader.readAsText(file);
  };

  const handleLicenseSubmit = async () => {
    if (!licenseKey.trim()) {
      setError(t('errors.emptyLicense'));
      return;
    }

    setUploading(true);
    setError(null);
    setWarnings([]);

    try {
      const response = await api.post<UploadLicenseResponse>('/api/license/upload', {
        license: licenseKey.trim()
      });

      if (response.data.success) {
        setSuccess(t('success.licenseUploaded'));
        setUploadDialogOpen(false);
        setLicenseKey('');
        
        // Refresh license info
        await fetchLicenseInfo();
      }
    } catch (err: any) {
      console.error('Error uploading license:', err);
      
      // Extrair warnings da resposta de erro
      const errorData = err.response?.data;
      if (errorData?.warnings) {
        setWarnings(errorData.warnings);
      }
      
      // Verificar se é erro de duplicação
      const isDuplicateError = errorData?.warnings?.some((w: LicenseWarning) => w.type === 'duplicate_usage');
      
      if (isDuplicateError) {
        // Mensagem específica para duplicação
        setError(t('errors.licenseDuplicate') || 'Esta licença já está em uso em outro servidor');
      } else {
        setError(errorData?.error || t('errors.uploadLicense'));
      }
    } finally {
      setUploading(false);
    }
  };

  const handleDeleteLicense = async () => {
    setLoading(true);
    setError(null);

    try {
      await api.delete('/api/license');
      setSuccess(t('success.licenseDeleted'));
      setDeleteDialogOpen(false);
      setLicense(null);
    } catch (err: any) {
      console.error('Error deleting license:', err);
      setError(err.response?.data?.error || t('errors.deleteLicense'));
    } finally {
      setLoading(false);
    }
  };

  const fetchCountryValidations = async () => {
    try {
      const response = await api.get('/api/license/country-validations');
      setCountryValidations(response.data);
    } catch (err) {
      console.error('Error fetching country validations:', err);
    }
  };

  const handleRefresh = async () => {
    await Promise.all([
      fetchLicenseInfo(),
      checkSystemStatus()
    ]);
  };

  // Lista de países para o dropdown
  const countryList = useMemo(() => {
    const countries = new Set<string>();
    Object.values(countryValidations).forEach((validation: any) => {
      validation.countries.forEach((country: string) => {
        countries.add(country);
      });
    });
    return Array.from(countries).sort();
  }, [countryValidations]);

  // Validação atual baseada no país selecionado
  const currentValidation = useMemo(() => {
    if (!selectedCountryCode || !countryValidations[selectedCountryCode]) {
      return null;
    }
    return countryValidations[selectedCountryCode];
  }, [selectedCountryCode, countryValidations]);

  const validateTrialForm = () => {
    const errors: Record<string, string> = {};
    
    if (!trialFormData.contactName.trim()) {
      errors.contactName = t('errors.fieldRequired');
    }
    
    if (!trialFormData.companyName.trim()) {
      errors.companyName = t('errors.fieldRequired');
    }
    
    if (!trialFormData.email.trim()) {
      errors.email = t('errors.fieldRequired');
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trialFormData.email)) {
      errors.email = t('errors.invalidEmail');
    }
    
    if (!trialFormData.country.trim()) {
      errors.country = t('errors.fieldRequired');
    }
    
    // Validação condicional de phone e taxId
    if (currentValidation) {
      // Phone é opcional mas se preenchido deve seguir formato
      if (trialFormData.phone.trim() && currentValidation.phoneFormat) {
        // Validação básica de formato de telefone
        const phoneDigits = trialFormData.phone.replace(/\D/g, '');
        if (phoneDigits.length < 8 || phoneDigits.length > 15) {
          errors.phone = `Format: ${currentValidation.phoneExample}`;
        }
      }
      
      // TaxId é opcional mas se preenchido deve seguir formato
      if (trialFormData.taxId.trim() && currentValidation.taxIdRegex) {
        const regex = new RegExp(currentValidation.taxIdRegex);
        if (!regex.test(trialFormData.taxId)) {
          errors.taxId = `Format: ${currentValidation.taxIdExample}`;
        }
      }
    }
    
    // employeeCount e databaseCount são opcionais
    
    setTrialFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleTrialFormChange = (field: string, value: string) => {
    setTrialFormData(prev => ({
      ...prev,
      [field]: value
    }));
    
    // Se mudou o país, encontrar o código do país
    if (field === 'country') {
      let foundCode = '';
      for (const [code, validation] of Object.entries(countryValidations)) {
        if ((validation as any).countries.includes(value)) {
          foundCode = code;
          break;
        }
      }
      setSelectedCountryCode(foundCode);
    }
    
    // Clear error for this field
    if (trialFormErrors[field]) {
      setTrialFormErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleTrialSubmit = async () => {
    if (!validateTrialForm()) {
      return;
    }

    setSendingTrial(true);
    setError(null);

    try {
      // Preparar dados para a API
      const requestData: any = {
        contactName: trialFormData.contactName,
        companyName: trialFormData.companyName,
        email: trialFormData.email,
        country: trialFormData.country
      };
      
      // Adicionar campos opcionais se preenchidos
      if (trialFormData.phone.trim()) {
        requestData.phone = trialFormData.phone;
      }
      if (trialFormData.taxId.trim()) {
        requestData.taxId = trialFormData.taxId;
      }
      if (trialFormData.employeeCount) {
        requestData.numberOfEmployees = trialFormData.employeeCount;
      }
      if (trialFormData.databaseCount) {
        requestData.numberOfDatabases = parseInt(trialFormData.databaseCount);
      }
      
      // Enviar para a API
      const response = await api.post('/api/license/trial/request', requestData);
      
      if (response.data.success) {
        setSuccess(t('success.trialRequested'));
        setTrialDialogOpen(false);
        
        // Resetar formulário
        setTrialFormData({
          contactName: '',
          companyName: '',
          email: '',
          phone: '',
          country: '',
          taxId: '',
          employeeCount: '',
          databaseCount: ''
        });
        setSelectedCountryCode('');
      } else {
        setError(response.data.error || t('errors.trialRequest'));
      }
    } catch (err: any) {
      console.error('Error requesting trial:', err);
      setError(err.response?.data?.error || t('errors.trialRequest'));
    } finally {
      setSendingTrial(false);
    }
  };

  const getPlanColor = (plan: string) => {
    switch (plan.toLowerCase()) {
      case 'trial':
        return 'warning';
      case 'basic':
        return 'info';
      case 'professional':
        return 'primary';
      case 'enterprise':
        return 'success';
      default:
        return 'default';
    }
  };

  const getExpirationStatus = () => {
    if (!license) return null;

    if (license.isExpired) {
      return { color: 'error', icon: <ErrorIcon />, text: t('license.expired') };
    }
    
    if (license.daysRemaining <= 7) {
      return { color: 'error', icon: <WarningIcon />, text: t('license.expiringSoon', { days: license.daysRemaining }) };
    }
    
    if (license.daysRemaining <= 30) {
      return { color: 'warning', icon: <WarningIcon />, text: t('license.expiringWarning', { days: license.daysRemaining }) };
    }

    return { color: 'success', icon: <CheckIcon />, text: t('license.valid', { days: license.daysRemaining }) };
  };

  return (
    <ConfigPageTemplate
      title={t('sections.license.title')}
      icon={<CardMembershipIcon sx={{ fontSize: 32 }} />}
      description={t('sections.license.description')}
    >
      <Fade in timeout={300}>
        <Box>
          <Stack direction="row" justifyContent="flex-end" mb={3}>
            <Button
              variant="outlined"
              startIcon={<RefreshIcon />}
              onClick={handleRefresh}
              disabled={loading}
            >
              {t('common:refresh')}
            </Button>
          </Stack>

        {/* System Status Alert */}
        {systemStatus && !systemStatus.ntpValidated && (
          <Alert 
            severity="error" 
            sx={{ mb: 3 }}
            icon={<ErrorIcon />}
          >
            <Typography variant="body2" fontWeight="medium">
              {t('license.ntpError')}
            </Typography>
            {systemStatus.ntpError && (
              <Typography variant="caption" display="block" mt={1}>
                {systemStatus.ntpError}
              </Typography>
            )}
          </Alert>
        )}

        {/* Error/Success Messages */}
        {error && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
            {error}
          </Alert>
        )}
        
        {success && (
          <Alert severity="success" sx={{ mb: 3 }} onClose={() => setSuccess(null)}>
            {success}
          </Alert>
        )}

        {loading ? (
          <Box display="flex" justifyContent="center" py={8}>
            <CircularProgress />
          </Box>
        ) : license && license.customerId !== 'DEMO' ? (
          /* License Info Display */
          <Grid container spacing={3}>
            <Grid item xs={12} md={8}>
              <Card elevation={0} sx={{ border: `1px solid ${alpha(theme.palette.divider, 0.2)}` }}>
                <CardContent>
                  <Stack direction="row" alignItems="center" spacing={2} mb={3}>
                    <LicenseIcon color="primary" fontSize="large" />
                    <Box flex={1}>
                      <Typography variant="h5" fontWeight="bold">
                        {license.customerName}
                      </Typography>
                      <Stack direction="row" spacing={2} alignItems="center" mt={1}>
                        <Chip 
                          label={license.plan.toUpperCase()} 
                          color={getPlanColor(license.plan) as any}
                          size="small"
                        />
                        {license.isTrial && (
                          <Chip 
                            label={t('license.trialMode')} 
                            color="warning" 
                            size="small"
                            variant="outlined"
                          />
                        )}
                      </Stack>
                    </Box>
                    <Tooltip title={license.isTrial ? 'Cannot delete trial license' : t('license.deleteLicense')}>
                      <span>
                        <IconButton
                          color="error"
                          onClick={() => setDeleteDialogOpen(true)}
                          disabled={license.isTrial || loading}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </span>
                    </Tooltip>
                  </Stack>

                  <Divider sx={{ my: 3 }} />

                  {/* License Details */}
                  <Grid container spacing={3}>
                    <Grid item xs={12} sm={6}>
                      <Stack spacing={2}>
                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {t('license.licenseId')}
                          </Typography>
                          <Typography variant="body2" fontFamily="monospace">
                            {license.licenseId}
                          </Typography>
                        </Box>
                        
                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {t('license.customerId')}
                          </Typography>
                          <Typography variant="body2" fontFamily="monospace">
                            {license.customerId}
                          </Typography>
                        </Box>

                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {t('license.issuedAt')}
                          </Typography>
                          <Typography variant="body2">
                            {new Date(license.issuedAt).toLocaleDateString()}
                          </Typography>
                        </Box>
                      </Stack>
                    </Grid>

                    <Grid item xs={12} sm={6}>
                      <Stack spacing={2}>
                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {t('license.maxServers')}
                          </Typography>
                          <Stack direction="row" alignItems="center" spacing={1}>
                            <StorageIcon fontSize="small" color="action" />
                            <Typography variant="body2">
                              {license.maxServers === 0 ? t('license.unlimited') : license.maxServers}
                            </Typography>
                          </Stack>
                        </Box>

                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {t('license.maxUsers')}
                          </Typography>
                          <Stack direction="row" alignItems="center" spacing={1}>
                            <PeopleIcon fontSize="small" color="action" />
                            <Typography variant="body2">
                              {license.maxUsers === 0 ? t('license.unlimited') : license.maxUsers}
                            </Typography>
                          </Stack>
                        </Box>

                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {t('license.expiresAt')}
                          </Typography>
                          <Typography variant="body2">
                            {new Date(license.expiresAt).toLocaleDateString()}
                          </Typography>
                        </Box>
                      </Stack>
                    </Grid>
                  </Grid>

                  {/* Features */}
                  {license.features.length > 0 && (
                    <>
                      <Divider sx={{ my: 3 }} />
                      <Box>
                        <Typography variant="subtitle2" gutterBottom>
                          {t('license.features')}
                        </Typography>
                        <Stack direction="row" flexWrap="wrap" gap={1} mt={1}>
                          {license.features.map((feature) => (
                            <Chip
                              key={feature}
                              label={feature}
                              size="small"
                              variant="outlined"
                              icon={<CheckIcon />}
                            />
                          ))}
                        </Stack>
                      </Box>
                    </>
                  )}
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} md={4}>
              {/* Expiration Status */}
              <Paper 
                sx={{ 
                  p: 3, 
                  mb: 3,
                  backgroundColor: alpha(
                    (theme.palette[(getExpirationStatus()?.color || 'success') as 'primary' | 'secondary' | 'error' | 'warning' | 'info' | 'success'] as any).main, 
                    0.05
                  ),
                  border: `1px solid ${alpha(
                    (theme.palette[(getExpirationStatus()?.color || 'success') as 'primary' | 'secondary' | 'error' | 'warning' | 'info' | 'success'] as any).main, 
                    0.2
                  )}`
                }}
              >
                <Stack direction="row" alignItems="center" spacing={2}>
                  {getExpirationStatus()?.icon}
                  <Box>
                    <Typography variant="subtitle2">
                      {t('license.status')}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      {getExpirationStatus()?.text}
                    </Typography>
                  </Box>
                </Stack>
              </Paper>

              {/* Actions */}
              <Stack spacing={2}>
                <Button
                  variant="contained"
                  fullWidth
                  startIcon={<UploadIcon />}
                  onClick={handleUploadClick}
                  disabled={loading}
                >
                  {t('license.updateLicense')}
                </Button>
              </Stack>
            </Grid>
          </Grid>
        ) : (
          /* No License - Trial Mode */
          <Paper sx={{ p: 6, textAlign: 'center' }}>
            <WarningIcon color="warning" sx={{ fontSize: 64, mb: 2 }} />
            <Typography variant="h5" gutterBottom>
              {t('license.noLicense')}
            </Typography>
            <Typography variant="body1" color="text.secondary" mb={4}>
              {t('license.trialDescription')}
            </Typography>
            <Stack direction="row" spacing={2} justifyContent="center">
              <Button
                variant="outlined"
                size="large"
                startIcon={<EmailIcon />}
                onClick={() => setTrialDialogOpen(true)}
              >
                {t('license.requestTrial')}
              </Button>
              <Button
                variant="contained"
                size="large"
                startIcon={<UploadIcon />}
                onClick={handleUploadClick}
              >
                {t('license.uploadLicense')}
              </Button>
            </Stack>
          </Paper>
        )}

        {/* Upload Dialog */}
        <Dialog
          open={uploadDialogOpen}
          onClose={() => {
            if (!uploading) {
              setUploadDialogOpen(false);
              setError(null);
              setWarnings([]);
              setLicenseKey('');
            }
          }}
          maxWidth="sm"
          fullWidth
        >
          <DialogTitle>
            {t('license.uploadLicenseTitle')}
          </DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary" mb={3}>
              {t('license.uploadDescription')}
            </Typography>

            {/* File Upload */}
            <input
              ref={fileInputRef}
              type="file"
              accept=".lic,.txt"
              style={{ display: 'none' }}
              onChange={handleFileUpload}
            />
            
            <Button
              variant="outlined"
              fullWidth
              startIcon={<DownloadIcon />}
              onClick={() => fileInputRef.current?.click()}
              sx={{ mb: 2 }}
            >
              {t('license.selectFile')}
            </Button>

            <Typography variant="body2" color="text.secondary" align="center" mb={2}>
              {t('common:or')}
            </Typography>

            {/* License Key Input */}
            <TextField
              fullWidth
              multiline
              rows={8}
              variant="outlined"
              label={t('license.licenseKey')}
              value={licenseKey}
              onChange={(e) => setLicenseKey(e.target.value)}
              placeholder={t('license.pasteLicense') as string}
              sx={{ fontFamily: 'monospace' }}
            />
            
            {/* Error Alert for Duplicate License */}
            {error && warnings.some(w => w.type === 'duplicate_usage') && (
              <Alert severity="error" sx={{ mt: 2 }}>
                <Typography variant="body2" fontWeight="bold" gutterBottom>
                  {t('errors.licenseDuplicate') || 'Licença Bloqueada - Uso Duplicado'}
                </Typography>
                {warnings.find(w => w.type === 'duplicate_usage')?.message && (
                  <Typography variant="body2" sx={{ mt: 1 }}>
                    {warnings.find(w => w.type === 'duplicate_usage')?.message}
                  </Typography>
                )}
                <Typography variant="body2" sx={{ mt: 1 }} color="text.secondary">
                  {t('errors.duplicateHelp') || 'Para usar esta licença neste servidor, primeiro desative-a nos outros servidores listados acima.'}
                </Typography>
              </Alert>
            )}
            
            {/* General Error Alert */}
            {error && !warnings.some(w => w.type === 'duplicate_usage') && (
              <Alert severity="error" sx={{ mt: 2 }}>
                {error}
              </Alert>
            )}
          </DialogContent>
          <DialogActions>
            <Button 
              onClick={() => {
                setUploadDialogOpen(false);
                setError(null);
                setWarnings([]);
                setLicenseKey('');
              }} 
              disabled={uploading}
            >
              {t('common:cancel')}
            </Button>
            <Button
              variant="contained"
              onClick={handleLicenseSubmit}
              disabled={uploading || !licenseKey.trim()}
              startIcon={uploading && <CircularProgress size={20} />}
            >
              {t('common:upload')}
            </Button>
          </DialogActions>
        </Dialog>

        {/* Delete Confirmation Dialog */}
        <Dialog
          open={deleteDialogOpen}
          onClose={() => setDeleteDialogOpen(false)}
        >
          <DialogTitle>
            {t('license.deleteConfirmTitle')}
          </DialogTitle>
          <DialogContent>
            <Typography variant="body2">
              {t('license.deleteConfirmMessage')}
            </Typography>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setDeleteDialogOpen(false)}>
              {t('common:cancel')}
            </Button>
            <Button
              variant="contained"
              color="error"
              onClick={handleDeleteLicense}
              disabled={loading}
            >
              {t('common:delete')}
            </Button>
          </DialogActions>
        </Dialog>

        {/* Trial Request Dialog */}
        <Dialog
          open={trialDialogOpen}
          onClose={() => !sendingTrial && setTrialDialogOpen(false)}
          maxWidth="md"
          fullWidth
        >
          <DialogTitle>
            {t('license.requestTrialTitle')}
          </DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary" mb={3}>
              {t('license.trialFormDescription')}
            </Typography>

            <Grid container spacing={3}>
              {/* Contact Information */}
              <Grid item xs={12}>
                <Typography variant="h6" gutterBottom>
                  {t('license.contactInfo')}
                </Typography>
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('license.contactName')}
                  value={trialFormData.contactName}
                  onChange={(e) => handleTrialFormChange('contactName', e.target.value)}
                  error={!!trialFormErrors.contactName}
                  helperText={trialFormErrors.contactName}
                  required
                  InputProps={{
                    startAdornment: <PersonIcon sx={{ mr: 1, color: 'action.active' }} />
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('license.companyName')}
                  value={trialFormData.companyName}
                  onChange={(e) => handleTrialFormChange('companyName', e.target.value)}
                  error={!!trialFormErrors.companyName}
                  helperText={trialFormErrors.companyName}
                  required
                  InputProps={{
                    startAdornment: <BusinessIcon sx={{ mr: 1, color: 'action.active' }} />
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  type="email"
                  label={t('license.email')}
                  value={trialFormData.email}
                  onChange={(e) => handleTrialFormChange('email', e.target.value)}
                  error={!!trialFormErrors.email}
                  helperText={trialFormErrors.email}
                  required
                  InputProps={{
                    startAdornment: <EmailIcon sx={{ mr: 1, color: 'action.active' }} />
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <Autocomplete
                  fullWidth
                  options={countryList}
                  value={trialFormData.country}
                  onChange={(_, value) => handleTrialFormChange('country', value || '')}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      label={t('license.country')}
                      error={!!trialFormErrors.country}
                      helperText={trialFormErrors.country}
                      required
                      InputProps={{
                        ...params.InputProps,
                        startAdornment: (
                          <>
                            <PublicIcon sx={{ mr: 1, color: 'action.active' }} />
                            {params.InputProps.startAdornment}
                          </>
                        ),
                      }}
                    />
                  )}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('license.phone')}
                  value={trialFormData.phone}
                  onChange={(e) => handleTrialFormChange('phone', e.target.value)}
                  error={!!trialFormErrors.phone}
                  helperText={trialFormErrors.phone || (currentValidation && `${t('license.format')}: ${currentValidation.phoneExample}`)}
                  placeholder={currentValidation?.phoneExample || "+1 (555) 123-4567"}
                  InputProps={{
                    startAdornment: <PhoneIcon sx={{ mr: 1, color: 'action.active' }} />
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label={t('license.taxId')} 
                  value={trialFormData.taxId}
                  onChange={(e) => handleTrialFormChange('taxId', e.target.value)}
                  error={!!trialFormErrors.taxId}
                  helperText={
                    trialFormErrors.taxId || 
                    (currentValidation && `${currentValidation.taxIdFormat}${currentValidation.taxIdExample ? ` - Ex: ${currentValidation.taxIdExample}` : ''}`)
                  }
                  placeholder={currentValidation?.taxIdExample || "123456789"}
                  InputProps={{
                    startAdornment: <BadgeIcon sx={{ mr: 1, color: 'action.active' }} />
                  }}
                />
              </Grid>

              {/* Company Information */}
              <Grid item xs={12}>
                <Divider sx={{ my: 2 }} />
                <Typography variant="h6" gutterBottom>
                  {t('license.companyInfo')}
                </Typography>
              </Grid>

              <Grid item xs={12} sm={6}>
                <FormControl fullWidth error={!!trialFormErrors.employeeCount}>
                  <InputLabel>{t('license.employeeCount')}</InputLabel>
                  <Select
                    value={trialFormData.employeeCount}
                    onChange={(e) => handleTrialFormChange('employeeCount', e.target.value)}
                    label={t('license.employeeCount')}
                    startAdornment={<PeopleIcon sx={{ mr: 1, ml: 1, color: 'action.active' }} />}
                  >
                    <MenuItem value="1-10">1-10</MenuItem>
                    <MenuItem value="11-50">11-50</MenuItem>
                    <MenuItem value="51-200">51-200</MenuItem>
                    <MenuItem value="201-500">201-500</MenuItem>
                    <MenuItem value="500+">500+</MenuItem>
                  </Select>
                  {trialFormErrors.employeeCount && (
                    <FormHelperText>{trialFormErrors.employeeCount}</FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  type="number"
                  label={t('license.databaseCount')}
                  value={trialFormData.databaseCount}
                  onChange={(e) => handleTrialFormChange('databaseCount', e.target.value)}
                  error={!!trialFormErrors.databaseCount}
                  helperText={trialFormErrors.databaseCount}
                  InputProps={{
                    startAdornment: <StorageIcon sx={{ mr: 1, color: 'action.active' }} />,
                    inputProps: { min: 1, max: 999 }
                  }}
                />
              </Grid>
            </Grid>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setTrialDialogOpen(false)} disabled={sendingTrial}>
              {t('common:cancel')}
            </Button>
            <Button
              variant="contained"
              onClick={handleTrialSubmit}
              disabled={sendingTrial}
              startIcon={sendingTrial && <CircularProgress size={20} />}
            >
              {t('license.submitTrialRequest')}
            </Button>
          </DialogActions>
        </Dialog>
        </Box>
      </Fade>
    </ConfigPageTemplate>
  );
};

export default LicenseConfigPage;
