import React, { useEffect, useState, useRef } from 'react';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  CircularProgress,
  Chip,
  Paper,
  Avatar,
  alpha,
  styled,
  useTheme,
  Zoom,
  Collapse
} from '@mui/material';
import {
  FolderOpen as FolderOpenIcon,
  Public as PublicIcon,
  DataObject as DataObjectIcon,
  Shield as ShieldIcon,
  ErrorOutline as ErrorIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps, DatabaseType } from '../../types';
import StepLayout from '../shared/StepLayout';

// Card selecionável com efeitos de hover
const StyledCard = styled(Card)(({ theme }) => ({
  transition: 'all 0.3s ease',
  position: 'relative',
  overflow: 'hidden',
  height: '100%',
  cursor: 'pointer',
  '&:hover': {
    transform: 'translateY(-4px)',
    boxShadow: theme.shadows[4],
  },
  '&::after': {
    content: '""',
    position: 'absolute',
    inset: 0,
    transition: 'opacity 0.3s ease',
    opacity: 0,
    background: `linear-gradient(45deg, ${alpha(theme.palette.primary.main, 0.1)}, ${alpha(theme.palette.primary.light, 0.15)})`,
  },
  '&:hover::after': {
    opacity: 1,
  }
}));

// Card selecionado com efeito de destaque
const SelectedCard = styled(Card)(({ theme }) => ({
  border: `2px solid ${theme.palette.primary.main}`,
  boxShadow: `0 0 12px ${alpha(theme.palette.primary.main, 0.4)}`,
  position: 'relative',
  overflow: 'hidden',
  height: '100%',
  cursor: 'pointer',
  '&::after': {
    content: '""',
    position: 'absolute',
    inset: 0,
    background: `linear-gradient(45deg, ${alpha(theme.palette.primary.main, 0.15)}, ${alpha(theme.palette.primary.light, 0.2)})`,
  }
}));

// Error container with shake animation
const ErrorContainer = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(1.5),
  marginTop: theme.spacing(2),
  backgroundColor: alpha(theme.palette.error.main, 0.1),
  border: `1px solid ${theme.palette.error.light}`,
  borderRadius: theme.shape.borderRadius,
  '@keyframes shake': {
    '0%, 100%': { transform: 'translateX(0)' },
    '10%, 30%, 50%, 70%, 90%': { transform: 'translateX(-5px)' },
    '20%, 40%, 60%, 80%': { transform: 'translateX(5px)' }
  }
}));

// NextButton removido - não utilizado

/**
 * Componente para a etapa de seleção de schema
 */
const SchemaStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t } = useTranslation(['requests', 'common', 'error']);
  const theme = useTheme();
  // setShakeError removido - não utilizado
  const errorRef = useRef<HTMLDivElement>(null);
  const selectedCardRef = useRef<HTMLDivElement>(null);
  // Flag para controlar tentativa de avanço automático
  const autoAdvanceAttempted = useRef(false);

  // Debug do estado inicial
  console.log("SchemaStep - Estado inicial:", {
    schemaName: state.schemaName,
    databaseType: state.databaseType,
    serverId: state.serverId,
    databaseName: state.databaseName,
    schemas: state.schemas
  });

  // Scroll para o card selecionado quando um schema é selecionado
  useEffect(() => {
    console.log("useEffect - state.schemaName mudou para:", state.schemaName);
    if (state.schemaName && selectedCardRef.current) {
      console.log("Scrolling para schema selecionado:", state.schemaName);
      selectedCardRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest'
      });
    }
  }, [state.schemaName]);

  // Efeito para resetar o flag quando o banco de dados ou servidor mudam
  useEffect(() => {
    autoAdvanceAttempted.current = false;
    console.log("Reset flag autoAdvanceAttempted devido a mudança de servidor ou banco");
  }, [state.serverId, state.databaseName]);

  // Verificar se estamos trabalhando com banco que usa schemas (PostgreSQL ou MSSQL)
  useEffect(() => {
    const usesSchemas = state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE;
    if (!usesSchemas) {
      // Se não usa schemas (MySQL), avançar para a próxima etapa automaticamente
      onNext();
    } else {
      console.log(`Estamos trabalhando com ${state.databaseType}, aguardando seleção de schema...`);

      // Verificar se já temos schemas disponíveis - não fazemos nada neste caso
    }
  }, [state.databaseType, onNext]);

  // Efeito separado para lidar com schemas vazios e buscar dados
  useEffect(() => {
    // Não fazemos nada se não usa schemas
    const usesSchemas = state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE;
    if (!usesSchemas) return;

    // Se já temos schemas e há apenas um schema, tentar avançar automaticamente
    if (state.schemas.length === 1 && !autoAdvanceAttempted.current) {
      autoAdvanceAttempted.current = true;
      const selectedSchema = state.schemas[0];
      console.log(`Apenas um schema disponível (${selectedSchema}), selecionando automaticamente e buscando tabelas`);
      dispatch({ type: 'SET_SCHEMA', payload: selectedSchema });
      
      // Buscar tabelas para o schema antes de avançar
      const fetchTablesAndAdvance = async () => {
        try {
          const realServerId = state.serverId.includes(':') ? state.serverId.split(':')[0] : state.serverId;
          console.log(`Buscando tabelas para servidor ${realServerId}, banco ${state.databaseName}, schema ${selectedSchema}`);

          const { serverService } = await import('../../../../services/api');
          const response = await serverService.getTables(realServerId, state.databaseName, selectedSchema);

          if (response && response.tables && Array.isArray(response.tables)) {
            const tables = response.tables.map(tableName => ({
              name: tableName,
              serverId: realServerId,
              databaseName: state.databaseName,
              schemaName: selectedSchema
            }));

            console.log(`${tables.length} tabelas encontradas para o schema ${selectedSchema}`);
            dispatch({ type: 'SET_TABLES_DATA', payload: tables });
          } else {
            console.warn(`Nenhuma tabela encontrada ou resposta inválida:`, response);
          }
        } catch (error) {
          console.error("Erro ao buscar tabelas:", error);
        } finally {
          // Avançar após buscar tabelas (com ou sem sucesso)
          console.log("Avançando automaticamente após buscar tabelas");
          onNext();
        }
      };
      
      // Iniciar busca de tabelas com pequeno delay
      setTimeout(fetchTablesAndAdvance, 300);
      
      return;
    }

    // Se não temos schemas ainda, buscá-los
    if (state.schemas.length === 0) {
      // Garantir que temos um serverId válido
      const serverId = state.serverId;
      if (serverId) {
        console.log("Schemas vazios, iniciando busca...");
        
        // Buscar schemas para o servidor e database selecionados
        const fetchSchemas = async () => {
          try {
            // Obter o ID real do servidor (sem componentes)
            const realServerId = serverId.includes(':') ? serverId.split(':')[0] : serverId;
            console.log(`Buscando schemas para servidor ${realServerId} e banco ${state.databaseName}`);

            const { serverService } = await import('../../../../services/api');
            const response = await serverService.getSchemas(realServerId, state.databaseName);

            if (response && response.schemas && Array.isArray(response.schemas)) {
              console.log(`Schemas encontrados:`, response.schemas);
              dispatch({ type: 'SET_SCHEMAS', payload: response.schemas });
            }
          } catch (error) {
            console.error("Erro ao buscar schemas:", error);
            // Usar schemas padrão como fallback
            const fallbackSchemas = ['public', 'information_schema', 'pg_catalog'];
            console.log("Usando schemas padrão como fallback:", fallbackSchemas);
            dispatch({ type: 'SET_SCHEMAS', payload: fallbackSchemas });
          }
        };

        fetchSchemas();
      }
    }
    
    // Resetar flag quando o componente é desmontado
    return () => {
      autoAdvanceAttempted.current = false;
      console.log("Cleanup: reset autoAdvanceAttempted on unmount");
    };
  }, [state.databaseType, state.schemas.length, state.serverId, state.databaseName, state.schemas, dispatch, onNext]);


  // Manipulador para mudança de schema
  const handleSchemaChange = async (schemaName: string) => {
    console.log("Schema selecionado:", schemaName);

    // Verificar se o clique está sendo processado
    if (state.schemaName === schemaName) {
      console.log("Schema já selecionado, ignorando clique");
      return;
    }

    // Mostrar que estamos carregando
    dispatch({ type: 'SET_LOADING', payload: true });

    try {
      // Atualizar o estado
      dispatch({ type: 'SET_SCHEMA', payload: schemaName });

      // Resetar tabelas
      dispatch({ type: 'SET_TABLES', payload: [] });

      // Buscar tabelas para o schema selecionado
      if (schemaName && state.serverId && state.databaseName) {
        try {
          // Obter o ID real do servidor
          const realServerId = state.serverId.includes(':') ? state.serverId.split(':')[0] : state.serverId;

          console.log(`Buscando tabelas para servidor ${realServerId}, banco ${state.databaseName}, schema ${schemaName}`);

          const { serverService } = await import('../../../../services/api');
          const response = await serverService.getTables(realServerId, state.databaseName, schemaName);

          if (response && response.tables && Array.isArray(response.tables)) {
            const tables = response.tables.map(tableName => ({
              name: tableName,
              serverId: realServerId,
              databaseName: state.databaseName,
              schemaName
            }));

            console.log(`${tables.length} tabelas encontradas para o schema ${schemaName}`);
            dispatch({ type: 'SET_TABLES_DATA', payload: tables });
          } else {
            console.warn(`Nenhuma tabela encontrada para o schema ${schemaName}`);
            dispatch({
              type: 'SET_ERRORS',
              payload: { tables: `Nenhuma tabela encontrada no schema ${schemaName}. O schema pode estar vazio ou inacessível.` }
            });
            dispatch({ type: 'SET_TABLES_DATA', payload: [] });
          }
        } catch (error) {
          console.error('Erro ao buscar tabelas para o schema:', error);
          dispatch({
            type: 'SET_ERRORS',
            payload: { tables: 'Ocorreu um erro ao buscar tabelas. Tente novamente mais tarde.' }
          });
          dispatch({ type: 'SET_TABLES_DATA', payload: [] });
        }
      } else {
        console.warn("Dados insuficientes para buscar tabelas (serverId, databaseName ou schema ausente)");
      }
    } catch (error) {
      console.error("Erro ao processar mudança de schema:", error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { schemaName: 'Erro ao processar schema. Tente novamente.' }
      });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Função para avançar para a próxima etapa
  // Removida a função handleNext para evitar duplicação de botões
  // A validação é feita no componente principal do modal

  // Obter configurações visuais baseado no tipo de schema
  const getSchemaConfig = (schema: string) => {
    if (schema === 'public') {
      return {
        icon: <PublicIcon />,
        color: theme.palette.success.main,
        label: t('requests:database.defaultSchema', 'Default Schema'),
        description: t('database.containsUserObjects', 'Contains user tables and objects'),
        isSystem: false,
        tooltipText: t('database.publicSchemaTooltip', 'PostgreSQL default schema')
      };
    } else if (schema === 'information_schema') {
      return {
        icon: <DataObjectIcon />,
        color: theme.palette.warning.main,
        label: t('database.systemSchema', 'System Schema'),
        description: t('database.containsMetadata', 'Contains database metadata'),
        isSystem: true,
        tooltipText: t('database.infoSchemaTooltip', 'Contains metadata for database objects')
      };
    } else if (schema === 'pg_catalog') {
      return {
        icon: <ShieldIcon />,
        color: theme.palette.error.main,
        label: t('database.systemSchema', 'System Schema'),
        description: t('database.containsSystemObjects', 'Contains system tables and functions'),
        isSystem: true,
        tooltipText: t('database.pgCatalogTooltip', 'Critical schema with system objects')
      };
    } else {
      return {
        icon: <FolderOpenIcon />,
        color: theme.palette.primary.main,
        label: t('database.customSchema', 'Custom Schema'),
        description: t('database.userDefinedSchema', 'User-defined schema'),
        isSystem: false,
        tooltipText: t('database.customSchemaTooltip', 'Custom PostgreSQL schema')
      };
    }
  };

  // Renderizar informação adicional para o schema selecionado
  const renderSchemaInfo = () => {
    if (!state.schemaName) return null;

    if (state.schemaName === 'public') {
      return (
        <Paper elevation={0} sx={{ mt: 2, p: 2, bgcolor: alpha(theme.palette.info.main, 0.1), borderRadius: 1 }}>
          <Typography variant="body2">
            {t('wizard.publicSchemaInfo')}
          </Typography>
        </Paper>
      );
    } else if (state.schemaName === 'information_schema') {
      return (
        <Paper elevation={0} sx={{ mt: 2, p: 2, bgcolor: alpha(theme.palette.warning.main, 0.1), borderRadius: 1 }}>
          <Typography variant="body2">
            {t('wizard.informationSchemaWarning')}
          </Typography>
        </Paper>
      );
    } else if (state.schemaName === 'pg_catalog') {
      return (
        <Paper elevation={0} sx={{ mt: 2, p: 2, bgcolor: alpha(theme.palette.error.main, 0.1), borderRadius: 1 }}>
          <Typography variant="body2">
            {t('wizard.pgCatalogWarning')}
          </Typography>
        </Paper>
      );
    }

    return null;
  };

  return (
    <StepLayout
      title={String(t('wizard.steps.schema'))}
      subtitle={String(t('wizard.schemaStepSubtitle'))}
      icon="schema"
    >
      <Grid container spacing={3}>
        {state.isLoading ? (
          <Grid item xs={12} display="flex" justifyContent="center">
            <CircularProgress />
          </Grid>
        ) : state.schemas.length === 0 ? (
          <Grid item xs={12}>
            <Typography color="error">
              {state.errors.schemaName || t('wizard.error.noSchemasAvailable')}
            </Typography>
          </Grid>
        ) : (
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom sx={{ mb: 2 }}>
              {t('wizard.selectSchema')}
            </Typography>

            {/* Debug info */}
            {state.schemaName && (
              <Typography variant="body2" color="primary" sx={{ mb: 2 }}>
                Schema selecionado atualmente: {state.schemaName}
              </Typography>
            )}

            <Grid container spacing={2}>
              {state.schemas.map((schema, index) => {
                const isSelected = schema === state.schemaName;
                const CardComponent = isSelected ? SelectedCard : StyledCard;
                const config = getSchemaConfig(schema);

                return (
                  <Zoom
                    in={true}
                    style={{ transitionDelay: `${index * 50}ms` }}
                    key={schema}
                  >
                    <Grid item xs={12} sm={6} md={4}
                      ref={isSelected ? selectedCardRef : undefined}
                    >
                      <CardComponent 
                        elevation={isSelected ? 8 : 1}
                        onClick={() => {
                          if (!state.isLoading) {
                            console.log(`Card clicado diretamente para schema: ${schema}`);
                            handleSchemaChange(schema);
                          }
                        }}
                        sx={{ 
                          cursor: state.isLoading ? 'wait' : 'pointer',
                          '&:hover': {
                            transform: state.isLoading ? 'none' : 'translateY(-4px)',
                          }
                        }}
                      >
                        <CardContent sx={{ p: 2 }}>
                            <Box display="flex" alignItems="center" mb={1}>
                              <Avatar
                                sx={{
                                  bgcolor: alpha(config.color, 0.8),
                                  color: '#fff',
                                  width: 48,
                                  height: 48,
                                  mr: 1.5,
                                }}
                              >
                                {config.icon}
                              </Avatar>
                              <Box flexGrow={1}>
                                <Typography variant="h6" component="div" noWrap>
                                  {schema}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                  {config.description}
                                </Typography>
                              </Box>
                            </Box>

                            <Box display="flex" justifyContent="space-between" alignItems="center" mt={1}>
                              <Chip
                                label={config.label}
                                size="small"
                                variant={isSelected ? "filled" : "outlined"}
                                color={config.isSystem ? "warning" : "primary"}
                              />

                              {isSelected && (
                                <Chip
                                  label={t('common:selected')}
                                  size="small"
                                  color="success"
                                />
                              )}
                            </Box>
                          </CardContent>
                      </CardComponent>
                    </Grid>
                  </Zoom>
                );
              })}
            </Grid>

            {/* Mensagem de erro com animação de shake */}
            <Collapse in={!!state.errors.schemaName}>
              <Box ref={errorRef}>
                <ErrorContainer
                  sx={{
                    mt: 2,
                    animation: 'none'
                  }}
                >
                  <Box display="flex" alignItems="center">
                    <ErrorIcon color="error" fontSize="small" sx={{ mr: 1 }} />
                    <Typography color="error" variant="body2">
                      {state.errors.schemaName}
                    </Typography>
                  </Box>
                </ErrorContainer>
              </Box>
            </Collapse>

            {/* O botão de navegação foi removido para evitar duplicação com os botões do modal principal */}
          </Grid>
        )}

        {state.schemaName && renderSchemaInfo()}
      </Grid>
    </StepLayout>
  );
};

export default React.memo(SchemaStep);
