import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Box,
  Typography,
  CircularProgress,
  alpha
} from '@mui/material';
import { Key as KeyIcon } from '@mui/icons-material';
import { syncService } from '../../services/syncService';
import { authService } from '../../services/auth';

interface RequiredCredentialsModalProps {
  open: boolean;
  onClose: () => void;
  onCredentialsSet: () => void;
}

const RequiredCredentialsModal: React.FC<RequiredCredentialsModalProps> = ({ 
  open, 
  onClose,
  onCredentialsSet
}) => {
  const { t } = useTranslation();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Validação da senha
  const [passwordValid, setPasswordValid] = useState(true);
  const [passwordErrors, setPasswordErrors] = useState<string[]>([]);

  // Carregar dados do usuário atual quando o componente montar
  useEffect(() => {
    const loadUserData = async () => {
      try {
        // Usar uma cópia local para evitar dependência do state
        let tempUsername = '';
        
        const user = await authService.getCurrentUser(true);
        if (user && user.username) {
          tempUsername = user.username;
          setUsername(tempUsername);
        }
      } catch (error) {
        console.error('Erro ao carregar dados do usuário:', error);
      }
    };

    if (open) {
      loadUserData();
    }
  }, [open]);

  const validatePassword = useCallback((password: string) => {
    const errors = [];
    
    if (password.length < 8) {
      errors.push(t('common:validation.password.tooShort') as string);
    }
    
    if (!/[A-Z]/.test(password)) {
      errors.push(t('common:validation.password.noUppercase') as string);
    }
    
    if (!/[a-z]/.test(password)) {
      errors.push(t('common:validation.password.noLowercase') as string);
    }
    
    if (!/[0-9]/.test(password)) {
      errors.push(t('common:validation.password.noNumber') as string);
    }
    
    if (!/[^A-Za-z0-9]/.test(password)) {
      errors.push(t('common:validation.password.noSpecial') as string);
    }
    
    setPasswordErrors(errors);
    setPasswordValid(errors.length === 0);
    
    return errors.length === 0;
  }, [t]);

  // Atualizar validação quando a senha mudar
  useEffect(() => {
    if (password) {
      validatePassword(password);
    } else {
      setPasswordValid(true);
      setPasswordErrors([]);
    }
  }, [password, validatePassword]);

  const handleSaveCredentials = async () => {
    if (!username || !password) {
      setError(t('profile.credentialsForm.error.fieldsRequired') as string);
      return;
    }
    
    // Validar senha
    if (!validatePassword(password)) {
      setError(t('profile.credentialsForm.error.invalidPassword') as string);
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      // Obter ID do usuário atual uma única vez
      let userId = '';
      
      try {
        const user = await authService.getCurrentUser();
        userId = user?.id || '';
        
        if (!userId) {
          throw new Error(t('profile.error.userNotFound') || 'User not found');
        }
      } catch (userError) {
        console.error(t('profile.error.loadingUser'), userError);
        throw new Error(t('profile.error.identifyCurrentUser') || 'Failed to identify current user');
      }

      console.log(t('profile.log.tryingUpdateCredentials'), username);
      
      try {
        // Tentar atualizar credenciais universais pelo endpoint dedicado primeiro
        await syncService.updateUniversalCredentials(userId, {
          username,
          password
        });
        console.log(t('profile.log.credentialsUpdatedMainEndpoint'));
      } catch (apiError) {
        console.error(t('profile.log.errorMainCredentialsEndpoint'), apiError);
        console.log(t('profile.log.tryingAlternativeMethod'));
        
        // Se o endpoint dedicado falhar, tentar usar o endpoint de atualização de credenciais normal
        // ou outro método compatível com a API atual
        try {
          await syncService.updateDatabaseCredentials(userId, {
            username,
            password,
            universal: true
          });
          console.log(t('profile.log.credentialsSavedAlternativeMethod'));
        } catch (secondError) {
          console.error(t('profile.log.errorAlternativeMethod'), secondError);
          // Se ambos falharem, propagar o erro
          throw apiError;
        }
      }
      
      setIsLoading(false);
      onCredentialsSet(); // Notificar que as credenciais foram definidas com sucesso
    } catch (error) {
      console.error(t('profile.error.updatingUniversalCredentials'), error);
      
      // Mostrar uma mensagem de erro mais descritiva se possível
      let errorMessage = t('profile.credentialsError');
      if (error instanceof Error && error.message) {
        errorMessage = `${errorMessage}: ${error.message}`;
      }
      
      setError(errorMessage);
      setIsLoading(false);
    }
  };

  return (
    <Dialog 
      open={open} 
      maxWidth="sm" 
      fullWidth
      disableEscapeKeyDown
      // Impedir que o usuário clique fora do modal para fechá-lo
      onClose={(event, reason) => {
        if (reason !== 'backdropClick') {
          onClose();
        }
      }}
    >
      <DialogTitle sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <KeyIcon color="primary" />
        {t('profile.requiredCredentials.title')}
      </DialogTitle>
      <DialogContent>
        <Box sx={{ mt: 2 }}>
          <Typography variant="body1" sx={{ mb: 2, fontWeight: 'medium', color: 'warning.main' }}>
            {t('profile.requiredCredentials.warning')}
          </Typography>
          
          <Typography variant="body2" color="text.secondary" paragraph>
            {t('profile.requiredCredentials.description')}
          </Typography>
          
          <TextField
            label={t('profile.credentialsForm.username')}
            fullWidth
            value={username}
            disabled={true} // Desabilitar a edição do username
            margin="normal"
            sx={{ mb: 2 }}
            helperText={t('profile.credentialsForm.usernameHelp') as string}
          />

          <TextField
            label={t('profile.credentialsForm.password')}
            type="password"
            fullWidth
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            margin="normal"
            error={!passwordValid && password.length > 0}
            helperText={
              password.length > 0 && !passwordValid ? (
                <Box component="span">
                  {t('common:validation.password.requirements') as string}
                  <ul style={{ margin: '4px 0', paddingLeft: '20px' }}>
                    {passwordErrors.map((error, index) => (
                      <li key={index}>{error}</li>
                    ))}
                  </ul>
                </Box>
              ) : (
                t('profile.credentialsForm.passwordHelp') as string
              )
            }
          />

          {error && (
            <Typography color="error" variant="body2" sx={{ mt: 2 }}>
              {error}
            </Typography>
          )}
        </Box>
      </DialogContent>
      <DialogActions>
        <Button 
          onClick={handleSaveCredentials} 
          variant="contained" 
          color="primary"
          disabled={!username || !password || !passwordValid || isLoading}
          startIcon={isLoading ? <CircularProgress size={20} /> : null}
          sx={{ 
            fontWeight: 'bold',
            color: 'white',
            '&:hover': {
              backgroundColor: (theme) => theme.palette.primary.dark,
            },
            '&.Mui-disabled': {
              backgroundColor: (theme) => alpha(theme.palette.primary.main, 0.5),
              color: 'rgba(255, 255, 255, 0.8)',
            }
          }}
        >
          {isLoading ? t('common:loading') : t('profile.credentialsForm.saveButton')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default RequiredCredentialsModal;