import React from 'react';
import { MenuItem, MenuItemProps, styled } from '@mui/material';

/**
 * StyledMenuItem - A properly styled MenuItem for better layout in dropdowns
 * Fixes the layout issues with nested content in MenuItems
 */
const StyledMenuItem = styled(MenuItem)<MenuItemProps>(({ theme }) => ({
  '&.MuiMenuItem-root': {
    padding: theme.spacing(1, 2),
    minHeight: 'auto',
    display: 'flex',
    alignItems: 'center',
    
    // Fix for nested Box and flex layouts
    '& > .MuiBox-root': {
      display: 'flex',
      alignItems: 'center',
      width: '100%',
      gap: theme.spacing(1),
    },
    
    // Ensure Typography components align properly
    '& .MuiTypography-root': {
      margin: 0,
      lineHeight: 1.5,
    },
    
    // Fix icon alignment
    '& .MuiSvgIcon-root': {
      flexShrink: 0,
    },
    
    // Ensure proper spacing for nested content
    '& .MuiBox-root .MuiBox-root': {
      display: 'flex',
      alignItems: 'center',
      gap: theme.spacing(0.5),
    },
    
    // Hover state
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
    
    // Selected state
    '&.Mui-selected': {
      backgroundColor: theme.palette.action.selected,
      '&:hover': {
        backgroundColor: theme.palette.action.selected,
      },
    },
  },
}));

export default StyledMenuItem;