import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Box,
  Typography,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Alert,
  Snackbar,
  CircularProgress,
  Tabs,
  Tab,
  Divider,
  Card,
  CardContent,
  Grid,
  LinearProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
  IconButton,
  Tooltip,
  ToggleButton,
  ToggleButtonGroup,
  Avatar,
  Stack,
  alpha,
  useTheme
} from '@mui/material';
import { 
  Refresh as RefreshIcon, 
  Storage as DatabaseIcon, 
  Person as UserIcon,
  Person as PersonIcon,
  Shield as ShieldIcon, 
  DeleteForever as DeleteIcon,
  Block as RevokeIcon,
  RemoveRedEye as ViewIcon,
  List as ListIcon,
  ViewModule as ViewModuleIcon,
  ViewList as ViewListIcon,
  CheckCircle as CheckCircleIcon,
  Warning as WarningIcon,
  Cancel as CancelIcon,
  Assignment as AssignmentIcon,
  AccessTime as AccessTimeIcon
} from '@mui/icons-material';
import { green, orange, red, blue, grey } from '@mui/material/colors';
import { requestService } from '../../services/api';
import { authService } from '../../services/auth';
import RequestActionForm from '../../components/RequestActionForm';

// Interface para consolidação por servidor
interface ServerSummary {
  serverId: string;
  serverName: string;
  serverHost: string;
  serverType?: string;
  databases: string[];
  totalRequests: number;
  pending: number;
  approved: number;
  rejected: number;
}

// Interface para consolidação por usuário
interface UserSummary {
  user: string;
  totalRequests: number;
  pending: number;
  approved: number;
  rejected: number;
}

// Interface para a solicitação completa
interface Request {
  id: string;
  user: string;
  requestedBy?: string | null;
  database: string;
  server_id?: string;
  server_name?: string;
  server_host?: string;
  server_type?: string;
  tables: string;
  operations: string;
  status: string;
  requestDate: string;
  justification?: string;
  is_service_user?: boolean;
}

const ConsolidatedRequestsPage: React.FC = () => {
  const { t } = useTranslation(['requests', 'common']);
  const theme = useTheme();
  const [requests, setRequests] = useState<Request[]>([]);
  const [serverSummaries, setServerSummaries] = useState<ServerSummary[]>([]);
  const [userSummaries, setUserSummaries] = useState<UserSummary[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'server' | 'user'>('server');
  const [displayMode, setDisplayMode] = useState<'cards' | 'list'>('cards');
  
  // States for dialogs and actions
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [confirmAction, setConfirmAction] = useState<'revoke' | 'delete' | null>(null);
  const [selectedRequest, setSelectedRequest] = useState<Request | null>(null);
  const [actionType, setActionType] = useState<'approve' | 'reject' | 'view' | 'cancel' | 'revoke' | 'delete' | null>(null);
  const [userRole, setUserRole] = useState<string>('');
  const [detailsDialogOpen, setDetailsDialogOpen] = useState(false);
  const [detailsTitle, setDetailsTitle] = useState('');
  const [filteredRequests, setFilteredRequests] = useState<Request[]>([]);

  useEffect(() => {
    fetchUserRole();
    fetchRequests();
  }, []);
  
  // Busca o papel do usuário atual
  const fetchUserRole = async () => {
    try {
      const role = await authService.getUserRole();
      if (role) {
        setUserRole(role.toLowerCase());
      }
    } catch (error) {
      console.error('Error fetching user role:', error);
    }
  };

  const fetchRequests = async () => {
    setLoading(true);
    setError(null);
    try {
      // Chamar a API para obter todas as requisições
      const response = await requestService.getRequests();
      
      if (response && response.success) {
        // Verificar se as solicitações existem e são um array
        const requestsArray = Array.isArray(response.requests) ? response.requests : [];
        
        if (requestsArray.length === 0) {
          setRequests([]);
          setServerSummaries([]);
          setUserSummaries([]);
        } else {
          // Mapear a resposta da API para o formato esperado
          const formattedRequests = requestsArray.map((req: any) => {
            const tablesString = Array.isArray(req.tables) 
              ? req.tables.join(', ') 
              : typeof req.tables === 'string' ? req.tables : '';
              
            const operationsString = Array.isArray(req.operations) 
              ? req.operations.map((op: string) => op.toLowerCase()).join(',')
              : typeof req.operations === 'string' ? req.operations : '';
            
            // Para service users, mostrar o nome do service user
            // Para usuários normais, mostrar o username
            const displayName = req.is_service_user 
              ? (req.service_user_name || 'N/A')
              : (req.username || req.user_id || 'N/A');
            
            // Para service users, o requestedBy é o usuário que fez a solicitação (admin)
            // Como temos apenas um username no retorno, e para service users ele mostra o solicitante,
            // vamos sempre mostrar "admin" quando é service user
            const requestedBy = req.is_service_user 
              ? (req.username || req.user_id || 'N/A')
              : null;
              
            return {
              id: req.id || 'N/A',
              user: displayName,
              requestedBy: requestedBy,
              database: req.database_name || req.database || 'N/A',
              server_id: req.server_id || req.server?.id || '',
              server_name: req.server_name || req.server?.name || '',
              server_host: req.server_host || req.server?.host || '',
              server_type: req.server_type || req.server?.type || '',
              tables: tablesString,
              operations: operationsString,
              status: req.status || 'pending',
              requestDate: new Date(req.created_at).toLocaleString() || 'N/A',
              justification: req.reason || '',
              is_service_user: req.is_service_user || false
            };
          });
          
          setRequests(formattedRequests);
          
          // Consolidar por servidor
          const serverSummary: { [key: string]: ServerSummary } = {};
          
          formattedRequests.forEach((req: Request) => {
            const serverId = req.server_id || req.server_name || 'unknown';
            
            if (!serverSummary[serverId]) {
              serverSummary[serverId] = {
                serverId: serverId,
                serverName: req.server_name || 'Unknown Server',
                serverHost: req.server_host || '',
                serverType: req.server_type || '',
                databases: [],
                totalRequests: 0,
                pending: 0,
                approved: 0,
                rejected: 0
              };
            }
            
            // Adicionar database à lista se ainda não estiver
            if (req.database && !serverSummary[serverId].databases.includes(req.database)) {
              serverSummary[serverId].databases.push(req.database);
            }
            
            // Contar apenas permissões aprovadas no total
            if (req.status === 'approved') {
              serverSummary[serverId].totalRequests++;
              serverSummary[serverId].approved++;
            } else if (req.status === 'pending') {
              serverSummary[serverId].pending++;
            } else if (req.status === 'rejected') {
              serverSummary[serverId].rejected++;
            }
          });
          
          setServerSummaries(Object.values(serverSummary).sort((a, b) => b.totalRequests - a.totalRequests));
          
          // Consolidar por usuário
          const userSummary: { [key: string]: UserSummary } = {};
          
          formattedRequests.forEach((req: Request) => {
            if (!userSummary[req.user]) {
              userSummary[req.user] = {
                user: req.user,
                totalRequests: 0,
                pending: 0,
                approved: 0,
                rejected: 0
              };
            }
            
            // Contar apenas permissões aprovadas no total
            if (req.status === 'approved') {
              userSummary[req.user].totalRequests++;
              userSummary[req.user].approved++;
            } else if (req.status === 'pending') {
              userSummary[req.user].pending++;
            } else if (req.status === 'rejected') {
              userSummary[req.user].rejected++;
            }
          });
          
          setUserSummaries(Object.values(userSummary).sort((a, b) => b.totalRequests - a.totalRequests));
        }
      } else {
        setRequests([]);
        setServerSummaries([]);
        setUserSummaries([]);
      }
    } catch (error) {
      console.error('Error fetching requests:', error);
      setError(t('fetchError'));
      setRequests([]);
      setServerSummaries([]);
      setUserSummaries([]);
    } finally {
      setLoading(false);
    }
  };

  const handleChangeViewMode = (event: React.SyntheticEvent, newValue: 'server' | 'user') => {
    setViewMode(newValue);
  };

  const handleCloseSnackbar = () => {
    setSuccessMessage(null);
  };

  // Calcular porcentagem para o componente LinearProgress
  const calculatePercentage = (value: number, total: number) => {
    return total > 0 ? (value / total) * 100 : 0;
  };
  
  // Função para obter cor do status
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'approved':
        return green[500];
      case 'pending':
        return orange[500];
      case 'rejected':
        return red[500];
      case 'revoked':
        return grey[500];
      default:
        return blue[500];
    }
  };

  // Função para obter ícone do status
  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'approved':
        return <CheckCircleIcon sx={{ fontSize: 20 }} />;
      case 'pending':
        return <AccessTimeIcon sx={{ fontSize: 20 }} />;
      case 'rejected':
        return <CancelIcon sx={{ fontSize: 20 }} />;
      default:
        return <AssignmentIcon sx={{ fontSize: 20 }} />;
    }
  };
  
  // Handler para abrir o formulário de visualização de detalhes
  const handleViewDetails = (request: Request) => {
    console.log("Abrindo visualização de detalhes para a solicitação:", request.id);
    setSelectedRequest(request);
    setActionType('view'); // Define a ação como visualização
  };
  
  // Este handler foi mantido apenas para compatibilidade com código existente
  // e agora faz o mesmo que handleCloseActionForm
  const handleCloseDetailDialog = () => {
    setSelectedRequest(null);
    setActionType(null);
  };
  
  // Handler para fechar o formulário de ação
  const handleCloseActionForm = () => {
    setSelectedRequest(null);
    setActionType(null);
  };
  
  // Handler para quando a ação for completada
  const handleActionCompleted = (newStatus?: string, success?: boolean) => {
    if (success) {
      // Se a ação foi bem-sucedida, mostrar mensagem de sucesso apenas para ações que não sejam visualização
      if (actionType !== 'view' && newStatus) {
        setSuccessMessage(t(`${actionType}Success`));
      }
    }
    
    handleCloseActionForm();
    fetchRequests(); // Atualizar a lista após a ação
  };
  
  // Handler para abrir o diálogo de confirmação
  const handleActionClick = (request: Request, action: 'revoke' | 'delete') => {
    setSelectedRequest(request);
    setConfirmAction(action);
    setConfirmDialogOpen(true);
  };
  
  // Handler para fechar o diálogo de confirmação
  const handleCloseConfirmDialog = () => {
    setConfirmDialogOpen(false);
    setSelectedRequest(null);
    setConfirmAction(null);
  };
  
  // Handler para executar a ação confirmada
  const handleConfirmExecute = async () => {
    if (!selectedRequest || !confirmAction) return;
    
    try {
      if (confirmAction === 'revoke') {
        await requestService.revokeRequest(selectedRequest.id, {
          reason: t('revokeReasonDefault')
        });
        setSuccessMessage(t('revokeSuccess'));
      } else if (confirmAction === 'delete') {
        await requestService.deleteRequest(selectedRequest.id);
        setSuccessMessage(t('deleteSuccess'));
      }
      
      // Atualizar a lista de solicitações
      fetchRequests();
    } catch (error) {
      console.error(`Error performing ${confirmAction} action:`, error);
      setError(t(`${confirmAction}Error`));
    } finally {
      handleCloseConfirmDialog();
    }
  };

  // Handler para abrir diálogo de detalhes do servidor
  const handleServerDetails = (serverSummary: ServerSummary) => {
    const serverRequests = requests.filter(
      req => req.server_id === serverSummary.serverId || req.server_name === serverSummary.serverName
    );
    setFilteredRequests(serverRequests);
    setDetailsTitle(`${t('detailsFor')} ${serverSummary.serverName}`);
    setDetailsDialogOpen(true);
  };

  // Handler para abrir diálogo de detalhes do usuário
  const handleUserDetails = (userSummary: UserSummary) => {
    const userRequests = requests.filter(
      req => req.user === userSummary.user
    );
    setFilteredRequests(userRequests);
    setDetailsTitle(`${t('detailsFor')} ${userSummary.user}`);
    setDetailsDialogOpen(true);
  };

  // Handler para fechar diálogo de detalhes
  const handleCloseDetailsDialog = () => {
    setDetailsDialogOpen(false);
    setFilteredRequests([]);
    setDetailsTitle('');
  };

  return (
    <Box>
      <Snackbar
        open={!!successMessage}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>

      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3} flexWrap="wrap" gap={2}>
        <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <ViewModuleIcon color="primary" />
          {t('consolidated')}
        </Typography>
        <Box display="flex" gap={2} alignItems="center">
          <ToggleButtonGroup
            value={displayMode}
            exclusive
            onChange={(e, newMode) => newMode && setDisplayMode(newMode)}
            aria-label="display mode"
            size="small"
          >
            <ToggleButton value="cards" aria-label="card view">
              <Tooltip title={t('viewMode.cards')}>
                <ViewModuleIcon />
              </Tooltip>
            </ToggleButton>
            <ToggleButton value="list" aria-label="list view">
              <Tooltip title={t('viewMode.list')}>
                <ViewListIcon />
              </Tooltip>
            </ToggleButton>
          </ToggleButtonGroup>
          <Button
            variant="outlined"
            startIcon={<RefreshIcon />}
            onClick={fetchRequests}
            disabled={loading}
          >
            {t('common:refresh')}
          </Button>
        </Box>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}

      {loading ? (
        <Box display="flex" justifyContent="center" alignItems="center" p={4}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <Paper sx={{ mb: 3 }}>
            <Tabs
              value={viewMode}
              onChange={handleChangeViewMode}
              indicatorColor="primary"
              textColor="primary"
              variant="fullWidth"
              aria-label="view mode tabs"
            >
              <Tab 
                icon={<DatabaseIcon />} 
                iconPosition="start" 
                label={t('byServer')} 
                value="server" 
              />
              <Tab 
                icon={<UserIcon />} 
                iconPosition="start" 
                label={t('byUser')} 
                value="user" 
              />
            </Tabs>
          </Paper>

          {viewMode === 'server' ? (
            displayMode === 'cards' ? (
              <Grid container spacing={3}>
                {serverSummaries.length === 0 ? (
                  <Grid item xs={12}>
                    <Paper sx={{ p: 4, textAlign: 'center', borderRadius: 2 }}>
                      <Typography variant="body1" color="text.secondary">
                        {t('common:noData')}
                      </Typography>
                    </Paper>
                  </Grid>
                ) : (
                  serverSummaries.map((summary) => {
                    const totalActive = summary.approved;
                    const hasIssues = summary.pending > 0 || summary.rejected > 0;
                    
                    return (
                      <Grid item xs={12} sm={6} lg={4} xl={3} key={summary.serverId}>
                        <Card
                          elevation={0}
                          sx={{
                            height: '100%',
                            background: theme.palette.mode === 'dark' 
                              ? 'linear-gradient(145deg, #1e1e1e 0%, #2d2d2d 100%)'
                              : 'linear-gradient(145deg, #ffffff 0%, #f8f9fa 100%)',
                            border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
                            borderRadius: 3,
                            position: 'relative',
                            overflow: 'hidden',
                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                            '&:hover': {
                              transform: 'translateY(-4px)',
                              boxShadow: `0 12px 24px ${alpha(theme.palette.primary.main, 0.15)}`,
                              '& .server-icon': {
                                transform: 'rotate(360deg)',
                              }
                            }
                          }}
                        >
                          {/* Decorative background element */}
                          <Box
                            sx={{
                              position: 'absolute',
                              top: -50,
                              right: -50,
                              width: 150,
                              height: 150,
                              borderRadius: '50%',
                              background: alpha(theme.palette.primary.main, 0.05),
                            }}
                          />
                          
                          <CardContent sx={{ p: 3, position: 'relative', zIndex: 1 }}>
                            {/* Header */}
                            <Box sx={{ display: 'flex', alignItems: 'flex-start', mb: 3 }}>
                              <Avatar
                                className="server-icon"
                                sx={{
                                  bgcolor: alpha(theme.palette.primary.main, 0.1),
                                  color: theme.palette.primary.main,
                                  width: 56,
                                  height: 56,
                                  mr: 2,
                                  transition: 'all 0.6s',
                                }}
                              >
                                <DatabaseIcon sx={{ fontSize: 28 }} />
                              </Avatar>
                              <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Typography
                                  variant="h6"
                                  sx={{
                                    fontWeight: 600,
                                    overflow: 'hidden',
                                    textOverflow: 'ellipsis',
                                    whiteSpace: 'nowrap',
                                    mb: 0.5
                                  }}
                                  title={summary.serverName}
                                >
                                  {summary.serverName}
                                </Typography>
                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                  {summary.serverHost}
                                </Typography>
                                {summary.serverType && (
                                  <Chip
                                    label={summary.serverType.toUpperCase()}
                                    size="small"
                                    sx={{
                                      mt: 0.5,
                                      height: 20,
                                      fontSize: '0.7rem',
                                      bgcolor: alpha(blue[500], 0.1),
                                      color: blue[700],
                                      border: `1px solid ${alpha(blue[500], 0.3)}`
                                    }}
                                  />
                                )}
                              </Box>
                            </Box>

                            {/* Active Permissions Counter */}
                            <Paper
                              elevation={0}
                              sx={{
                                p: 2,
                                mb: 3,
                                borderRadius: 2,
                                bgcolor: alpha(theme.palette.primary.main, 0.05),
                                border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
                              }}
                            >
                              <Typography variant="body2" color="text.secondary" gutterBottom>
                                {t('activePermissions')}
                              </Typography>
                              <Typography variant="h4" color="primary" fontWeight={600}>
                                {totalActive}
                              </Typography>
                              {summary.databases.length > 0 && (
                                <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                                  {summary.databases.length} database{summary.databases.length > 1 ? 's' : ''}
                                </Typography>
                              )}
                            </Paper>

                            {/* Status Metrics */}
                            <Stack spacing={2}>
                              {/* Pending */}
                              {summary.pending > 0 && (
                                <Box>
                                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                      {getStatusIcon('pending')}
                                      <Typography variant="body2" color="text.secondary">
                                        {t('status.pending')}
                                      </Typography>
                                    </Box>
                                    <Chip
                                      label={summary.pending}
                                      size="small"
                                      sx={{
                                        height: 20,
                                        bgcolor: alpha(orange[500], 0.1),
                                        color: orange[700],
                                        fontWeight: 600
                                      }}
                                    />
                                  </Box>
                                  <LinearProgress
                                    variant="determinate"
                                    value={100}
                                    sx={{
                                      height: 6,
                                      borderRadius: 3,
                                      bgcolor: alpha(orange[500], 0.1),
                                      '& .MuiLinearProgress-bar': {
                                        borderRadius: 3,
                                        bgcolor: orange[500]
                                      }
                                    }}
                                  />
                                </Box>
                              )}

                              {/* Approved */}
                              <Box>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    {getStatusIcon('approved')}
                                    <Typography variant="body2" color="text.secondary">
                                      {t('status.approved')}
                                    </Typography>
                                  </Box>
                                  <Chip
                                    label={summary.approved}
                                    size="small"
                                    sx={{
                                      height: 20,
                                      bgcolor: alpha(green[500], 0.1),
                                      color: green[700],
                                      fontWeight: 600
                                    }}
                                  />
                                </Box>
                                <LinearProgress
                                  variant="determinate"
                                  value={totalActive > 0 ? (summary.approved / totalActive) * 100 : 0}
                                  sx={{
                                    height: 6,
                                    borderRadius: 3,
                                    bgcolor: alpha(green[500], 0.1),
                                    '& .MuiLinearProgress-bar': {
                                      borderRadius: 3,
                                      bgcolor: green[500]
                                    }
                                  }}
                                />
                              </Box>

                              {/* Rejected */}
                              {summary.rejected > 0 && (
                                <Box>
                                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                      {getStatusIcon('rejected')}
                                      <Typography variant="body2" color="text.secondary">
                                        {t('status.rejected')}
                                      </Typography>
                                    </Box>
                                    <Chip
                                      label={summary.rejected}
                                      size="small"
                                      sx={{
                                        height: 20,
                                        bgcolor: alpha(red[500], 0.1),
                                        color: red[700],
                                        fontWeight: 600
                                      }}
                                    />
                                  </Box>
                                  <LinearProgress
                                    variant="determinate"
                                    value={100}
                                    sx={{
                                      height: 6,
                                      borderRadius: 3,
                                      bgcolor: alpha(red[500], 0.1),
                                      '& .MuiLinearProgress-bar': {
                                        borderRadius: 3,
                                        bgcolor: red[500]
                                      }
                                    }}
                                  />
                                </Box>
                              )}
                            </Stack>

                            {/* View Details Button */}
                            <Button
                              fullWidth
                              variant="outlined"
                              size="small"
                              sx={{
                                mt: 3,
                                borderRadius: 2,
                                textTransform: 'none',
                                borderColor: alpha(theme.palette.primary.main, 0.3),
                                '&:hover': {
                                  borderColor: theme.palette.primary.main,
                                  bgcolor: alpha(theme.palette.primary.main, 0.05)
                                }
                              }}
                              onClick={() => handleServerDetails(summary)}
                            >
                              {t('viewDetails')}
                            </Button>
                          </CardContent>
                        </Card>
                      </Grid>
                    );
                  })
                )}
              </Grid>
            ) : (
              // Visualização em Lista para Servidores
              <TableContainer component={Paper} sx={{ borderRadius: 2 }}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>{t('server')}</TableCell>
                      <TableCell>{t('host')}</TableCell>
                      <TableCell>{t('type')}</TableCell>
                      <TableCell>{t('databases')}</TableCell>
                      <TableCell align="center">{t('activePermissions')}</TableCell>
                      <TableCell align="center">{t('status.pending')}</TableCell>
                      <TableCell align="center">{t('status.approved')}</TableCell>
                      <TableCell align="center">{t('status.rejected')}</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {serverSummaries.map((summary) => (
                      <TableRow key={summary.serverId} hover>
                        <TableCell>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Avatar
                              sx={{
                                bgcolor: alpha(theme.palette.primary.main, 0.1),
                                color: theme.palette.primary.main,
                                width: 36,
                                height: 36
                              }}
                            >
                              <DatabaseIcon fontSize="small" />
                            </Avatar>
                            <Typography variant="body1" fontWeight={500}>
                              {summary.serverName}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell>{summary.serverHost || '-'}</TableCell>
                        <TableCell>
                          {summary.serverType ? (
                            <Chip
                              label={summary.serverType.toUpperCase()}
                              size="small"
                              sx={{
                                bgcolor: alpha(blue[500], 0.1),
                                color: blue[700]
                              }}
                            />
                          ) : '-'}
                        </TableCell>
                        <TableCell>{summary.databases.length}</TableCell>
                        <TableCell align="center">
                          <Typography variant="body1" fontWeight={600} color="primary">
                            {summary.approved}
                          </Typography>
                        </TableCell>
                        <TableCell align="center">
                          {summary.pending > 0 ? (
                            <Chip
                              label={summary.pending}
                              size="small"
                              color="warning"
                              sx={{ minWidth: 32 }}
                            />
                          ) : '-'}
                        </TableCell>
                        <TableCell align="center">
                          {summary.approved > 0 ? (
                            <Chip
                              label={summary.approved}
                              size="small"
                              color="success"
                              sx={{ minWidth: 32 }}
                            />
                          ) : '-'}
                        </TableCell>
                        <TableCell align="center">
                          {summary.rejected > 0 ? (
                            <Chip
                              label={summary.rejected}
                              size="small"
                              color="error"
                              sx={{ minWidth: 32 }}
                            />
                          ) : '-'}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )
          ) : (
            displayMode === 'cards' ? (
              <Grid container spacing={3}>
                {userSummaries.length === 0 ? (
                  <Grid item xs={12}>
                    <Paper sx={{ p: 4, textAlign: 'center', borderRadius: 2 }}>
                      <Typography variant="body1" color="text.secondary">
                        {t('common:noData')}
                      </Typography>
                    </Paper>
                  </Grid>
                ) : (
                  userSummaries.map((summary) => {
                    const totalActive = summary.approved;
                    
                    return (
                      <Grid item xs={12} sm={6} lg={4} xl={3} key={summary.user}>
                        <Card
                          elevation={0}
                          sx={{
                            height: '100%',
                            background: theme.palette.mode === 'dark' 
                              ? 'linear-gradient(145deg, #1e1e1e 0%, #2d2d2d 100%)'
                              : 'linear-gradient(145deg, #ffffff 0%, #f8f9fa 100%)',
                            border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
                            borderRadius: 3,
                            position: 'relative',
                            overflow: 'hidden',
                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                            '&:hover': {
                              transform: 'translateY(-4px)',
                              boxShadow: `0 12px 24px ${alpha(theme.palette.primary.main, 0.15)}`,
                              '& .user-icon': {
                                transform: 'scale(1.1)',
                              }
                            }
                          }}
                        >
                          {/* Decorative background element */}
                          <Box
                            sx={{
                              position: 'absolute',
                              top: -50,
                              right: -50,
                              width: 150,
                              height: 150,
                              borderRadius: '50%',
                              background: alpha(theme.palette.secondary.main, 0.05),
                            }}
                          />
                          
                          <CardContent sx={{ p: 3, position: 'relative', zIndex: 1 }}>
                            {/* Header */}
                            <Box sx={{ display: 'flex', alignItems: 'flex-start', mb: 3 }}>
                              <Avatar
                                className="user-icon"
                                sx={{
                                  bgcolor: alpha(theme.palette.secondary.main, 0.1),
                                  color: theme.palette.secondary.main,
                                  width: 56,
                                  height: 56,
                                  mr: 2,
                                  transition: 'all 0.3s',
                                }}
                              >
                                <UserIcon sx={{ fontSize: 28 }} />
                              </Avatar>
                              <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Typography
                                  variant="h6"
                                  sx={{
                                    fontWeight: 600,
                                    overflow: 'hidden',
                                    textOverflow: 'ellipsis',
                                    whiteSpace: 'nowrap',
                                    mb: 0.5
                                  }}
                                  title={summary.user}
                                >
                                  {summary.user}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                  {t('user')}
                                </Typography>
                              </Box>
                            </Box>

                            {/* Active Permissions Counter */}
                            <Paper
                              elevation={0}
                              sx={{
                                p: 2,
                                mb: 3,
                                borderRadius: 2,
                                bgcolor: alpha(theme.palette.secondary.main, 0.05),
                                border: `1px solid ${alpha(theme.palette.secondary.main, 0.1)}`,
                              }}
                            >
                              <Typography variant="body2" color="text.secondary" gutterBottom>
                                {t('activePermissions')}
                              </Typography>
                              <Typography variant="h4" color="secondary" fontWeight={600}>
                                {totalActive}
                              </Typography>
                            </Paper>

                            {/* Status Metrics */}
                            <Stack spacing={2}>
                              {/* Pending */}
                              {summary.pending > 0 && (
                                <Box>
                                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                      {getStatusIcon('pending')}
                                      <Typography variant="body2" color="text.secondary">
                                        {t('status.pending')}
                                      </Typography>
                                    </Box>
                                    <Chip
                                      label={summary.pending}
                                      size="small"
                                      sx={{
                                        height: 20,
                                        bgcolor: alpha(orange[500], 0.1),
                                        color: orange[700],
                                        fontWeight: 600
                                      }}
                                    />
                                  </Box>
                                  <LinearProgress
                                    variant="determinate"
                                    value={100}
                                    sx={{
                                      height: 6,
                                      borderRadius: 3,
                                      bgcolor: alpha(orange[500], 0.1),
                                      '& .MuiLinearProgress-bar': {
                                        borderRadius: 3,
                                        bgcolor: orange[500]
                                      }
                                    }}
                                  />
                                </Box>
                              )}

                              {/* Approved */}
                              <Box>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    {getStatusIcon('approved')}
                                    <Typography variant="body2" color="text.secondary">
                                      {t('status.approved')}
                                    </Typography>
                                  </Box>
                                  <Chip
                                    label={summary.approved}
                                    size="small"
                                    sx={{
                                      height: 20,
                                      bgcolor: alpha(green[500], 0.1),
                                      color: green[700],
                                      fontWeight: 600
                                    }}
                                  />
                                </Box>
                                <LinearProgress
                                  variant="determinate"
                                  value={totalActive > 0 ? (summary.approved / totalActive) * 100 : 0}
                                  sx={{
                                    height: 6,
                                    borderRadius: 3,
                                    bgcolor: alpha(green[500], 0.1),
                                    '& .MuiLinearProgress-bar': {
                                      borderRadius: 3,
                                      bgcolor: green[500]
                                    }
                                  }}
                                />
                              </Box>

                              {/* Rejected */}
                              {summary.rejected > 0 && (
                                <Box>
                                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                      {getStatusIcon('rejected')}
                                      <Typography variant="body2" color="text.secondary">
                                        {t('status.rejected')}
                                      </Typography>
                                    </Box>
                                    <Chip
                                      label={summary.rejected}
                                      size="small"
                                      sx={{
                                        height: 20,
                                        bgcolor: alpha(red[500], 0.1),
                                        color: red[700],
                                        fontWeight: 600
                                      }}
                                    />
                                  </Box>
                                  <LinearProgress
                                    variant="determinate"
                                    value={100}
                                    sx={{
                                      height: 6,
                                      borderRadius: 3,
                                      bgcolor: alpha(red[500], 0.1),
                                      '& .MuiLinearProgress-bar': {
                                        borderRadius: 3,
                                        bgcolor: red[500]
                                      }
                                    }}
                                  />
                                </Box>
                              )}
                            </Stack>

                            {/* View Details Button */}
                            <Button
                              fullWidth
                              variant="outlined"
                              size="small"
                              sx={{
                                mt: 3,
                                borderRadius: 2,
                                textTransform: 'none',
                                borderColor: alpha(theme.palette.secondary.main, 0.3),
                                '&:hover': {
                                  borderColor: theme.palette.secondary.main,
                                  bgcolor: alpha(theme.palette.secondary.main, 0.05)
                                }
                              }}
                              onClick={() => handleUserDetails(summary)}
                            >
                              {t('viewDetails')}
                            </Button>
                          </CardContent>
                        </Card>
                      </Grid>
                    );
                  })
                )}
              </Grid>
            ) : (
              // Visualização em Lista para Usuários
              <TableContainer component={Paper} sx={{ borderRadius: 2 }}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>{t('user')}</TableCell>
                      <TableCell align="center">{t('activePermissions')}</TableCell>
                      <TableCell align="center">{t('status.pending')}</TableCell>
                      <TableCell align="center">{t('status.approved')}</TableCell>
                      <TableCell align="center">{t('status.rejected')}</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {userSummaries.map((summary) => (
                      <TableRow key={summary.user} hover>
                        <TableCell>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Avatar
                              sx={{
                                bgcolor: alpha(theme.palette.secondary.main, 0.1),
                                color: theme.palette.secondary.main,
                                width: 36,
                                height: 36
                              }}
                            >
                              <UserIcon fontSize="small" />
                            </Avatar>
                            <Typography variant="body1" fontWeight={500}>
                              {summary.user}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell align="center">
                          <Typography variant="body1" fontWeight={600} color="secondary">
                            {summary.approved}
                          </Typography>
                        </TableCell>
                        <TableCell align="center">
                          {summary.pending > 0 ? (
                            <Chip
                              label={summary.pending}
                              size="small"
                              color="warning"
                              sx={{ minWidth: 32 }}
                            />
                          ) : '-'}
                        </TableCell>
                        <TableCell align="center">
                          {summary.approved > 0 ? (
                            <Chip
                              label={summary.approved}
                              size="small"
                              color="success"
                              sx={{ minWidth: 32 }}
                            />
                          ) : '-'}
                        </TableCell>
                        <TableCell align="center">
                          {summary.rejected > 0 ? (
                            <Chip
                              label={summary.rejected}
                              size="small"
                              color="error"
                              sx={{ minWidth: 32 }}
                            />
                          ) : '-'}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )
          )}
          
          {/* Exibir uma lista das solicitações */}
          {requests.length > 0 && (
            <Paper sx={{ mt: 4 }}>
              <Box p={2} display="flex" justifyContent="space-between" alignItems="center">
                <Typography variant="h6">
                  {t('allRequests')}
                </Typography>
                <Button
                  variant="outlined"
                  startIcon={<ListIcon />}
                  size="small"
                  onClick={() => {
                    // Usar history.push ou location.href para redirecionar para a página de solicitações
                    // com a aba de solicitações selecionada (não a aba de visão consolidada)
                    window.location.href = "/requests";
                  }}
                >
                  {t('common:viewAll')}
                </Button>
              </Box>
              
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>{t('table.requestId')}</TableCell>
                      <TableCell>{t('table.user')}</TableCell>
                      <TableCell>{t('table.userType')}</TableCell>
                      <TableCell>{t('table.database')}</TableCell>
                      <TableCell>{t('table.server')}</TableCell>
                      <TableCell>{t('table.status')}</TableCell>
                      <TableCell>{t('table.requestDate')}</TableCell>
                      <TableCell>{t('table.actions')}</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {requests.slice(0, 5).map((request) => (
                      <TableRow key={request.id}>
                        <TableCell>
                          {request.id.length > 8 
                            ? `REQ-${request.id.substring(0, 6)}` 
                            : request.id}
                        </TableCell>
                        <TableCell>
                          <Box>
                            <Typography variant="body2">{request.user}</Typography>
                            {request.requestedBy && (
                              <Typography variant="caption" color="text.secondary">
                                Solicitado por: {request.requestedBy}
                              </Typography>
                            )}
                          </Box>
                        </TableCell>
                        <TableCell>
                          <Box display="flex" alignItems="center" gap={1}>
                            {request.is_service_user ? (
                              <>
                                <Box
                                  sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    width: 32,
                                    height: 32,
                                    borderRadius: '50%',
                                    bgcolor: 'info.light',
                                    color: 'info.contrastText'
                                  }}
                                >
                                  <ShieldIcon fontSize="small" />
                                </Box>
                                <Typography variant="body2">
                                  {t('userType.service')}
                                </Typography>
                              </>
                            ) : (
                              <>
                                <Box
                                  sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    width: 32,
                                    height: 32,
                                    borderRadius: '50%',
                                    bgcolor: 'success.light',
                                    color: 'success.contrastText'
                                  }}
                                >
                                  <PersonIcon fontSize="small" />
                                </Box>
                                <Typography variant="body2">
                                  {t('userType.regular')}
                                </Typography>
                              </>
                            )}
                          </Box>
                        </TableCell>
                        <TableCell>{request.database}</TableCell>
                        <TableCell>
                          {request.server_name ? (
                            <Box>
                              <Typography variant="body2">{request.server_name}</Typography>
                              {request.server_host && (
                                <Typography variant="caption" color="text.secondary">
                                  {request.server_host}
                                </Typography>
                              )}
                            </Box>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>
                          <Chip
                            label={t(`status.${request.status}`)}
                            color={
                              request.status === 'pending' ? 'warning' :
                              request.status === 'approved' ? 'success' :
                              request.status === 'rejected' ? 'error' :
                              request.status === 'revoked' ? 'secondary' : 
                              'default'
                            }
                            size="small"
                          />
                        </TableCell>
                        <TableCell>{request.requestDate}</TableCell>
                        <TableCell>
                          <Tooltip title={t('common:view')}>
                            <IconButton 
                              size="small" 
                              onClick={() => handleViewDetails(request)}
                            >
                              <ViewIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                          
                          {request.status === 'approved' && (userRole === 'admin' || userRole === 'administrator' || userRole === 'approver') && (
                            <>
                              <Tooltip title={t('common:revoke')}>
                                <IconButton 
                                  size="small" 
                                  color="warning"
                                  onClick={() => handleActionClick(request, 'revoke')}
                                >
                                  <RevokeIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>
                              
                              <Tooltip title={t('common:delete')}>
                                <IconButton 
                                  size="small" 
                                  color="error"
                                  onClick={() => handleActionClick(request, 'delete')}
                                >
                                  <DeleteIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>
                            </>
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          )}
        </>
      )}
      
      {/* Diálogo de confirmação para revogar/excluir solicitação */}
      <Dialog
        open={confirmDialogOpen}
        onClose={handleCloseConfirmDialog}
        aria-labelledby="confirm-dialog-title"
        aria-describedby="confirm-dialog-description"
        disableEnforceFocus
        disableRestoreFocus
      >
        <DialogTitle id="confirm-dialog-title">
          {confirmAction === 'revoke' 
            ? t('revokeRequestTitle') 
            : t('deleteRequestTitle')}
        </DialogTitle>
        <DialogContent>
          <DialogContentText id="confirm-dialog-description">
            {confirmAction === 'revoke'
              ? t('revokeRequestConfirm')
              : t('deleteRequestConfirm')}
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseConfirmDialog}>
            {t('common:cancel')}
          </Button>
          <Button 
            onClick={handleConfirmExecute} 
            color={confirmAction === 'revoke' ? 'warning' : 'error'}
            variant="contained"
            autoFocus
          >
            {confirmAction === 'revoke' 
              ? t('common:revoke') 
              : t('common:delete')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Formulário de ação (visualizar/revogar/excluir) */}
      {selectedRequest && actionType && (
        <RequestActionForm
          open={true}
          onClose={handleCloseActionForm}
          onAction={handleActionCompleted}
          request={selectedRequest}
          action={actionType}
        />
      )}

      {/* Diálogo de detalhes */}
      <Dialog
        open={detailsDialogOpen}
        onClose={handleCloseDetailsDialog}
        maxWidth="lg"
        fullWidth
        aria-labelledby="details-dialog-title"
      >
        <DialogTitle id="details-dialog-title" sx={{
          bgcolor: theme.palette.primary.main,
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <ListIcon />
            {detailsTitle}
          </Box>
          <IconButton
            edge="end"
            color="inherit"
            onClick={handleCloseDetailsDialog}
            aria-label="close"
          >
            <CancelIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ p: 0 }}>
          {filteredRequests.length === 0 ? (
            <Box p={3} textAlign="center">
              <Typography variant="body1" color="text.secondary">
                {t('noRequestsFound')}
              </Typography>
            </Box>
          ) : (
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>{t('table.requestId')}</TableCell>
                    <TableCell>{t('table.user')}</TableCell>
                    <TableCell>{t('table.userType')}</TableCell>
                    <TableCell>{t('table.server')}</TableCell>
                    <TableCell>{t('table.database')}</TableCell>
                    <TableCell>{t('table.tables')}</TableCell>
                    <TableCell>{t('table.operations')}</TableCell>
                    <TableCell>{t('table.status')}</TableCell>
                    <TableCell>{t('table.requestDate')}</TableCell>
                    <TableCell>{t('table.actions')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredRequests.map((request) => (
                    <TableRow key={request.id} hover>
                      <TableCell>
                        {request.id.length > 8 
                          ? `REQ-${request.id.substring(0, 6)}` 
                          : request.id}
                      </TableCell>
                      <TableCell>
                        <Box>
                          <Typography variant="body2">{request.user}</Typography>
                          {request.requestedBy && (
                            <Typography variant="caption" color="text.secondary">
                              {t('requestedBy')}: {request.requestedBy}
                            </Typography>
                          )}
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Box display="flex" alignItems="center" gap={1}>
                          {request.is_service_user ? (
                            <Chip
                              icon={<ShieldIcon fontSize="small" />}
                              label={t('userType.service')}
                              size="small"
                              color="info"
                            />
                          ) : (
                            <Chip
                              icon={<PersonIcon fontSize="small" />}
                              label={t('userType.regular')}
                              size="small"
                              color="success"
                            />
                          )}
                        </Box>
                      </TableCell>
                      <TableCell>
                        {request.server_name ? (
                          <Box>
                            <Typography variant="body2" fontWeight={500}>
                              {request.server_name}
                            </Typography>
                            {request.server_type && (
                              <Chip
                                label={request.server_type.toUpperCase()}
                                size="small"
                                sx={{
                                  height: 16,
                                  fontSize: '0.7rem',
                                  bgcolor: alpha(blue[500], 0.1),
                                  color: blue[700]
                                }}
                              />
                            )}
                          </Box>
                        ) : '-'}
                      </TableCell>
                      <TableCell>{request.database}</TableCell>
                      <TableCell>
                        <Tooltip title={request.tables}>
                          <Typography variant="body2" noWrap sx={{ maxWidth: 150 }}>
                            {request.tables}
                          </Typography>
                        </Tooltip>
                      </TableCell>
                      <TableCell>
                        {request.operations.split(',').map((op, index) => (
                          <Chip
                            key={index}
                            label={op.trim().toUpperCase()}
                            size="small"
                            sx={{ mr: 0.5, mb: 0.5 }}
                          />
                        ))}
                      </TableCell>
                      <TableCell>
                        <Chip
                          icon={getStatusIcon(request.status)}
                          label={t(`status.${request.status}`)}
                          color={
                            request.status === 'pending' ? 'warning' :
                            request.status === 'approved' ? 'success' :
                            request.status === 'rejected' ? 'error' :
                            request.status === 'revoked' ? 'default' : 
                            'default'
                          }
                          size="small"
                        />
                      </TableCell>
                      <TableCell>{request.requestDate}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                          <Tooltip title={t('common:view')}>
                            <IconButton 
                              size="small" 
                              onClick={() => handleViewDetails(request)}
                            >
                              <ViewIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                          
                          {request.status === 'approved' && (userRole === 'admin' || userRole === 'administrator' || userRole === 'approver') && (
                            <>
                              <Tooltip title={t('common:revoke')}>
                                <IconButton 
                                  size="small" 
                                  color="warning"
                                  onClick={() => handleActionClick(request, 'revoke')}
                                >
                                  <RevokeIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>
                              
                              <Tooltip title={t('common:delete')}>
                                <IconButton 
                                  size="small" 
                                  color="error"
                                  onClick={() => handleActionClick(request, 'delete')}
                                >
                                  <DeleteIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>
                            </>
                          )}
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDetailsDialog}>
            {t('common:close')}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ConsolidatedRequestsPage;
