import React, { useState, useRef } from 'react';
import {
  Box,
  Paper,
  TextField,
  List,
  ListItem,
  ListItemButton,
  ClickAwayListener,
  InputAdornment,
} from '@mui/material';
import { ArrowDropDown, ArrowDropUp } from '@mui/icons-material';

interface DropdownOption {
  value: string;
  label: string;
  icon?: React.ReactNode;
}

interface BasicDropdownProps {
  value: string;
  onChange: (value: string) => void;
  options: DropdownOption[];
  label?: string;
  size?: 'small' | 'medium';
  fullWidth?: boolean;
}

const BasicDropdown: React.FC<BasicDropdownProps> = ({
  value,
  onChange,
  options,
  label,
  size = 'medium',
  fullWidth = false,
}) => {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const selectedOption = options.find(opt => opt.value === value);

  const handleToggle = () => {
    setOpen(prev => !prev);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleSelect = (optionValue: string) => {
    onChange(optionValue);
    setOpen(false);
  };

  return (
    <Box ref={containerRef} sx={{ position: 'relative', width: fullWidth ? '100%' : 200 }}>
      <TextField
        fullWidth
        size={size}
        label={label}
        value={selectedOption?.label || ''}
        onClick={handleToggle}
        InputProps={{
          readOnly: true,
          style: { cursor: 'pointer' },
          startAdornment: selectedOption?.icon ? (
            <InputAdornment position="start">
              {selectedOption.icon}
            </InputAdornment>
          ) : null,
          endAdornment: (
            <InputAdornment position="end">
              {open ? <ArrowDropUp /> : <ArrowDropDown />}
            </InputAdornment>
          ),
        }}
        sx={{
          '& .MuiInputBase-input': {
            color: 'text.primary',
            backgroundColor: 'transparent',
          },
          '& .MuiInputLabel-root': {
            color: 'text.secondary',
            backgroundColor: 'background.paper',
            px: 0.5,
            '&.Mui-focused': {
              color: 'primary.main',
            },
          },
          '& .MuiOutlinedInput-root': {
            backgroundColor: 'background.paper',
            '& fieldset': {
              borderColor: 'divider',
            },
            '&:hover fieldset': {
              borderColor: 'text.primary',
            },
            '&.Mui-focused fieldset': {
              borderColor: 'primary.main',
            },
          },
        }}
      />
      
      {open && (
        <ClickAwayListener onClickAway={handleClose}>
          <Paper
            sx={{
              position: 'absolute',
              top: '100%',
              left: 0,
              right: 0,
              mt: 0.5,
              maxHeight: 300,
              overflow: 'auto',
              zIndex: (theme) => theme.zIndex.modal + 100, // Garante que fica acima de tudo
              boxShadow: 4,
              backgroundColor: 'background.paper',
              border: '1px solid',
              borderColor: 'divider',
            }}
          >
            <List disablePadding>
              {options.map((option) => (
                <ListItem key={option.value} disablePadding>
                  <ListItemButton
                    selected={value === option.value}
                    onClick={() => handleSelect(option.value)}
                    sx={{ gap: 1 }}
                  >
                    {option.icon}
                    {option.label}
                  </ListItemButton>
                </ListItem>
              ))}
            </List>
          </Paper>
        </ClickAwayListener>
      )}
    </Box>
  );
};

export default BasicDropdown;