import React from 'react';
import BasicDropdown from './BasicDropdown';
import { Box, Typography } from '@mui/material';
import { Storage as StorageIcon, Circle as CircleIcon } from '@mui/icons-material';

interface Server {
  id: string;
  name: string;
  type: string;
}

interface ServerStatus {
  enabled: boolean;
  query_count: number;
}

interface ServerDropdownProps {
  value: string;
  onChange: (value: string) => void;
  servers: Server[];
  label?: string;
  fullWidth?: boolean;
  getServerStatus?: (serverId: string) => ServerStatus | null;
}

const ServerDropdown: React.FC<ServerDropdownProps> = ({
  value,
  onChange,
  servers,
  label,
  fullWidth = true,
  getServerStatus,
}) => {
  const options = servers.map((server) => {
    const status = getServerStatus ? getServerStatus(server.id) : null;
    
    return {
      value: server.id,
      label: `${server.name} (${server.type})`,
      icon: (
        <Box display="flex" alignItems="center" gap={1}>
          <StorageIcon sx={{ fontSize: 20 }} />
          {status && (
            <>
              <CircleIcon
                sx={{
                  fontSize: 10,
                  color: status.enabled ? 'success.main' : 'text.disabled',
                }}
              />
              <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                {status.query_count} queries
              </Typography>
            </>
          )}
        </Box>
      ),
    };
  });

  return (
    <BasicDropdown
      value={value}
      onChange={onChange}
      options={options}
      label={label}
      fullWidth={fullWidth}
    />
  );
};

export default ServerDropdown;