import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  Avatar,
  Typography,
  Divider,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Snackbar,
  Alert,
  Box,
  useTheme,
  alpha,
  Tooltip,
  IconButton
} from '@mui/material';
import {
  Notifications as NotificationsIcon,
  Save as SaveIcon,
  Refresh as RefreshIcon,
  Send as SendIcon,
  Check as CheckIcon,
  Info as InfoIcon,
  Email as EmailIcon,
  Chat as ChatIcon,
  Tag as TagIcon,
  VpnKey as ApiKeyIcon
} from '@mui/icons-material';

import { configurationService } from '../../services/api';

interface NotificationConfig {
  email: boolean;
  slack: boolean;
  slack_api_key: string;
  slack_channel: string;
}

const NotificationConfigPanel: React.FC = () => {
  const { t } = useTranslation(['settings', 'common']);
  const theme = useTheme();

  // Estado para configuração de notificações
  const [notificationConfig, setNotificationConfig] = useState<NotificationConfig>({
    email: true,
    slack: false,
    slack_api_key: '',
    slack_channel: ''
  });

  // Estado para controle do painel
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [testSlackOpen, setTestSlackOpen] = useState(false);
  const [testingSlack, setTestingSlack] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);

  // Carrega as configurações de notificações iniciais
  useEffect(() => {
    fetchNotificationConfig();
  }, []);

  // Obtém as configurações de notificações do servidor
  const fetchNotificationConfig = async () => {
    setLoading(true);
    try {
      const response = await configurationService.getConfiguration('notifications');
      console.log('Notification config response:', response);
      
      if (response && response.notifications) {
        setNotificationConfig(response.notifications);
        setHasChanges(false);
      }
    } catch (error) {
      console.error('Erro ao buscar configuração de notificações:', error);
      setErrorMessage('Erro ao carregar configurações de notificações');
    } finally {
      setLoading(false);
    }
  };

  // Salva a configuração de notificações
  const handleSaveNotificationConfig = async () => {
    setSaving(true);
    setErrorMessage(null);
    
    try {
      // Validar campos obrigatórios
      if (notificationConfig.slack) {
        if (!notificationConfig.slack_api_key) {
          setErrorMessage('A chave de API do Slack é obrigatória quando as notificações do Slack estão habilitadas');
          setSaving(false);
          return;
        }
        
        if (!notificationConfig.slack_channel) {
          setErrorMessage('O canal do Slack é obrigatório quando as notificações do Slack estão habilitadas');
          setSaving(false);
          return;
        }
      }
      
      // Envia a configuração para o servidor
      const response = await configurationService.updateConfiguration({ notifications: notificationConfig });
      
      console.log('Resposta ao salvar configuração de notificações:', response);
      setSuccessMessage('Configuração de notificações salva com sucesso');
      setHasChanges(false);
    } catch (error) {
      console.error('Erro ao salvar configuração de notificações:', error);
      setErrorMessage('Erro ao salvar configuração de notificações');
    } finally {
      setSaving(false);
    }
  };

  // Testa a integração com o Slack
  const handleTestSlack = async () => {
    setTestingSlack(true);
    try {
      const response = await configurationService.testSlackNotification({
        slack_channel: notificationConfig.slack_channel,
        slack_api_key: notificationConfig.slack_api_key
      });
      setSuccessMessage('Mensagem de teste enviada para o Slack com sucesso');
      setTestSlackOpen(false);
    } catch (error) {
      console.error('Erro ao testar integração com Slack:', error);
      setErrorMessage('Erro ao enviar mensagem de teste para o Slack');
    } finally {
      setTestingSlack(false);
    }
  };

  // Manipula mudanças nos campos de texto
  const handleTextChange = (field: keyof NotificationConfig, value: string) => {
    setNotificationConfig(prev => ({
      ...prev,
      [field]: value
    }));
    setHasChanges(true);
  };

  // Manipula mudanças nos toggles
  const handleToggleChange = (field: keyof NotificationConfig, checked: boolean) => {
    setNotificationConfig(prev => ({
      ...prev,
      [field]: checked
    }));
    setHasChanges(true);
  };

  return (
    <Card sx={{ 
      borderRadius: 2, 
      mb: 3, 
      boxShadow: 2,
      overflow: 'hidden',
      transition: 'box-shadow 0.3s ease-in-out',
      '&:hover': {
        boxShadow: 5
      }
    }}>
      <CardHeader
        avatar={
          <Avatar sx={{ 
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            width: 48,
            height: 48
          }}>
            <NotificationsIcon />
          </Avatar>
        }
        title={
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            {t('sections.notifications.title')}
          </Typography>
        }
        subheader={t('sections.notifications.description')}
        action={
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<RefreshIcon />}
              onClick={fetchNotificationConfig}
              disabled={loading}
              sx={{ borderRadius: 8 }}
            >
              {t('common:refresh')}
            </Button>
            <Button
              variant="contained"
              size="small"
              startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
              onClick={handleSaveNotificationConfig}
              disabled={saving || !hasChanges}
              sx={{ 
                borderRadius: 8,
                fontWeight: 'bold',
                color: 'white'
              }}
            >
              {t('common:save')}
            </Button>
          </Box>
        }
      />
      <Divider />
      <CardContent sx={{ p: 3 }}>
        {errorMessage && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setErrorMessage(null)}>
            {errorMessage}
          </Alert>
        )}
        
        {loading ? (
          <Box display="flex" justifyContent="center" p={4}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            <Typography variant="subtitle2" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
              <EmailIcon sx={{ mr: 1 }} fontSize="small" />
              {t('notifications.email.title')}
            </Typography>
            
            <Box sx={{ mb: 3, ml: 2 }}>
              <FormControlLabel
                control={
                  <Switch
                    checked={notificationConfig.email}
                    onChange={(e) => handleToggleChange('email', e.target.checked)}
                  />
                }
                label={
                  <Box display="flex" alignItems="center">
                    <Typography>
                      {t('notifications.email.enabled')}
                    </Typography>
                    <Tooltip title={t('notifications.email.description')}>
                      <IconButton size="small">
                        <InfoIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                }
              />
            </Box>
            
            <Divider sx={{ my: 3 }} />
            
            <Typography variant="subtitle2" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
              <ChatIcon sx={{ mr: 1 }} fontSize="small" />
              {t('notifications.slack.title')}
            </Typography>
            
            <Box sx={{ mb: 3, ml: 2 }}>
              <FormControlLabel
                control={
                  <Switch
                    checked={notificationConfig.slack}
                    onChange={(e) => handleToggleChange('slack', e.target.checked)}
                  />
                }
                label={
                  <Box display="flex" alignItems="center">
                    <Typography>
                      {t('notifications.slack.enabled')}
                    </Typography>
                    <Tooltip title={t('notifications.slack.description')}>
                      <IconButton size="small">
                        <InfoIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                }
              />
            </Box>
            
            {notificationConfig.slack && (
              <Grid container spacing={2} sx={{ mb: 3, ml: 0 }}>
                <Grid item xs={12} md={6}>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <ApiKeyIcon fontSize="small" sx={{ mr: 1, color: theme.palette.text.secondary }} />
                    <Typography variant="body2" fontWeight="medium">
                      {t('notifications.slack.apiKey')}
                    </Typography>
                  </Box>
                  <TextField
                    fullWidth
                    type="password"
                    value={notificationConfig.slack_api_key}
                    onChange={(e) => handleTextChange('slack_api_key', e.target.value)}
                    variant="outlined"
                    size="small"
                    placeholder="xoxb-..."
                    disabled={!notificationConfig.slack}
                    helperText={t('notifications.slack.apiKeyHelper')}
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <TagIcon fontSize="small" sx={{ mr: 1, color: theme.palette.text.secondary }} />
                    <Typography variant="body2" fontWeight="medium">
                      {t('notifications.slack.channel')}
                    </Typography>
                  </Box>
                  <TextField
                    fullWidth
                    value={notificationConfig.slack_channel}
                    onChange={(e) => handleTextChange('slack_channel', e.target.value)}
                    variant="outlined"
                    size="small"
                    placeholder="#db-manager-alerts"
                    disabled={!notificationConfig.slack}
                    helperText={t('notifications.slack.channelHelper')}
                  />
                </Grid>
              </Grid>
            )}
            
            {notificationConfig.slack && notificationConfig.slack_api_key && notificationConfig.slack_channel && (
              <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
                <Button
                  variant="outlined"
                  color="primary"
                  startIcon={<SendIcon />}
                  onClick={() => setTestSlackOpen(true)}
                  disabled={!notificationConfig.slack || !notificationConfig.slack_api_key || !notificationConfig.slack_channel}
                  sx={{
                    borderRadius: 8,
                    px: 3,
                    py: 1
                  }}
                >
                  {t('notifications.slack.test')}
                </Button>
              </Box>
            )}
            
            {!notificationConfig.email && !notificationConfig.slack && (
              <Alert severity="warning" sx={{ mt: 3 }}>
                {t('notifications.allDisabled')}
              </Alert>
            )}
            
            {notificationConfig.email && (
              <Alert 
                severity="info" 
                icon={<CheckIcon />}
                sx={{ mt: 3 }}
              >
                {t('notifications.email.enabledInfo')}
              </Alert>
            )}
          </>
        )}
      </CardContent>

      {/* Diálogo para testar Slack */}
      <Dialog open={testSlackOpen} onClose={() => setTestSlackOpen(false)}>
        <DialogTitle sx={{ 
          bgcolor: theme.palette.primary.main, 
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          pb: 2
        }}>
          <SendIcon />
          {t('notifications.slack.testDialog.title')}
        </DialogTitle>
        <DialogContent sx={{ pt: 3 }}>
          <Typography variant="body1" paragraph>
            {t('notifications.slack.testDialog.message', { channel: notificationConfig.slack_channel || '#channel' })}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {t('notifications.slack.testDialog.help')}
          </Typography>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 3 }}>
          <Button onClick={() => setTestSlackOpen(false)} color="inherit">
            {t('common:cancel')}
          </Button>
          <Button 
            onClick={handleTestSlack} 
            color="primary" 
            variant="contained"
            disabled={testingSlack}
            startIcon={testingSlack ? <CircularProgress size={20} /> : <SendIcon />}
            sx={{ 
              fontWeight: 'bold',
              borderRadius: 6,
              px: 2
            }}
          >
            {t('notifications.slack.testDialog.send')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notificação de sucesso */}
      <Snackbar 
        open={!!successMessage} 
        autoHideDuration={6000} 
        onClose={() => setSuccessMessage(null)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>
    </Card>
  );
};

export default NotificationConfigPanel;