import React from 'react';
import { Chip } from '@mui/material';
import { useTranslation } from 'react-i18next';
import { 
  Environment, 
  ENVIRONMENT_COLORS, 
  ENVIRONMENT_BACKGROUND_COLORS 
} from '../../types/environment';

interface EnvironmentBadgeProps {
  environment: Environment;
  size?: 'small' | 'medium';
  variant?: 'filled' | 'outlined';
}

const EnvironmentBadge: React.FC<EnvironmentBadgeProps> = ({ 
  environment, 
  size = 'small',
  variant = 'filled'
}) => {
  const { t } = useTranslation('common');

  const getLabel = () => {
    switch (environment) {
      case 'dev':
        return t('environment.dev');
      case 'qa':
        return t('environment.qa');
      case 'prod':
        return t('environment.prod');
      default:
        return environment;
    }
  };

  return (
    <Chip
      label={getLabel()}
      size={size}
      sx={{
        backgroundColor: variant === 'filled' ? ENVIRONMENT_COLORS[environment] : ENVIRONMENT_BACKGROUND_COLORS[environment],
        color: variant === 'filled' ? '#fff' : ENVIRONMENT_COLORS[environment],
        border: variant === 'outlined' ? `1px solid ${ENVIRONMENT_COLORS[environment]}` : 'none',
        fontWeight: 600,
        letterSpacing: '0.5px',
        textTransform: 'uppercase',
        fontSize: size === 'small' ? '0.7rem' : '0.8rem',
        '&:hover': {
          backgroundColor: variant === 'filled' 
            ? ENVIRONMENT_COLORS[environment] 
            : ENVIRONMENT_BACKGROUND_COLORS[environment],
          opacity: 0.9
        }
      }}
    />
  );
};

export default EnvironmentBadge;