import React, { useState } from 'react';
import { useTranslation } from '../../i18n/i18n';
import { 
  Box, 
  Button, 
  Container, 
  TextField, 
  Typography, 
  Paper, 
  Alert,
  IconButton,
  InputAdornment,
  useTheme,
  useMediaQuery,
  Fade,
  Stack,
  Card,
  Grid,
  CardContent,
  Chip
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { 
  Visibility, 
  VisibilityOff, 
  Language, 
  LockOutlined,
  PersonOutlined,
  LoginOutlined,
  ShieldOutlined,
  SecurityOutlined,
  VerifiedUserOutlined,
  GppGoodOutlined,
  FingerprintOutlined,
  StorageOutlined,
  BusinessOutlined,
  CloudOffOutlined
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

interface LoginPageProps {
  onLogin: (username: string, password: string) => Promise<boolean>;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const { t, i18n } = useTranslation('auth');
  const { t: tCommon } = useTranslation('common');
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [language, setLanguage] = useState(i18n.language);
  const [languageMenuAnchor, setLanguageMenuAnchor] = useState<null | HTMLElement>(null);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const isDarkMode = theme.palette.mode === 'dark';

  const handleLanguageMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setLanguageMenuAnchor(event.currentTarget);
  };

  const handleLanguageMenuClose = () => {
    setLanguageMenuAnchor(null);
  };

  const handleLanguageChange = (newLanguage: string) => {
    setLanguage(newLanguage);
    i18n.changeLanguage(newLanguage);
    handleLanguageMenuClose();
  };

  React.useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const invalidToken = urlParams.get('invalid_token');
    
    if (invalidToken) {
      document.cookie = 'dbmanager_session=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;';
      document.cookie = 'csrf_token=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;';
      
      localStorage.removeItem('auth_token');
      localStorage.removeItem('user_info');
      localStorage.removeItem('currentUser');
      
      setError(t('login.sessionExpired') || 'Sua sessão expirou. Por favor, faça login novamente.');
      
      if (window.location.search) {
        const newUrl = window.location.pathname;
        window.history.replaceState({}, document.title, newUrl);
      }
    }
  }, [t]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!username || !password) {
      setError(t('login.error') as string || 'Invalid email or password');
      return;
    }
    
    setLoading(true);
    setError('');
    
    try {
      const loginSuccess = await onLogin(username, password);
      
      if (loginSuccess) {
        navigate('/dashboard');
      } else {
        setError(t('login.error') as string || 'Invalid email or password');
      }
    } catch (err: any) {
      if (err && err.message) {
        setError(err.message);
      } else {
        setError(tCommon('error') as string || 'Error');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSSOLogin = async () => {
    setLoading(true);
    setError('');
    
    try {
      const response = await fetch('/api/auth/sso/init', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || 'SSO não está configurado');
      }

      const data = await response.json();
      
      if (data.authUrl) {
        window.location.href = data.authUrl;
      } else {
        throw new Error('URL de autenticação SSO não encontrada');
      }
    } catch (err: any) {
      setError(err.message || 'Erro ao inicializar SSO');
      setLoading(false);
    }
  };

  const features = [
    {
      icon: <ShieldOutlined fontSize="large" />,
      title: t('login.features.dataProtection.title'),
      description: t('login.features.dataProtection.description'),
      color: '#4CAF50'
    },
    {
      icon: <VerifiedUserOutlined fontSize="large" />,
      title: t('login.features.accessControl.title'),
      description: t('login.features.accessControl.description'),
      color: '#2196F3'
    },
    {
      icon: <SecurityOutlined fontSize="large" />,
      title: t('login.features.completeAudit.title'),
      description: t('login.features.completeAudit.description'),
      color: '#FF9800'
    }
  ];

  const enterpriseFeatures = [
    { icon: <CloudOffOutlined />, label: 'On-Premise', description: t('login.enterpriseFeatures.onPremise') },
    { icon: <BusinessOutlined />, label: 'Enterprise', description: t('login.enterpriseFeatures.enterprise') },
    { icon: <StorageOutlined />, label: 'Secure', description: t('login.enterpriseFeatures.secure') }
  ];

  return (
    <>
      {/* Background que sempre ocupa toda a tela */}
      <Box
        sx={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          zIndex: -1,
          background: isDarkMode
            ? 'linear-gradient(135deg, #1a1a1a 0%, #2d2d30 100%)'
            : 'linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)',
        }}
      />
      
      {/* Language Selector - Dropdown customizado */}
      <Box
        sx={{
          position: 'fixed',
          top: 20,
          right: 20,
          zIndex: 9999,
        }}
      >
        <Box sx={{ position: 'relative' }}>
          <Button
            onClick={handleLanguageMenuOpen}
            variant="contained"
            sx={{
              borderRadius: 3,
              background: isDarkMode 
                ? alpha(theme.palette.background.paper, 0.95)
                : alpha('#ffffff', 0.95),
              backdropFilter: 'blur(10px)',
              border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
              color: theme.palette.text.primary,
              padding: '8px 16px',
              minWidth: 140,
              textTransform: 'none',
              boxShadow: theme.shadows[2],
              '&:hover': {
                background: isDarkMode 
                  ? alpha(theme.palette.background.paper, 0.98)
                  : alpha('#ffffff', 0.98),
              }
            }}
            startIcon={<Language fontSize="small" />}
          >
            {language === 'en' && '🇺🇸 English'}
            {language === 'pt' && '🇧🇷 Português'}
            {language === 'es' && '🇪🇸 Español'}
          </Button>
          
          {/* Dropdown customizado que aparece EXATAMENTE abaixo do botão */}
          {Boolean(languageMenuAnchor) && (
            <Paper
              sx={{
                position: 'absolute',
                top: '100%',
                left: 0,
                right: 0,
                mt: 0.5,
                borderRadius: 2,
                background: isDarkMode 
                  ? alpha(theme.palette.background.paper, 0.95)
                  : alpha('#ffffff', 0.95),
                backdropFilter: 'blur(10px)',
                border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                boxShadow: theme.shadows[8],
                zIndex: 10000,
              }}
            >
              <Box
                sx={{
                  py: 1,
                  '& > *': {
                    padding: '8px 16px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    '&:hover': {
                      backgroundColor: alpha(theme.palette.primary.main, 0.08),
                    }
                  }
                }}
              >
                <Box
                  onClick={() => handleLanguageChange('en')}
                  sx={{
                    backgroundColor: language === 'en' ? alpha(theme.palette.primary.main, 0.12) : 'transparent',
                  }}
                >
                  🇺🇸 English
                </Box>
                <Box
                  onClick={() => handleLanguageChange('pt')}
                  sx={{
                    backgroundColor: language === 'pt' ? alpha(theme.palette.primary.main, 0.12) : 'transparent',
                  }}
                >
                  🇧🇷 Português
                </Box>
                <Box
                  onClick={() => handleLanguageChange('es')}
                  sx={{
                    backgroundColor: language === 'es' ? alpha(theme.palette.primary.main, 0.12) : 'transparent',
                  }}
                >
                  🇪🇸 Español
                </Box>
              </Box>
            </Paper>
          )}
        </Box>
        
        {/* Overlay para fechar quando clicar fora */}
        {Boolean(languageMenuAnchor) && (
          <Box
            sx={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              zIndex: 9998,
            }}
            onClick={handleLanguageMenuClose}
          />
        )}
      </Box>
      
      <Box
        sx={{
          minHeight: '100vh',
          width: '100%',
          display: 'flex',
          position: 'relative',
        }}
      >
      {/* Subtle Pattern Overlay */}
      <Box
        sx={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          opacity: isDarkMode ? 0.02 : 0.03,
          backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23000000' fill-opacity='0.4'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`,
          backgroundSize: '30px 30px',
        }}
      />

      {/* Main Content */}
      <Container maxWidth="xl" sx={{ width: '100%', display: 'flex', alignItems: 'center', py: 4, position: 'relative', zIndex: 1 }}>
        <Grid container sx={{ width: '100%' }}>
          {/* Left Side - Features (Desktop only) */}
          {!isMobile && (
            <Grid 
              item 
              md={6}
              sx={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                padding: { md: 4, lg: 6 },
                minHeight: '600px',
                background: isDarkMode
                  ? 'linear-gradient(135deg, rgba(45, 45, 48, 0.6) 0%, rgba(26, 26, 26, 0.8) 100%)'
                  : 'linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(248, 249, 250, 0.9) 100%)',
                backdropFilter: 'blur(20px)',
                borderRadius: '24px 0 0 24px',
                border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                borderRight: 'none',
              }}
            >
              {/* Logo and Title */}
              <Box sx={{ textAlign: 'center', marginBottom: 4 }}>
                <Box
                  component="img"
                  src="https://i.ibb.co/d0ZPFyWs/dbmanager4.png"
                  alt="DB-Manager Logo"
                  sx={{
                    width: '60%',
                    maxWidth: 240,
                    height: 'auto',
                    marginBottom: 2,
                    filter: isDarkMode ? 'brightness(1.1)' : 'none',
                  }}
                />
                <Typography 
                  variant="subtitle1" 
                  sx={{ 
                    color: isDarkMode ? alpha('#ffffff', 0.8) : '#6c757d',
                    fontWeight: 400,
                    maxWidth: 350,
                    mx: 'auto',
                    lineHeight: 1.4,
                    marginTop: 1,
                  }}
                >
                  {tCommon('app.description')}
                </Typography>
              </Box>

              {/* Enterprise Features */}
              <Box sx={{ marginBottom: 3 }}>
                <Grid container spacing={1}>
                  {enterpriseFeatures.map((feature, index) => (
                    <Grid item xs={4} key={index}>
                      <Box sx={{ textAlign: 'center' }}>
                        <Box 
                          sx={{ 
                            color: isDarkMode ? alpha('#ffffff', 0.7) : '#6c757d',
                            marginBottom: 0.5,
                            display: 'flex',
                            justifyContent: 'center',
                          }}
                        >
                          {feature.icon}
                        </Box>
                        <Typography 
                          variant="caption" 
                          sx={{ 
                            color: isDarkMode ? '#ffffff' : '#212529',
                            fontWeight: 600,
                            marginBottom: 0.5,
                            fontSize: '0.75rem',
                          }}
                        >
                          {feature.label}
                        </Typography>
                        <Typography 
                          variant="caption" 
                          sx={{ 
                            color: isDarkMode ? alpha('#ffffff', 0.6) : '#6c757d',
                            fontSize: '0.7rem',
                            lineHeight: 1.3,
                          }}
                        >
                          {feature.description}
                        </Typography>
                      </Box>
                    </Grid>
                  ))}
                </Grid>
              </Box>

              {/* Features Cards */}
              <Stack spacing={2}>
                {features.map((feature, index) => (
                  <Card
                    key={index}
                    sx={{
                      background: isDarkMode
                        ? alpha('#ffffff', 0.05)
                        : alpha('#ffffff', 0.7),
                      backdropFilter: 'blur(10px)',
                      border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                      borderRadius: 2,
                      transition: 'all 0.2s ease',
                      '&:hover': {
                        background: isDarkMode
                          ? alpha('#ffffff', 0.08)
                          : alpha('#ffffff', 0.9),
                        transform: 'translateY(-1px)',
                        boxShadow: isDarkMode 
                          ? '0 4px 20px rgba(255, 255, 255, 0.1)'
                          : '0 4px 20px rgba(0, 0, 0, 0.08)',
                      },
                    }}
                  >
                    <CardContent sx={{ padding: '12px !important' }}>
                      <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1.5 }}>
                        <Box 
                          sx={{ 
                            color: feature.color,
                            backgroundColor: alpha(feature.color, 0.1),
                            borderRadius: 1,
                            p: 1,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            minWidth: 40,
                            height: 40,
                          }}
                        >
                          {React.cloneElement(feature.icon, { fontSize: 'small' })}
                        </Box>
                        <Box sx={{ flex: 1 }}>
                          <Typography 
                            variant="body2" 
                            sx={{ 
                              color: isDarkMode ? '#ffffff' : '#212529',
                              fontWeight: 600,
                              marginBottom: 0.5,
                            }}
                          >
                            {feature.title}
                          </Typography>
                          <Typography 
                            variant="caption" 
                            sx={{ 
                              color: isDarkMode ? alpha('#ffffff', 0.8) : '#6c757d',
                              lineHeight: 1.4,
                              fontSize: '0.75rem',
                            }}
                          >
                            {feature.description}
                          </Typography>
                        </Box>
                      </Box>
                    </CardContent>
                  </Card>
                ))}
              </Stack>
            </Grid>
          )}

          {/* Right Side - Login Form */}
          <Grid 
            item 
            xs={12} 
            md={6}
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: { xs: 3, md: 4, lg: 5 },
              minHeight: '600px',
            }}
          >
            <Paper
              elevation={12}
              sx={{
                width: '100%',
                maxWidth: 420,
                padding: { xs: 3, sm: 4 },
                borderRadius: isMobile ? 3 : '0 24px 24px 0',
                background: isDarkMode 
                  ? alpha(theme.palette.background.paper, 0.95)
                  : alpha('#ffffff', 0.95),
                backdropFilter: 'blur(20px)',
                border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                borderLeft: isMobile ? `1px solid ${alpha(theme.palette.divider, 0.1)}` : 'none',
                position: 'relative',
                overflow: 'hidden',
                '&::before': {
                  content: '""',
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  height: 4,
                  background: `linear-gradient(90deg, ${theme.palette.primary.main}, ${theme.palette.primary.dark})`,
                }
              }}
            >
              {/* Mobile Logo */}
              {isMobile && (
                <Box sx={{ textAlign: 'center', marginBottom: 4 }}>
                  <Box
                    component="img"
                    src="https://i.ibb.co/d0ZPFyWs/dbmanager4.png"
                    alt="DB-Manager Logo"
                    sx={{
                      width: '60%',
                      maxWidth: 200,
                      height: 'auto',
                      marginBottom: 2,
                    }}
                  />
                  <Typography 
                    variant="body2" 
                    color="text.secondary"
                    sx={{ marginBottom: 2, marginTop: 1 }}
                  >
                    {tCommon('app.description')}
                  </Typography>
                  
                  {/* Mobile Enterprise Features */}
                  <Stack direction="row" spacing={1} justifyContent="center" sx={{ marginBottom: 2 }}>
                    {enterpriseFeatures.map((feature, index) => (
                      <Chip
                        key={index}
                        icon={feature.icon}
                        label={feature.label}
                        size="small"
                        variant="outlined"
                        sx={{
                          borderColor: alpha(theme.palette.divider, 0.3),
                          backgroundColor: alpha(theme.palette.background.default, 0.5),
                          fontSize: '0.75rem',
                        }}
                      />
                    ))}
                  </Stack>
                </Box>
              )}

              {/* Welcome Text */}
              <Box sx={{ marginBottom: 4, textAlign: 'center' }}>
                <Typography 
                  variant="h4" 
                  sx={{ 
                    fontWeight: 700,
                    marginBottom: 1,
                    color: theme.palette.text.primary,
                  }}
                >
                  {t('login.welcomeBack')}
                </Typography>
                <Typography variant="body1" color="text.secondary">
                  {t('login.subtitle')}
                </Typography>
              </Box>

              {/* Error Alert */}
              {error && (
                <Fade in={true} timeout={300}>
                  <Alert
                    severity="error"
                    sx={{
                      marginBottom: 3,
                      borderRadius: 2,
                      '& .MuiAlert-icon': {
                        fontSize: '1.2rem',
                      }
                    }}
                  >
                    {error}
                  </Alert>
                </Fade>
              )}

              {/* Login Form */}
              <Box component="form" onSubmit={handleSubmit} noValidate>
                <Stack spacing={3}>
                  <TextField
                    fullWidth
                    label={t('login.username')}
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    variant="outlined"
                    autoComplete="username"
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <PersonOutlined color="action" />
                        </InputAdornment>
                      ),
                    }}
                    sx={{
                      '& .MuiInputLabel-root': {
                        color: theme.palette.text.secondary,
                        backgroundColor: theme.palette.background.paper,
                        px: 0.5,
                        '&.Mui-focused': {
                          color: theme.palette.primary.main,
                        },
                      },
                      '& .MuiOutlinedInput-root': {
                        borderRadius: 2,
                        backgroundColor: isDarkMode
                          ? alpha(theme.palette.background.default, 0.3)
                          : alpha('#ffffff', 0.8),
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          '& .MuiOutlinedInput-notchedOutline': {
                            borderColor: theme.palette.primary.main,
                          }
                        }
                      },
                    }}
                  />

                  <TextField
                    fullWidth
                    label={t('login.password')}
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    variant="outlined"
                    autoComplete="current-password"
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <LockOutlined color="action" />
                        </InputAdornment>
                      ),
                      endAdornment: (
                        <InputAdornment position="end">
                          <IconButton
                            onClick={() => setShowPassword(!showPassword)}
                            edge="end"
                            size="small"
                          >
                            {showPassword ? <VisibilityOff /> : <Visibility />}
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                    sx={{
                      '& .MuiInputLabel-root': {
                        color: theme.palette.text.secondary,
                        backgroundColor: theme.palette.background.paper,
                        px: 0.5,
                        '&.Mui-focused': {
                          color: theme.palette.primary.main,
                        },
                      },
                      '& .MuiOutlinedInput-root': {
                        borderRadius: 2,
                        backgroundColor: isDarkMode
                          ? alpha(theme.palette.background.default, 0.3)
                          : alpha('#ffffff', 0.8),
                        transition: 'all 0.2s ease',
                        '&:hover': {
                          '& .MuiOutlinedInput-notchedOutline': {
                            borderColor: theme.palette.primary.main,
                          }
                        }
                      },
                    }}
                  />

                  {/* Forgot Password */}
                  <Box sx={{ textAlign: 'right' }}>
                    <Typography
                      variant="body2"
                      sx={{
                        color: theme.palette.primary.main,
                        cursor: 'pointer',
                        fontWeight: 500,
                        '&:hover': {
                          textDecoration: 'underline',
                        },
                      }}
                    >
                      {t('login.forgotPassword')}
                    </Typography>
                  </Box>

                  {/* Login Button */}
                  <Button
                    type="submit"
                    fullWidth
                    variant="contained"
                    size="large"
                    disabled={loading}
                    startIcon={<LoginOutlined />}
                    sx={{
                      padding: '14px',
                      textTransform: 'none',
                      fontSize: '1.1rem',
                      fontWeight: 600,
                      borderRadius: 2,
                      background: theme.palette.primary.main,
                      color: '#ffffff',
                      boxShadow: `0 4px 12px ${alpha(theme.palette.primary.main, 0.3)}`,
                      transition: 'all 0.2s ease',
                      '&:hover': {
                        background: theme.palette.primary.dark,
                        transform: 'translateY(-1px)',
                        boxShadow: `0 6px 16px ${alpha(theme.palette.primary.main, 0.4)}`,
                      },
                      '&:disabled': {
                        background: alpha(theme.palette.action.disabled, 0.3),
                        color: theme.palette.action.disabled,
                      }
                    }}
                  >
                    {loading ? t('common:loading') : t('login.loginButton')}
                  </Button>

                  {/* Divider */}
                  <Box sx={{ position: 'relative', textAlign: 'center', my: 2 }}>
                    <Typography
                      variant="body2"
                      sx={{
                        position: 'relative',
                        backgroundColor: isDarkMode ? theme.palette.background.paper : '#ffffff',
                        color: theme.palette.text.secondary,
                        padding: '0 16px',
                        zIndex: 1,
                      }}
                    >
                      {t('login.or')}
                    </Typography>
                    <Box
                      sx={{
                        position: 'absolute',
                        top: '50%',
                        left: 0,
                        right: 0,
                        height: 1,
                        backgroundColor: theme.palette.divider,
                        zIndex: 0,
                      }}
                    />
                  </Box>

                  {/* SSO Button */}
                  <Button
                    fullWidth
                    variant="outlined"
                    size="large"
                    startIcon={<FingerprintOutlined />}
                    onClick={handleSSOLogin}
                    sx={{
                      padding: '12px',
                      textTransform: 'none',
                      fontSize: '1rem',
                      fontWeight: 500,
                      borderRadius: 2,
                      borderColor: alpha(theme.palette.divider, 0.5),
                      color: theme.palette.text.secondary,
                      backgroundColor: isDarkMode 
                        ? alpha(theme.palette.background.default, 0.3)
                        : alpha('#ffffff', 0.8),
                      transition: 'all 0.2s ease',
                      '&:hover': {
                        borderColor: theme.palette.primary.main,
                        backgroundColor: alpha(theme.palette.primary.main, 0.04),
                        transform: 'translateY(-1px)',
                        boxShadow: `0 4px 12px ${alpha(theme.palette.primary.main, 0.15)}`,
                      },
                    }}
                  >
                    {t('login.sso')}
                  </Button>
                </Stack>
              </Box>

              {/* Security Badge */}
              <Box sx={{ textAlign: 'center', marginTop: 4 }}>
                <Chip
                  icon={<GppGoodOutlined />}
                  label={t('login.enterpriseSecurity')}
                  size="small"
                  variant="outlined"
                  sx={{
                    borderColor: alpha(theme.palette.success.main, 0.3),
                    color: theme.palette.success.main,
                    backgroundColor: alpha(theme.palette.success.main, 0.05),
                    marginBottom: 2,
                  }}
                />
                <Typography variant="caption" color="text.secondary" display="block">
                  {tCommon('app.name')} © {new Date().getFullYear()} - {t('login.allRightsReserved')}
                </Typography>
              </Box>
            </Paper>
          </Grid>
        </Grid>
      </Container>
    </Box>
    </>
  );
};

export default LoginPage;