import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Stepper,
  Step,
  StepLabel,
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Typography,
  Alert,
  CircularProgress,
  Card,
  CardContent,
  Grid,
  Divider,
  Switch,
  FormControlLabel,
  Slider,
  Chip,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  InputAdornment,
  Tooltip,
  IconButton,
  Collapse,
  Paper,
  Snackbar,
} from '@mui/material';
import {
  Cloud as CloudIcon,
  Storage as StorageIcon,
  Security as SecurityIcon,
  AttachMoney as MoneyIcon,
  CloudQueue as AWSIcon,
  CloudCircle as AzureIcon,
  CloudOutlined as GCPIcon,
  Info as InfoIcon,
  Check as CheckIcon,
  NavigateNext as NextIcon,
  NavigateBefore as BackIcon,
  Launch as LaunchIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { apiClient as api } from '../../services/api';

interface CloudProvisionModalProps {
  open: boolean;
  onClose: () => void;
  onSuccess?: (instanceId: string) => void;
}

const steps = ['Provider Selection', 'Instance Configuration', 'Database Settings', 'Review & Launch'];

const CloudProvisionModal: React.FC<CloudProvisionModalProps> = ({ open, onClose, onSuccess }) => {
  const { t } = useTranslation(['settings', 'common']);
  const [activeStep, setActiveStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [providers, setProviders] = useState<{ [key: string]: any[] }>({});
  const [regions, setRegions] = useState<any[]>([]);
  const [instanceTypes, setInstanceTypes] = useState<any[]>([]);
  const [estimatedCost, setEstimatedCost] = useState<number | null>(null);
  const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
    open: false,
    message: '',
    severity: 'success'
  });

  const [formData, setFormData] = useState({
    // Provider
    provider: '',
    credentialsId: '',

    // Instance
    region: '',
    instanceName: '',
    instanceType: '',
    engine: 'postgres',
    engineVersion: '',
    environment: 'dev',

    // Storage
    storageType: 'gp3',
    storageSize: 100,
    iops: 3000,
    encrypted: true,

    // High Availability
    multiAZ: false,
    backupRetentionDays: 7,
    backupWindow: '03:00-04:00',
    maintenanceWindow: 'sun:04:00-sun:05:00',

    // Networking
    publiclyAccessible: false,
    vpcId: '',
    subnetGroup: '',
    securityGroups: [] as string[],

    // Database
    databaseName: '',
    masterUsername: 'admin',
    masterPassword: '',
    port: 5432,

    // DBManager Integration
    autoRegister: true,
    createServiceUser: true,
    serviceUsername: 'dbmanager_service',
    enableAuditLogs: false,
    enableMonitoring: true,
  });

  useEffect(() => {
    if (open) {
      fetchProviders();
    }
  }, [open]);

  useEffect(() => {
    if (formData.provider && formData.credentialsId) {
      fetchRegions();
    }
  }, [formData.provider, formData.credentialsId]);

  useEffect(() => {
    if (formData.region) {
      fetchInstanceTypes();
    }
  }, [formData.region]);

  useEffect(() => {
    if (formData.instanceType && formData.storageSize) {
      estimateCost();
    }
  }, [formData.instanceType, formData.storageSize, formData.multiAZ]);

  const fetchProviders = async () => {
    try {
      const response = await api.get('/cloud/credentials');
      const credentials = response.data.data || [];

      // Group credentials by provider
      const providerMap: any = {};
      credentials.forEach((cred: any) => {
        if (!providerMap[cred.provider]) {
          providerMap[cred.provider] = [];
        }
        providerMap[cred.provider].push(cred);
      });

      setProviders(providerMap);
    } catch (error) {
      console.error('Failed to fetch providers:', error);
    }
  };

  const fetchRegions = async () => {
    try {
      const response = await api.get(`/cloud/providers/${formData.provider}/regions`);
      setRegions(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch regions:', error);
    }
  };

  const fetchInstanceTypes = async () => {
    try {
      const response = await api.get(`/cloud/providers/${formData.provider}/instance-types`, {
        params: { region: formData.region, engine: formData.engine }
      });
      setInstanceTypes(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch instance types:', error);
    }
  };

  const estimateCost = async () => {
    try {
      const response = await api.post('/cloud/estimate-cost', {
        provider: formData.provider,
        region: formData.region,
        instanceType: formData.instanceType,
        storageSize: formData.storageSize,
        multiAZ: formData.multiAZ,
      });
      setEstimatedCost(response.data.data?.estimatedMonthly || null);
    } catch (error) {
      console.error('Failed to estimate cost:', error);
    }
  };

  const handleNext = () => {
    setActiveStep((prevActiveStep) => prevActiveStep + 1);
  };

  const handleBack = () => {
    setActiveStep((prevActiveStep) => prevActiveStep - 1);
  };

  const handleProvision = async () => {
    try {
      setLoading(true);

      const response = await api.post('/cloud/provision', formData);

      if (response.data.success) {
        setSnackbar({ open: true, message: t('provision.provisionSuccess'), severity: 'success' });
        if (onSuccess) {
          onSuccess(response.data.data.requestId);
        }
        setTimeout(() => onClose(), 2000);
      } else {
        setSnackbar({ open: true, message: response.data.error || t('provision.provisionError'), severity: 'error' });
      }
    } catch (error: any) {
      setSnackbar({ open: true, message: error.response?.data?.error || t('provision.provisionError'), severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const getProviderIcon = (provider: string) => {
    switch (provider) {
      case 'aws':
        return <AWSIcon sx={{ fontSize: 40, color: '#FF9900' }} />;
      case 'azure':
        return <AzureIcon sx={{ fontSize: 40, color: '#0078D4' }} />;
      case 'gcp':
        return <GCPIcon sx={{ fontSize: 40, color: '#4285F4' }} />;
      default:
        return <CloudIcon sx={{ fontSize: 40 }} />;
    }
  };

  const renderStepContent = (step: number) => {
    switch (step) {
      case 0: // Provider Selection
        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('provision.selectProvider')}
            </Typography>

            <Grid container spacing={3}>
              {Object.keys(providers).map((provider) => (
                <Grid item xs={12} md={4} key={provider}>
                  <Card
                    sx={{
                      cursor: 'pointer',
                      border: formData.provider === provider ? 2 : 1,
                      borderColor: formData.provider === provider ? 'primary.main' : 'divider',
                      transition: 'all 0.3s',
                      '&:hover': {
                        transform: 'translateY(-4px)',
                        boxShadow: 3,
                      },
                    }}
                    onClick={() => setFormData({ ...formData, provider })}
                  >
                    <CardContent sx={{ textAlign: 'center' }}>
                      {getProviderIcon(provider)}
                      <Typography variant="h6" sx={{ mt: 2 }}>
                        {t(`cloud:providers.${provider}`)}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {providers[provider].length} {t('credentials.title')}
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>

            {formData.provider && (
              <Box sx={{ mt: 3 }}>
                <FormControl fullWidth>
                  <InputLabel>{t('provision.selectCredentials')}</InputLabel>
                  <Select
                    value={formData.credentialsId}
                    onChange={(e) => setFormData({ ...formData, credentialsId: e.target.value })}
                    label={t('provision.selectCredentials')}
                  >
                    {providers[formData.provider]?.map((cred: any) => (
                      <MenuItem key={cred.id} value={cred.id}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          {cred.name}
                          {cred.is_default && (
                            <Chip label={t('credentials.default')} size="small" color="primary" />
                          )}
                          {cred.validated_at && (
                            <CheckIcon color="success" fontSize="small" />
                          )}
                        </Box>
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>

                {formData.credentialsId && (
                  <FormControl fullWidth sx={{ mt: 2 }}>
                    <InputLabel>{t('provision.selectRegion')}</InputLabel>
                    <Select
                      value={formData.region}
                      onChange={(e) => setFormData({ ...formData, region: e.target.value })}
                      label={t('provision.selectRegion')}
                    >
                      {regions.map((region: any) => (
                        <MenuItem key={region.id} value={region.id}>
                          {region.name} ({region.location})
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                )}
              </Box>
            )}
          </Box>
        );

      case 1: // Instance Configuration
        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('provision.instanceDetails')}
            </Typography>

            <Grid container spacing={2}>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label={t('provision.instanceName')}
                  value={formData.instanceName}
                  onChange={(e) => setFormData({ ...formData, instanceName: e.target.value })}
                  required
                  helperText="Must be unique within the region"
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>{t('provision.selectEngine')}</InputLabel>
                  <Select
                    value={formData.engine}
                    onChange={(e) => setFormData({ ...formData, engine: e.target.value })}
                    label={t('provision.selectEngine')}
                  >
                    <MenuItem value="postgres">PostgreSQL</MenuItem>
                    <MenuItem value="mysql">MySQL</MenuItem>
                    <MenuItem value="mariadb">MariaDB</MenuItem>
                    <MenuItem value="mssql">SQL Server</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>{t('provision.selectVersion')}</InputLabel>
                  <Select
                    value={formData.engineVersion}
                    onChange={(e) => setFormData({ ...formData, engineVersion: e.target.value })}
                    label={t('provision.selectVersion')}
                  >
                    <MenuItem value="14.6">14.6</MenuItem>
                    <MenuItem value="13.9">13.9</MenuItem>
                    <MenuItem value="12.14">12.14</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <FormControl fullWidth>
                  <InputLabel>{t('provision.instanceType')}</InputLabel>
                  <Select
                    value={formData.instanceType}
                    onChange={(e) => setFormData({ ...formData, instanceType: e.target.value })}
                    label={t('provision.instanceType')}
                  >
                    {instanceTypes.map((type: any) => (
                      <MenuItem key={type.id} value={type.id}>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', width: '100%' }}>
                          <Box>
                            <Typography>{type.name}</Typography>
                            <Typography variant="caption" color="text.secondary">
                              {type.vcpus} vCPUs • {type.memory} GB RAM • {type.network}
                            </Typography>
                          </Box>
                          <Typography variant="body2" color="primary">
                            ${type.pricePerHour}/hr
                          </Typography>
                        </Box>
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <Divider sx={{ my: 2 }} />
                <Typography variant="subtitle1" gutterBottom>
                  {t('provision.storage')}
                </Typography>
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>{t('provision.storageType')}</InputLabel>
                  <Select
                    value={formData.storageType}
                    onChange={(e) => setFormData({ ...formData, storageType: e.target.value })}
                    label={t('provision.storageType')}
                  >
                    <MenuItem value="gp3">General Purpose SSD (gp3)</MenuItem>
                    <MenuItem value="io2">Provisioned IOPS SSD (io2)</MenuItem>
                    <MenuItem value="standard">Magnetic</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12} md={6}>
                <Typography gutterBottom>
                  {t('provision.storageSize')}: {formData.storageSize} GB
                </Typography>
                <Slider
                  value={formData.storageSize}
                  onChange={(e, value) => setFormData({ ...formData, storageSize: value as number })}
                  min={20}
                  max={16000}
                  step={10}
                  marks={[
                    { value: 100, label: '100 GB' },
                    { value: 1000, label: '1 TB' },
                    { value: 5000, label: '5 TB' },
                  ]}
                />
              </Grid>

              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.encrypted}
                      onChange={(e) => setFormData({ ...formData, encrypted: e.target.checked })}
                    />
                  }
                  label={t('provision.encrypted')}
                />
              </Grid>

              <Grid item xs={12}>
                <Divider sx={{ my: 2 }} />
                <Typography variant="subtitle1" gutterBottom>
                  {t('provision.highAvailability')}
                </Typography>
              </Grid>

              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.multiAZ}
                      onChange={(e) => setFormData({ ...formData, multiAZ: e.target.checked })}
                    />
                  }
                  label={t('provision.multiAZ')}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  type="number"
                  label={t('provision.backupRetention')}
                  value={formData.backupRetentionDays}
                  onChange={(e) => setFormData({ ...formData, backupRetentionDays: parseInt(e.target.value) })}
                  InputProps={{
                    inputProps: { min: 1, max: 35 }
                  }}
                />
              </Grid>
            </Grid>
          </Box>
        );

      case 2: // Database Settings
        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {t('provision.database')}
            </Typography>

            <Grid container spacing={2}>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label={t('provision.databaseName')}
                  value={formData.databaseName}
                  onChange={(e) => setFormData({ ...formData, databaseName: e.target.value })}
                  required
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label={t('provision.masterUsername')}
                  value={formData.masterUsername}
                  onChange={(e) => setFormData({ ...formData, masterUsername: e.target.value })}
                  required
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  type="password"
                  label={t('provision.masterPassword')}
                  value={formData.masterPassword}
                  onChange={(e) => setFormData({ ...formData, masterPassword: e.target.value })}
                  required
                  helperText="Min 8 characters, including uppercase, lowercase, and numbers"
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  type="number"
                  label={t('provision.port')}
                  value={formData.port}
                  onChange={(e) => setFormData({ ...formData, port: parseInt(e.target.value) })}
                  required
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>{t('provision.environment')}</InputLabel>
                  <Select
                    value={formData.environment}
                    onChange={(e) => setFormData({ ...formData, environment: e.target.value })}
                    label={t('provision.environment')}
                  >
                    <MenuItem value="dev">Development</MenuItem>
                    <MenuItem value="qa">QA/Testing</MenuItem>
                    <MenuItem value="staging">Staging</MenuItem>
                    <MenuItem value="prod">Production</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <Divider sx={{ my: 2 }} />
                <Typography variant="subtitle1" gutterBottom>
                  DBManager Integration
                </Typography>
              </Grid>

              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.autoRegister}
                      onChange={(e) => setFormData({ ...formData, autoRegister: e.target.checked })}
                    />
                  }
                  label={t('provision.autoRegister')}
                />
              </Grid>

              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.createServiceUser}
                      onChange={(e) => setFormData({ ...formData, createServiceUser: e.target.checked })}
                    />
                  }
                  label={t('provision.createServiceUser')}
                />
              </Grid>

              {formData.createServiceUser && (
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label={t('provision.serviceUsername')}
                    value={formData.serviceUsername}
                    onChange={(e) => setFormData({ ...formData, serviceUsername: e.target.value })}
                  />
                </Grid>
              )}

              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.enableAuditLogs}
                      onChange={(e) => setFormData({ ...formData, enableAuditLogs: e.target.checked })}
                    />
                  }
                  label={t('provision.enableAuditLogs')}
                />
              </Grid>

              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formData.enableMonitoring}
                      onChange={(e) => setFormData({ ...formData, enableMonitoring: e.target.checked })}
                    />
                  }
                  label={t('provision.enableMonitoring')}
                />
              </Grid>
            </Grid>
          </Box>
        );

      case 3: // Review & Launch
        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              Review Configuration
            </Typography>

            <List>
              <ListItem>
                <ListItemIcon>
                  <CloudIcon />
                </ListItemIcon>
                <ListItemText
                  primary="Provider"
                  secondary={`${formData.provider.toUpperCase()} - ${formData.region}`}
                />
              </ListItem>

              <ListItem>
                <ListItemIcon>
                  <StorageIcon />
                </ListItemIcon>
                <ListItemText
                  primary="Instance"
                  secondary={`${formData.instanceName} • ${formData.instanceType} • ${formData.engine} ${formData.engineVersion}`}
                />
              </ListItem>

              <ListItem>
                <ListItemIcon>
                  <StorageIcon />
                </ListItemIcon>
                <ListItemText
                  primary="Storage"
                  secondary={`${formData.storageSize} GB ${formData.storageType} ${formData.encrypted ? '• Encrypted' : ''}`}
                />
              </ListItem>

              <ListItem>
                <ListItemIcon>
                  <SecurityIcon />
                </ListItemIcon>
                <ListItemText
                  primary="High Availability"
                  secondary={formData.multiAZ ? 'Multi-AZ Enabled' : 'Single Availability Zone'}
                />
              </ListItem>

              {estimatedCost && (
                <ListItem>
                  <ListItemIcon>
                    <MoneyIcon />
                  </ListItemIcon>
                  <ListItemText
                    primary={t('provision.estimatedCost')}
                    secondary={
                      <Typography variant="h6" color="primary">
                        ${estimatedCost} / {t('provision.monthly')}
                      </Typography>
                    }
                  />
                </ListItem>
              )}
            </List>

            <Alert severity="info" sx={{ mt: 2 }}>
              {t('provision.provisioning')} This process may take 10-15 minutes to complete.
            </Alert>
          </Box>
        );

      default:
        return null;
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <CloudIcon />
          {t('provisionDatabase')}
        </Box>
      </DialogTitle>

      <DialogContent>
        <Box sx={{ mt: 2, mb: 4 }}>
          <Stepper activeStep={activeStep} alternativeLabel>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </Box>

        <Box sx={{ mt: 3, minHeight: 400 }}>
          {renderStepContent(activeStep)}
        </Box>
      </DialogContent>

      <DialogActions sx={{ px: 3, pb: 2 }}>
        <Button onClick={onClose} disabled={loading}>
          {t('common:cancel')}
        </Button>
        <Box sx={{ flex: '1 1 auto' }} />
        <Button
          onClick={handleBack}
          disabled={activeStep === 0 || loading}
          startIcon={<BackIcon />}
        >
          {t('common:back')}
        </Button>
        {activeStep === steps.length - 1 ? (
          <Button
            variant="contained"
            onClick={handleProvision}
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} /> : <LaunchIcon />}
          >
            {loading ? t('provision.provisioning') : t('provision.provision')}
          </Button>
        ) : (
          <Button
            variant="contained"
            onClick={handleNext}
            disabled={
              (activeStep === 0 && (!formData.provider || !formData.credentialsId || !formData.region)) ||
              (activeStep === 1 && (!formData.instanceName || !formData.instanceType)) ||
              (activeStep === 2 && (!formData.databaseName || !formData.masterUsername || !formData.masterPassword))
            }
            endIcon={<NextIcon />}
          >
            {t('common:next')}
          </Button>
        )}
      </DialogActions>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert
          onClose={() => setSnackbar({ ...snackbar, open: false })}
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Dialog>
  );
};

export default CloudProvisionModal;