import React from 'react';
import { useTranslation } from 'react-i18next';
import BasicDropdown from './BasicDropdown';
import { AccessTime as TimeIcon } from '@mui/icons-material';

interface TimeRangeDropdownProps {
  value: string;
  onChange: (value: string) => void;
  size?: 'small' | 'medium';
  fullWidth?: boolean;
}

const TimeRangeDropdown: React.FC<TimeRangeDropdownProps> = ({ 
  value, 
  onChange, 
  size = 'medium',
  fullWidth = false,
}) => {
  const { t } = useTranslation('discrepancy');

  const options = [
    { value: '7d', label: t('last7Days') as string },
    { value: '30d', label: t('last30Days') as string },
    { value: '90d', label: t('last90Days') as string },
    { value: 'all', label: t('allTime') as string },
  ];

  return (
    <BasicDropdown
      value={value}
      onChange={onChange}
      options={options}
      label={t('timeRange') as string}
      size={size}
      fullWidth={fullWidth}
    />
  );
};

export default TimeRangeDropdown;