import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { 
  Box, 
  Typography, 
  Paper, 
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  SelectChangeEvent,
  CircularProgress,
  Alert,
  Snackbar,
  Tooltip,
  IconButton,
  Card,
  CardContent,
  Fade,
  styled,
  alpha,
  useTheme,
  Stack,
  Badge,
  Avatar
} from '@mui/material';
import { 
  FilterList as FilterIcon,
  Refresh as RefreshIcon,
  FileDownload as ExportIcon,
  Info as InfoIcon,
  Warning as WarningIcon,
  Error as ErrorIcon,
  Security as SecurityIcon,
  History as HistoryIcon,
  TrendingUp as TrendingUpIcon,
  CheckCircle as CheckCircleIcon,
  Schedule as ScheduleIcon,
  Person as PersonIcon,
  Storage as DatabaseIcon,
  MoreVert as MoreVertIcon
} from '@mui/icons-material';
import { logService } from '../../services/api';
import { EnvironmentFilter } from '../../components/common';
import { Environment } from '../../types/environment';

// Styled components
const StyledCard = styled(Card)(({ theme }) => ({
  height: '100%',
  transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
  border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
  boxShadow: `0 4px 20px ${alpha(theme.palette.primary.main, 0.05)}`,
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: `0 8px 30px ${alpha(theme.palette.primary.main, 0.15)}`,
  },
}));

const FilterCard = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(3),
  marginBottom: theme.spacing(3),
  background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.02)} 0%, ${alpha(theme.palette.primary.main, 0.05)} 100%)`,
  border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
  borderRadius: theme.shape.borderRadius * 2,
}));

const StatusChip = styled(Chip)<{ status?: string }>(({ theme, status }) => ({
  fontWeight: 'bold',
  ...(status === 'success' && {
    backgroundColor: alpha(theme.palette.success.main, 0.1),
    color: theme.palette.success.main,
  }),
  ...(status === 'error' && {
    backgroundColor: alpha(theme.palette.error.main, 0.1),
    color: theme.palette.error.main,
  }),
  ...(status === 'warning' && {
    backgroundColor: alpha(theme.palette.warning.main, 0.1),
    color: theme.palette.warning.main,
  }),
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  '&:hover': {
    backgroundColor: alpha(theme.palette.primary.main, 0.02),
  },
  '&:last-child td, &:last-child th': {
    border: 0,
  },
}));

const StyledTableHead = styled(TableHead)(({ theme }) => ({
  backgroundColor: alpha(theme.palette.primary.main, 0.03),
  '& th': {
    fontWeight: 'bold',
    borderBottomWidth: 2,
    borderBottomColor: theme.palette.primary.main,
  },
}));

// Style for input labels to fix black background issue
const labelStyle = {
  backgroundColor: 'background.paper',
  px: 1
};

// Using translations for time ranges
const getTimeRangeOptions = (t: (key: string) => string) => [
  { value: '1h', label: t('timeRanges.1h'), icon: <ScheduleIcon /> },
  { value: '6h', label: t('timeRanges.6h'), icon: <ScheduleIcon /> },
  { value: '12h', label: t('timeRanges.12h'), icon: <ScheduleIcon /> },
  { value: '24h', label: t('timeRanges.24h'), icon: <HistoryIcon /> },
  { value: '7d', label: t('timeRanges.7d'), icon: <HistoryIcon /> },
  { value: '30d', label: t('timeRanges.30d'), icon: <HistoryIcon /> }
];

const getDatabaseOptions = (t: (key: string) => string) => [
  { value: 'all', label: t('common:all') + ' ' + t('databases:title') },
  { value: 'mysql-test', label: 'MySQL Test' },
  { value: 'postgres-test', label: 'PostgreSQL Test' },
  { value: 'mssql-test', label: 'MSSQL Test' }
];

// Using translations for operation types - Updated for audit system
const getOperationOptions = (t: (key: string) => string) => [
  { value: 'all', label: t('operationTypes.all') },
  
  // Authentication operations
  { value: 'LOGIN', label: t('operationTypes.LOGIN') },
  { value: 'LOGOUT', label: t('operationTypes.LOGOUT') },
  { value: 'FAILED_LOGIN', label: t('operationTypes.FAILED_LOGIN') },
  { value: 'PASSWORD_RESET', label: t('operationTypes.PASSWORD_RESET') },
  { value: 'PASSWORD_CHANGE', label: t('operationTypes.PASSWORD_CHANGE') },
  { value: 'MFA_VERIFICATION', label: t('operationTypes.MFA_VERIFICATION') },
  
  // User management operations
  { value: 'USER_CREATED', label: t('operationTypes.CREATE_USER') },
  { value: 'USER_UPDATED', label: t('operationTypes.UPDATE_USER') },
  { value: 'USER_DELETED', label: t('operationTypes.DELETE_USER') },
  { value: 'USER_INVITED', label: t('operationTypes.INVITE_USER') },
  { value: 'USER_ACTIVATED', label: t('operationTypes.USER_ACTIVATION') },
  
  // Permission operations
  { value: 'PERMISSION_CREATED', label: t('operationTypes.CREATE_PERMISSION') },
  { value: 'PERMISSION_UPDATED', label: t('operationTypes.UPDATE_PERMISSION') },
  { value: 'PERMISSION_DELETED', label: t('operationTypes.DELETE_PERMISSION') },
  { value: 'PERMISSION_REVOKED', label: t('operationTypes.REVOKE_PERMISSION') },
  { value: 'PERMISSIONS_BULK_UPDATE', label: t('operationTypes.BULK_PERMISSION_UPDATE') },
  
  // Access request operations
  { value: 'REQUEST_CREATED', label: t('operationTypes.CREATE_REQUEST') },
  { value: 'REQUEST_APPROVED', label: t('operationTypes.APPROVE_REQUEST') },
  { value: 'REQUEST_REJECTED', label: t('operationTypes.REJECT_REQUEST') },
  
  // System configuration operations
  { value: 'CONFIG_UPDATED', label: t('operationTypes.CONFIG_CHANGE') },
  { value: 'SECURITY_CONFIG_UPDATED', label: t('operationTypes.SECURITY_CHANGE') },
  
  // Database operations
  { value: 'DATABASE_ADDED', label: t('operationTypes.ADD_DATABASE') },
  { value: 'DATABASE_UPDATED', label: t('operationTypes.UPDATE_DATABASE') },
  { value: 'DATABASE_REMOVED', label: t('operationTypes.REMOVE_DATABASE') },
  { value: 'DATABASE_SYNC', label: t('operationTypes.SYNC_DATABASE') },
  
  // Data operations
  { value: 'QUERY_EXECUTED', label: t('operationTypes.SELECT') },
  { value: 'SYSTEM_EVENT', label: t('operationTypes.SYSTEM_EVENT') },
  { value: 'AUTHENTICATION_EVENT', label: t('operationTypes.AUTHENTICATION_EVENT') },
  { value: 'OTHER', label: t('operationTypes.OTHER') }
];

const getStatusOptions = (t: (key: string) => string) => [
  { value: 'all', label: t('common:all') },
  { value: 'success', label: t('status.success') },
  { value: 'error', label: t('status.error') }
];

const LogsPage: React.FC = () => {
  const { t } = useTranslation(['logs', 'common', 'databases']);
  const theme = useTheme();
  const [timeRange, setTimeRange] = useState('24h');
  const [database, setDatabase] = useState('all');
  const [user, setUser] = useState('');
  const [operation, setOperation] = useState('all');
  const [status, setStatus] = useState('all');
  const [environmentFilter, setEnvironmentFilter] = useState<Environment | 'all'>('all');
  const [showContent, setShowContent] = useState(false);
  
  // Get options with translations
  const timeRangeOptions = getTimeRangeOptions(t);
  const databaseOptions = getDatabaseOptions(t);
  const operationOptions = getOperationOptions(t);
  const statusOptions = getStatusOptions(t);
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [totalLogs, setTotalLogs] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => setShowContent(true), 100);
    return () => clearTimeout(timer);
  }, []);

  const handleTimeRangeChange = (event: SelectChangeEvent) => {
    setTimeRange(event.target.value);
  };

  const handleDatabaseChange = (event: SelectChangeEvent) => {
    setDatabase(event.target.value);
  };

  const handleUserChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setUser(event.target.value);
  };

  const handleOperationChange = (event: SelectChangeEvent) => {
    setOperation(event.target.value);
  };

  const handleStatusChange = (event: SelectChangeEvent) => {
    setStatus(event.target.value);
  };

  // Função para carregar logs do serviço
  const fetchLogs = async (pageNumber = page) => {
    setLoading(true);
    setError(null);

    try {
      // Preparar parâmetros consistentes com o backend
      const params = {
        timeRange,
        database: database !== 'all' ? database : undefined,
        user: user || undefined,
        operation: operation !== 'all' ? operation : undefined,
        status: status !== 'all' ? status : undefined,
        page: pageNumber,
        pageSize
      };

      // Adicionar log para debug
      console.debug('Buscando logs com parâmetros:', params);

      // Chamar o serviço de logs
      const response = await logService.getLogs(params);

      // Verificar se a resposta contém logs
      if (response && response.logs) {
        setLogs(response.logs);
        setTotalLogs(response.total || 0);
        setPage(response.page || 1);

        if (response.logs.length > 0) {
          setSuccessMessage(t('loadSuccess'));
        } else {
          setError(t('noData'));
        }
      } else {
        setLogs([]);
        setTotalLogs(0);
        setError(t('noData'));
      }
    } catch (error: any) {
      console.error('Error fetching logs:', error);
      const errorMessage = error.response?.data?.message || t('fetchError');
      setError(errorMessage);
      setLogs([]);
      setTotalLogs(0);
    } finally {
      setLoading(false);
    }
  };
  
  // Carregar logs quando o componente monta
  useEffect(() => {
    fetchLogs();
  }, []);
  
  // Resetar para a primeira página ao aplicar filtros
  const handleApplyFilters = () => {
    setPage(1);
    fetchLogs(1);
  };
  
  const handleCloseSnackbar = () => {
    setSuccessMessage(null);
    setError(null);
  };
  
  // Lidar com mudança de página
  const handleChangePage = (_event: React.MouseEvent<HTMLButtonElement> | null, newPage: number) => {
    setPage(newPage + 1); // MUI usa base 0, nossa API usa base 1
    fetchLogs(newPage + 1);
  };
  
  // Lidar com mudança de itens por página
  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newPageSize = parseInt(event.target.value, 10);
    setPageSize(newPageSize);
    setPage(1);
    fetchLogs(1);
  };
  
  // Função para exportar logs
  const handleExportLogs = async () => {
    try {
      setLoading(true);

      // Preparar parâmetros consistentes com o backend
      const params = {
        timeRange,
        database: database !== 'all' ? database : undefined,
        user: user || undefined,
        operation: operation !== 'all' ? operation : undefined,
        status: status !== 'all' ? status : undefined,
        format: 'csv'
      };

      // Log para debug
      console.debug('Exportando logs com parâmetros:', params);

      // Obter blob com os dados CSV
      const blob = await logService.exportLogs(params);

      // Criar URL para download
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `logs-${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();

      // Limpar
      setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }, 100);

      setSuccessMessage(t('export.success'));
    } catch (error) {
      console.error('Error exporting logs:', error);
      setError(t('export.error'));
    } finally {
      setLoading(false);
    }
  };

  const getOperationIcon = (operationType: string) => {
    if (operationType?.includes('USER_')) return <PersonIcon />;
    if (operationType?.includes('PERMISSION_')) return <SecurityIcon />;
    if (operationType?.includes('DATABASE_')) return <DatabaseIcon />;
    if (operationType?.includes('LOGIN') || operationType?.includes('LOGOUT')) return <PersonIcon />;
    if (operationType?.includes('CONFIG_')) return <SecurityIcon />;
    return <InfoIcon />;
  };

  const getOperationColor = (operationType: string): "default" | "primary" | "secondary" | "error" | "info" | "success" | "warning" => {
    if (operationType?.includes('PERMISSION_')) return 'primary';
    if (operationType?.includes('USER_')) return 'success';
    if (operationType === 'LOGIN' || operationType === 'LOGOUT') return 'default';
    if (operationType?.includes('FAILED_')) return 'error';
    if (operationType?.includes('CONFIG_')) return 'secondary';
    if (operationType?.includes('DATABASE_')) return 'info';
    if (operationType?.includes('REQUEST_')) return 'warning';
    return 'default';
  };

  return (
    <Fade in={showContent} timeout={800}>
      <Box>
        <Snackbar
          open={!!successMessage}
          autoHideDuration={3000}
          onClose={handleCloseSnackbar}
          anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
        >
          <Alert onClose={handleCloseSnackbar} severity="success" sx={{ width: '100%' }}>
            {successMessage}
          </Alert>
        </Snackbar>

        <Snackbar
          open={!!error}
          autoHideDuration={5000}
          onClose={handleCloseSnackbar}
          anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
        >
          <Alert onClose={handleCloseSnackbar} severity="error" sx={{ width: '100%' }}>
            {error}
          </Alert>
        </Snackbar>

        <Box mb={4}>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={1}>
            <Box>
              <Typography variant="h4" fontWeight="bold" gutterBottom>
                {t('title')}
              </Typography>
              <Typography variant="body1" color="text.secondary">
                {t('description')}
              </Typography>
            </Box>
            <Stack direction="row" spacing={1}>
              <Badge badgeContent={totalLogs} color="primary" max={999}>
                <Button
                  variant="outlined"
                  startIcon={<RefreshIcon />}
                  onClick={() => fetchLogs(page)}
                  disabled={loading}
                >
                  {t('common:refresh')}
                </Button>
              </Badge>
              <Tooltip title={t('export.button')}>
                <span>
                  <Button
                    variant="contained"
                    startIcon={<ExportIcon />}
                    onClick={handleExportLogs}
                    disabled={loading || logs.length === 0}
                  >
                    {t('export.button')}
                  </Button>
                </span>
              </Tooltip>
            </Stack>
          </Box>
        </Box>

        <FilterCard elevation={0}>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
            <Typography variant="h6" fontWeight="medium">
              {t('filters.title')}
            </Typography>
            <IconButton size="small">
              <MoreVertIcon />
            </IconButton>
          </Box>
          <Grid container spacing={2} alignItems="flex-end">
            <Grid item xs={12} md={2}>
              <FormControl fullWidth variant="outlined">
                <InputLabel
                  id="time-range-label"
                  sx={labelStyle}
                >
                  {t('filters.timeRange')}
                </InputLabel>
                <Select
                  labelId="time-range-label"
                  id="time-range"
                  value={timeRange}
                  label={t('filters.timeRange')}
                  onChange={handleTimeRangeChange}
                >
                  {timeRangeOptions.map(option => (
                    <MenuItem key={option.value} value={option.value}>
                      <Box display="flex" alignItems="center" gap={1}>
                        {option.icon}
                        {t(`timeRanges.${option.value}`)}
                      </Box>
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={3}>
              <TextField
                fullWidth
                variant="outlined"
                label={t('filters.user')}
                value={user}
                onChange={handleUserChange}
                placeholder="Filtrar por nome de usuário"
                InputProps={{
                  startAdornment: <PersonIcon sx={{ mr: 1, color: 'text.secondary' }} />,
                }}
                InputLabelProps={{
                  sx: labelStyle
                }}
              />
            </Grid>
            <Grid item xs={12} md={3}>
              <FormControl fullWidth variant="outlined">
                <InputLabel
                  id="operation-label"
                  sx={labelStyle}
                >
                  {t('filters.operation')}
                </InputLabel>
                <Select
                  labelId="operation-label"
                  id="operation"
                  value={operation}
                  label={t('filters.operation')}
                  onChange={handleOperationChange}
                >
                  {operationOptions.map(option => (
                    <MenuItem key={option.value} value={option.value}>
                      {t(`operationTypes.${option.value}`)}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={2}>
              <EnvironmentFilter
                value={environmentFilter}
                onChange={setEnvironmentFilter}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <Stack direction="row" spacing={1}>
                <Button
                  variant="contained"
                  startIcon={<FilterIcon />}
                  onClick={handleApplyFilters}
                  sx={{ flexGrow: 1 }}
                  size="large"
                >
                  {t('filters.applyButton')}
                </Button>
                <Button
                  variant="outlined"
                  onClick={() => {
                    setTimeRange('24h');
                    setUser('');
                    setOperation('all');
                    setStatus('all');
                    setDatabase('all');
                    setEnvironmentFilter('all');
                  }}
                  size="large"
                >
                  {t('filters.clear')}
                </Button>
              </Stack>
            </Grid>
          </Grid>
        </FilterCard>

        <StyledCard>
          {loading ? (
            <Box display="flex" justifyContent="center" alignItems="center" p={8}>
              <Box textAlign="center">
                <CircularProgress size={60} thickness={4} />
                <Typography variant="h6" color="text.secondary" sx={{ mt: 2 }}>
                  {t('loading')}
                </Typography>
              </Box>
            </Box>
          ) : logs.length === 0 ? (
            <Box p={8} textAlign="center">
              <InfoIcon sx={{ fontSize: 64, color: 'text.disabled', mb: 2 }} />
              <Typography variant="h6" color="text.secondary" gutterBottom>
                {t('common:noData')}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {t('noDataDescription')}
              </Typography>
            </Box>
          ) : (
            <>
              <TableContainer>
                <Table>
                  <StyledTableHead>
                    <TableRow>
                      <TableCell>{t('table.timestamp')}</TableCell>
                      <TableCell>{t('table.user')}</TableCell>
                      <TableCell>{t('table.operation')}</TableCell>
                      <TableCell>{t('table.details')}</TableCell>
                      <TableCell>{t('table.resource')}</TableCell>
                      <TableCell align="center">{t('table.status')}</TableCell>
                      <TableCell>{t('table.clientIp')}</TableCell>
                    </TableRow>
                  </StyledTableHead>
                  <TableBody>
                    {Array.isArray(logs) ? logs.map((log) => (
                      <StyledTableRow key={log?.id || Math.random().toString(36).substring(7)} hover>
                        <TableCell>
                          <Box>
                            <Typography variant="body2" fontWeight="medium">
                              {log?.timestamp ? 
                                (typeof log.timestamp === 'string' ? 
                                  new Date(log.timestamp).toLocaleDateString() : 
                                  new Date(log.timestamp).toLocaleDateString()) 
                                : 'N/A'}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {log?.timestamp ? 
                                (typeof log.timestamp === 'string' ? 
                                  new Date(log.timestamp).toLocaleTimeString() : 
                                  new Date(log.timestamp).toLocaleTimeString()) 
                                : 'N/A'}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell>
                          <Box display="flex" alignItems="center" gap={1}>
                            <Avatar sx={{ width: 32, height: 32, bgcolor: alpha(theme.palette.primary.main, 0.1) }}>
                              <PersonIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                            </Avatar>
                            <Typography variant="body2" fontWeight="medium">
                              {log?.username || log?.user_display_name || log?.user || 'System'}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            {/* Add icon based on severity */}
                            {log?.severity === 'error' ? (
                              <ErrorIcon color="error" fontSize="small" />
                            ) : log?.severity === 'warning' ? (
                              <WarningIcon color="warning" fontSize="small" />
                            ) : log?.severity === 'critical' ? (
                              <SecurityIcon color="error" fontSize="small" />
                            ) : (
                              getOperationIcon(log?.operationType || log?.operation_type)
                            )}
                            
                            <Chip
                              label={log?.operationType || log?.operation_type || 'Unknown'}
                              color={getOperationColor(log?.operationType || log?.operation_type)}
                              size="small"
                              sx={{ fontWeight: 'medium' }}
                            />
                          </Box>
                        </TableCell>
                        <TableCell sx={{ maxWidth: 300 }}>
                          <Tooltip 
                            title={
                              <Box sx={{ whiteSpace: 'pre-wrap' }}>
                                <Typography variant="body2" paragraph>
                                  {log?.command || log?.message || 'No message'}
                                </Typography>
                                {log?.details && Object.keys(log.details).length > 0 && (
                                  <Typography variant="caption">
                                    Details: {JSON.stringify(log.details, null, 2)}
                                  </Typography>
                                )}
                              </Box>
                            }
                            placement="top"
                          >
                            <Typography 
                              variant="body2" 
                              sx={{ 
                                overflow: 'hidden', 
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap',
                                cursor: 'pointer'
                              }}
                            >
                              {log?.command || log?.message ||
                               (log?.details ?
                                  Object.keys(log.details)
                                    .filter(k => typeof log.details[k] !== 'object')
                                    .map(k => `${k}: ${log.details[k]}`)
                                    .join(', ') :
                                  'No details available')}
                            </Typography>
                          </Tooltip>
                        </TableCell>
                        <TableCell>
                          <Box display="flex" alignItems="center" gap={1}>
                            <DatabaseIcon sx={{ fontSize: 18, color: 'text.secondary' }} />
                            <Typography variant="body2">
                              {log?.resource_display_name || log?.resource || log?.database || (log?.Details?.database) || (log?.details?.database) || 'N/A'}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell align="center">
                          <StatusChip
                            label={log?.status || 'Unknown'}
                            status={log?.status}
                            size="small"
                          />
                        </TableCell>
                        <TableCell>
                          <Typography variant="body2" color="text.secondary">
                            {log?.clientIp || log?.client_ip || 'Unknown'}
                          </Typography>
                        </TableCell>
                      </StyledTableRow>
                    )) : (
                      <TableRow>
                        <TableCell colSpan={7} align="center">
                          <Typography variant="body1" color="text.secondary">
                            {t('common:noData')}
                          </Typography>
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
              <TablePagination
                component="div"
                count={totalLogs}
                page={page - 1} // MUI usa base 0
                onPageChange={handleChangePage}
                rowsPerPage={pageSize}
                onRowsPerPageChange={handleChangeRowsPerPage}
                rowsPerPageOptions={[10, 20, 50, 100]}
                labelRowsPerPage={t('common:rowsPerPage')}
                labelDisplayedRows={({ from, to, count }) => 
                  `${from}-${to} ${t('common:of')} ${count}`
                }
                sx={{
                  borderTop: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
                  backgroundColor: alpha(theme.palette.primary.main, 0.02),
                }}
              />
            </>
          )}
        </StyledCard>
      </Box>
    </Fade>
  );
};

export default LogsPage;
