import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  Avatar,
  Typography,
  Divider,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Snackbar,
  Alert,
  Box,
  useTheme,
  alpha,
  Tooltip,
  IconButton,
  Slider,
  Select,
  MenuItem,
  InputLabel,
  FormControl
} from '@mui/material';
import {
  Sync as SyncIcon,
  Save as SaveIcon,
  Refresh as RefreshIcon,
  PlayArrow as StartIcon,
  Info as InfoIcon,
  Check as CheckIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Timer as TimerIcon,
  Repeat as RepeatIcon,
  Notifications as NotificationIcon
} from '@mui/icons-material';

import { configurationService, databaseService } from '../../services/api';
import syncService from '../../services/syncService';

interface SyncConfig {
  enabled: boolean;
  interval: number;
  retryCount: number;
  autoCorrect: boolean;
  autoRemoveUsers: boolean;
  notifyOnDiscrepancy: boolean;
  notifyOnUnmanaged: boolean;
  notificationEmail: string;
}

interface Database {
  id: string;
  name: string;
  type: string;
}

const SyncConfigPanelEnhanced: React.FC = () => {
  const { t, i18n, ready } = useTranslation(['syncconfig', 'common']);
  const theme = useTheme();
  

  // Estado para configuração de sincronização
  const [syncConfig, setSyncConfig] = useState<SyncConfig>({
    enabled: false,
    interval: 60,
    retryCount: 3,
    autoCorrect: false,
    autoRemoveUsers: false,
    notifyOnDiscrepancy: true,
    notifyOnUnmanaged: true,
    notificationEmail: ""
  });

  // Estado para controle do painel
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [triggerSyncOpen, setTriggerSyncOpen] = useState(false);
  const [selectedDatabase, setSelectedDatabase] = useState<string>("");
  const [syncDirection, setSyncDirection] = useState<string>("both");
  const [triggeringSync, setTriggeringSync] = useState(false);
  const [databases, setDatabases] = useState<Database[]>([]);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);

  // Verificar se SMTP está configurado (para notificações)
  const checkSMTPConfiguration = async () => {
    try {
      return await configurationService.isSMTPConfigured();
    } catch (error) {
      console.error('Erro ao verificar configuração SMTP:', error);
      return false;
    }
  };

  // Carrega as configurações de sincronização iniciais
  useEffect(() => {
    // Limpar cache antes de buscar dados
    syncService.resetCache();
    fetchSyncConfig();
    fetchDatabases();
  }, []);

  // Obtém as configurações de sincronização do servidor
  const fetchSyncConfig = async () => {
    setLoading(true);
    try {
      console.log('COMPONENTE - Buscando configuração de sincronização...');
      const response = await syncService.getSyncConfig();
      console.log('COMPONENTE - Resposta recebida:', response);
      
      if (response && response.config) {
        console.log('COMPONENTE - Configuração recebida:', response.config);
        console.log('COMPONENTE - Email recebido:', response.config.notificationEmail);
        setSyncConfig(response.config);
        setHasChanges(false);
      } else {
        console.warn('COMPONENTE - Resposta sem campo config válido');
      }
    } catch (error) {
      console.error('Erro ao buscar configuração de sincronização:', error);
      setErrorMessage(t('errors.loadError'));
    } finally {
      setLoading(false);
    }
  };

  // Obtém a lista de bancos de dados para sincronização
  const fetchDatabases = async () => {
    try {
      const response = await databaseService.getDatabases();
      if (response && Array.isArray(response.databases)) {
        setDatabases(response.databases.map((db: any) => ({
          id: db.id,
          name: db.name,
          type: db.type
        })));
      } else {
        // Fallback para dados simulados se a API falhar
        setDatabases([
          { id: "1", name: "Production Database", type: "postgresql" },
          { id: "2", name: "Development Database", type: "mysql" }
        ]);
      }
    } catch (error) {
      console.error('Erro ao buscar bancos de dados:', error);
      // Fallback para dados simulados em caso de erro
      setDatabases([
        { id: "1", name: "Production Database", type: "postgresql" },
        { id: "2", name: "Development Database", type: "mysql" }
      ]);
    }
  };

  // Salva a configuração de sincronização
  const handleSaveSyncConfig = async () => {
    setSaving(true);
    setErrorMessage(null);
    
    try {
      // Validar campos obrigatórios
      if (syncConfig.interval <= 0) {
        setErrorMessage(t('errors.intervalRequired'));
        setSaving(false);
        return;
      }
      
      if (syncConfig.retryCount <= 0) {
        setErrorMessage(t('errors.retryCountRequired'));
        setSaving(false);
        return;
      }
      
      // Log para depuração antes de enviar
      console.log('COMPONENTE - Config a ser salva:', syncConfig);
      console.log('COMPONENTE - Email a ser salvo:', syncConfig.notificationEmail);
      
      // Criar uma cópia do objeto para garantir que temos tanto o campo em camelCase quanto em snake_case
      const configToSave = { ...syncConfig };
      
      // O backend agora usa camelCase, não é mais necessário converter
      
      // Envia a configuração para o servidor
      const response = await syncService.updateSyncConfig(configToSave);
      
      console.log('Resposta ao salvar configuração de sincronização:', response);
      
      // Atualizar o estado local com os dados da resposta (para garantir consistência)
      if (response && response.config) {
        // Mapear campo de email da resposta se necessário
        if (response.config.notification_email !== undefined && response.config.notificationEmail === undefined) {
          response.config.notificationEmail = response.config.notification_email;
        }
        
        setSyncConfig(response.config);
      }
      
      setSuccessMessage(t('success.saved'));
      setHasChanges(false);
    } catch (error) {
      console.error('Erro ao salvar configuração de sincronização:', error);
      setErrorMessage(t('errors.saveError'));
    } finally {
      setSaving(false);
    }
  };

  // Inicia manualmente um processo de sincronização
  const handleTriggerSync = async () => {
    if (!selectedDatabase) {
      setErrorMessage(t('errors.databaseRequired'));
      return;
    }

    setTriggeringSync(true);
    try {
      // Enviar solicitação de sincronização
      const response = await syncService.triggerSync(selectedDatabase, syncDirection);
      
      setSuccessMessage(t('success.triggered'));
      setTriggerSyncOpen(false);
      setSelectedDatabase("");
      setSyncDirection("both");
    } catch (error) {
      console.error('Erro ao iniciar sincronização:', error);
      setErrorMessage(t('errors.triggerError'));
    } finally {
      setTriggeringSync(false);
    }
  };

  // Manipula mudanças nos campos numéricos
  const handleNumberChange = (field: keyof SyncConfig, value: number) => {
    setSyncConfig(prev => ({
      ...prev,
      [field]: value
    }));
    setHasChanges(true);
  };

  // Manipula mudanças nos toggles
  const handleToggleChange = (field: keyof SyncConfig, checked: boolean) => {
    setSyncConfig(prev => ({
      ...prev,
      [field]: checked
    }));
    setHasChanges(true);
  };

  // Renderiza o slider de intervalo
  const renderIntervalSlider = () => {
    const marks = [
      { value: 1, label: '1m' },
      { value: 5, label: '5m' },
      { value: 15, label: '15m' },
      { value: 30, label: '30m' },
      { value: 60, label: '1h' }
    ];

    return (
      <Box sx={{ width: '100%', mt: 3, mb: 1 }}>
        <Typography gutterBottom variant="body2" sx={{ display: 'flex', alignItems: 'center' }}>
          <TimerIcon fontSize="small" sx={{ mr: 1, color: theme.palette.text.secondary }} />
          {t('settings.interval')}
        </Typography>
        <Box sx={{ px: 2 }}>
          <Slider
            value={syncConfig.interval}
            min={1}
            max={60}
            step={null}
            marks={marks}
            valueLabelDisplay="auto"
            valueLabelFormat={(value) => {
              if (value < 60) return t('intervals.minutes', { value });
              return t('intervals.hours', { value: value / 60 });
            }}
            onChange={(_, value) => handleNumberChange('interval', value as number)}
            disabled={!syncConfig.enabled}
          />
        </Box>
      </Box>
    );
  };

  // Aguardar o carregamento das traduções
  if (!ready) {
    return (
      <Box display="flex" justifyContent="center" p={4}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Card sx={{ 
      borderRadius: 2, 
      mb: 3, 
      boxShadow: 2,
      overflow: 'hidden',
      transition: 'box-shadow 0.3s ease-in-out',
      '&:hover': {
        boxShadow: 5
      }
    }}>
      <CardHeader
        avatar={
          <Avatar sx={{ 
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            width: 48,
            height: 48
          }}>
            <SyncIcon />
          </Avatar>
        }
        title={
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            {t('title')}
          </Typography>
        }
        subheader={t('description')}
        action={
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<RefreshIcon />}
              onClick={fetchSyncConfig}
              disabled={loading}
              sx={{ borderRadius: 8 }}
            >
              {t('common:refresh')}
            </Button>
            <Button
              variant="contained"
              size="small"
              startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
              onClick={handleSaveSyncConfig}
              disabled={saving || !hasChanges}
              sx={{ 
                borderRadius: 8,
                fontWeight: 'bold',
                color: 'white'
              }}
            >
              {t('common:save')}
            </Button>
          </Box>
        }
      />
      <Divider />
      <CardContent sx={{ p: 3 }}>
        {errorMessage && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setErrorMessage(null)}>
            {errorMessage}
          </Alert>
        )}
        
        {/* Aviso de modificação temporária */}
        <Alert severity="warning" sx={{ mb: 3 }}>
          {t('alerts.smtpWarning')}
        </Alert>
        
        {loading ? (
          <Box display="flex" justifyContent="center" p={4}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            <Box sx={{ mb: 3 }}>
              <FormControlLabel
                control={
                  <Switch
                    checked={syncConfig.enabled}
                    onChange={(e) => handleToggleChange('enabled', e.target.checked)}
                  />
                }
                label={
                  <Box display="flex" alignItems="center">
                    <Typography fontWeight="medium">
                      {t('settings.enabled')}
                    </Typography>
                    <Tooltip title={t('settings.enabledDescription')}>
                      <IconButton size="small">
                        <InfoIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                }
              />
            </Box>
            
            {syncConfig.enabled && (
              <>
                {renderIntervalSlider()}
                
                <Grid container spacing={2} sx={{ mt: 2 }}>
                  <Grid item xs={12} md={4}>
                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                      <RepeatIcon fontSize="small" sx={{ mr: 1, color: theme.palette.text.secondary }} />
                      <Typography variant="body2">
                        {t('settings.retryCount')}
                      </Typography>
                    </Box>
                    <TextField
                      fullWidth
                      type="number"
                      InputProps={{ inputProps: { min: 1, max: 10 } }}
                      value={syncConfig.retryCount}
                      onChange={(e) => handleNumberChange('retryCount', parseInt(e.target.value))}
                      variant="outlined"
                      size="small"
                      disabled={!syncConfig.enabled}
                      helperText={t('settings.retryCountDescription')}
                    />
                  </Grid>
                  
                  <Grid item xs={12} md={8}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={syncConfig.autoCorrect}
                          onChange={(e) => handleToggleChange('autoCorrect', e.target.checked)}
                          disabled={!syncConfig.enabled}
                        />
                      }
                      label={
                        <Box display="flex" alignItems="center">
                          <Typography>
                            {t('settings.autoCorrect')}
                          </Typography>
                          <Tooltip title={t('settings.autoCorrectDescription')}>
                            <IconButton size="small">
                              <InfoIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      }
                    />
                    
                    {/* AutoRemoveUsers toggle with warning */}
                    <Box sx={{ mt: 2 }}>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={syncConfig.autoRemoveUsers}
                            onChange={(e) => handleToggleChange('autoRemoveUsers', e.target.checked)}
                            disabled={!syncConfig.enabled || !syncConfig.autoCorrect}
                            color="warning"
                          />
                        }
                        label={
                          <Box display="flex" alignItems="center">
                            <Typography>
                              {t('settings.autoRemoveUsers')}
                            </Typography>
                            <Tooltip title={t('settings.autoRemoveUsersDescription')}>
                              <IconButton size="small">
                                <InfoIcon fontSize="small" />
                              </IconButton>
                            </Tooltip>
                          </Box>
                        }
                      />
                      {syncConfig.autoRemoveUsers && (
                        <Alert severity="warning" sx={{ mt: 1, mb: 1 }}>
                          <Typography variant="body2">
                            {t('settings.autoRemoveUsersWarning')}
                          </Typography>
                        </Alert>
                      )}
                    </Box>
                  </Grid>
                </Grid>
                
                <Typography variant="subtitle2" sx={{ mt: 4, mb: 2 }}>
                  {t('notificationSettings')}
                </Typography>
                
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={syncConfig.notifyOnDiscrepancy}
                          onChange={(e) => {
                            // Modificado: Removida a verificação de SMTP temporariamente
                            handleToggleChange('notifyOnDiscrepancy', e.target.checked);
                            if (e.target.checked) {
                              console.log('Aviso: Ativando notificações sem verificar configuração SMTP');
                            }
                          }}
                          disabled={!syncConfig.enabled}
                        />
                      }
                      label={
                        <Box display="flex" alignItems="center">
                          <Typography>
                            {t('settings.notifyOnDiscrepancy')}
                          </Typography>
                          <Tooltip title={t('settings.notifyOnDiscrepancyDescription')}>
                            <IconButton size="small">
                              <InfoIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      }
                    />
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={syncConfig.notifyOnUnmanaged}
                          onChange={(e) => {
                            // Modificado: Removida a verificação de SMTP temporariamente
                            handleToggleChange('notifyOnUnmanaged', e.target.checked);
                            if (e.target.checked) {
                              console.log('Aviso: Ativando notificações sem verificar configuração SMTP');
                            }
                          }}
                          disabled={!syncConfig.enabled}
                        />
                      }
                      label={
                        <Box display="flex" alignItems="center">
                          <Typography>
                            {t('settings.notifyOnUnmanaged')}
                          </Typography>
                          <Tooltip title={t('settings.notifyOnUnmanagedDescription')}>
                            <IconButton size="small">
                              <InfoIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      }
                    />
                  </Grid>
                  
                  {/* Campo de e-mail para notificações */}
                  {(syncConfig.notifyOnDiscrepancy || syncConfig.notifyOnUnmanaged) && (
                    <Grid item xs={12}>
                      <Box sx={{ mt: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                          <NotificationIcon fontSize="small" sx={{ mr: 1, color: theme.palette.text.secondary }} />
                          <Typography variant="body2">
                            {t('settings.notificationEmail')}
                          </Typography>
                          <Tooltip title={t('settings.notificationEmailDescription')}>
                            <IconButton size="small">
                              <InfoIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                        <TextField
                          fullWidth
                          type="email"
                          value={syncConfig.notificationEmail || ""}
                          onChange={(e) => {
                            // Modificado: Removida a verificação de SMTP temporariamente
                            setSyncConfig(prev => ({
                              ...prev,
                              notificationEmail: e.target.value
                            }));
                            setHasChanges(true);
                            console.log('COMPONENTE - Email atualizado para:', e.target.value);
                          }}
                          variant="outlined"
                          size="small"
                          disabled={!syncConfig.enabled}
                          placeholder={t('settings.notificationEmailPlaceholder') as string}
                          helperText={t('settings.notificationEmailHelp')}
                          InputLabelProps={{ shrink: true }}
                          sx={{ mt: 1 }}
                        />
                      </Box>
                    </Grid>
                  )}
                </Grid>
              </>
            )}
            
            <Box sx={{ mt: 4, display: 'flex', justifyContent: 'center' }}>
              <Button
                variant="contained"
                color="primary"
                startIcon={<StartIcon />}
                onClick={() => setTriggerSyncOpen(true)}
                sx={{
                  borderRadius: 8,
                  px: 3,
                  py: 1,
                  fontWeight: 'bold',
                  boxShadow: 3
                }}
              >
                {t('triggerSync')}
              </Button>
            </Box>
            
            {!syncConfig.enabled && (
              <Alert severity="warning" sx={{ mt: 3 }}>
                {t('enabledRequired')}
              </Alert>
            )}
          </>
        )}
      </CardContent>

      {/* Diálogo para iniciar sincronização manual */}
      <Dialog open={triggerSyncOpen} onClose={() => setTriggerSyncOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ 
          bgcolor: theme.palette.primary.main, 
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          pb: 2
        }}>
          <SyncIcon />
          {t('triggerSyncDialog.title')}
        </DialogTitle>
        <DialogContent sx={{ pt: 3 }}>
          <Typography variant="body1" paragraph>
            {t('triggerSyncDialog.message')}
          </Typography>
          
          <FormControl fullWidth variant="outlined" sx={{ mb: 3 }}>
            <InputLabel>{t('triggerSyncDialog.database')}</InputLabel>
            <Select
              value={selectedDatabase}
              onChange={(e) => setSelectedDatabase(e.target.value)}
              label={t('triggerSyncDialog.database')}
            >
              <MenuItem value="">
                <em>{t('common:select')}</em>
              </MenuItem>
              {databases.map(db => (
                <MenuItem key={db.id} value={db.id}>{db.name} ({db.type})</MenuItem>
              ))}
            </Select>
          </FormControl>
          
          <FormControl fullWidth variant="outlined">
            <InputLabel>{t('triggerSyncDialog.direction')}</InputLabel>
            <Select
              value={syncDirection}
              onChange={(e) => setSyncDirection(e.target.value)}
              label={t('triggerSyncDialog.direction')}
            >
              <MenuItem value="both">{t('directions.both')}</MenuItem>
              <MenuItem value="import">{t('directions.import')}</MenuItem>
              <MenuItem value="export">{t('directions.export')}</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 3 }}>
          <Button onClick={() => setTriggerSyncOpen(false)} color="inherit">
            {t('common:cancel')}
          </Button>
          <Button 
            onClick={handleTriggerSync} 
            color="primary" 
            variant="contained"
            disabled={triggeringSync || !selectedDatabase}
            startIcon={triggeringSync ? <CircularProgress size={20} /> : <StartIcon />}
            sx={{ 
              fontWeight: 'bold',
              borderRadius: 6,
              px: 2
            }}
          >
            {t('triggerSyncDialog.start')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notificação de sucesso */}
      <Snackbar 
        open={!!successMessage} 
        autoHideDuration={6000} 
        onClose={() => setSuccessMessage(null)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>
    </Card>
  );
};

export default SyncConfigPanelEnhanced;