import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  Avatar,
  Typography,
  Divider,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Snackbar,
  Alert,
  Box,
  useTheme,
  alpha,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  FormHelperText,
  IconButton,
  Tooltip
} from '@mui/material';
import {
  VerifiedUser as VerifiedUserIcon,
  Save as SaveIcon,
  Refresh as RefreshIcon,
  Google as GoogleIcon,
  Microsoft as MicrosoftIcon,
  Help as HelpIcon,
  Info as InfoIcon
} from '@mui/icons-material';

import { configurationService } from '../../services/api';

interface SSOConfig {
  enabled: boolean;
  provider: string;
  clientId: string;
  clientSecret: string;
  domain: string;
  tenantId: string;
  validateBeforeAccess: boolean;
}

const SSOConfigPanel: React.FC = () => {
  const { t } = useTranslation(['settings', 'common']);
  const theme = useTheme();

  // Estado para configuração SSO
  const [ssoConfig, setSSOConfig] = useState<SSOConfig>({
    enabled: false,
    provider: 'google',
    clientId: '',
    clientSecret: '',
    domain: '',
    tenantId: '',
    validateBeforeAccess: true
  });

  // Estado para controle do painel
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);
  // showHelp state removido - não utilizado

  // Carrega as configurações SSO iniciais
  useEffect(() => {
    fetchSSOConfig();
  }, []);

  // Obtém as configurações SSO do servidor
  const fetchSSOConfig = async () => {
    setLoading(true);
    try {
      const response = await configurationService.getConfiguration('sso');
      console.log('SSO config response:', response);
      
      if (response && response.ssoProviders) {
        setSSOConfig(response.ssoProviders);
        setHasChanges(false);
      }
    } catch (error) {
      console.error('Erro ao buscar configuração SSO:', error);
      setErrorMessage('Erro ao carregar configurações de SSO');
    } finally {
      setLoading(false);
    }
  };

  // Salva a configuração SSO
  const handleSaveSSOConfig = async () => {
    setSaving(true);
    setErrorMessage(null);
    
    try {
      // Validar campos obrigatórios conforme o provedor
      if (ssoConfig.enabled) {
        if (!ssoConfig.clientId) {
          setErrorMessage('O Client ID é obrigatório');
          setSaving(false);
          return;
        }
        
        if (!ssoConfig.clientSecret) {
          setErrorMessage('O Client Secret é obrigatório');
          setSaving(false);
          return;
        }
        
        if (ssoConfig.provider === 'google' && !ssoConfig.domain) {
          setErrorMessage('O Domínio é obrigatório para o Google Workspace');
          setSaving(false);
          return;
        }
        
        if (ssoConfig.provider === 'microsoft' && !ssoConfig.tenantId) {
          setErrorMessage('O Tenant ID é obrigatório para o Microsoft Entra ID');
          setSaving(false);
          return;
        }
      }
      
      // Envia a configuração para o servidor
      const response = await configurationService.updateConfiguration({ ssoProviders: ssoConfig });
      
      console.log('Resposta ao salvar configuração SSO:', response);
      setSuccessMessage('Configuração SSO salva com sucesso');
      setHasChanges(false);
    } catch (error) {
      console.error('Erro ao salvar configuração SSO:', error);
      setErrorMessage('Erro ao salvar configuração SSO');
    } finally {
      setSaving(false);
    }
  };

  // Manipula mudanças nos campos de texto
  const handleTextChange = (field: keyof SSOConfig, value: string) => {
    setSSOConfig(prev => ({
      ...prev,
      [field]: value
    }));
    setHasChanges(true);
  };

  // Manipula mudanças nos toggles
  const handleToggleChange = (field: keyof SSOConfig, checked: boolean) => {
    setSSOConfig(prev => ({
      ...prev,
      [field]: checked
    }));
    setHasChanges(true);
  };

  // Manipula mudanças no seletor de provedor
  const handleProviderChange = (provider: string) => {
    setSSOConfig(prev => ({
      ...prev,
      provider
    }));
    setHasChanges(true);
  };

  // Obter ícone do provedor
  const getProviderIcon = () => {
    if (ssoConfig.provider === 'microsoft') {
      return <MicrosoftIcon />;
    }
    return <GoogleIcon />;
  };

  return (
    <Card sx={{ 
      borderRadius: 2, 
      mb: 3, 
      boxShadow: 2,
      overflow: 'hidden',
      transition: 'box-shadow 0.3s ease-in-out',
      '&:hover': {
        boxShadow: 5
      }
    }}>
      <CardHeader
        avatar={
          <Avatar sx={{ 
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            width: 48,
            height: 48
          }}>
            <VerifiedUserIcon />
          </Avatar>
        }
        title={
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            {t('sections.ssoProviders.title', 'Configuração SSO')}
          </Typography>
        }
        subheader={t('sections.ssoProviders.description', 'Configure Single Sign-On para autenticação empresarial')}
        action={
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<RefreshIcon />}
              onClick={fetchSSOConfig}
              disabled={loading}
              sx={{ borderRadius: 8 }}
            >
              {t('common:refresh', 'Atualizar')}
            </Button>
            <Button
              variant="contained"
              size="small"
              startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
              onClick={handleSaveSSOConfig}
              disabled={saving || !hasChanges}
              sx={{ 
                borderRadius: 8,
                fontWeight: 'bold',
                color: 'white'
              }}
            >
              {t('common:save', 'Salvar')}
            </Button>
          </Box>
        }
      />
      <Divider />
      <CardContent sx={{ p: 3 }}>
        {errorMessage && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setErrorMessage(null)}>
            {errorMessage}
          </Alert>
        )}
        
        {loading ? (
          <Box display="flex" justifyContent="center" p={4}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            <Box sx={{ mb: 3 }}>
              <FormControlLabel
                control={
                  <Switch
                    checked={ssoConfig.enabled}
                    onChange={(e) => handleToggleChange('enabled', e.target.checked)}
                  />
                }
                label={
                  <Box display="flex" alignItems="center">
                    <Typography fontWeight="medium">
                      {t('sections.ssoProviders.enabled', 'Habilitar SSO')}
                    </Typography>
                    <Tooltip title={t('sections.ssoProviders.settings.enabledHelpText', 'Habilite o Single Sign-On para permitir que os usuários façam login com suas credenciais corporativas')}>
                      <IconButton size="small">
                        <HelpIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                }
              />
            </Box>
            
            <Divider sx={{ my: 3 }} />
            
            <Typography variant="subtitle2" gutterBottom>
              {t('sections.ssoProviders.providerSettings', 'Configurações do Provedor')}
            </Typography>
            
            {/* Informação da URL de Callback */}
            {ssoConfig.enabled && (
              <Alert severity="info" sx={{ mb: 3, mt: 2 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                  URL de Callback/Redirect URI
                </Typography>
                <Typography variant="body2" sx={{ mb: 1 }}>
                  Configure esta URL no seu provedor de SSO:
                </Typography>
                <Box sx={{ 
                  backgroundColor: theme.palette.grey[100], 
                  p: 1.5, 
                  borderRadius: 1,
                  fontFamily: 'monospace',
                  fontSize: '0.875rem',
                  wordBreak: 'break-all'
                }}>
                  {`${window.location.origin}/api/auth/sso/${ssoConfig.provider}/callback`}
                </Box>
                {ssoConfig.provider === 'google' && (
                  <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
                    {t('sections.ssoProviders.googleCallbackHint', 
                      'No Google Cloud Console, adicione esta URL em "Authorized redirect URIs"')}
                  </Typography>
                )}
                {ssoConfig.provider === 'microsoft' && (
                  <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
                    {t('sections.ssoProviders.microsoftCallbackHint', 
                      'No Azure AD, adicione esta URL em "Redirect URIs" do tipo "Web"')}
                  </Typography>
                )}
              </Alert>
            )}
            
            <Grid container spacing={2} sx={{ mb: 3 }}>
              <Grid item xs={12} md={12}>
                <FormControl fullWidth variant="outlined" size="small">
                  <InputLabel>
                    {t('sections.ssoProviders.settings.provider', 'Provedor')}
                  </InputLabel>
                  <Select
                    value={ssoConfig.provider}
                    onChange={(e) => handleProviderChange(e.target.value)}
                    label={t('sections.ssoProviders.settings.provider', 'Provedor')}
                    disabled={!ssoConfig.enabled}
                    startAdornment={
                      <Box component="span" sx={{ mr: 1, display: 'flex', alignItems: 'center' }}>
                        {getProviderIcon()}
                      </Box>
                    }
                  >
                    <MenuItem value="google">Google Workspace</MenuItem>
                    <MenuItem value="microsoft">Microsoft Entra ID</MenuItem>
                  </Select>
                  <FormHelperText>
                    {t('sections.ssoProviders.settings.providerDescription', 'Selecione o provedor de identidade que deseja integrar')}
                  </FormHelperText>
                </FormControl>
              </Grid>
            </Grid>
            
            <Grid container spacing={2} sx={{ mb: 3 }}>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label={t('sections.ssoProviders.settings.clientId', 'Client ID')}
                  value={ssoConfig.clientId}
                  onChange={(e) => handleTextChange('clientId', e.target.value)}
                  variant="outlined"
                  size="small"
                  disabled={!ssoConfig.enabled}
                  helperText={t('sections.ssoProviders.settings.clientIdDescription', 'ID do cliente fornecido pelo provedor de identidade')}
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  type="password"
                  label={t('sections.ssoProviders.settings.clientSecret', 'Client Secret')}
                  value={ssoConfig.clientSecret}
                  onChange={(e) => handleTextChange('clientSecret', e.target.value)}
                  variant="outlined"
                  size="small"
                  disabled={!ssoConfig.enabled}
                  helperText={t('sections.ssoProviders.settings.clientSecretDescription', 'Secret do cliente fornecido pelo provedor de identidade')}
                />
              </Grid>
            </Grid>
            
            <Grid container spacing={2} sx={{ mb: 3 }}>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label={t('sections.ssoProviders.settings.domain', 'Domínio')}
                  value={ssoConfig.domain}
                  onChange={(e) => handleTextChange('domain', e.target.value)}
                  placeholder="exemplo.com"
                  variant="outlined"
                  size="small"
                  disabled={!ssoConfig.enabled}
                  helperText={t('sections.ssoProviders.settings.domainDescription', 'Domínio permitido para autenticação (ex: exemplo.com)')}
                />
              </Grid>
              {ssoConfig.provider === 'microsoft' && (
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label={t('sections.ssoProviders.settings.tenantId', 'Tenant ID')}
                    value={ssoConfig.tenantId}
                    onChange={(e) => handleTextChange('tenantId', e.target.value)}
                    variant="outlined"
                    size="small"
                    disabled={!ssoConfig.enabled}
                    helperText={t('sections.ssoProviders.settings.tenantIdDescription', 'ID do tenant Microsoft (necessário apenas para Microsoft Entra ID)')}
                  />
                </Grid>
              )}
            </Grid>
            
            <Box sx={{ my: 3 }}>
              <FormControlLabel
                control={
                  <Switch
                    checked={ssoConfig.validateBeforeAccess}
                    onChange={(e) => handleToggleChange('validateBeforeAccess', e.target.checked)}
                    disabled={!ssoConfig.enabled}
                  />
                }
                label={
                  <Box display="flex" alignItems="center">
                    <Typography>
                      {t('sections.ssoProviders.settings.validateBeforeAccess', 'Validar Acesso')}
                    </Typography>
                    <Tooltip title={t('sections.ssoProviders.settings.validateBeforeAccessDescription', 'Valida se o usuário tem permissão de acesso antes de permitir a autenticação')}>
                      <IconButton size="small">
                        <InfoIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                }
              />
            </Box>
            
            {!ssoConfig.enabled && (
              <Alert severity="info" sx={{ mt: 2 }}>
                {t('sections.ssoProviders.enabledRequired', 'Habilite o SSO para configurar as opções de provedor')}
              </Alert>
            )}
            
            {ssoConfig.enabled && ssoConfig.clientId && ssoConfig.clientSecret && (
              <Alert 
                severity="success" 
                sx={{ 
                  mt: 3,
                  borderRadius: 2,
                  '& .MuiAlert-icon': {
                    display: 'flex',
                    alignItems: 'center',
                  }
                }}
              >
                <Typography variant="body2">
                  {t('sections.ssoProviders.validConfiguration', 'Configuração de SSO válida. Os usuários poderão fazer login com suas credenciais corporativas.')}
                </Typography>
              </Alert>
            )}
          </>
        )}
      </CardContent>

      {/* Notificação de sucesso */}
      <Snackbar 
        open={!!successMessage} 
        autoHideDuration={6000} 
        onClose={() => setSuccessMessage(null)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>
    </Card>
  );
};

export default SSOConfigPanel;
