// Armazena o perfil do usuário atual em cache
let userProfile: any = null;
// Armazena a promise de uma requisição em andamento para evitar duplicatas
let userProfileFetchPromise: Promise<any> | null = null;
// sessionActive removido - não utilizado

// Função para gerar hash SHA-256 de um objeto
const generateUserDataHash = async (userData: any): Promise<string> => {
  // Criar uma string determinística do objeto (ordenar chaves)
  const sortedKeys = Object.keys(userData).sort();
  const dataString = sortedKeys.map(key => `${key}:${userData[key]}`).join('|');
  
  // Usar Web Crypto API para gerar hash
  const encoder = new TextEncoder();
  const data = encoder.encode(dataString);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  
  // Converter para string hex
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  
  return hashHex;
};

// Função para validar integridade dos dados
const validateUserDataIntegrity = async (userData: any): Promise<boolean> => {
  try {
    const storedHash = localStorage.getItem('userDataHash');
    if (!storedHash) {
      // Não há hash armazenado, então consideramos válido e criamos um novo
      const newHash = await generateUserDataHash(userData);
      localStorage.setItem('userDataHash', newHash);
      return true;
    }
    
    const currentHash = await generateUserDataHash(userData);
    const isValid = currentHash === storedHash;
    
    if (!isValid) {
      // Remover console.warn desnecessário - apenas retornar false
      // console.log('Hash mismatch:', {
      //   stored: storedHash.substring(0, 8) + '...',
      //   current: currentHash.substring(0, 8) + '...',
      //   userData: { 
      //     id: userData.id, 
      //     username: userData.username, 
      //     role: userData.role 
      //   }
      // });
    }
    
    return isValid;
  } catch (error) {
    console.error('Error validating user data integrity:', error);
    return false;
  }
};

// Função auxiliar para buscar o perfil do usuário da API
const fetchUserFromAPI = async () => {
  try {
    // Tentar obter o perfil do usuário usando o endpoint específico
    const response = await userService.getUserById('me');
    if (response && response.user && response.user.id && 
        response.user.username && response.user.role) {
      userProfile = response.user;
      return userProfile;
    } else {
      console.error('Invalid user data received from API:', response);
      userProfile = null;
      return null;
    }
  } catch (error) {
    console.error('Error getting current user:', error);
    
    // Se recebermos erro 401 ou 403, o usuário não está autenticado
    if (error && typeof error === 'object' && 'response' in error && 
        error.response && typeof error.response === 'object' && 
        'status' in error.response && 
        (error.response.status === 401 || error.response.status === 403)) {
      console.warn('Authentication error');
      userProfile = null;
    }
    
    return null;
  }
};

export const authService = {
  /**
   * Faz login do usuário
   */
  login: async (username: string, password: string) => {
    try {
      console.log("Realizando login via fetch em auth.ts...");

      // Usar um objeto simples para passar no corpo
      const loginPayload = {
        username,
        password
      };

      // Usar fetch diretamente para evitar problemas com cookies
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include', // Mesmo com problemas de cookies, tentar incluí-los
        body: JSON.stringify(loginPayload)
      });

      if (!response.ok) {
        console.error(`Login falhou com status ${response.status}`);
        return false;
      }

      // Ler a resposta
      const data = await response.json();
      console.log("Dados de resposta do login:", data);

      if (data && data.success === true) {
        console.log("Login bem-sucedido via token!");

        // Extrair manualmente o token da resposta
        // O token PASETO normalmente está dentro de auth.token_preview
        let token = data.auth?.token_preview;

        // Se não temos token mas temos sucesso, criar um token sintético
        if (!token && data.user && data.user.id) {
          // Criar um token sintético para uso interno apenas
          console.log("Criando token sintético para autenticação local");
          token = `synthetic_${Date.now()}_${data.user.id}`;
        }

        if (token) {
          // Armazenar o token de forma segura
          console.log("Token encontrado/criado, salvando no localStorage");
          localStorage.setItem('auth_token', token);
          localStorage.setItem('token_timestamp', Date.now().toString());
        } else {
          console.warn("Nenhum token encontrado na resposta e não foi possível criar sintético");
          // Ainda consideramos login bem-sucedido se data.success = true
        }

        // Armazenar dados do usuário
        if (data.user) {
          // Remover quaisquer dados antigos
          localStorage.removeItem('currentUser');
          localStorage.removeItem('user_info');
          localStorage.removeItem('userDataHash');

          // Sempre validar role com o servidor antes de armazenar
          try {
            // Validar dados do usuário com o servidor
            const validationResponse = await fetch('/api/auth/validate-session', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json'
              },
              credentials: 'include',
              body: JSON.stringify({
                user_id: data.user.id,
                claimed_role: data.user.role
              })
            });

            if (!validationResponse.ok) {
              console.error('Failed to validate user data with server');
              throw new Error('User data validation failed');
            }

            const validationData = await validationResponse.json();
            
            // Usar dados validados do servidor
            const validatedUser = validationData.user || data.user;
            
            // Garantir que a role vem do servidor
            if (validationData.validated_role) {
              validatedUser.role = validationData.validated_role;
            }

            // Gerar hash para detecção de manipulação
            const userDataHash = await generateUserDataHash(validatedUser);
            
            // Salvar dados validados
            localStorage.setItem('currentUser', JSON.stringify(validatedUser));
            localStorage.setItem('user_info', JSON.stringify({
              id: validatedUser.id,
              username: validatedUser.username,
              role: validatedUser.role || 'user'
            }));
            localStorage.setItem('userDataHash', userDataHash);

            // Atualizar o cache interno para evitar chamadas à API
            userProfile = validatedUser;

            console.log("Dados do usuário validados e salvos:", {
              id: validatedUser.id,
              username: validatedUser.username,
              role: validatedUser.role,
              hash: userDataHash.substring(0, 8) + '...'
            });
          } catch (validationError) {
            console.error('Failed to validate user data:', validationError);
            // Em caso de erro, usar dados mínimos seguros
            const safeUser = {
              id: data.user.id,
              username: data.user.username,
              role: 'user' // Role padrão segura
            };
            
            // Gerar hash para o usuário seguro
            const safeUserHash = await generateUserDataHash(safeUser);
            
            localStorage.setItem('currentUser', JSON.stringify(safeUser));
            localStorage.setItem('user_info', JSON.stringify(safeUser));
            localStorage.setItem('userDataHash', safeUserHash);
            userProfile = safeUser;
            
            console.warn("Using safe defaults due to validation error");
          }
        } else {
          console.warn("Dados do usuário ausentes na resposta de login");
        }

        // Salvar marcas de timestamp
        const now = Date.now().toString();
        localStorage.setItem('login_timestamp', now);
        sessionStorage.setItem('login_attempt_time', now);
        sessionStorage.removeItem('auth_refresh_attempts');

        // Verificar se algum cookie está acessível (diagnóstico)
        const cookies = document.cookie.split(';').map(c => c.trim()).filter(c => c);
        if (cookies.length > 0) {
          console.log("Cookies disponíveis após login:");
          cookies.forEach(c => console.log(` - ${c}`));
        } else {
          console.warn("Nenhum cookie acessível após login");

          // Se não temos cookies, tentar garantir que eles sejam configurados via endpoint específico
          console.log("Tentando configurar cookie de sessão via endpoint específico...");
          try {
            const sessionCookieResponse = await fetch('/api/auth/session-cookie', {
              method: 'POST',
              credentials: 'include',
              headers: {
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({
                user_id: data.user.id,
                username: data.user.username,
                role: data.user.role,
                token: token
              })
            });

            const sessionCookieData = await sessionCookieResponse.json();
            console.log("Resposta da configuração de cookie de sessão:", sessionCookieData);

            // Verificar novamente se temos cookies após a tentativa
            const cookiesAfterFix = document.cookie.split(';').map(c => c.trim()).filter(c => c);
            if (cookiesAfterFix.length > 0) {
              console.log("Cookies disponíveis após correção:");
              cookiesAfterFix.forEach(c => console.log(` - ${c}`));
            } else {
              console.warn("Ainda não há cookies acessíveis após tentativa de correção");
            }
          } catch (error) {
            console.error("Erro ao tentar configurar cookie de sessão:", error);
          }
        }

        return true;
      }

      console.warn("Login falhou - resposta não indica sucesso:", data);
      return false;
    } catch (error) {
      console.error("Erro no login:", error);
      return false;
    }
  },

  /**
   * Muda a senha do usuário atual
   */
  changePassword: async (currentPassword: string, newPassword: string) => {
    try {
      // Obter o perfil do usuário para ter o ID
      const user = await authService.getCurrentUser();
      if (!user || !user.id) {
        throw new Error('User not authenticated');
      }
      
      // Fazer a chamada para a API - não precisamos enviar o user_id, o servidor extrai do token PASETO
      const response = await axios.post(
        `/api/users/change-password`,
        {
          current_password: currentPassword,
          new_password: newPassword
        },
        {
          headers: {
            'Content-Type': 'application/json'
          },
          withCredentials: true // Importante: isso garante que os cookies sejam enviados
        }
      );
      
      return response.data;
    } catch (error) {
      console.error('Error changing password:', error);
      
      // Retornar mensagem de erro apropriada baseada no código de status
      if (error && typeof error === 'object' && 'response' in error && 
          error.response && typeof error.response === 'object') {
        if ('status' in error.response && error.response.status === 401) {
          throw new Error('Current password is incorrect');
        } else {
          let errorMessage = 'Failed to change password';
          
          // Try to extract a string error message from the response data
          if ('data' in error.response && error.response.data) {
            if (typeof error.response.data === 'string') {
              errorMessage = error.response.data;
            } else if (typeof error.response.data === 'object' && error.response.data !== null) {
              // If data is an object, try to extract a message property or stringify it
              if ('message' in error.response.data && typeof error.response.data.message === 'string') {
                errorMessage = error.response.data.message;
              } else {
                try {
                  errorMessage = JSON.stringify(error.response.data);
                } catch (e) {
                  // If JSON stringification fails, keep the default message
                }
              }
            }
          }
          
          throw new Error(errorMessage);
        }
      } else {
        throw new Error('Network error, please try again');
      }
    }
  },
  /**
   * Obtém o perfil do usuário atual a partir da API ou do cache
   */
  getCurrentUser: async (forceRefresh = false) => {
    // Se já temos um perfil em cache e não é necessário atualizar
    if (userProfile && !forceRefresh) {
      // Validar integridade dos dados em cache
      const isValid = await validateUserDataIntegrity(userProfile);
      
      if (!isValid) {
        // Se integridade falhou, forçar atualização do servidor silenciosamente
        forceRefresh = true;
      }
    }
    
    // Se forçar atualização ou não temos cache
    if (!userProfile || forceRefresh) {
      // Use debouncing to prevent multiple parallel API calls for the same data
      const fetchPromise = userProfileFetchPromise = userProfileFetchPromise || fetchUserFromAPI();
      
      try {
        const result = await fetchPromise;
        // Clear the promise reference only after completion
        if (fetchPromise === userProfileFetchPromise) {
          userProfileFetchPromise = null;
        }
        
        // Se conseguimos obter o usuário
        if (result) {
          // Validar dados com o servidor antes de armazenar
          const validatedUser = await authService.validateUserData(result);
          
          // Atualizar cache com dados validados
          userProfile = validatedUser;
          
          // Atualizar localStorage com dados validados
          localStorage.setItem('currentUser', JSON.stringify(validatedUser));
          const userDataHash = await generateUserDataHash(validatedUser);
          localStorage.setItem('userDataHash', userDataHash);
          
          return validatedUser;
        }
        
        return null;
      } catch (error) {
        // Clear the promise reference on error
        if (fetchPromise === userProfileFetchPromise) {
          userProfileFetchPromise = null;
        }
        
        throw error;
      }
    }
    
    return userProfile;
  },
  
  // Helper variable to track in-flight API requests
  getUserById: async (userId: string) => {
    // Implement direct access to a specific user ID
    try {
      const response = await userService.getUserById(userId);
      return response?.user || null;
    } catch (error) {
      console.error(`Error fetching user with ID ${userId}:`, error);
      return null;
    }
  },

  /**
   * Valida dados do usuário com o servidor
   */
  validateUserData: async (userData: any) => {
    try {
      const response = await fetch('/api/auth/validate-session', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          user_id: userData.id,
          claimed_role: userData.role
        })
      });

      if (!response.ok) {
        throw new Error('Validation failed');
      }

      const data = await response.json();
      
      // Retornar dados validados
      return {
        ...userData,
        role: data.validated_role || userData.role,
        validated: true
      };
    } catch (error) {
      console.error('Error validating user data:', error);
      // Em caso de erro, retornar dados com role segura
      return {
        ...userData,
        role: 'user',
        validated: false
      };
    }
  },

  /**
   * Obtém dados do usuário diretamente do servidor (sem cache)
   */
  getCurrentUserFromServer: async () => {
    console.log('[AuthService] getCurrentUserFromServer called');
    try {
      console.log('[AuthService] Fetching user from server...');
      console.log('[AuthService] Request URL:', '/api/check-auth');
      console.log('[AuthService] Request method:', 'GET');
      console.log('[AuthService] Request credentials:', 'include');
      
      console.log('[AuthService] About to call fetch...');
      let response;
      try {
        response = await fetch('/api/check-auth', {
          method: 'GET',
          credentials: 'include',
          headers: {
            'Content-Type': 'application/json'
          }
        });
        console.log('[AuthService] Fetch completed successfully');
      } catch (fetchError) {
        console.error('[AuthService] Fetch error:', fetchError);
        throw fetchError;
      }

      console.log('[AuthService] Server response status:', response.status);
      console.log('[AuthService] Response object:', response);

      if (!response.ok) {
        console.error('[AuthService] Server responded with error:', {
          status: response.status,
          statusText: response.statusText
        });
        // Para erros 401, retornar null indicando não autenticado
        if (response.status === 401) {
          console.log('[AuthService] User not authenticated (401)');
          return null;
        }
        throw new Error(`Server error: ${response.status}`);
      }

      // Verificar se a resposta tem conteúdo
      const contentType = response.headers.get('content-type');
      const contentLength = response.headers.get('content-length');
      
      console.log('[AuthService] Response headers:', {
        contentType,
        contentLength,
        status: response.status
      });

      // Se não tiver conteúdo, retornar null
      if (!contentType?.includes('application/json') || contentLength === '0') {
        console.warn('[AuthService] Response is not JSON or is empty');
        return null;
      }

      const data = await response.json();
      console.log('[AuthService] Full response data:', data);
      console.log('[AuthService] Response data summary:', {
        authenticated: data.authenticated,
        hasUser: !!data.user,
        userRole: data.user?.role,
        userName: data.user?.username,
        fullUser: data.user
      });
      
      if (data.authenticated && data.user) {
        // Validar que os dados do usuário são completos
        if (!data.user.role || !data.user.username) {
          console.error('[AuthService] Incomplete user data from server:', data.user);
          return null;
        }
        
        // Retornar dados diretamente do servidor
        console.log('[AuthService] Returning valid user data:', {
          username: data.user.username,
          role: data.user.role,
          id: data.user.id
        });
        
        return data.user;
      }
      
      // Se não está autenticado, retornar null
      console.log('[AuthService] User not authenticated or no user data');
      console.log('[AuthService] Returning null from getCurrentUserFromServer');
      return null;
    } catch (error) {
      console.error('[AuthService] Error fetching user from server:', error);
      console.error('[AuthService] Error details:', {
        message: error instanceof Error ? error.message : String(error),
        type: error instanceof Error ? error.constructor.name : typeof error,
        stack: error instanceof Error ? error.stack : undefined
      });
      // Para erros de rede, lançar exceção para que o MainLayout possa forçar re-autenticação
      if (error instanceof TypeError && error.message.includes('Failed to fetch')) {
        throw new Error('Network error - cannot validate user');
      }
      console.log('[AuthService] End of catch block, returning null');
      return null;
    }
  },
  
  /**
   * Verifica se o usuário atual tem um determinado papel
   */
  // Cache para resultados de verificações de role para evitar chamadas desnecessárias
  _roleCheckCache: new Map<string, {result: boolean, timestamp: number}>(),
  _roleCheckTTL: 300000, // 5 minutos

  hasRole: async (role: string | string[], options: { serverValidation?: boolean } = {}): Promise<boolean> => {
    const roles = Array.isArray(role) ? role : [role];
    const useServerValidation = options.serverValidation ?? roles.some(r => 
      ['admin', 'administrator', 'approver'].includes(r.toLowerCase())
    );

    // Para roles críticas, sempre validar com o servidor
    if (useServerValidation) {
      try {
        const user = await authService.getCurrentUserFromServer();
        if (!user || !user.role) return false;

        const userRole = user.role.toLowerCase();
        const hasRole = roles.some(r => r.toLowerCase() === userRole);
        
        console.log('Server-validated role check:', {
          userRole,
          requiredRoles: roles,
          result: hasRole
        });
        
        return hasRole;
      } catch (error) {
        console.error('Error validating role with server:', error);
        return false; // Falhar seguramente se não puder validar
      }
    }

    // Para roles não-críticas, usar cache
    const cacheKey = roles.sort().join(',');
    const cachedResult = authService._roleCheckCache.get(cacheKey);

    // Se temos um resultado em cache e não expirou, usar
    if (cachedResult && (Date.now() - cachedResult.timestamp < authService._roleCheckTTL)) {
      return cachedResult.result;
    }

    // Se não está em cache ou expirou, fazer a verificação
    const user = await authService.getCurrentUser();
    if (!user || !user.role) return false;

    // Validar integridade dos dados antes de usar
    const isValid = await validateUserDataIntegrity(user);
    if (!isValid) {
      console.warn('User data integrity check failed in hasRole');
      // Para dados suspeitos, forçar validação do servidor
      return authService.hasRole(role, { serverValidation: true });
    }

    // Make sure we're comparing in a case-insensitive way and that the role is valid
    const userRole = user.role.toLowerCase();

    // Apenas registrar no log se DEBUG está definido
    if (process.env.NODE_ENV === 'development') {
      console.debug('hasRole check - User role:', userRole, 'Required roles:', roles);
    }

    // Special case for admin - if the user has any role containing "admin", they can access admin-only routes
    // Mas apenas quando a rota exigida também é para admins
    if (userRole.includes('admin') && roles.some(r => r.toLowerCase().includes('admin'))) {
      if (process.env.NODE_ENV === 'development') {
        console.debug('Admin access granted based on role containing "admin"');
      }

      // Armazenar no cache
      authService._roleCheckCache.set(cacheKey, {
        result: true,
        timestamp: Date.now()
      });

      return true;
    }

    // For exact matches
    const hasExactRole = roles.some(r => r.toLowerCase() === userRole);

    if (process.env.NODE_ENV === 'development') {
      console.debug('Role exact match result:', hasExactRole);
    }

    // Armazenar no cache
    authService._roleCheckCache.set(cacheKey, {
      result: hasExactRole,
      timestamp: Date.now()
    });

    return hasExactRole;
  },
  
  /**
   * Verifica se o usuário atual é um administrador - versão otimizada com cache
   */
  isAdmin: async () => {
    // Verificar no cache primeiro
    const cacheKey = 'admin';
    const cachedResult = authService._roleCheckCache.get(cacheKey);
    
    if (cachedResult && (Date.now() - cachedResult.timestamp < authService._roleCheckTTL)) {
      return cachedResult.result;
    }
    
    // Não está em cache ou expirou, fazer a verificação
    const result = await authService.hasRole(['admin', 'administrator']);
    
    // Armazenar no cache
    authService._roleCheckCache.set(cacheKey, {
      result,
      timestamp: Date.now()
    });
    
    return result;
  },
  
  /**
   * Verifica se o usuário atual é um aprovador - versão otimizada com cache
   */
  isApprover: async () => {
    // Verificar no cache primeiro
    const cacheKey = 'approver';
    const cachedResult = authService._roleCheckCache.get(cacheKey);
    
    if (cachedResult && (Date.now() - cachedResult.timestamp < authService._roleCheckTTL)) {
      return cachedResult.result;
    }
    
    // Não está em cache ou expirou, fazer a verificação
    const result = await authService.hasRole(['approver']);
    
    // Armazenar no cache
    authService._roleCheckCache.set(cacheKey, {
      result,
      timestamp: Date.now()
    });
    
    return result;
  },
  
  /**
   * Verifica se o usuário atual é um solicitante - versão otimizada com cache
   */
  isRequester: async () => {
    // Verificar no cache primeiro
    const cacheKey = 'requester';
    const cachedResult = authService._roleCheckCache.get(cacheKey);
    
    if (cachedResult && (Date.now() - cachedResult.timestamp < authService._roleCheckTTL)) {
      return cachedResult.result;
    }
    
    // Não está em cache ou expirou, fazer a verificação
    const result = await authService.hasRole(['requester']);
    
    // Armazenar no cache
    authService._roleCheckCache.set(cacheKey, {
      result,
      timestamp: Date.now()
    });
    
    return result;
  },
  
  /**
   * Limpa o cache de verificações de papel
   */
  clearRoleCache: () => {
    authService._roleCheckCache.clear();
  },
  
  /**
   * Limpa todos os caches
   */
  clearUserCache: () => {
    userProfile = null;
    userProfileFetchPromise = null;
    authService.clearRoleCache();
  },
  
  /**
   * Obtém o papel do usuário atual
   */
  getUserRole: async () => {
    const user = await authService.getCurrentUser();
    if (user && user.role) {
      return user.role;
    }
    return null;
  },

  /**
   * Obtém o ID do usuário atual
   */
  getUserId: async () => {
    const user = await authService.getCurrentUser();
    return user?.id || null;
  },
  
  /**
   * Atualiza o cache interno do perfil do usuário
   */
  updateUserProfileCache: (updatedProfile: any) => {
    if (updatedProfile) {
      userProfile = { ...userProfile, ...updatedProfile };
      console.log('User profile cache updated:', userProfile);
    }
  }
};

export default authService;