import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Collapse,
  Grid,
  Tooltip,
  Alert,
  CircularProgress,
  Paper,
} from '@mui/material';
import {
  Search as SearchIcon,
  Refresh as RefreshIcon,
  Code as CodeIcon,
  Error as ErrorIcon,
  AccessTime as TimeIcon,
  FilterList as FilterIcon,
} from '@mui/icons-material';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';
import { Dayjs } from 'dayjs';
import queryAuditService, { QueryAuditLog, QueryAuditFilter } from '../../services/queryAuditService';
import { useNotification } from '../../contexts/NotificationContext';
import SyntaxHighlighter from 'react-syntax-highlighter';
import { docco } from 'react-syntax-highlighter/dist/esm/styles/hljs';

interface QueryAuditLogsProps {
  serverId?: string;
  serverName?: string;
}

// Style for input labels to fix black background issue
const labelStyle = {
  backgroundColor: 'background.paper',
  px: 1
};

const labelStyleTextField = {
  shrink: true,
  sx: {
    '&.MuiInputLabel-shrink': {
      backgroundColor: 'background.paper',
      px: 1
    }
  }
};

const QueryAuditLogsComponent: React.FC<QueryAuditLogsProps> = ({ serverId, serverName }) => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const { showError } = useNotification();
  const [loading, setLoading] = useState(true);
  const [logs, setLogs] = useState<QueryAuditLog[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(25);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedLog, setSelectedLog] = useState<QueryAuditLog | null>(null);
  
  // Filters
  const [filter, setFilter] = useState<QueryAuditFilter>({
    server_id: serverId,
    limit: rowsPerPage,
    offset: 0,
  });
  const [searchText, setSearchText] = useState('');
  const [queryType, setQueryType] = useState('');
  const [username, setUsername] = useState('');
  const [startDate, setStartDate] = useState<Dayjs | null>(null);
  const [endDate, setEndDate] = useState<Dayjs | null>(null);
  const [minDuration, setMinDuration] = useState('');
  const [hasError, setHasError] = useState<boolean | undefined>();

  const loadLogs = useCallback(async () => {
    try {
      setLoading(true);
      const result = await queryAuditService.getQueryLogs({
        ...filter,
        limit: rowsPerPage,
        offset: page * rowsPerPage,
      });
      setLogs(result.logs || []);
      setTotal(result.total || 0);
    } catch (error: any) {
      showError(t('queryAudit:errors.loadLogs'));
    } finally {
      setLoading(false);
    }
  }, [filter, rowsPerPage, page, showError, t]);

  useEffect(() => {
    loadLogs();
  }, [loadLogs]);

  const handleSearch = () => {
    const newFilter: QueryAuditFilter = {
      server_id: serverId,
      search_text: searchText || undefined,
      query_type: queryType || undefined,
      username: username || undefined,
      start_date: startDate ? startDate.toISOString() : undefined,
      end_date: endDate ? endDate.toISOString() : undefined,
      min_duration: minDuration ? parseInt(minDuration) : undefined,
      has_error: hasError,
    };
    setFilter(newFilter);
    setPage(0);
  };

  const handleReset = () => {
    setSearchText('');
    setQueryType('');
    setUsername('');
    setStartDate(null);
    setEndDate(null);
    setMinDuration('');
    setHasError(undefined);
    setFilter({ server_id: serverId });
    setPage(0);
  };

  const getQueryTypeColor = (type: string) => {
    switch (type.toUpperCase()) {
      case 'SELECT': return 'primary';
      case 'INSERT': return 'success';
      case 'UPDATE': return 'warning';
      case 'DELETE': return 'error';
      case 'DDL': return 'info';
      case 'DCL': return 'secondary';
      default: return 'default';
    }
  };

  const formatDuration = (ms?: number) => {
    if (!ms) return '-';
    if (ms < 1000) return `${ms}ms`;
    if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
    return `${(ms / 60000).toFixed(1)}m`;
  };

  return (
    <Card>
      <CardContent>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
          <Typography variant="h6">
            {serverName ? t('queryAudit:logs.titleWithServer', { serverName }) : t('queryAudit:logs.title')}
          </Typography>
          <Box>
            <IconButton onClick={() => setShowFilters(!showFilters)}>
              <FilterIcon />
            </IconButton>
            <IconButton onClick={loadLogs}>
              <RefreshIcon />
            </IconButton>
          </Box>
        </Box>

        {/* Filters */}
        <Collapse in={showFilters}>
          <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label={t('queryAudit:logs.searchQuery')}
                  value={searchText}
                  onChange={(e) => setSearchText(e.target.value)}
                  placeholder={t('queryAudit:logs.searchPlaceholder') as string}
                  InputLabelProps={labelStyleTextField}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <FormControl fullWidth>
                  <InputLabel sx={labelStyle}>
                    {t('queryAudit:logs.queryType')}
                  </InputLabel>
                  <Select
                    value={queryType}
                    onChange={(e) => setQueryType(e.target.value)}
                    label={t('queryAudit:logs.queryType')}
                  >
                    <MenuItem value="">
                      <em>{t('common:all')}</em>
                    </MenuItem>
                    <MenuItem value="SELECT">SELECT</MenuItem>
                    <MenuItem value="INSERT">INSERT</MenuItem>
                    <MenuItem value="UPDATE">UPDATE</MenuItem>
                    <MenuItem value="DELETE">DELETE</MenuItem>
                    <MenuItem value="DDL">DDL</MenuItem>
                    <MenuItem value="DCL">DCL</MenuItem>
                    <MenuItem value="OTHER">OTHER</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  fullWidth
                  label={t('queryAudit:logs.username')}
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  InputLabelProps={labelStyleTextField}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  fullWidth
                  label={t('queryAudit:logs.minDuration')}
                  value={minDuration}
                  onChange={(e) => setMinDuration(e.target.value)}
                  type="number"
                  InputProps={{ endAdornment: 'ms' }}
                  InputLabelProps={labelStyleTextField}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <FormControl fullWidth>
                  <InputLabel sx={labelStyle}>
                    {t('queryAudit:logs.hasError')}
                  </InputLabel>
                  <Select
                    value={hasError === undefined ? '' : hasError.toString()}
                    onChange={(e) => setHasError(e.target.value === '' ? undefined : e.target.value === 'true')}
                    label={t('queryAudit:logs.hasError')}
                  >
                    <MenuItem value="">
                      <em>{t('common:all')}</em>
                    </MenuItem>
                    <MenuItem value="true">{t('common:yes')}</MenuItem>
                    <MenuItem value="false">{t('common:no')}</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} md={6}>
                <LocalizationProvider dateAdapter={AdapterDayjs}>
                  <DateTimePicker
                    label={t('queryAudit:logs.startDate')}
                    value={startDate}
                    onChange={setStartDate}
                    slotProps={{ textField: { fullWidth: true } }}
                  />
                </LocalizationProvider>
              </Grid>
              <Grid item xs={12} md={6}>
                <LocalizationProvider dateAdapter={AdapterDayjs}>
                  <DateTimePicker
                    label={t('queryAudit:logs.endDate')}
                    value={endDate}
                    onChange={setEndDate}
                    slotProps={{ textField: { fullWidth: true } }}
                  />
                </LocalizationProvider>
              </Grid>
              <Grid item xs={12}>
                <Box display="flex" gap={1}>
                  <Button
                    variant="contained"
                    startIcon={<SearchIcon />}
                    onClick={handleSearch}
                  >
                    {t('common:search')}
                  </Button>
                  <Button variant="outlined" onClick={handleReset}>
                    {t('common:reset')}
                  </Button>
                </Box>
              </Grid>
            </Grid>
          </Paper>
        </Collapse>

        {loading ? (
          <Box display="flex" justifyContent="center" p={3}>
            <CircularProgress />
          </Box>
        ) : logs.length === 0 ? (
          <Alert severity="info">{t('queryAudit:logs.noLogs')}</Alert>
        ) : (
          <>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>{t('queryAudit:logs.executedAt')}</TableCell>
                    <TableCell>{t('queryAudit:logs.type')}</TableCell>
                    <TableCell>{t('queryAudit:logs.username')}</TableCell>
                    <TableCell>{t('queryAudit:logs.database')}</TableCell>
                    <TableCell>{t('queryAudit:logs.duration')}</TableCell>
                    <TableCell>{t('queryAudit:logs.rows')}</TableCell>
                    <TableCell>{t('queryAudit:logs.status')}</TableCell>
                    <TableCell align="center">{t('common:actions')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {logs.map((log) => (
                    <TableRow key={log.id} hover>
                      <TableCell>
                        {format(new Date(log.executed_at), 'dd/MM/yyyy HH:mm:ss')}
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={log.query_type}
                          size="small"
                          color={getQueryTypeColor(log.query_type) as any}
                        />
                      </TableCell>
                      <TableCell>{log.username}</TableCell>
                      <TableCell>{log.database_name || '-'}</TableCell>
                      <TableCell>
                        <Box display="flex" alignItems="center">
                          <TimeIcon fontSize="small" sx={{ mr: 0.5 }} />
                          {formatDuration(log.execution_time_ms)}
                        </Box>
                      </TableCell>
                      <TableCell>{log.rows_affected || '-'}</TableCell>
                      <TableCell>
                        {log.error_code ? (
                          <Tooltip title={log.error_message || ''}>
                            <Chip
                              label={log.error_code}
                              size="small"
                              color="error"
                              icon={<ErrorIcon />}
                            />
                          </Tooltip>
                        ) : (
                          <Chip label="OK" size="small" color="success" />
                        )}
                      </TableCell>
                      <TableCell align="center">
                        <IconButton
                          size="small"
                          onClick={() => setSelectedLog(log)}
                        >
                          <CodeIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
            <TablePagination
              component="div"
              count={total}
              page={page}
              onPageChange={(_, newPage) => setPage(newPage)}
              rowsPerPage={rowsPerPage}
              onRowsPerPageChange={(e) => {
                setRowsPerPage(parseInt(e.target.value));
                setPage(0);
              }}
              rowsPerPageOptions={[10, 25, 50, 100]}
              labelRowsPerPage={t('common:rowsPerPage')}
              labelDisplayedRows={({ from, to, count }) =>
                t('common:displayedRows', { from, to, count })
              }
            />
          </>
        )}

        {/* Query Details Dialog */}
        <Dialog
          open={!!selectedLog}
          onClose={() => setSelectedLog(null)}
          maxWidth="lg"
          fullWidth
        >
          {selectedLog && (
            <>
              <DialogTitle>
                {t('queryAudit:logs.queryDetails')}
              </DialogTitle>
              <DialogContent>
                <Grid container spacing={2} sx={{ mb: 2 }}>
                  <Grid item xs={12} md={6}>
                    <Typography variant="body2" color="textSecondary">
                      {t('queryAudit:logs.executedAt')}
                    </Typography>
                    <Typography variant="body1">
                      {format(new Date(selectedLog.executed_at), 'dd/MM/yyyy HH:mm:ss')}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <Typography variant="body2" color="textSecondary">
                      {t('queryAudit:logs.username')}
                    </Typography>
                    <Typography variant="body1">
                      {selectedLog.username}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <Typography variant="body2" color="textSecondary">
                      {t('queryAudit:logs.database')}
                    </Typography>
                    <Typography variant="body1">
                      {selectedLog.database_name || '-'}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <Typography variant="body2" color="textSecondary">
                      {t('queryAudit:logs.clientAddress')}
                    </Typography>
                    <Typography variant="body1">
                      {selectedLog.client_address || '-'}
                    </Typography>
                  </Grid>
                  {selectedLog.error_message && (
                    <Grid item xs={12}>
                      <Alert severity="error">
                        <Typography variant="body2">
                          <strong>{selectedLog.error_code}:</strong> {selectedLog.error_message}
                        </Typography>
                      </Alert>
                    </Grid>
                  )}
                </Grid>
                <Typography variant="subtitle2" gutterBottom>
                  {t('queryAudit:logs.queryText')}
                </Typography>
                <Paper variant="outlined">
                  <SyntaxHighlighter
                    language="sql"
                    style={docco}
                    customStyle={{ margin: 0 }}
                  >
                    {selectedLog.query_text}
                  </SyntaxHighlighter>
                </Paper>
                {selectedLog.table_names && Array.isArray(selectedLog.table_names) && selectedLog.table_names.length > 0 && (
                  <Box mt={2}>
                    <Typography variant="subtitle2" gutterBottom>
                      {t('queryAudit:logs.affectedTables')}
                    </Typography>
                    <Box>
                      {selectedLog.table_names.map((table) => (
                        <Chip key={table} label={table} size="small" sx={{ m: 0.5 }} />
                      ))}
                    </Box>
                  </Box>
                )}
              </DialogContent>
              <DialogActions>
                <Button onClick={() => setSelectedLog(null)}>
                  {t('common:close')}
                </Button>
              </DialogActions>
            </>
          )}
        </Dialog>
      </CardContent>
    </Card>
  );
};

export default QueryAuditLogsComponent;