// Permission interface
interface Permission {
  id: string;
  user_id: string;
  server_id: string; // ID do servidor de banco de dados
  server_name?: string; // Nome do servidor
  database_id?: string; // Campo legado
  database?: string; // Campo legado
  database_name?: string; // Nome do banco de dados
  schema?: string; // Schema do banco (para PostgreSQL)
  table: string;
  tables?: string[];
  operations: string[] | string; // Pode ser um array ou string separada por vírgulas
  level?: string; // Nível da permissão (database, schema, table, column)
  created_at: string;
  updated_at: string;
  expires_at?: string;
  created_by?: string;
  status?: string;
  revoked_at?: string;
  is_permanent?: boolean;
}

// Database permissions interface (grouped by database)
interface DatabasePermissions {
  database: string;
  database_id: string;
  readTables: string[];
  writeTables: string[];
  adminTables: string[];
  status: string;
  expires_at?: string;
}

// Extrair operações para formato consistente
const normalizeOperations = (operations: string | string[] | undefined): string[] => {
  if (!operations) {
    return [];
  }
  if (typeof operations === 'string') {
    return operations.split(',').map(op => op.trim());
  }
  if (Array.isArray(operations)) {
    return operations;
  }
  return [];
};

// Função para determinar o status da permissão
const getPermissionStatus = (permission: Permission): string => {
  if (permission.status) {
    return permission.status;
  }
  
  if (!permission.expires_at || 
      permission.expires_at === "0001-01-01T00:00:00Z" || 
      permission.expires_at === "0001-01-01T00:00:00" || 
      new Date(permission.expires_at).getFullYear() <= 1) {
    return 'active';
  }
  
  const now = new Date();
  const expiresAt = new Date(permission.expires_at);
  
  if (expiresAt < now) {
    return 'expired';
  }
  
  return 'active';
};

// Group permissions by database and categorize tables by operation types
const processPermissions = (permissions: Permission[]): DatabasePermissions[] => {
  // First, group by database
  const databaseGroups: { [key: string]: Permission[] } = {};
  
  permissions.forEach(permission => {
    // Usar server_name para o nome do banco, ou database_name se server_name não estiver disponível
    const databaseName = permission.server_name || permission.database_name || 'Unknown Database';
    const key = `${databaseName}_${permission.server_id}`;
    
    if (!databaseGroups[key]) {
      databaseGroups[key] = [];
    }
    databaseGroups[key].push(permission);
  });
  
  // Then, for each database, categorize tables by operation types
  return Object.entries(databaseGroups).map(([key, perms]) => {
    // Extrair o nome do banco do key (tudo antes do último underscore)
    const databaseName = key.substring(0, key.lastIndexOf('_'));
    console.log(`Processing database ${databaseName} with ${perms.length} permissions`);
    
    const dbPermission: DatabasePermissions = {
      database: databaseName,
      database_id: perms[0].server_id,
      readTables: [],
      writeTables: [],
      adminTables: [],
      status: 'active', // Default status
      expires_at: undefined
    };
    
    // Process all permissions for this database
    perms.forEach(permission => {
      // Update status (if any permission is expired, mark database as expired)
      const permStatus = getPermissionStatus(permission);
      if (permStatus === 'expired') {
        dbPermission.status = 'expired';
      }
      
      // Keep the latest expiration date
      if (permission.expires_at && 
          permission.expires_at !== "0001-01-01T00:00:00Z" &&
          permission.expires_at !== "0001-01-01T00:00:00" &&
          new Date(permission.expires_at).getFullYear() > 1) {
        if (!dbPermission.expires_at || new Date(permission.expires_at) > new Date(dbPermission.expires_at)) {
          dbPermission.expires_at = permission.expires_at;
        }
      }
      
      // Get tables from permission
      const tables = Array.isArray(permission.tables) ? permission.tables : [permission.table];
      
      // Categorize each table based on operations
      tables.forEach(table => {
        console.log(`Processing table ${table} with operations:`, permission.operations);
        
        // Normalizar operações para um formato consistente
        const operationsArray = normalizeOperations(permission.operations);
        console.log(`Normalized operations for table ${table}:`, operationsArray);
        
        // Verificar níveis de acesso em ordem (admin > write > read)
        const hasAdmin = operationsArray.some(op => 
          op === 'DELETE' || op === 'ALL' || op === 'admin');
          
        const hasWrite = operationsArray.some(op => 
          op === 'INSERT' || op === 'UPDATE' || op === 'write');
          
        const hasRead = operationsArray.some(op => 
          op === 'SELECT' || op === 'read');
          
        console.log(`Table ${table} access levels - Admin: ${hasAdmin}, Write: ${hasWrite}, Read: ${hasRead}`);
        
        // Atribuir à categoria apropriada baseado no nível mais alto de acesso
        if (hasAdmin) {
          if (!dbPermission.adminTables.includes(table)) {
            dbPermission.adminTables.push(table);
          }
        } else if (hasWrite) {
          if (!dbPermission.writeTables.includes(table) && 
              !dbPermission.adminTables.includes(table)) {
            dbPermission.writeTables.push(table);
          }
        } else if (hasRead) {
          if (!dbPermission.readTables.includes(table) && 
              !dbPermission.writeTables.includes(table) &&
              !dbPermission.adminTables.includes(table)) {
            dbPermission.readTables.push(table);
          }
        }
      });
    });
    
    return dbPermission;
  });
};

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`permissions-tabpanel-${index}`}
      aria-labelledby={`permissions-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 2 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

const UserPermissionsSection: React.FC = () => {
  const { t } = useTranslation(['permissions', 'common', 'profile', 'access']);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [databasePermissions, setDatabasePermissions] = useState<DatabasePermissions[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedDatabase, setSelectedDatabase] = useState<DatabasePermissions | null>(null);
  const [tabValue, setTabValue] = useState(0);
  
  // States for permission actions
  const [menuAnchorEl, setMenuAnchorEl] = useState<null | HTMLElement>(null);
  const [selectedPermission, setSelectedPermission] = useState<Permission | null>(null);
  const [confirmDialogOpen, setConfirmDialogOpen] = useState<boolean>(false);
  const [confirmDialogType, setConfirmDialogType] = useState<'revoke' | 'delete'>('revoke');
  const [confirmDialogTitle, setConfirmDialogTitle] = useState<string>('');
  const [confirmDialogMessage, setConfirmDialogMessage] = useState<string>('');
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [snackbarOpen, setSnackbarOpen] = useState<boolean>(false);

  useEffect(() => {
    fetchUserPermissions();
    console.log("UserPermissionsSection mounted"); // Debug log
  }, []);

  const fetchUserPermissions = async () => {
    setLoading(true);
    try {
      // Get current user
      const user = await authService.getCurrentUser();
      setCurrentUser(user);
      
      if (!user || !user.id) {
        console.error('Current user not found or missing ID');
        setLoading(false);
        return;
      }
      
      // Get permissions - passar o ID do usuário para garantir que requesters possam ver suas permissões
      const response = await permissionService.getPermissions(user.id);
      
      if (!response) {
        setPermissions([]);
        setDatabasePermissions([]);
        setLoading(false);
        return;
      }
      
      if (response && response.success === true && !response.permissions) {
        setPermissions([]);
        setDatabasePermissions([]);
        setLoading(false);
        return;
      }
      
      if (response && response.success) {
        // Process permissions to add status based on expiration date
        const permissionsArray = Array.isArray(response.permissions) ? response.permissions : [];
        const rawPermissions = permissionsArray.map((perm: Permission) => ({
          ...perm,
          status: perm.status || getPermissionStatus(perm)
        }));
        
        // Filter permissions for current user only
        const userPermissions = rawPermissions.filter((perm: any) => perm.user_id === user.id);
        
        // Processamos cada permissão individualizando por tabela
        const processedPermissions: Permission[] = [];
        
        userPermissions.forEach((perm: Permission) => {
          // Verificamos se temos múltiplas tabelas definidas
          if (perm.tables && Array.isArray(perm.tables) && perm.tables.length > 0) {
            // Para cada tabela na permissão, criamos uma permissão individual
            perm.tables.forEach(table => {
              processedPermissions.push({
                ...perm,
                table: table,
                tables: [table],  // Mantemos tables como um array para compatibilidade, mas só com a tabela atual
                operations: normalizeOperations(perm.operations)
              });
            });
          } else {
            // Se não tiver múltiplas tabelas, apenas normaliza as operações
            processedPermissions.push({
              ...perm,
              tables: perm.table ? [perm.table] : [],  // Garantir que tables sempre seja um array
              operations: normalizeOperations(perm.operations)
            });
          }
        });
        // Log para depuração
        console.log("Raw permissions data:", processedPermissions);
        
        setPermissions(processedPermissions);
        
        // Process permissions by database
        const dbPermissions = processPermissions(processedPermissions);
        
        // Log para depuração
        console.log("Processed database permissions:", dbPermissions);
        
        setDatabasePermissions(dbPermissions);
        
        console.log("Permissions loaded:", processedPermissions.length, "Database permissions:", dbPermissions.length);
      }
    } catch (error) {
      console.error('Error fetching user permissions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (dbPermission: DatabasePermissions) => {
    setSelectedDatabase(dbPermission);
    setDialogOpen(true);
    setTabValue(0); // Reset to first tab
  };

  const handleCloseDialog = () => {
    setDialogOpen(false);
    setSelectedDatabase(null);
  };

  const handleChangeTab = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  const getStatusColor = (status: string) => {
    return status === 'active' ? 'success' :
           status === 'approved' ? 'success' :
           status === 'expired' ? 'warning' : 
           status === 'pending' ? 'info' : 
           status === 'rejected' ? 'error' : 
           status === 'revoked' ? 'error' : 'default';
  };
  
  // Permission action handlers
  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>, permission: Permission) => {
    event.stopPropagation();
    setMenuAnchorEl(event.currentTarget);
    setSelectedPermission(permission);
  };
  
  const handleMenuClose = () => {
    setMenuAnchorEl(null);
    setSelectedPermission(null);
  };
  
  const handleConfirmDialogOpen = (type: 'revoke' | 'delete', permission: Permission) => {
    setConfirmDialogType(type);
    setSelectedPermission(permission);
    
    // operationsStr removido - não utilizado
    // As operações são processadas diretamente no JSX
    
    if (type === 'revoke') {
      setConfirmDialogTitle(String(t('permissions:dialog.revokeTitle')));
      setConfirmDialogMessage(
        String(t('permissions:dialog.revokeMessage'))
      );
    } else {
      setConfirmDialogTitle(String(t('permissions:dialog.deleteTitle')));
      setConfirmDialogMessage(
        String(t('permissions:dialog.deleteMessage'))
      );
    }
    
    setConfirmDialogOpen(true);
    handleMenuClose();
  };
  
  const handleConfirmDialogClose = () => {
    setConfirmDialogOpen(false);
    setSelectedPermission(null);
  };
  
  const handleConfirmAction = async () => {
    if (!selectedPermission) return;
    
    try {
      console.log(`UserPermissionsSection - Executing action: ${confirmDialogType}, permission ID: ${selectedPermission.id}`);
      
      if (confirmDialogType === 'revoke') {
        await permissionService.revokePermission(selectedPermission.id);
        setSuccessMessage(String(t('permissions:messages.revokeSuccess')));
      } else if (confirmDialogType === 'delete') {
        console.log(`UserPermissionsSection - Deleting permission with ID: ${selectedPermission.id}`);
        const response = await permissionService.deletePermission(selectedPermission.id);
        console.log("UserPermissionsSection - Delete response:", response);
        setSuccessMessage(String(t('permissions:messages.deleteSuccess')));
      }
      
      // Refresh the data
      fetchUserPermissions();
      setSnackbarOpen(true);
    } catch (error) {
      console.error(`Error ${confirmDialogType === 'revoke' ? 'revoking' : 'deleting'} permission:`, error);
      setErrorMessage(
        confirmDialogType === 'revoke' 
          ? String(t('permissions:messages.revokeError'))
          : String(t('permissions:messages.deleteError'))
      );
      setSnackbarOpen(true);
    } finally {
      handleConfirmDialogClose();
    }
  };
  
  const handleSnackbarClose = () => {
    setSnackbarOpen(false);
    setSuccessMessage(null);
    setErrorMessage(null);
  };

  const getFormattedDate = (dateString?: string) => {
    if (!dateString || 
        dateString === "0001-01-01T00:00:00Z" || 
        dateString === "0001-01-01T00:00:00" ||
        new Date(dateString).getFullYear() <= 1) {
      return String(t('permissions:permanent'));
    }
    
    // Format the date based on locale
    return new Date(dateString).toLocaleDateString();
  };

  const renderDatabaseCard = (dbPermission: DatabasePermissions, index: number) => {
    const totalTables = 
      dbPermission.readTables.length + 
      dbPermission.writeTables.length + 
      dbPermission.adminTables.length;
    
    return (
      <Grid item xs={6} sm={4} md={3} key={`${dbPermission.database}-${index}`}>
        <Card 
          sx={{ 
            height: '100%',
            display: 'flex',
            flexDirection: 'column',
            maxWidth: '240px',
            borderRadius: '8px',
            overflow: 'hidden',
            transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
            border: '1px solid rgba(0, 0, 0, 0.08)',
            '&:hover': {
              boxShadow: 6,
              transform: 'translateY(-4px)'
            }
          }}
        >
          <CardActionArea onClick={() => handleOpenDialog(dbPermission)} sx={{ flexGrow: 1 }}>
            <CardContent sx={{ p: 2 }}>
              <Typography 
                variant="h6" 
                gutterBottom 
                noWrap
                sx={{ 
                  fontSize: '1rem',
                  fontWeight: 600,
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  mb: 1
                }}
              >
                {dbPermission.database}
              </Typography>
              
              <Box display="flex" alignItems="center" mb={1}>
                <Chip
                  label={String(t(`permissions:status.${dbPermission.status}`))}
                  color={getStatusColor(dbPermission.status)}
                  size="small"
                  sx={{ mr: 1, height: '22px', fontSize: '0.7rem' }}
                />
                
                <Typography 
                  variant="body2" 
                  color="text.secondary"
                  sx={{
                    fontSize: '0.75rem',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis'
                  }}
                >
                  {dbPermission.expires_at 
                    ? `${String(t('common:expires'))}: ${getFormattedDate(dbPermission.expires_at)}`
                    : String(t('permissions:permanent'))}
                </Typography>
              </Box>
              
              <Divider sx={{ my: 1 }} />
              
              <Box mt={1}>
                <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>
                  <strong>{String(t('permissions:table.tables'))}:</strong> {totalTables}
                </Typography>
                
                {dbPermission.readTables.length > 0 && (
                  <Box display="flex" alignItems="center" mt={0.5}>
                    <LockIcon color="success" sx={{ fontSize: '0.9rem', mr: 0.5 }} />
                    <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                      {String(t('access:readOnly'))}: {dbPermission.readTables.length}
                    </Typography>
                  </Box>
                )}
                
                {dbPermission.writeTables.length > 0 && (
                  <Box display="flex" alignItems="center" mt={0.5}>
                    <EditIcon color="warning" sx={{ fontSize: '0.9rem', mr: 0.5 }} />
                    <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                      {String(t('access:readWrite'))}: {dbPermission.writeTables.length}
                    </Typography>
                  </Box>
                )}
                
                {dbPermission.adminTables.length > 0 && (
                  <Box display="flex" alignItems="center" mt={0.5}>
                    <AdminIcon color="error" sx={{ fontSize: '0.9rem', mr: 0.5 }} />
                    <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                      {String(t('access:admin'))}: {dbPermission.adminTables.length}
                    </Typography>
                  </Box>
                )}
              </Box>
            </CardContent>
          </CardActionArea>
        </Card>
      </Grid>
    );
  };

  const renderTableList = (tables: string[], emptyMessage: string) => {
    if (tables.length === 0) {
      return (
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', py: 4 }}>
          <Typography color="text.secondary" align="center">
            {emptyMessage}
          </Typography>
        </Box>
      );
    }
    
    return (
      <Box sx={{ maxHeight: '350px', overflow: 'auto', py: 1 }}>
        <List dense>
          {tables.map((table, index) => {
            // Encontrar a permissão correspondente para esta tabela
            const tablePermission = permissions.find(p => p.table === table);
            
            return (
              <ListItem 
                key={index} 
                divider={index < tables.length - 1}
                sx={{ 
                  py: 0.75,
                  '&:hover': {
                    backgroundColor: 'rgba(0, 0, 0, 0.03)'
                  },
                  borderLeft: '3px solid',
                  borderColor: theme => 
                    tabValue === 0 ? theme.palette.success.main :
                    tabValue === 1 ? theme.palette.warning.main :
                    theme.palette.error.main,
                  pl: 2,
                  display: 'flex',
                  justifyContent: 'space-between'
                }}
              >
                <ListItemText 
                  primary={table} 
                  primaryTypographyProps={{
                    fontSize: '0.9rem',
                    fontWeight: 500
                  }}
                />
                
                {tablePermission && (
                  <Box>
                    {tablePermission.status !== 'revoked' && (
                      <Tooltip title={String(t('permissions:actions.revoke'))}>
                        <IconButton 
                          size="small" 
                          color="warning"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleConfirmDialogOpen('revoke', tablePermission);
                          }}
                          sx={{ mr: 1 }}
                        >
                          <RevokeIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    )}
                    <IconButton 
                      size="small"
                      onClick={(e) => handleMenuOpen(e, tablePermission)}
                      aria-label="mais ações"
                      aria-controls="permission-menu"
                      aria-haspopup="true"
                    >
                      <MoreVertIcon fontSize="small" />
                    </IconButton>
                  </Box>
                )}
              </ListItem>
            );
          })}
        </List>
      </Box>
    );
  };

  return (
    <Paper sx={{ p: 3, mt: 1 }}>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
        <Typography variant="h6">
          {String(t('profile:permissions.title'))}
        </Typography>
      </Box>
      <Divider sx={{ mb: 2 }} />
      
      {loading ? (
        <Box display="flex" justifyContent="center" alignItems="center" p={4}>
          <CircularProgress />
        </Box>
      ) : databasePermissions.length === 0 ? (
        <Typography align="center" color="textSecondary" sx={{ py: 4 }}>
          {String(t('profile:permissions.noPermissions'))}
        </Typography>
      ) : (
        <Grid container spacing={2} justifyContent="flex-start" alignItems="stretch">
          {databasePermissions.map((dbPermission, index) => renderDatabaseCard(dbPermission, index))}
        </Grid>
      )}
      
      {/* Database Permission Details Dialog */}
      <Dialog 
        open={dialogOpen} 
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: {
            borderRadius: '12px',
            overflow: 'hidden'
          }
        }}
      >
        {selectedDatabase && (
          <>
            <DialogTitle 
              sx={{ 
                py: 2, 
                background: theme => `linear-gradient(90deg, ${theme.palette.primary.light}, ${theme.palette.primary.main})`,
                color: 'white'
              }}
            >
              {/* Usando div com estilo de h6 para evitar erro de h6 dentro de h2 */}
              <div style={{ 
                fontSize: '1.25rem',
                fontWeight: 600,
                margin: 0,
                lineHeight: 1.6
              }}>
                {selectedDatabase.database}
              </div>
              <Box display="flex" alignItems="center" mt={1}>
                <Chip
                  label={String(t(`permissions:status.${selectedDatabase.status}`))}
                  color={getStatusColor(selectedDatabase.status)}
                  size="small"
                  sx={{ 
                    mr: 1,
                    color: 'white',
                    backgroundColor: theme => selectedDatabase.status === 'active' 
                      ? theme.palette.success.dark 
                      : theme.palette.warning.dark 
                  }}
                />
                
                <Typography variant="body2" sx={{ color: 'rgba(255, 255, 255, 0.85)' }}>
                  {selectedDatabase.expires_at 
                    ? `${String(t('common:expires'))}: ${getFormattedDate(selectedDatabase.expires_at)}`
                    : String(t('permissions:permanent'))}
                </Typography>
              </Box>
            </DialogTitle>
            
            <DialogContent dividers sx={{ px: 0, py: 0 }}>
              <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
                <Tabs 
                  value={tabValue} 
                  onChange={handleChangeTab} 
                  aria-label="permission tabs"
                  variant="fullWidth"
                  sx={{
                    '& .MuiTab-root': {
                      py: 1.5
                    }
                  }}
                >
                  <Tab 
                    icon={<LockIcon />} 
                    iconPosition="start" 
                    label={String(t('access:readOnly'))} 
                    sx={{ color: theme => theme.palette.success.main }}
                  />
                  <Tab 
                    icon={<EditIcon />} 
                    iconPosition="start" 
                    label={String(t('access:readWrite'))} 
                    sx={{ color: theme => theme.palette.warning.main }}
                  />
                  <Tab 
                    icon={<AdminIcon />} 
                    iconPosition="start" 
                    label={String(t('access:admin'))} 
                    sx={{ color: theme => theme.palette.error.main }}
                  />
                </Tabs>
              </Box>
              
              <TabPanel value={tabValue} index={0}>
                {renderTableList(
                  selectedDatabase.readTables,
                  `${String(t('permissions:table.tables'))} ${String(t('common:noData'))}`
                )}
              </TabPanel>
              
              <TabPanel value={tabValue} index={1}>
                {renderTableList(
                  selectedDatabase.writeTables,
                  `${String(t('permissions:table.tables'))} ${String(t('common:noData'))}`
                )}
              </TabPanel>
              
              <TabPanel value={tabValue} index={2}>
                {renderTableList(
                  selectedDatabase.adminTables,
                  `${String(t('permissions:table.tables'))} ${String(t('common:noData'))}`
                )}
              </TabPanel>
            </DialogContent>
            
            <DialogActions sx={{ px: 3, py: 2 }}>
              <Button 
                onClick={handleCloseDialog} 
                variant="contained" 
                color="primary"
              >
                {String(t('common:close'))}
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>
      
      {/* Menu de contexto para ações em permissões */}
      <Menu
        id="permission-menu"
        anchorEl={menuAnchorEl}
        open={Boolean(menuAnchorEl)}
        onClose={handleMenuClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
      >
        {selectedPermission && selectedPermission.status !== 'revoked' && (
          <MenuItem 
            onClick={() => handleConfirmDialogOpen('revoke', selectedPermission)}
            sx={{ color: theme => theme.palette.warning.main }}
          >
            <RevokeIcon fontSize="small" sx={{ mr: 1 }} />
            {String(t('permissions:actions.revoke'))}
          </MenuItem>
        )}
        <MenuItem 
          onClick={() => selectedPermission && handleConfirmDialogOpen('delete', selectedPermission)}
          sx={{ color: theme => theme.palette.error.main }}
        >
          <DeletePermanentlyIcon fontSize="small" sx={{ mr: 1 }} />
          {String(t('permissions:actions.delete'))}
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleMenuClose}>
          <InfoIcon fontSize="small" sx={{ mr: 1 }} />
          {String(t('permissions:actions.details'))}
        </MenuItem>
        <MenuItem onClick={handleMenuClose}>
          <HistoryIcon fontSize="small" sx={{ mr: 1 }} />
          {String(t('permissions:actions.history'))}
        </MenuItem>
      </Menu>
      
      {/* Diálogo de confirmação */}
      <Dialog
        open={confirmDialogOpen}
        onClose={handleConfirmDialogClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle id="alert-dialog-title">
          {confirmDialogTitle}
        </DialogTitle>
        <DialogContent>
          <DialogContentText id="alert-dialog-description">
            {confirmDialogMessage}
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleConfirmDialogClose} color="primary">
            {String(t('common:cancel'))}
          </Button>
          <Button 
            onClick={handleConfirmAction} 
            color={confirmDialogType === 'revoke' ? 'warning' : 'error'} 
            variant="contained" 
            autoFocus
          >
            {confirmDialogType === 'revoke' 
              ? String(t('permissions:actions.revoke'))
              : String(t('permissions:actions.delete'))}
          </Button>
        </DialogActions>
      </Dialog>
      
      {/* Snackbar para mostrar mensagens de sucesso e erro */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={6000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleSnackbarClose} 
          severity={successMessage ? 'success' : 'error'} 
          sx={{ width: '100%' }}
        >
          {successMessage || errorMessage}
        </Alert>
      </Snackbar>
    </Paper>
  );
};

export default UserPermissionsSection;
