import React, { useEffect, useState } from 'react';
import {
  Card,
  CardContent,
  Typography,
  Box,
  Grid,
  LinearProgress,
  Tooltip,
  Chip,
  IconButton,
  Alert,
} from '@mui/material';
import {
  Storage as StorageIcon,
  TrendingUp as TrendingUpIcon,
  Info as InfoIcon,
  Warning as WarningIcon,
  Refresh as RefreshIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import queryAuditService from '../../services/queryAuditService';

interface StorageMetrics {
  table_size: string;
  total_size: string;
  index_size: string;
  total_records: number;
  growth_rate_daily: string;
  growth_rate_monthly: string;
  estimated_days_until_limit: number;
  oldest_record: string;
  newest_record: string;
}

interface QueryAuditStorageMetricsProps {
  serverId: string;
}

export const QueryAuditStorageMetrics: React.FC<QueryAuditStorageMetricsProps> = ({ serverId }) => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const [metrics, setMetrics] = useState<StorageMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchMetrics = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await queryAuditService.getStorageMetrics();
      setMetrics(data);
    } catch (err) {
      setError('Failed to fetch storage metrics');
      console.error('Error fetching storage metrics:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMetrics();
  }, []);

  // const formatBytes = (bytes: number): string => {
  //   if (bytes === 0) return '0 Bytes';
  //   const k = 1024;
  //   const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
  //   const i = Math.floor(Math.log(bytes) / Math.log(k));
  //   return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  // };

  const getStorageWarningLevel = (daysUntilLimit: number): 'success' | 'warning' | 'error' => {
    if (daysUntilLimit > 90) return 'success';
    if (daysUntilLimit > 30) return 'warning';
    return 'error';
  };

  if (loading) {
    return (
      <Card>
        <CardContent>
          <Box display="flex" justifyContent="center" p={3}>
            <LinearProgress style={{ width: '50%' }} />
          </Box>
        </CardContent>
      </Card>
    );
  }

  if (error || !metrics) {
    return (
      <Card>
        <CardContent>
          <Alert severity="error">{error || 'No data available'}</Alert>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardContent>
        <Box display="flex" alignItems="center" justifyContent="space-between" mb={3}>
          <Box display="flex" alignItems="center">
            <StorageIcon color="primary" sx={{ mr: 1 }} />
            <Typography variant="h6">{t('statistics.storageMetrics.title')}</Typography>
            <Tooltip title={t('statistics.storageMetrics.tooltip')}>
              <IconButton size="small" sx={{ ml: 1 }}>
                <InfoIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </Box>
          <IconButton onClick={fetchMetrics} size="small">
            <RefreshIcon />
          </IconButton>
        </Box>

        <Grid container spacing={3}>
          {/* Total Size */}
          <Grid item xs={12} sm={6} md={3}>
            <Box textAlign="center">
              <Typography variant="h4" color="primary">
                {metrics.total_size}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                {t('statistics.storageMetrics.totalSize')}
              </Typography>
              <Typography variant="caption" display="block" mt={1}>
                {t('statistics.storageMetrics.tableSize')}: {metrics.table_size}
              </Typography>
              <Typography variant="caption" display="block">
                {t('statistics.storageMetrics.indexSize')}: {metrics.index_size}
              </Typography>
            </Box>
          </Grid>

          {/* Total Records */}
          <Grid item xs={12} sm={6} md={3}>
            <Box textAlign="center">
              <Typography variant="h4" color="secondary">
                {metrics.total_records.toLocaleString()}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                {t('statistics.storageMetrics.totalRecords')}
              </Typography>
              <Typography variant="caption" display="block" mt={1}>
                {t('statistics.storageMetrics.oldest')}: {new Date(metrics.oldest_record).toLocaleDateString()}
              </Typography>
              <Typography variant="caption" display="block">
                {t('statistics.storageMetrics.newest')}: {new Date(metrics.newest_record).toLocaleDateString()}
              </Typography>
            </Box>
          </Grid>

          {/* Growth Rate */}
          <Grid item xs={12} sm={6} md={3}>
            <Box textAlign="center">
              <Box display="flex" alignItems="center" justifyContent="center">
                <TrendingUpIcon color="action" sx={{ mr: 1 }} />
                <Typography variant="h4">
                  {metrics.growth_rate_daily}
                </Typography>
              </Box>
              <Typography variant="body2" color="textSecondary">
                {t('statistics.storageMetrics.dailyGrowth')}
              </Typography>
              <Typography variant="caption" display="block" mt={1}>
                {t('statistics.storageMetrics.monthlyGrowth')}: {metrics.growth_rate_monthly}
              </Typography>
            </Box>
          </Grid>

          {/* Storage Warning */}
          <Grid item xs={12} sm={6} md={3}>
            <Box textAlign="center">
              <Chip
                icon={<WarningIcon />}
                label={
                  metrics.estimated_days_until_limit > 0
                    ? t('statistics.storageMetrics.daysUntilLimit', { days: metrics.estimated_days_until_limit })
                    : t('statistics.storageMetrics.noLimit')
                }
                color={getStorageWarningLevel(metrics.estimated_days_until_limit)}
                variant="outlined"
              />
              <Typography variant="body2" color="textSecondary" mt={2}>
                {t('statistics.storageMetrics.storageStatus')}
              </Typography>
            </Box>
          </Grid>
        </Grid>

        {/* Storage Usage Bar */}
        <Box mt={3}>
          <Typography variant="body2" gutterBottom>
            {t('statistics.storageMetrics.storageUsage')}
          </Typography>
          <LinearProgress
            variant="determinate"
            value={Math.min((metrics.total_records / 10000000) * 100, 100)} // Assuming 10M records as limit
            sx={{ height: 10, borderRadius: 5 }}
          />
          <Typography variant="caption" color="textSecondary">
            {t('statistics.storageMetrics.recommendation')}
          </Typography>
        </Box>
      </CardContent>
    </Card>
  );
};