const CategoryHeader = styled(Box)(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(2),
  marginBottom: theme.spacing(3),
  paddingBottom: theme.spacing(2),
  borderBottom: `2px solid ${alpha(theme.palette.primary.main, 0.1)}`,
}));

const StatusBadge = styled(Badge)<{ status?: 'active' | 'warning' | 'error' }>(({ theme, status = 'active' }) => ({
  '& .MuiBadge-badge': {
    width: 12,
    height: 12,
    borderRadius: '50%',
    border: `2px solid ${theme.palette.background.paper}`,
    backgroundColor: status === 'active' ? theme.palette.success.main : 
                     status === 'warning' ? theme.palette.warning.main : 
                     theme.palette.error.main,
  }
}));

const ConfigurationPage: React.FC = () => {
  const { t } = useTranslation('settings');
  const theme = useTheme();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [showContent, setShowContent] = useState(false);
  const [systemStatus, setSystemStatus] = useState({
    healthy: true,
    lastCheck: new Date().toLocaleString(),
    issues: 0
  });
  const [configStatuses, setConfigStatuses] = useState<{[key: string]: any}>({});

  useEffect(() => {
    const timer = setTimeout(() => setShowContent(true), 100);
    checkSystemStatus();
    fetchConfigStatuses();
    return () => clearTimeout(timer);
  }, []);


  const checkSystemStatus = async () => {
    try {
      // Simular verificação de status do sistema
      setSystemStatus({
        healthy: true,
        lastCheck: new Date().toLocaleString(),
        issues: 0
      });
    } catch (error) {
      console.error('Error checking system status:', error);
    }
  };

  const fetchConfigStatuses = async () => {
    try {
      // Buscar status do Elasticsearch
      const elasticsearchConfig = await configurationService.getElasticsearchConfig();
      if (elasticsearchConfig.success && elasticsearchConfig.config) {
        setConfigStatuses(prev => ({
          ...prev,
          elasticsearch: {
            configured: elasticsearchConfig.config.enabled,
            enabled: elasticsearchConfig.config.enabled,
            host: elasticsearchConfig.config.host
          }
        }));
      }

      // Buscar status das notificações
      const notificationConfig = await configurationService.getNotificationConfig();
      if (notificationConfig && notificationConfig.notifications) {
        let activeChannels = 0;
        let totalChannels = 2; // Email e Slack
        
        // Verificar se email está ativo
        if (notificationConfig.notifications.email) {
          activeChannels++;
        }
        
        // Verificar se Slack está ativo
        if (notificationConfig.notifications.slack) {
          activeChannels++;
        }
        
        setConfigStatuses(prev => ({
          ...prev,
          notifications: {
            channels: totalChannels,
            active: activeChannels,
            allEnabled: activeChannels === totalChannels
          }
        }));
      }

      // Buscar configuração de interface (idioma e tema)
      try {
        // Buscar idioma atual do localStorage ou do i18n
        const currentLanguage = localStorage.getItem('i18nextLng') || 'en';
        const currentTheme = localStorage.getItem('theme') || 'light';
        
        setConfigStatuses(prev => ({
          ...prev,
          interface: {
            language: currentLanguage,
            theme: currentTheme
          }
        }));
      } catch (err) {
        console.error('Error fetching interface config:', err);
      }

      // Buscar status de sincronização
      try {
        const { syncService } = await import('../../services/syncService');
        
        // Buscar configuração de sync primeiro
        const syncConfig = await syncService.getSyncConfig();
        const isSyncEnabled = syncConfig?.config?.enabled || false;
        
        // Buscar status apenas se sync estiver habilitado
        const syncStatus = await syncService.getSyncStatus();
        
        if (syncStatus && syncStatus.statuses) {
          // Calcular última sincronização
          let lastSyncTime: number | null = null;
          syncStatus.statuses.forEach((status: any) => {
            if (status.last_sync) {
              const syncTime = new Date(status.last_sync).getTime();
              if (lastSyncTime === null || syncTime > lastSyncTime) {
                lastSyncTime = syncTime;
              }
            }
          });

          // Calcular minutos desde última sincronização
          let minutesSinceLastSync = 999999; // Default alto para "nunca sincronizado"
          if (lastSyncTime !== null) {
            minutesSinceLastSync = Math.round((new Date().getTime() - lastSyncTime) / 60000);
          }

          setConfigStatuses(prev => ({
            ...prev,
            sync: {
              enabled: isSyncEnabled,
              databases: syncStatus.statuses.length,
              lastSync: minutesSinceLastSync
            }
          }));
        } else {
          // Se não há status, definir valores padrão
          setConfigStatuses(prev => ({
            ...prev,
            sync: {
              enabled: isSyncEnabled,
              databases: 0,
              lastSync: 999999
            }
          }));
        }
      } catch (err) {
        console.error('Error fetching sync status:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          sync: {
            enabled: false,
            databases: 0,
            lastSync: 999999
          }
        }));
      }

      // Buscar status SSO
      try {
        const ssoConfig = await configurationService.getConfiguration('sso');
        console.log('Raw SSO config response:', ssoConfig);
        
        if (ssoConfig && ssoConfig.ssoProviders) {
          // O SSO agora retorna um objeto ssoProviders único, não uma lista de providers
          const ssoData = ssoConfig.ssoProviders;
          const ssoUserCounts = ssoConfig.ssoUserCounts || {};
          
          // Determinar quantos provedores estão configurados (Google e/ou Microsoft)
          let totalProviders = 2; // Google e Microsoft são os provedores suportados
          let enabledProviders = 0;
          
          // Se o SSO está habilitado e tem clientId configurado, considerar o provider ativo
          if (ssoData.enabled) {
            // Contar como habilitado se tem as configurações necessárias
            if (ssoData.clientId && ssoData.clientSecret) {
              // Se é Google, precisa do domain
              if (ssoData.provider === 'google' && ssoData.domain) {
                enabledProviders = 1;
              }
              // Se é Microsoft, precisa do tenantId
              else if (ssoData.provider === 'microsoft' && ssoData.tenantId) {
                enabledProviders = 1;
              }
            }
          }
          
          // Usar a contagem real de usuários SSO do backend
          const activeUsers = ssoUserCounts.total || 0;
          
          const ssoStatus = {
            providers: totalProviders,
            enabledProviders: enabledProviders,
            activeUsers: activeUsers,
            enabled: ssoData.enabled && enabledProviders > 0,
            currentProvider: ssoData.enabled ? ssoData.provider : null
          };
          
          console.log('SSO Status:', ssoStatus);
          console.log('SSO Data from server:', ssoData);
          
          setConfigStatuses(prev => ({
            ...prev,
            sso: ssoStatus
          }));
        } else {
          // Se não há configuração SSO, definir valores padrão
          console.log('No SSO config found, setting defaults');
          setConfigStatuses(prev => ({
            ...prev,
            sso: {
              providers: 2,
              enabledProviders: 0,
              activeUsers: 0,
              enabled: false
            }
          }));
        }
      } catch (err) {
        console.error('Error fetching SSO config:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          sso: {
            providers: 2,
            enabledProviders: 0,
            activeUsers: 0,
            enabled: false
          }
        }));
      }

      // Buscar status de API Keys
      try {
        console.log('Fetching API keys for stats...');
        const response = await api.get('/api/api-keys');
        console.log('API Keys stats response:', response);
        const apiKeys = response.data || [];
        const activeKeys = apiKeys.filter((key: any) => key.is_active).length;
        
        setConfigStatuses(prev => ({
          ...prev,
          apiKeys: {
            total: apiKeys.length,
            active: activeKeys
          }
        }));
      } catch (err) {
        console.error('Error fetching API keys for stats:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          apiKeys: {
            total: 0,
            active: 0
          }
        }));
      }

      // Buscar status de Secret Managers
      try {
        const secretManagersConfig = await configurationService.getSecretManagersConfig();
        console.log('Secret Managers config:', secretManagersConfig);
        
        // Determinar o provider real baseado nos dados configurados
        let actualProvider = 'local';
        if (secretManagersConfig.enabled) {
          if (secretManagersConfig.aws && secretManagersConfig.aws.region && secretManagersConfig.aws.access_key_id) {
            actualProvider = 'aws';
          } else if (secretManagersConfig.azure && secretManagersConfig.azure.tenant_id) {
            actualProvider = 'azure';
          }
        }
        
        setConfigStatuses(prev => ({
          ...prev,
          secretManagers: {
            configured: secretManagersConfig.enabled && actualProvider !== 'local',
            provider: actualProvider,
            enabled: secretManagersConfig.enabled || false
          }
        }));
      } catch (err) {
        console.error('Error fetching secret managers config:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          secretManagers: {
            configured: false,
            provider: 'local',
            enabled: false
          }
        }));
      }

      // Buscar status do SMTP
      try {
        const smtpConfig = await configurationService.getConfiguration('smtp');
        console.log('SMTP config response:', smtpConfig);
        
        if (smtpConfig && smtpConfig.smtp) {
          const smtp = smtpConfig.smtp;
          // SMTP está configurado se tem server (host) e porta definidos e from_email
          const isConfigured = !!(smtp.server && smtp.port && smtp.from_email);
          
          setConfigStatuses(prev => ({
            ...prev,
            smtp: {
              configured: isConfigured,
              enabled: smtp.use_auth || false,
              host: smtp.server || '',
              port: smtp.port || 0,
              fromEmail: smtp.from_email || '',
              useTLS: smtp.use_tls || false
            }
          }));
        } else {
          // Se não há configuração SMTP, definir valores padrão
          setConfigStatuses(prev => ({
            ...prev,
            smtp: {
              configured: false,
              enabled: false,
              host: '',
              port: 0
            }
          }));
        }
      } catch (err) {
        console.error('Error fetching SMTP config:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          smtp: {
            configured: false,
            enabled: false,
            host: '',
            port: 0
          }
        }));
      }

      // Buscar status de métricas
      try {
        const metricsStatus = await configurationService.getMetricsConfigSummary();
        console.log('Metrics status:', metricsStatus);
        
        setConfigStatuses(prev => ({
          ...prev,
          metrics: {
            configured: metricsStatus.configured,
            servers: metricsStatus.servers,
            configuredServers: metricsStatus.configuredServers
          }
        }));
      } catch (err) {
        console.error('Error fetching metrics config:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          metrics: {
            configured: false,
            servers: 0,
            configuredServers: 0
          }
        }));
      }

      // Buscar status de backup
      try {
        // Buscar configuração de backup
        const backupConfigResponse = await api.get('/api/backup/config');
        const backupConfig = backupConfigResponse.data;
        
        // Buscar histórico de backup para obter o último backup
        const backupHistoryResponse = await api.get('/api/backup/history');
        const backupHistory = backupHistoryResponse.data || [];
        
        // Encontrar o último backup completado com sucesso
        let lastBackupMinutes: number | null = null;
        const completedBackups = backupHistory.filter((backup: any) => backup.status === 'completed');
        if (completedBackups.length > 0) {
          const lastBackup = completedBackups[0]; // Já vem ordenado por data DESC
          if (lastBackup.completed_at) {
            const lastBackupTime = new Date(lastBackup.completed_at).getTime();
            lastBackupMinutes = Math.round((new Date().getTime() - lastBackupTime) / 60000);
          }
        }
        
        setConfigStatuses(prev => ({
          ...prev,
          backup: {
            configured: backupConfig?.enabled || false,
            enabled: backupConfig?.enabled || false,
            type: backupConfig?.backup_type || 'full',
            schedule: backupConfig?.schedule_cron || '',
            lastBackup: lastBackupMinutes,
            s3Enabled: backupConfig?.s3_enabled || false,
            storageType: backupConfig?.storage_type || 'local'
          }
        }));
      } catch (err) {
        console.error('Error fetching backup config:', err);
        // Em caso de erro, definir valores padrão
        setConfigStatuses(prev => ({
          ...prev,
          backup: {
            configured: false,
            enabled: false,
            lastBackup: null
          }
        }));
      }

      // Buscar status da licença
      try {
        const licenseResponse = await api.get('/api/license/info');
        if (licenseResponse.data) {
          const licenseData = licenseResponse.data;
          setConfigStatuses(prev => ({
            ...prev,
            license: {
              configured: true,
              type: licenseData.plan || 'Trial',
              customerId: licenseData.customerId,
              isExpired: licenseData.isExpired || false,
              daysRemaining: licenseData.daysRemaining || 0
            }
          }));
        }
      } catch (err: any) {
        console.error('Error fetching license info:', err);
        // Se não há licença, considerar como Trial
        if (err.response?.status === 404) {
          setConfigStatuses(prev => ({
            ...prev,
            license: {
              configured: false,
              type: 'Trial',
              customerId: 'DEMO',
              isExpired: false,
              daysRemaining: 30
            }
          }));
        }
      }

      // Buscar outros status conforme necessário
    } catch (error) {
      console.error('Error fetching config statuses:', error);
    }
  };

  const handleRefresh = async () => {
    setLoading(true);
    try {
      await Promise.all([
        checkSystemStatus(),
        fetchConfigStatuses()
      ]);
      setSuccessMessage(t('refreshSuccess'));
    } catch (error) {
      console.error('Error refreshing data:', error);
      setError(t('refreshError'));
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string): 'success' | 'warning' | 'error' | 'primary' => {
    switch (status) {
      case 'active':
        return 'success';
      case 'warning':
        return 'warning';
      case 'error':
        return 'error';
      default:
        return 'primary';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'active':
        return <CheckCircleIcon />;
      case 'warning':
        return <WarningIcon />;
      case 'error':
        return <ErrorIcon />;
      default:
        return <ScheduleIcon />;
    }
  };

  // Dados das configurações organizadas por categoria com status dinâmico
  const settingCategories = [
    {
      id: 'core-settings',
      title: 'categories.core',
      icon: <SettingsIcon />,
      description: 'categories.coreDescription',
      settings: [
        {
          id: 'license',
          title: 'sections.license.title',
          description: 'sections.license.description',
          icon: <LicenseIcon />,
          path: '/settings/license',
          status: configStatuses.license?.isExpired ? 'error' : 
                  configStatuses.license?.daysRemaining <= 7 ? 'warning' : 'active',
          stats: { 
            configured: configStatuses.license?.configured || false, 
            type: configStatuses.license?.type || 'Trial',
            daysRemaining: configStatuses.license?.daysRemaining
          }
        },
        {
          id: 'security',
          title: 'sections.security.title',
          description: 'sections.security.description',
          icon: <SecurityIcon />,
          path: '/settings/security',
          status: 'active',
          stats: { configured: true, lastUpdate: 2 }
        },
        {
          id: 'backup',
          title: 'sections.backup.title',
          description: 'sections.backup.description',
          icon: <BackupIcon />,
          path: '/settings/backup',
          status: configStatuses.backup?.configured ? 'active' : 'warning',
          stats: { 
            configured: configStatuses.backup?.configured || false, 
            lastBackup: configStatuses.backup?.lastBackup,
            s3Enabled: configStatuses.backup?.s3Enabled || false,
            storageType: configStatuses.backup?.storageType || 'local'
          }
        }
      ]
    },
    {
      id: 'communication',
      title: 'categories.communication',
      icon: <EmailIcon />,
      description: 'categories.communicationDescription',
      settings: [
        {
          id: 'smtp',
          title: 'sections.smtp.title',
          description: 'sections.smtp.description',
          icon: <EmailIcon />,
          path: '/settings/smtp',
          status: configStatuses.smtp?.configured ? 'active' : 'warning',
          stats: { 
            configured: configStatuses.smtp?.configured || false,
            host: configStatuses.smtp?.host || '',
            port: configStatuses.smtp?.port || 0,
            useTLS: configStatuses.smtp?.useTLS || false
          }
        },
        {
          id: 'notifications',
          title: 'sections.notifications.title',
          description: 'sections.notifications.description',
          icon: <NotificationsIcon />,
          path: '/settings/notifications',
          status: configStatuses.notifications?.active > 0 ? 'active' : 'error',
          stats: { 
            channels: configStatuses.notifications?.channels || 0, 
            active: configStatuses.notifications?.active || 0 
          }
        }
      ]
    },
    {
      id: 'integration',
      title: 'categories.integration',
      icon: <CloudIcon />,
      description: 'categories.integrationDescription',
      settings: [
        {
          id: 'sso',
          title: 'sections.sso.title',
          description: 'sections.sso.description',
          icon: <VerifiedUserIcon />,
          path: '/settings/sso',
          status: configStatuses.sso?.enabled ? 'active' : 'warning',
          stats: { 
            providers: configStatuses.sso?.providers || 0, 
            activeUsers: configStatuses.sso?.activeUsers || 0,
            currentProvider: configStatuses.sso?.currentProvider || null
          }
        },
        {
          id: 'cloud',
          title: 'sections.cloud.title',
          description: 'sections.cloud.description',
          icon: <CloudIcon />,
          path: '/settings/cloud',
          status: 'active',
          stats: {
            providers: 3,
            configured: 0
          }
        },
        {
          id: 'sync',
          title: 'sections.sync.title',
          description: 'sections.sync.description',
          icon: <SyncIcon />,
          path: '/settings/sync',
          status: configStatuses.sync?.enabled ? 'active' : 'warning',
          stats: { 
            lastSync: configStatuses.sync?.lastSync || 999999, 
            databases: configStatuses.sync?.databases || 0 
          }
        },
        {
          id: 'elasticsearch',
          title: 'sections.elasticsearch.title',
          description: 'sections.elasticsearch.description',
          icon: <StorageIcon />,
          path: '/settings/elasticsearch',
          status: configStatuses.elasticsearch?.enabled ? 'active' : 'warning',
          stats: { 
            configured: configStatuses.elasticsearch?.configured || false, 
            enabled: configStatuses.elasticsearch?.enabled || false 
          }
        },
        {
          id: 'apiKeys',
          title: 'sections.apiKeys.title',
          description: 'sections.apiKeys.description',
          icon: <VpnKeyIcon />,
          path: '/settings/api-keys',
          status: 'active', // Sempre ativo pois é uma funcionalidade do sistema
          stats: { 
            keys: configStatuses.apiKeys?.total || 0,
            active: configStatuses.apiKeys?.active || 0
          }
        },
        {
          id: 'secretManagers',
          title: 'sections.secretManagers.title',
          description: 'sections.secretManagers.description',
          icon: <SecretIcon />,
          path: '/settings/secret-managers',
          status: configStatuses.secretManagers?.enabled ? 'active' : 'warning',
          stats: { 
            configured: configStatuses.secretManagers?.configured || false,
            provider: configStatuses.secretManagers?.provider || 'local'
          }
        },
        {
          id: 'metrics',
          title: 'sections.metrics.title',
          description: 'sections.metrics.description',
          icon: <MetricsIcon />,
          path: '/settings/metrics',
          status: configStatuses.metrics?.configured ? 'active' : 'warning',
          stats: { 
            configured: configStatuses.metrics?.configured || false,
            servers: configStatuses.metrics?.servers || 0,
            configuredServers: configStatuses.metrics?.configuredServers || 0
          }
        }
      ]
    },
    {
      id: 'appearance',
      title: 'categories.appearance',
      icon: <PaletteIcon />,
      description: 'categories.appearanceDescription',
      settings: [
        {
          id: 'interface',
          title: 'sections.interface.title',
          description: 'sections.interface.description',
          icon: <ViewQuiltIcon />,
          path: '/settings/interface',
          status: 'active',
          stats: { 
            theme: configStatuses.interface?.theme || 'light', 
            language: configStatuses.interface?.language || 'en' 
          }
        }
      ]
    }
  ];

  return (
    <Fade in={showContent} timeout={800}>
      <Box sx={{ width: '100%', px: 3, py: 2 }}>
        <Snackbar 
          open={!!successMessage} 
          autoHideDuration={6000} 
          onClose={() => setSuccessMessage(null)}
          anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
        >
          <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
            {successMessage}
          </Alert>
        </Snackbar>

        {/* Header */}
        <Box mb={4}>
          <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2}>
            <Box>
              <Typography variant="h4" fontWeight="bold" gutterBottom>
                {t('title')}
              </Typography>
              <Typography variant="body1" color="text.secondary">
                {t('subtitle')}
              </Typography>
            </Box>
            <Button
              variant="contained"
              startIcon={loading ? <CircularProgress size={20} /> : <RefreshIcon />}
              onClick={handleRefresh}
              disabled={loading}
              sx={{
                borderRadius: 2,
                px: 3,
              }}
            >
              {t('common:refresh')}
            </Button>
          </Stack>

          {/* System Status Bar */}
          <Paper 
            sx={{ 
              p: 3, 
              borderRadius: 2,
              background: systemStatus.healthy 
                ? alpha(theme.palette.success.main, 0.05)
                : alpha(theme.palette.error.main, 0.05),
              border: `1px solid ${systemStatus.healthy 
                ? alpha(theme.palette.success.main, 0.2)
                : alpha(theme.palette.error.main, 0.2)}`
            }}
          >
            <Stack direction="row" alignItems="center" spacing={2}>
              <StatusBadge status={systemStatus.healthy ? 'active' : 'error'} variant="dot">
                <Avatar sx={{ bgcolor: 'transparent' }}>
                  {systemStatus.healthy ? <CheckCircleIcon color="success" /> : <ErrorIcon color="error" />}
                </Avatar>
              </StatusBadge>
              <Box flex={1}>
                <Typography variant="h6" fontWeight="medium">
                  {systemStatus.healthy 
                    ? t('status.healthy')
                    : t('status.issues')}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {t('status.lastCheck')}: {systemStatus.lastCheck}
                </Typography>
              </Box>
              {systemStatus.issues > 0 && (
                <Chip 
                  label={`${systemStatus.issues} ${t('status.issuesCount')}`}
                  color="error"
                  size="small"
                />
              )}
            </Stack>
          </Paper>
        </Box>

        {/* Settings Categories */}
        {settingCategories.map((category, categoryIndex) => (
          <Grow key={category.id} in={showContent} timeout={800 + categoryIndex * 100}>
            <Box mb={6}>
              <CategoryHeader>
                <Avatar sx={{ bgcolor: alpha(theme.palette.primary.main, 0.1), color: 'primary.main' }}>
                  {category.icon}
                </Avatar>
                <Box>
                  <Typography variant="h5" fontWeight="bold">
                    {t(category.title)}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {t(category.description)}
                  </Typography>
                </Box>
              </CategoryHeader>

              <Grid container spacing={3}>
                {category.settings.map((setting, settingIndex) => (
                  <Grid item xs={12} sm={6} md={4} lg={3} xl={3} key={setting.id}>
                    <Grow in={showContent} timeout={1000 + categoryIndex * 100 + settingIndex * 50}>
                      <StyledCard>
                        <CardContent sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                          <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                            <IconWrapper color={getStatusColor(setting.status) as any}>
                              {setting.icon}
                            </IconWrapper>
                            <Chip
                              icon={getStatusIcon(setting.status)}
                              label={t(`status.${setting.status}`)}
                              color={getStatusColor(setting.status) as any}
                              size="small"
                            />
                          </Box>

                          <Typography variant="h6" fontWeight="bold" gutterBottom>
                            {t(setting.title)}
                          </Typography>
                          
                          <Typography variant="body2" color="text.secondary" paragraph sx={{ flex: 1 }}>
                            {t(setting.description)}
                          </Typography>

                          {/* Stats */}
                          <Box mb={2}>
                            {Object.entries(setting.stats)
                              .filter(([key, value]) => {
                                // Não mostrar currentProvider se for null
                                if (key === 'currentProvider' && !value) return false;
                                // Não mostrar daysRemaining se for undefined
                                if (key === 'daysRemaining' && value === undefined) return false;
                                return true;
                              })
                              .map(([key, value]) => {
                              let displayValue = String(value);
                              // Format specific stats
                              if (key === 'lastUpdate' && typeof value === 'number') {
                                displayValue = value + ' ' + t('stats.daysText');
                              } else if (key === 'retention' && typeof value === 'number') {
                                displayValue = value + ' ' + t('stats.days');
                              } else if (key === 'lastTest' && typeof value === 'number') {
                                displayValue = value === 1 ? t('stats.yesterday') : value + ' ' + t('stats.daysText');
                              } else if (key === 'lastSync' && typeof value === 'number') {
                                if (value > 10000) {
                                  displayValue = t('stats.neverSynced') || 'Never';
                                } else {
                                  displayValue = value + ' ' + t('stats.minutesText');
                                }
                              } else if (key === 'lastBackup') {
                                if (value === null || value === undefined) {
                                  displayValue = t('stats.neverBackedUp') || 'Never';
                                } else if (typeof value === 'number') {
                                  if (value < 60) {
                                    displayValue = value + ' ' + t('stats.minutesText');
                                  } else if (value < 1440) {
                                    const hours = Math.floor(value / 60);
                                    displayValue = hours + ' ' + (hours === 1 ? t('stats.hour') : t('stats.hours'));
                                  } else {
                                    const days = Math.floor(value / 1440);
                                    displayValue = days + ' ' + (days === 1 ? t('stats.day') : t('stats.daysText'));
                                  }
                                }
                              } else if (key === 'storageType' && value) {
                                if (value === 's3') {
                                  displayValue = 'Amazon S3';
                                } else if (value === 'local') {
                                  displayValue = t('stats.storageLocal') || 'Local';
                                } else {
                                  displayValue = String(value).charAt(0).toUpperCase() + String(value).slice(1);
                                }
                              } else if (key === 'theme' && value === 'light') {
                                displayValue = t('stats.themeLight');
                              } else if (key === 'language') {
                                if (value === 'pt') {
                                  displayValue = t('stats.languagePT');
                                } else if (value === 'en') {
                                  displayValue = t('stats.languageEN');
                                }
                              } else if (key === 'currentProvider' && value) {
                                // Capitalizar o nome do provedor
                                displayValue = String(value).charAt(0).toUpperCase() + String(value).slice(1);
                              } else if (key === 'provider' && value) {
                                // Formatar o nome do provedor de secret managers
                                if (value === 'aws') {
                                  displayValue = 'AWS Secrets Manager';
                                } else if (value === 'azure') {
                                  displayValue = 'Azure Key Vault';
                                } else if (value === 'local') {
                                  displayValue = t('stats.providerLocal') || 'Local';
                                } else {
                                  displayValue = String(value).charAt(0).toUpperCase() + String(value).slice(1);
                                }
                              } else if (key === 'type' && value) {
                                // Formatar o tipo de licença
                                const licenseType = String(value);
                                if (licenseType.toLowerCase() === 'trial') {
                                  displayValue = 'Trial';
                                } else if (licenseType.toLowerCase() === 'basic') {
                                  displayValue = 'Basic';
                                } else if (licenseType.toLowerCase() === 'professional') {
                                  displayValue = 'Professional';
                                } else if (licenseType.toLowerCase() === 'enterprise') {
                                  displayValue = 'Enterprise';
                                } else {
                                  displayValue = licenseType.charAt(0).toUpperCase() + licenseType.slice(1);
                                }
                              } else if (key === 'daysRemaining' && typeof value === 'number') {
                                if (value <= 0) {
                                  displayValue = t('stats.expired') || 'Expired';
                                } else if (value === 1) {
                                  displayValue = t('stats.lastDay') || '1 day';
                                } else {
                                  displayValue = value + ' ' + t('stats.days');
                                }
                              } else if (typeof value === 'boolean') {
                                displayValue = value ? t('common:yes') : t('common:no');
                              }
                              
                              return (
                                <Box key={key} display="flex" justifyContent="space-between" alignItems="center" mb={0.5}>
                                  <Typography variant="caption" color="text.secondary">
                                    {t(`stats.${key}`)}:
                                  </Typography>
                                  <Typography variant="caption" fontWeight="medium">
                                    {displayValue}
                                  </Typography>
                                </Box>
                              );
                            })}
                          </Box>

                          <Button
                            variant="text"
                            color="primary"
                            endIcon={<ArrowForwardIcon className="card-arrow" sx={{ transition: 'transform 0.2s' }} />}
                            component={RouterLink}
                            to={setting.path}
                            sx={{ 
                              mt: 'auto',
                              alignSelf: 'flex-start',
                              fontWeight: 'medium',
                            }}
                          >
                            {t('configure')}
                          </Button>
                        </CardContent>
                      </StyledCard>
                    </Grow>
                  </Grid>
                ))}
              </Grid>
            </Box>
          </Grow>
        ))}

        {error && (
          <Alert severity="error" sx={{ mt: 3 }}>
            {error}
          </Alert>
        )}
      </Box>
    </Fade>
  );
};

export default ConfigurationPage;
