import React, { useEffect, useState, useCallback } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
} from '@mui/material';
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts';
import { useTranslation } from 'react-i18next';
import queryAuditService, { QueryAuditSummary } from '../../services/queryAuditService';
import { QueryAuditStorageMetrics } from './QueryAuditStorageMetrics';

interface QueryAuditStatisticsProps {
  serverId: string;
  serverName: string;
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8', '#82CA9D'];

export const QueryAuditStatistics: React.FC<QueryAuditStatisticsProps> = ({
  serverId,
  serverName,
}) => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const [loading, setLoading] = useState(true);
  const [summary, setSummary] = useState<QueryAuditSummary | null>(null);
  const [hours] = useState(24);

  const loadSummary = useCallback(async () => {
    try {
      setLoading(true);
      const data = await queryAuditService.getQuerySummary(serverId, hours);
      setSummary(data);
    } catch (error) {
      console.error('Error loading query summary:', error);
    } finally {
      setLoading(false);
    }
  }, [serverId, hours]);

  useEffect(() => {
    loadSummary();
  }, [serverId, hours, loadSummary]);

  const formatDuration = (ms: number) => {
    if (ms < 1000) return `${ms.toFixed(0)}ms`;
    if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
    return `${(ms / 60000).toFixed(1)}m`;
  };

  const formatNumber = (num: number) => {
    return num.toLocaleString();
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" p={4}>
        <CircularProgress />
      </Box>
    );
  }

  if (!summary) {
    return (
      <Box p={2}>
        <Typography>{t('queryAudit:noDataAvailable')}</Typography>
      </Box>
    );
  }

  // Prepare data for charts
  const queryTypeData = Object.entries(summary.query_type_breakdown || {}).map(([type, count]) => ({
    name: type,
    value: count,
  }));

  const topUsersData = summary.top_users || [];

  return (
    <Box>
      {/* Summary Cards */}
      <Grid container spacing={3} mb={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:statistics.totalQueries')}
              </Typography>
              <Typography variant="h4">
                {formatNumber(summary.total_queries)}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                {t('queryAudit:statistics.lastHours', { hours })}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:statistics.uniqueUsers')}
              </Typography>
              <Typography variant="h4">
                {formatNumber(summary.unique_users)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:statistics.avgExecutionTime')}
              </Typography>
              <Typography variant="h4">
                {formatDuration(summary.avg_execution_time_ms)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                {t('queryAudit:statistics.errorCount')}
              </Typography>
              <Typography variant="h4" color="error">
                {formatNumber(summary.error_count)}
              </Typography>
              {summary.total_queries > 0 && (
                <Typography variant="caption" color="textSecondary">
                  {((summary.error_count / summary.total_queries) * 100).toFixed(1)}%
                </Typography>
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Storage Metrics */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12}>
          <QueryAuditStorageMetrics serverId={serverId} />
        </Grid>
      </Grid>

      {/* Charts */}
      <Grid container spacing={3}>
        {/* Query Type Distribution */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                {t('queryAudit:statistics.queryTypeDistribution')}
              </Typography>
              {queryTypeData.length > 0 ? (
                <ResponsiveContainer width="100%" height={300}>
                  <PieChart>
                    <Pie
                      data={queryTypeData}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                      outerRadius={80}
                      fill="#8884d8"
                      dataKey="value"
                    >
                      {queryTypeData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <Typography color="textSecondary">{t('queryAudit:noDataAvailable')}</Typography>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Top Users */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                {t('queryAudit:statistics.topUsers')}
              </Typography>
              {topUsersData.length > 0 ? (
                <ResponsiveContainer width="100%" height={300}>
                  <BarChart data={topUsersData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="username" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="query_count" fill="#8884d8" name={t('queryAudit:statistics.queries') as string} />
                    <Bar dataKey="error_count" fill="#ff8042" name={t('queryAudit:statistics.errors') as string} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <Typography color="textSecondary">{t('queryAudit:noDataAvailable')}</Typography>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Top Users Table */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                {t('queryAudit:statistics.userActivity')}
              </Typography>
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>{t('queryAudit:statistics.username')}</TableCell>
                      <TableCell align="right">{t('queryAudit:statistics.queryCount')}</TableCell>
                      <TableCell align="right">{t('queryAudit:statistics.errorCount')}</TableCell>
                      <TableCell align="right">{t('queryAudit:statistics.avgDuration')}</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {(summary.top_users || []).map((user) => (
                      <TableRow key={user.username}>
                        <TableCell>{user.username}</TableCell>
                        <TableCell align="right">{formatNumber(user.query_count)}</TableCell>
                        <TableCell align="right">
                          {user.error_count > 0 ? (
                            <Chip
                              label={formatNumber(user.error_count)}
                              color="error"
                              size="small"
                            />
                          ) : (
                            '0'
                          )}
                        </TableCell>
                        <TableCell align="right">{formatDuration(user.avg_duration_ms)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </CardContent>
          </Card>
        </Grid>

        {/* Slowest Queries */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                {t('queryAudit:statistics.slowestQueries')}
              </Typography>
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>{t('queryAudit:statistics.query')}</TableCell>
                      <TableCell>{t('queryAudit:statistics.type')}</TableCell>
                      <TableCell>{t('queryAudit:statistics.user')}</TableCell>
                      <TableCell align="right">{t('queryAudit:statistics.duration')}</TableCell>
                      <TableCell>{t('queryAudit:statistics.executedAt')}</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {(summary.top_queries || []).slice(0, 10).map((query, index) => (
                      <TableRow key={query.id || index}>
                        <TableCell>
                          <Typography variant="body2" style={{ 
                            maxWidth: 400, 
                            overflow: 'hidden', 
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap' 
                          }}>
                            {query.query_text}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <Chip label={query.query_type} size="small" />
                        </TableCell>
                        <TableCell>{query.username}</TableCell>
                        <TableCell align="right">
                          <Chip
                            label={formatDuration(query.execution_time_ms || 0)}
                            color={query.execution_time_ms && query.execution_time_ms > 5000 ? 'error' : 'default'}
                            size="small"
                          />
                        </TableCell>
                        <TableCell>
                          {new Date(query.executed_at).toLocaleString()}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default QueryAuditStatistics;