import { apiClient as api } from './api';

export interface QueryAuditConfig {
  id?: string;
  server_id: string;
  server_name?: string;
  enabled: boolean;
  retention_days: number;
  excluded_users: string[];
  excluded_query_patterns: string[];
  min_duration_ms: number;
  capture_select: boolean;
  capture_insert: boolean;
  capture_update: boolean;
  capture_delete: boolean;
  capture_ddl: boolean;
  capture_dcl: boolean;
  created_at?: string;
  updated_at?: string;
}

export interface QueryAuditLog {
  id: string;
  server_id: string;
  server_name?: string;
  query_hash: string;
  query_text: string;
  query_type: string;
  username: string;
  database_name?: string;
  schema_name?: string;
  table_names?: string[];
  execution_time_ms?: number;
  rows_affected?: number;
  error_code?: string;
  error_message?: string;
  client_address?: string;
  application_name?: string;
  parameters?: any;
  executed_at: string;
  captured_at: string;
  metadata?: any;
}

export interface QueryAuditFilter {
  server_id?: string;
  username?: string;
  query_type?: string;
  start_date?: string;
  end_date?: string;
  min_duration?: number;
  has_error?: boolean;
  search_text?: string;
  limit?: number;
  offset?: number;
}

export interface QueryAuditSummary {
  total_queries: number;
  unique_users: number;
  error_count: number;
  avg_execution_time_ms: number;
  query_type_breakdown: Record<string, number>;
  top_users: UserQueryStats[];
  top_queries: QueryAuditLog[];
  recent_alerts: QueryAuditAlert[];
}

export interface UserQueryStats {
  username: string;
  query_count: number;
  error_count: number;
  avg_duration_ms: number;
}

export interface QueryAuditAlert {
  id: string;
  server_id: string;
  server_name?: string;
  alert_type: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  query_audit_log_id?: string;
  alert_message: string;
  details?: any;
  acknowledged: boolean;
  acknowledged_by?: string;
  acknowledged_by_name?: string;
  acknowledged_by_email?: string;
  acknowledged_at?: string;
  created_at: string;
}

export interface CollectionStatus {
  servers: ServerCollectionStatus[];
  active_count: number;
  total_servers: number;
  total_queries: number;
  collector_types: string[];
}

export interface ServerCollectionStatus {
  id: string;
  name: string;
  type: string;
  enabled: boolean;
  retention_days?: number;
  query_count: number;
  last_collected?: string;
  collecting: boolean;
}

class QueryAuditService {
  // Configuration
  async getConfig(serverId: string): Promise<QueryAuditConfig> {
    const response = await api.get(`/api/query-audit/config/${serverId}`);
    return response.data;
  }

  async saveConfig(serverId: string, config: Partial<QueryAuditConfig>): Promise<QueryAuditConfig> {
    const response = await api.post(`/api/query-audit/config/${serverId}`, config);
    return response.data;
  }

  async enableAuditing(serverId: string): Promise<void> {
    await api.post(`/api/query-audit/enable/${serverId}`);
  }

  // Query Logs
  async getQueryLogs(filter: QueryAuditFilter): Promise<{ logs: QueryAuditLog[]; total: number }> {
    const response = await api.get('/api/query-audit/logs', { params: filter });
    return response.data;
  }

  // Summary and Statistics
  async getQuerySummary(serverId: string, hours: number = 24): Promise<QueryAuditSummary> {
    const response = await api.get(`/api/query-audit/summary/${serverId}`, { params: { hours } });
    return response.data;
  }

  // Alerts
  async getAlerts(serverId?: string, unacknowledgedOnly: boolean = false, limit: number = 25, offset: number = 0): Promise<{
    alerts: QueryAuditAlert[];
    total_count: number;
    total_pages: number;
    current_page: number;
    limit: number;
    offset: number;
  }> {
    const params: any = { 
      unacknowledged_only: unacknowledgedOnly,
      limit: limit,
      offset: offset
    };
    if (serverId) {
      params.server_id = serverId;
    }
    const response = await api.get('/api/query-audit/alerts', { params });
    return response.data;
  }

  async acknowledgeAlert(alertId: string): Promise<void> {
    await api.post(`/api/query-audit/alerts/${alertId}/acknowledge`);
  }

  async whitelistQuery(alertId: string): Promise<void> {
    await api.post(`/api/query-audit/alerts/${alertId}/whitelist`);
  }

  async clearAlerts(serverId: string, limit: number = 25, acknowledgedOnly: boolean = false): Promise<{ cleared_count: number }> {
    const params = new URLSearchParams({
      server_id: serverId,
      limit: limit.toString(),
      acknowledged_only: acknowledgedOnly.toString(),
    });
    
    const response = await api.post(`/api/query-audit/alerts/clear?${params.toString()}`);
    return response.data;
  }

  // Collection
  async getCollectionStatus(): Promise<CollectionStatus> {
    const response = await api.get('/api/query-audit/collection/status');
    return response.data;
  }

  async triggerCollection(serverId: string): Promise<void> {
    await api.post(`/api/query-audit/collection/trigger/${serverId}`);
  }

  async checkPrerequisites(serverId: string): Promise<any> {
    const response = await api.get(`/api/query-audit/prerequisites/${serverId}`);
    console.log('API prerequisites response:', response);
    return response.data;
  }

  // Storage Metrics
  async getStorageMetrics(): Promise<any> {
    const response = await api.get('/api/query-audit/storage-metrics');
    return response.data;
  }
}

const queryAuditService = new QueryAuditService();
export default queryAuditService;