import { useReducer, useEffect, useCallback } from 'react';
import { requestFormReducer, initialState } from '../requestFormReducer';
import { RequestFormState, DatabaseType, User, DatabaseServer, Database, DatabaseInfo } from '../types';

/**
 * Hook personalizado para gerenciar o estado e lógica do formulário de solicitação
 */
export const useRequestForm = (
  currentUser?: User,
  defaultServer?: { id: string; name: string; type: string }
) => {
  // Inicializar o reducer
  const [state, dispatch] = useReducer(requestFormReducer, initialState);

  // Debug log para rastrear currentUser
  console.log('=== useRequestForm hook initialized ===');
  console.log('currentUser prop received:', currentUser);
  console.log('defaultServer prop received:', defaultServer);

  // Carregar dados iniciais quando o componente monta
  useEffect(() => {
    const initialize = async () => {
      dispatch({ type: 'SET_LOADING', payload: true });

      try {
        // Debug log dentro do useEffect
        console.log('=== useEffect initialize ===');
        console.log('currentUser in useEffect:', currentUser);
        
        // Inicializar com o usuário atual se disponível
        if (currentUser) {
          dispatch({
            type: 'INITIALIZE_FORM',
            payload: { userId: currentUser.id }
          });
          
          // Carregar lista de usuários somente se tivermos currentUser
          await fetchUsers(currentUser);
        } else {
          // Se não temos currentUser, carregar apenas do localStorage
          console.log('No currentUser provided, loading from localStorage only');
          await fetchUsers();
        }

        // Carregar servidores
        await fetchServers();

        // Se temos um servidor padrão, inicializar com ele
        if (defaultServer) {
          dispatch({
            type: 'INITIALIZE_FORM',
            payload: {
              serverId: defaultServer.id
            }
          });

          // Determinar o tipo de banco de dados
          const dbType = defaultServer.type.toLowerCase() === 'postgres'
            ? DatabaseType.POSTGRESQL
            : defaultServer.type.toLowerCase() === 'mssql'
              ? DatabaseType.MSSQL
              : defaultServer.type.toLowerCase() === 'oracle'
                ? DatabaseType.ORACLE
                : DatabaseType.MYSQL;

          dispatch({ type: 'SET_DATABASE_TYPE', payload: dbType });

          // Carregar dados dependentes
          await fetchDatabases(defaultServer.id);
        }
      } catch (error) {
        console.error('Error initializing form:', error);
      } finally {
        dispatch({ type: 'SET_LOADING', payload: false });
      }
    };

    initialize();
  }, [defaultServer]); // Removido currentUser para evitar loops
  
  // Efeito separado para quando currentUser mudar
  useEffect(() => {
    if (currentUser && currentUser.id) {
      console.log('=== currentUser changed, reloading users ===');
      console.log('New currentUser:', currentUser);
      fetchUsers(currentUser);
    }
  }, [currentUser]);

  // Função para buscar usuários
  const fetchUsers = async (userParam?: User) => {
    // Usar o parâmetro passado ou o currentUser do escopo
    const effectiveUser = userParam || currentUser;
    console.log('=== fetchUsers called ===');
    console.log('currentUser from scope:', currentUser);
    console.log('userParam passed:', userParam);
    console.log('effectiveUser to use:', effectiveUser);
    
    dispatch({ type: 'SET_LOADING', payload: true });

    try {
      // Check if current user is a requester
      const authService = await import('../../../services/auth').then(m => m.authService);
      const isRequester = await authService.hasRole('requester');
      console.log('Current user role check - isRequester:', isRequester);

      // Verificar se o usuário atual está disponível
      console.log('Effective user available?', !!effectiveUser);
      console.log('Effective user data:', effectiveUser);
      
      if (effectiveUser) {
        console.log('Current user exists, checking role...');
        if (isRequester) {
          // Se for requester, mostrar o próprio usuário e usuários de serviço
          const users = [{
            id: effectiveUser.id,
            username: effectiveUser.username,
            email: effectiveUser.email || ''
          }];
          
          // Buscar também usuários de serviço para requesters
          try {
            const { userService } = await import('../../../services/api');
            console.log('Fetching service users for requester...');
            const serviceUsersResponse = await userService.getServiceUsersForRequest();
            console.log('Service users for requester response:', serviceUsersResponse);
            
            if (serviceUsersResponse && Array.isArray(serviceUsersResponse)) {
              const serviceUsers = serviceUsersResponse.map((su: any) => ({
                id: su.id,
                username: su.username,
                email: 'serviceuser@dbmanager.local',
                is_service_user: true
              }));
              console.log('Formatted service users for requester:', serviceUsers);
              users.push(...serviceUsers);
            }
          } catch (error) {
            console.error('Error fetching service users for requester:', error);
          }
          
          console.log('Final users list (requester):', users);
          dispatch({ type: 'SET_USERS', payload: users });
          // Definir o usuário atual no formulário
          dispatch({ type: 'SET_USER', payload: effectiveUser.id });
        } else {
          // Se não for requester, buscar todos os usuários
          console.log('Entering non-requester block to fetch all users');
          try {
            const { userService } = await import('../../../services/api');
            console.log('userService imported successfully');
            console.log('Fetching all users...');
            const response = await userService.getUsers();
            console.log('Users API response:', response);
            let allUsers: any[] = [];

            if (response && Array.isArray(response.users)) {
              const formattedUsers = response.users.map((user: any) => ({
                id: user.id,
                username: user.username,
                email: user.email || ''
              }));
              allUsers = [...formattedUsers];
              console.log('Formatted regular users:', formattedUsers);
            } else if (response && Array.isArray(response)) {
              // Caso a resposta seja diretamente um array
              const formattedUsers = response.map((user: any) => ({
                id: user.id,
                username: user.username,
                email: user.email || ''
              }));
              allUsers = [...formattedUsers];
              console.log('Formatted regular users (direct array):', formattedUsers);
            } else {
              console.log('Unexpected users response format:', response);
            }
            
            // Buscar também usuários de serviço
            try {
              console.log('Fetching service users...');
              const serviceUsersResponse = await userService.getServiceUsers();
              console.log('Service users response:', serviceUsersResponse);
              
              if (serviceUsersResponse && Array.isArray(serviceUsersResponse.service_users)) {
                const serviceUsers = serviceUsersResponse.service_users.map((su: any) => ({
                  id: su.id,
                  username: su.username,
                  email: 'serviceuser@dbmanager.local',
                  is_service_user: true
                }));
                console.log('Formatted service users:', serviceUsers);
                allUsers.push(...serviceUsers);
              } else if (serviceUsersResponse && Array.isArray(serviceUsersResponse)) {
                // Caso a resposta seja diretamente um array
                const serviceUsers = serviceUsersResponse.map((su: any) => ({
                  id: su.id,
                  username: su.username,
                  email: 'serviceuser@dbmanager.local',
                  is_service_user: true
                }));
                console.log('Formatted service users (direct array):', serviceUsers);
                allUsers.push(...serviceUsers);
              }
            } catch (error) {
              console.error('Error fetching service users:', error);
            }

            if (allUsers.length > 0) {
              console.log('Final users list (non-requester):', allUsers);
              dispatch({ type: 'SET_USERS', payload: allUsers });
              dispatch({ type: 'SET_USER', payload: effectiveUser.id });
            } else {
              // Se a API não retornar usuários, usar apenas o atual
              dispatch({
                type: 'SET_USERS',
                payload: [{
                  id: effectiveUser.id,
                  username: effectiveUser.username,
                  email: effectiveUser.email || ''
                }]
              });
              dispatch({ type: 'SET_USER', payload: effectiveUser.id });
            }
          } catch (error) {
            console.error('Error fetching users - details:', error);
            console.error('Error stack:', error instanceof Error ? error.stack : 'No stack trace');
            // Em caso de erro, usar o usuário atual
            dispatch({
              type: 'SET_USERS',
              payload: [{
                id: effectiveUser.id,
                username: effectiveUser.username,
                email: effectiveUser.email || ''
              }]
            });
            dispatch({ type: 'SET_USER', payload: effectiveUser.id });
          }
        }
      } else {
        // Tentar obter o usuário atual do localStorage se não fornecido como prop
        try {
          const userStr = localStorage.getItem('currentUser');
          if (userStr) {
            const user = JSON.parse(userStr);
            if (user && user.id && user.username) {
              // Criar objeto de usuário a partir dos dados do localStorage
              const localUser = {
                id: user.id,
                username: user.username,
                email: user.email || ''
              };

              if (isRequester) {
                dispatch({ type: 'SET_USERS', payload: [localUser] });
                dispatch({ type: 'SET_USER', payload: localUser.id });
              } else {
                // Se não for requester, tentar buscar todos os usuários
                try {
                  const { userService } = await import('../../../services/api');
                  const response = await userService.getUsers();

                  if (response && Array.isArray(response.users)) {
                    const formattedUsers = response.users.map((user: any) => ({
                      id: user.id,
                      username: user.username,
                      email: user.email || ''
                    }));

                    dispatch({ type: 'SET_USERS', payload: formattedUsers });
                    dispatch({ type: 'SET_USER', payload: localUser.id });
                  } else {
                    dispatch({ type: 'SET_USERS', payload: [localUser] });
                    dispatch({ type: 'SET_USER', payload: localUser.id });
                  }
                } catch (error) {
                  console.error('Error fetching users:', error);
                  dispatch({ type: 'SET_USERS', payload: [localUser] });
                  dispatch({ type: 'SET_USER', payload: localUser.id });
                }
              }
            } else {
              throw new Error('Invalid user data in localStorage');
            }
          } else {
            throw new Error('No user data in localStorage');
          }
        } catch (error) {
          console.error('Error getting user from localStorage:', error);
          dispatch({
            type: 'SET_ERRORS',
            payload: { userId: 'Authentication error. Please log in again.' }
          });
        }
      }
    } catch (error) {
      console.error('Error in fetchUsers:', error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { userId: 'Failed to load users. Please try again later.' }
      });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Função para buscar servidores
  const fetchServers = async () => {
    dispatch({ type: 'SET_LOADING', payload: true });

    try {
      const { serverService } = await import('../../../services/api');
      const response = await serverService.getServers();

      console.log("Resposta da API de servidores:", response);

      // Verificar diferentes formatos de resposta possíveis
      if (response && Array.isArray(response.servers)) {
        // Nova API retorna servers
        const formattedServers = response.servers.map((server: any) => ({
          id: server.id,
          name: server.name,
          type: server.type || 'unknown',
          host: server.host || '',
          port: server.port,
          environment: server.environment, // Incluir ambiente
          databases: server.databases || [] // Incluir bancos de dados se disponíveis
        }));

        console.log("Servidores formatados:", formattedServers);
        dispatch({ type: 'SET_SERVERS', payload: formattedServers });
      } else if (response && Array.isArray(response.databases)) {
        // API legada retorna databases (agora servers)
        const formattedServers = response.databases.map((server: any) => ({
          id: server.id,
          name: server.name,
          type: server.type || 'unknown',
          host: server.host || '',
          port: server.port,
          environment: server.environment // Incluir ambiente
        }));

        console.log("Servidores formatados (legado):", formattedServers);
        dispatch({ type: 'SET_SERVERS', payload: formattedServers });
      } else if (Array.isArray(response)) {
        // Caso seja retornado um array diretamente
        const formattedServers = response.map((server: any) => ({
          id: server.id,
          name: server.name,
          type: server.type || 'unknown',
          host: server.host || '',
          port: server.port,
          environment: server.environment, // Incluir ambiente
          databases: server.databases || []
        }));

        console.log("Servidores formatados (array direto):", formattedServers);
        dispatch({ type: 'SET_SERVERS', payload: formattedServers });
      } else {
        console.warn("Formato de resposta não reconhecido:", response);
        dispatch({
          type: 'SET_ERRORS',
          payload: { serverId: 'No database servers found. Please contact your administrator.' }
        });
        dispatch({ type: 'SET_SERVERS', payload: [] });
      }
    } catch (error) {
      console.error('Error fetching servers:', error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { serverId: 'Failed to load database servers. Please try again later.' }
      });
      dispatch({ type: 'SET_SERVERS', payload: [] });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Função para buscar bancos de dados
  const fetchDatabases = async (serverId: string) => {
    if (!serverId) return;

    dispatch({ type: 'SET_LOADING', payload: true });

    try {
      // Identificar o tipo de banco de dados
      const selectedServer = state.servers.find(s => s.id === serverId);

      if (!selectedServer) {
        console.error(`Server with ID ${serverId} not found`);
        dispatch({
          type: 'SET_ERRORS',
          payload: { serverId: 'Server not found.' }
        });
        dispatch({ type: 'SET_DATABASES', payload: [] });
        return;
      }

      // Definir o tipo de banco de dados com base no servidor
      const dbType = selectedServer.type.toLowerCase() === 'postgres'
        ? DatabaseType.POSTGRESQL
        : selectedServer.type.toLowerCase() === 'mssql'
          ? DatabaseType.MSSQL
          : selectedServer.type.toLowerCase() === 'oracle'
            ? DatabaseType.ORACLE
            : DatabaseType.MYSQL;

      dispatch({ type: 'SET_DATABASE_TYPE', payload: dbType });

      // Usar o novo serviço de servidor
      const { serverService } = await import('../../../services/api');
      const response = await serverService.getServer(serverId);

      // Verificar o formato da resposta
      if (response && response.server) {
        // Nova estrutura: response.server
        console.log("Usando novo formato de resposta: response.server");

        // Verificar se o servidor tem bancos de dados
        if (response.server.databases && Array.isArray(response.server.databases)) {
          console.log("Bancos encontrados no servidor:", response.server.databases);

          // Mapear bancos para o formato que o formulário espera
          const databasesList = response.server.databases.map((db: DatabaseInfo) => ({
            id: `${serverId}:${db.name}`, // ID composto para referência
            name: db.name,
            serverId
          }));

          // Ordenar alfabeticamente
          databasesList.sort((a: Database, b: Database) => a.name.localeCompare(b.name));

          // Armazenar schemas se disponíveis
          if (dbType === DatabaseType.POSTGRESQL && response.server.schemas) {
            dispatch({ type: 'SET_SCHEMAS_MAP', payload: response.server.schemas });
          }

          // Armazenar lista de bancos
          dispatch({ type: 'SET_DATABASES', payload: databasesList });

          // Se só tiver um banco, selecioná-lo automaticamente
          if (databasesList.length === 1) {
            dispatch({ type: 'SET_DATABASE_NAME', payload: databasesList[0].name });
          }
        }
        // Fallback: tentar conexão automática se não encontrar bancos
        else {
          try {
            console.log("Tentando obter bancos via auto-connection test");
            // Passar o serverId como parte do objeto de conexão
            const testResponse = await serverService.testConnection({
              serverId: serverId,
              server_id: serverId
            });

            if (testResponse && testResponse.databases && testResponse.databases.length > 0) {
              // Processar bancos obtidos do teste
              const databasesList = testResponse.databases.map((db: DatabaseInfo) => ({
                id: `${serverId}:${db.name}`,
                name: db.name,
                serverId
              }));

              dispatch({ type: 'SET_DATABASES', payload: databasesList });

              // Se só tiver um banco, selecioná-lo automaticamente
              if (databasesList.length === 1) {
                dispatch({ type: 'SET_DATABASE_NAME', payload: databasesList[0].name });
              }
            } else {
              // Sem bancos disponíveis
              dispatch({
                type: 'SET_ERRORS',
                payload: { serverId: 'No databases found for this server.' }
              });
              dispatch({ type: 'SET_DATABASES', payload: [] });
            }
          } catch (error) {
            console.error('Error in auto connection test:', error);
            dispatch({
              type: 'SET_ERRORS',
              payload: { serverId: 'Error connecting to server.' }
            });
            dispatch({ type: 'SET_DATABASES', payload: [] });
          }
        }
      }
      // Formato legado ou outro formato não reconhecido
      else {
        console.warn("Formato de resposta não reconhecido ou legado:", response);

        // Tentar extrair bancos de dados do que estiver disponível
        const dbSource = response?.database || response;

        if (dbSource) {
          // Para PostgreSQL, buscar schemas como databases
          if (dbType === DatabaseType.POSTGRESQL && dbSource.schemas && Array.isArray(dbSource.schemas)) {
            const databasesList = dbSource.schemas.map((schema: string) => ({
              id: `${serverId}:${schema}`,
              name: schema,
              serverId
            }));

            dispatch({ type: 'SET_DATABASES', payload: databasesList });
            dispatch({ type: 'SET_SCHEMAS', payload: dbSource.schemas });
          }
          // Para outros tipos, tentar usar o banco configurado
          else if (dbSource.database) {
            dispatch({
              type: 'SET_DATABASES',
              payload: [{
                id: serverId,
                name: dbSource.database,
                serverId
              }]
            });

            // Selecionar automaticamente o único banco
            dispatch({ type: 'SET_DATABASE_NAME', payload: dbSource.database });
          }
          // Último recurso: tentar encontrar qualquer array que possa conter bancos
          else {
            const possibleArrays = Object.values(dbSource)
              .filter(val => Array.isArray(val)) as any[][];

            if (possibleArrays.length > 0) {
              // Usar o primeiro array encontrado como lista de bancos
              const names = possibleArrays[0];
              const databasesList = names.map((name: string) => ({
                id: `${serverId}:${name}`,
                name,
                serverId
              }));

              dispatch({ type: 'SET_DATABASES', payload: databasesList });
            } else {
              // Sem bancos encontrados
              dispatch({
                type: 'SET_ERRORS',
                payload: { serverId: 'No databases found for this server.' }
              });
              dispatch({ type: 'SET_DATABASES', payload: [] });
            }
          }
        } else {
          // Resposta vazia ou indefinida
          dispatch({
            type: 'SET_ERRORS',
            payload: { serverId: 'Failed to get database details.' }
          });
          dispatch({ type: 'SET_DATABASES', payload: [] });
        }
      }
    } catch (error) {
      console.error('Error handling databases:', error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { serverId: 'Error loading databases. Please try again later.' }
      });
      dispatch({ type: 'SET_DATABASES', payload: [] });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Função para buscar schemas (PostgreSQL/MSSQL)
  const fetchSchemas = async (serverId: string, databaseName: string) => {
    if (!serverId || !databaseName || (state.databaseType !== DatabaseType.POSTGRESQL && state.databaseType !== DatabaseType.MSSQL)) return;

    dispatch({ type: 'SET_LOADING', payload: true });

    try {
      const { serverService } = await import('../../../services/api');

      console.log(`Buscando schemas para servidor ${serverId} e banco ${databaseName}`);

      // Usar o endpoint para schemas PostgreSQL
      const response = await serverService.getSchemas(serverId, databaseName);

      let schemas: string[] = [];

      // Processar resposta para extrair schemas
      if (response && response.schemas && Array.isArray(response.schemas)) {
        schemas = response.schemas;
      } else if (response && Array.isArray(response)) {
        schemas = response;
      } else if (response && typeof response === 'object') {
        // Tentar extrair qualquer array na resposta
        const possibleArrays = Object.values(response)
          .filter(val => Array.isArray(val)) as string[][];

        if (possibleArrays.length > 0) {
          schemas = possibleArrays[0];
        }
      }

      if (schemas.length > 0) {
        console.log(`Schemas encontrados para ${databaseName}:`, schemas);
        dispatch({ type: 'SET_SCHEMAS', payload: schemas });

        // Selecionar schema padrão se necessário
        if (!state.schemaName) {
          const defaultSchema = schemas.includes('public') ? 'public' : schemas[0];
          dispatch({ type: 'SET_SCHEMA', payload: defaultSchema });
        }
      } else {
        // Schemas padrão como fallback
        console.log("Nenhum schema encontrado, usando padrões");
        const fallbackSchemas = ['public', 'information_schema', 'pg_catalog'];
        dispatch({ type: 'SET_SCHEMAS', payload: fallbackSchemas });

        if (!state.schemaName) {
          dispatch({ type: 'SET_SCHEMA', payload: 'public' });
        }
      }
    } catch (error) {
      console.error(`Error fetching schemas for ${databaseName}:`, error);

      // Schemas padrão em caso de erro
      const fallbackSchemas = ['public', 'information_schema', 'pg_catalog'];
      dispatch({ type: 'SET_SCHEMAS', payload: fallbackSchemas });

      if (!state.schemaName) {
        dispatch({ type: 'SET_SCHEMA', payload: 'public' });
      }

      dispatch({
        type: 'SET_ERRORS',
        payload: { schemaName: 'Failed to load schemas. Using defaults.' }
      });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Função para buscar tabelas
  const fetchTables = async (serverId: string, databaseName: string, schemaName?: string) => {
    if (!serverId || !databaseName) return;

    dispatch({ type: 'SET_LOADING', payload: true });

    try {
      const { serverService } = await import('../../../services/api');

      // Para PostgreSQL/MSSQL, o schema é obrigatório
      if ((state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE) && !schemaName) {
        console.warn("Schema é obrigatório para PostgreSQL/MSSQL");
        dispatch({ type: 'SET_TABLES_DATA', payload: [] });
        return;
      }

      console.log(`Buscando tabelas para servidor ${serverId}, banco ${databaseName}, schema ${schemaName || 'N/A'}`);

      // Usar o novo endpoint para tabelas
      const response = await serverService.getTables(serverId, databaseName, schemaName);

      // Processar lista de tabelas
      if (response && response.tables && Array.isArray(response.tables)) {
        const tables = response.tables.map(tableName => ({
          name: tableName,
          serverId,
          databaseName,
          schemaName
        }));

        console.log(`${tables.length} tabelas encontradas`);
        dispatch({ type: 'SET_TABLES_DATA', payload: tables });
      }
      // Caso a resposta seja diretamente um array de strings
      else if (response && Array.isArray(response)) {
        const tables = response.map(tableName => ({
          name: tableName,
          serverId,
          databaseName,
          schemaName
        }));

        console.log(`${tables.length} tabelas encontradas (formato array)`);
        dispatch({ type: 'SET_TABLES_DATA', payload: tables });
      }
      // Nenhuma tabela encontrada
      else {
        console.warn("Nenhuma tabela encontrada");
        dispatch({
          type: 'SET_ERRORS',
          payload: {
            tables: `No tables found in ${state.databaseType === DatabaseType.POSTGRESQL ? 'schema' : 'database'} ${state.databaseType === DatabaseType.POSTGRESQL ? schemaName : databaseName}`
          }
        });
        dispatch({ type: 'SET_TABLES_DATA', payload: [] });
      }
    } catch (error) {
      console.error('Error fetching tables:', error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { tables: 'An unexpected error occurred. Please try again later.' }
      });
      dispatch({ type: 'SET_TABLES_DATA', payload: [] });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Função para navegar para a próxima etapa
  const nextStep = useCallback(() => {
    dispatch({
      type: 'SET_CURRENT_STEP',
      payload: state.currentStep + 1
    });
  }, [state.currentStep]);

  // Função para voltar à etapa anterior
  const prevStep = useCallback(() => {
    dispatch({
      type: 'SET_CURRENT_STEP',
      payload: Math.max(0, state.currentStep - 1)
    });
  }, [state.currentStep]);

  // Função para validar o formulário
  const validateForm = useCallback(() => {
    const errors: Record<string, string> = {};

    // Validar userId
    if (!state.userId) {
      errors.userId = 'User is required';
    } else if (state.userId === 'NEW_SERVICE_USER') {
      // Validate service user fields
      if (!state.serviceUserName || state.serviceUserName.trim().length === 0) {
        errors.serviceUserName = 'Service user name is required';
      } else {
        // Validate service user name format (incluindo hífen)
        const invalidChars = /[-.\s@#$%^&*()+=\[\]{}\\|;:'",<>/?]/;
        if (invalidChars.test(state.serviceUserName)) {
          errors.serviceUserName = 'Nome de usuário só pode conter letras, números e underscore (_)';
        } else if (/^[0-9]/.test(state.serviceUserName)) {
          errors.serviceUserName = 'Nome de usuário deve começar com letra ou underscore';
        } else if (state.serviceUserName.length < 3) {
          errors.serviceUserName = 'Service user name must be at least 3 characters';
        } else if (state.serviceUserName.length > 30) {
          errors.serviceUserName = 'Service user name cannot exceed 30 characters';
        }
      }
    }

    // Validar serverId
    if (!state.serverId) {
      errors.serverId = 'Server is required';
    }

    // Validar databaseName
    if (!state.databaseName) {
      errors.databaseName = 'Database is required';
    }

    // Validar schemaName para PostgreSQL/MSSQL
    if ((state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL) && !state.schemaName) {
      errors.schemaName = 'Schema is required';
    }

    // Validar tables - apenas se não for database-level
    if (!state.isDatabaseLevel && state.tables.length === 0) {
      errors.tables = 'At least one table must be selected';
    }

    // Validar justification - garantir que não esteja vazia e tenha pelo menos 10 caracteres
    const justificationText = state.justification.trim();
    if (!justificationText) {
      errors.justification = 'Justification is required';
    } else if (justificationText.length < 10) {
      errors.justification = 'Justification must be at least 10 characters long';
    }

    // Validar expirationDate para acessos não permanentes
    if (!state.isPermanent && !state.expirationDate) {
      errors.expirationDate = 'Expiration date is required for temporary access';
    }

    dispatch({ type: 'SET_ERRORS', payload: errors });
    return Object.keys(errors).length === 0;
  }, [state]);

  // Função para preparar dados para envio
  const prepareSubmitData = useCallback(() => {
    
    // Check if the selected user is a service user
    const selectedUser = state.users.find(u => u.id === state.userId);
    const isExistingServiceUser = selectedUser && (selectedUser as any).is_service_user;
    
    // Get current logged in user ID
    let currentUserId: string | undefined;
    const currentUserStr = localStorage.getItem('currentUser');
    if (currentUserStr) {
      try {
        const currentUser = JSON.parse(currentUserStr);
        currentUserId = currentUser.id;
      } catch (e) {
        console.error('Error parsing current user:', e);
      }
    }
    
    // For service users (new or existing), we need the current user's ID as the requester
    let effectiveUserId = state.userId;
    let serviceUserId: string | undefined;
    
    if (state.userId === 'NEW_SERVICE_USER') {
      // Creating new service user - use current user as requester
      effectiveUserId = currentUserId || state.users[0]?.id;
    } else if (isExistingServiceUser) {
      // Existing service user - use current user as requester and pass service user ID separately
      serviceUserId = state.userId;
      effectiveUserId = currentUserId || state.users[0]?.id;
    }
    
    // Check if we should include schema
    const shouldIncludeSchema = state.databaseType === DatabaseType.POSTGRESQL || 
                                state.databaseType === DatabaseType.MSSQL || 
                                state.databaseType === DatabaseType.ORACLE;
    
    // Base data
    const data: any = {
      userId: effectiveUserId, // Always send the actual user ID (requester)
      serverId: state.serverId,
      databaseName: state.databaseName,
      databaseType: state.databaseType, // Include database type for proper schema handling
      schemaName: shouldIncludeSchema ? state.schemaName : undefined,
      tables: state.isDatabaseLevel ? ['*'] : state.tables, // Use '*' for database-level permissions
      accessType: state.accessType,
      justification: state.justification,
      expirationDate: state.isPermanent ? '' : state.expirationDate,
      isPermanent: state.isPermanent,
      isDatabaseLevel: state.isDatabaseLevel, // Include the flag
    };
    
    // Add service user info if creating new service user
    if (state.userId === 'NEW_SERVICE_USER' && state.isServiceUser) {
      // Use snake_case for backend API
      data.is_service_user = true;
      data.service_user_name = state.serviceUserName;
      data.service_user_description = state.serviceUserDescription;
    } else if (isExistingServiceUser && serviceUserId) {
      // For existing service user, send the service user ID
      data.service_user_id = serviceUserId;
      data.is_service_user = true;
    }
    
    // Debug log
    console.log('Final data para envio:', data);
    
    return data;
  }, [state]);

  // Função para resetar o formulário
  const resetForm = useCallback(() => {
    dispatch({ type: 'RESET_FORM' });
  }, []);

  // Retornar o estado, dispatch e funções auxiliares
  return {
    state,
    dispatch,
    nextStep,
    prevStep,
    validateForm,
    prepareSubmitData,
    resetForm,
    fetchServers,
    fetchDatabases,
    fetchSchemas,
    fetchTables,
    fetchUsers,
    currentUser, // Expor currentUser para debug
  };
};