import React, { useState, useEffect } from 'react';
import ConfigPageTemplate from '../../components/Settings/ConfigPageTemplate';
import {
  Paper,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Box,
  Alert,
  Tooltip,
  FormControlLabel,
  Checkbox,
  CircularProgress,
  Snackbar,
  InputAdornment,
} from '@mui/material';
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  ContentCopy as CopyIcon,
  Visibility as VisibilityIcon,
  VisibilityOff as VisibilityOffIcon,
  BarChart as StatsIcon,
  VpnKey as VpnKeyIcon,
} from '@mui/icons-material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs, { Dayjs } from 'dayjs';
import type { DatePickerProps } from '@mui/x-date-pickers/DatePicker';
import { useTranslation } from 'react-i18next';
import { apiClient as api } from '../../services/api';
import APIKeyStatsModal from '../../components/APIKeyStatsModal';

interface APIKey {
  id: string;
  name: string;
  key?: string;
  user_id: string;
  permissions: string[];
  expires_at?: string;
  last_used_at?: string;
  created_at: string;
  updated_at: string;
  is_active: boolean;
  description?: string;
  ip_whitelist?: string[];
  usage_count: number;
  user?: {
    username: string;
    email: string;
    full_name: string;
  };
}

const availablePermissions = [
  { value: '*', label: 'Full Access' },
  { value: 'read:servers', label: 'Read Servers' },
  { value: 'write:servers', label: 'Write Servers' },
  { value: 'read:users', label: 'Read Users' },
  { value: 'write:users', label: 'Write Users' },
  { value: 'read:permissions', label: 'Read Permissions' },
  { value: 'write:permissions', label: 'Write Permissions' },
  { value: 'read:requests', label: 'Read Requests' },
  { value: 'write:requests', label: 'Write Requests' },
  { value: 'read:audit', label: 'Read Audit Logs' },
];

const APIKeysConfigPage: React.FC = () => {
  const { t } = useTranslation(['settings', 'common']);
  const [apiKeys, setApiKeys] = useState<APIKey[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedKey, setSelectedKey] = useState<APIKey | null>(null);
  const [showKey, setShowKey] = useState(false);
  const [copiedKey, setCopiedKey] = useState(false);
  const [statsModalOpen, setStatsModalOpen] = useState(false);
  const [statsKeyId, setStatsKeyId] = useState<string>('');
  const [statsKeyName, setStatsKeyName] = useState<string>('');

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    permissions: [] as string[],
    expires_at: null as Dayjs | null,
    ip_whitelist: '',
    is_active: true,
  });

  useEffect(() => {
    fetchAPIKeys();
  }, []);

  const fetchAPIKeys = async () => {
    try {
      setLoading(true);
      console.log('Fetching API keys...');
      const response = await api.get('/api/api-keys');
      console.log('API Keys response:', response);
      setApiKeys(response.data || []);
      setError(null);
    } catch (err: any) {
      console.error('Error fetching API keys:', err);
      console.error('Error response:', err.response);
      setError(err.response?.data?.error || err.message || t('settings:apiKeys.error.fetchFailed'));
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async () => {
    try {
      const data = {
        name: formData.name,
        description: formData.description,
        permissions: formData.permissions,
        expires_at: formData.expires_at?.toISOString() || null,
        ip_whitelist: formData.ip_whitelist
          ? formData.ip_whitelist.split(',').map(ip => ip.trim()).filter(ip => ip)
          : [],
      };

      const response = await api.post('/api/api-keys', data);
      
      // Show the newly created key
      setSelectedKey(response.data);
      setShowKey(true);
      setCreateDialogOpen(false);
      
      // Reset form
      setFormData({
        name: '',
        description: '',
        permissions: [],
        expires_at: null,
        ip_whitelist: '',
        is_active: true,
      });

      // Refresh list
      fetchAPIKeys();
      setSuccess(t('settings:apiKeys.success.created'));
    } catch (err: any) {
      setError(err.response?.data?.error || t('settings:apiKeys.error.createFailed'));
    }
  };

  const handleUpdate = async () => {
    if (!selectedKey) return;

    try {
      const data = {
        name: formData.name,
        description: formData.description,
        permissions: formData.permissions,
        expires_at: formData.expires_at?.toISOString() || null,
        ip_whitelist: formData.ip_whitelist
          ? formData.ip_whitelist.split(',').map(ip => ip.trim()).filter(ip => ip)
          : [],
        is_active: formData.is_active,
      };

      await api.put(`/api/api-keys/${selectedKey.id}`, data);
      
      setEditDialogOpen(false);
      setSelectedKey(null);
      
      // Reset form
      setFormData({
        name: '',
        description: '',
        permissions: [],
        expires_at: null,
        ip_whitelist: '',
        is_active: true,
      });

      // Refresh list
      fetchAPIKeys();
      setSuccess(t('settings:apiKeys.success.updated'));
    } catch (err: any) {
      setError(err.response?.data?.error || t('settings:apiKeys.error.updateFailed'));
    }
  };

  const handleDelete = async () => {
    if (!selectedKey) return;

    try {
      await api.delete(`/api/api-keys/${selectedKey.id}`);
      
      setDeleteDialogOpen(false);
      setSelectedKey(null);
      
      // Refresh list
      fetchAPIKeys();
      setSuccess(t('settings:apiKeys.success.deleted'));
    } catch (err: any) {
      setError(err.response?.data?.error || t('settings:apiKeys.error.deleteFailed'));
    }
  };

  const handleCopyKey = () => {
    if (selectedKey?.key) {
      navigator.clipboard.writeText(selectedKey.key);
      setCopiedKey(true);
      setTimeout(() => setCopiedKey(false), 2000);
    }
  };

  const openEditDialog = (apiKey: APIKey) => {
    setSelectedKey(apiKey);
    setFormData({
      name: apiKey.name,
      description: apiKey.description || '',
      permissions: apiKey.permissions || [],
      expires_at: apiKey.expires_at ? dayjs(apiKey.expires_at) : null,
      ip_whitelist: apiKey.ip_whitelist?.join(', ') || '',
      is_active: apiKey.is_active,
    });
    setEditDialogOpen(true);
  };

  const openDeleteDialog = (apiKey: APIKey) => {
    setSelectedKey(apiKey);
    setDeleteDialogOpen(true);
  };

  const openStatsModal = (apiKey: APIKey) => {
    setStatsKeyId(apiKey.id);
    setStatsKeyName(apiKey.name);
    setStatsModalOpen(true);
  };

  const formatDate = (date: string) => {
    return dayjs(date).format('YYYY-MM-DD HH:mm');
  };

  if (loading) {
    return (
      <ConfigPageTemplate
        title={t('settings:apiKeys.title')}
        icon={<VpnKeyIcon sx={{ fontSize: 32 }} />}
        description={t('settings:apiKeys.pageDescription')}
      >
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      </ConfigPageTemplate>
    );
  }

  return (
    <ConfigPageTemplate
      title={t('settings:apiKeys.title')}
      icon={<VpnKeyIcon sx={{ fontSize: 32 }} />}
      description={t('settings:apiKeys.pageDescription')}
    >
      <Paper sx={{ p: 3 }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
          <Typography variant="h6" component="h2">
            {t('settings:apiKeys.listTitle')}
          </Typography>
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddIcon />}
            onClick={() => setCreateDialogOpen(true)}
          >
            {t('settings:apiKeys.createButton')}
          </Button>
        </Box>

        <Alert severity="info" sx={{ mb: 2 }}>
          {t('settings:apiKeys.info')}
        </Alert>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
            {error}
          </Alert>
        )}

        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>{t('settings:apiKeys.table.name')}</TableCell>
                <TableCell>{t('settings:apiKeys.table.description')}</TableCell>
                <TableCell>{t('settings:apiKeys.table.permissions')}</TableCell>
                <TableCell>{t('settings:apiKeys.table.lastUsed')}</TableCell>
                <TableCell>{t('settings:apiKeys.table.expiresAt')}</TableCell>
                <TableCell>{t('settings:apiKeys.table.status')}</TableCell>
                <TableCell>{t('settings:apiKeys.table.usage')}</TableCell>
                <TableCell align="right">{t('actions', { ns: 'common' })}</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {apiKeys.map((apiKey) => (
                <TableRow key={apiKey.id}>
                  <TableCell>{apiKey.name}</TableCell>
                  <TableCell>{apiKey.description || '-'}</TableCell>
                  <TableCell>
                    {apiKey.permissions.includes('*') ? (
                      <Chip label="Full Access" color="error" size="small" />
                    ) : (
                      apiKey.permissions.length > 2 ? (
                        <Tooltip title={apiKey.permissions.join(', ')}>
                          <Chip 
                            label={`${apiKey.permissions.length} permissions`} 
                            size="small" 
                          />
                        </Tooltip>
                      ) : (
                        apiKey.permissions.map(perm => (
                          <Chip key={perm} label={perm} size="small" sx={{ mr: 0.5 }} />
                        ))
                      )
                    )}
                  </TableCell>
                  <TableCell>
                    {apiKey.last_used_at ? formatDate(apiKey.last_used_at) : t('never', { ns: 'common' })}
                  </TableCell>
                  <TableCell>
                    {apiKey.expires_at ? formatDate(apiKey.expires_at) : t('never', { ns: 'common' })}
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={apiKey.is_active ? t('active', { ns: 'common' }) : t('inactive', { ns: 'common' })} 
                      color={apiKey.is_active ? 'success' : 'default'} 
                      size="small" 
                    />
                  </TableCell>
                  <TableCell>{apiKey.usage_count}</TableCell>
                  <TableCell align="right">
                    <Tooltip title={t('settings:apiKeys.viewStats')}>
                      <IconButton size="small" onClick={() => openStatsModal(apiKey)}>
                        <StatsIcon />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title={t('edit', { ns: 'common' })}>
                      <IconButton size="small" onClick={() => openEditDialog(apiKey)}>
                        <EditIcon />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title={t('delete', { ns: 'common' })}>
                      <IconButton size="small" onClick={() => openDeleteDialog(apiKey)}>
                        <DeleteIcon />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
              {apiKeys.length === 0 && (
                <TableRow>
                  <TableCell colSpan={8} align="center">
                    {t('settings:apiKeys.noKeys')}
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      {/* Create Dialog */}
      <Dialog open={createDialogOpen} onClose={() => setCreateDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{t('settings:apiKeys.createTitle')}</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label={t('settings:apiKeys.form.name')}
            fullWidth
            variant="outlined"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            sx={{ mb: 2 }}
          />
          <TextField
            margin="dense"
            label={t('settings:apiKeys.form.description')}
            fullWidth
            variant="outlined"
            multiline
            rows={2}
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            sx={{ mb: 2 }}
          />
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>{t('settings:apiKeys.form.permissions')}</InputLabel>
            <Select
              multiple
              value={formData.permissions}
              onChange={(e) => setFormData({ ...formData, permissions: e.target.value as string[] })}
              renderValue={(selected) => (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {(selected as string[]).map((value) => (
                    <Chip key={value} label={availablePermissions.find(p => p.value === value)?.label || value} size="small" />
                  ))}
                </Box>
              )}
            >
              {availablePermissions.map((permission) => (
                <MenuItem key={permission.value} value={permission.value}>
                  {permission.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DatePicker
              label={t('settings:apiKeys.form.expiresAt') as string}
              value={formData.expires_at as any}
              onChange={(newValue: any) => setFormData({ ...formData, expires_at: newValue })}
              slotProps={{
                textField: {
                  sx: { mb: 2, width: '100%' }
                }
              }}
            />
          </LocalizationProvider>
          <TextField
            margin="dense"
            label={t('settings:apiKeys.form.ipWhitelist')}
            fullWidth
            variant="outlined"
            value={formData.ip_whitelist}
            onChange={(e) => setFormData({ ...formData, ip_whitelist: e.target.value })}
            helperText={t('settings:apiKeys.form.ipWhitelistHelp')}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>{t('cancel', { ns: 'common' })}</Button>
          <Button onClick={handleCreate} variant="contained" disabled={!formData.name}>
            {t('create', { ns: 'common' })}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Edit Dialog */}
      <Dialog open={editDialogOpen} onClose={() => setEditDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{t('settings:apiKeys.editTitle')}</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label={t('settings:apiKeys.form.name')}
            fullWidth
            variant="outlined"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            sx={{ mb: 2 }}
          />
          <TextField
            margin="dense"
            label={t('settings:apiKeys.form.description')}
            fullWidth
            variant="outlined"
            multiline
            rows={2}
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            sx={{ mb: 2 }}
          />
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>{t('settings:apiKeys.form.permissions')}</InputLabel>
            <Select
              multiple
              value={formData.permissions}
              onChange={(e) => setFormData({ ...formData, permissions: e.target.value as string[] })}
              renderValue={(selected) => (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {(selected as string[]).map((value) => (
                    <Chip key={value} label={availablePermissions.find(p => p.value === value)?.label || value} size="small" />
                  ))}
                </Box>
              )}
            >
              {availablePermissions.map((permission) => (
                <MenuItem key={permission.value} value={permission.value}>
                  {permission.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DatePicker
              label={t('settings:apiKeys.form.expiresAt') as string}
              value={formData.expires_at as any}
              onChange={(newValue: any) => setFormData({ ...formData, expires_at: newValue })}
              slotProps={{
                textField: {
                  sx: { mb: 2, width: '100%' }
                }
              }}
            />
          </LocalizationProvider>
          <TextField
            margin="dense"
            label={t('settings:apiKeys.form.ipWhitelist')}
            fullWidth
            variant="outlined"
            value={formData.ip_whitelist}
            onChange={(e) => setFormData({ ...formData, ip_whitelist: e.target.value })}
            helperText={t('settings:apiKeys.form.ipWhitelistHelp')}
            sx={{ mb: 2 }}
          />
          <FormControlLabel
            control={
              <Checkbox
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
              />
            }
            label={t('settings:apiKeys.form.isActive')}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)}>{t('cancel', { ns: 'common' })}</Button>
          <Button onClick={handleUpdate} variant="contained" disabled={!formData.name}>
            {t('save', { ns: 'common' })}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Delete Dialog */}
      <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
        <DialogTitle>{t('settings:apiKeys.deleteTitle')}</DialogTitle>
        <DialogContent>
          <DialogContentText>
            {t('settings:apiKeys.deleteConfirm', { name: selectedKey?.name })}
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)}>{t('cancel', { ns: 'common' })}</Button>
          <Button onClick={handleDelete} color="error" variant="contained">
            {t('delete', { ns: 'common' })}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Show Key Dialog */}
      <Dialog open={!!selectedKey?.key} onClose={() => { setSelectedKey(null); setShowKey(false); }}>
        <DialogTitle>{t('settings:apiKeys.keyCreated')}</DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            {t('settings:apiKeys.keyWarning')}
          </Alert>
          <TextField
            fullWidth
            variant="outlined"
            value={selectedKey?.key || ''}
            InputProps={{
              readOnly: true,
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton onClick={handleCopyKey}>
                    <CopyIcon />
                  </IconButton>
                </InputAdornment>
              ),
              style: { fontFamily: 'monospace' }
            }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => { setSelectedKey(null); setShowKey(false); }} variant="contained">
            {t('close', { ns: 'common' })}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Success Snackbar */}
      <Snackbar
        open={!!success}
        autoHideDuration={6000}
        onClose={() => setSuccess(null)}
        message={success}
      />

      {/* Copy Snackbar */}
      <Snackbar
        open={copiedKey}
        autoHideDuration={2000}
        onClose={() => setCopiedKey(false)}
        message={t('settings:apiKeys.keyCopied')}
      />

      {/* Stats Modal */}
      <APIKeyStatsModal
        open={statsModalOpen}
        onClose={() => setStatsModalOpen(false)}
        apiKeyId={statsKeyId}
        apiKeyName={statsKeyName}
      />
    </ConfigPageTemplate>
  );
};

export default APIKeysConfigPage;